"use strict";
// Independent knowledge explanations and original exercises. Additive; no storage or network.
(() => {
const rows=[{"lessonId":"estimation-boundary","topicId":"estimation","courseRoute":"#course/data/topic/estimation","sections":[{"title":"除法先选一个容易控制的近似点","text":"求正数比值时，可以暂时保持分子不动，把分母换成邻近的整十、整百数。这样只有一个误差源，且方向好判断：分母调大，商就偏小。例如7350÷148，把148暂取150，得到49；原商大于49，又因148×50=7400大于7350，原商小于50。因此若从30、50、70、90中选最近值，50已能确定，不能把49说成精确商。","index":9,"domId":"ki-point-0001"},{"title":"连乘除要追踪误差倍率","text":"只动分母是一种方便的选择，不是除法必须遵守的规则。若连乘式中两个因子都被放大2%，积的放大倍率为1.02×1.02=1.0404，误差为4.04%；若一个正比值的分子放大2%、分母缩小2%，倍率为1.02÷0.98，误差约4.08%。单步看着很小的改动也会累计。选项接近时，应恢复精度或为整个式子求范围，不能逐步四舍五入后假定误差消失。","index":10,"domId":"ki-point-0002"}],"cards":[{"id":"ki-d-001","title":"除法近似的方向","core":"分子与分母均为正时，分子不变而分母增大，商减小；先夹住真值，再看能否选答案。","boundary":"此方向结论要求分子、分母均为正；分子为零时商不变，分子为负且正分母增大时商反而增大。多个近似因子的误差必须合并考察。","prompt":"7350÷148中把分母取150，估值为{{0}}，方向为{{1}}；真值落在49与{{2}}之间。","blanks":[{"answer":"49","accept":[]},{"answer":"偏小","accept":["低估","小于真值"]},{"answer":"50","accept":[]}]},{"id":"ki-d-002","title":"累计误差不是单项误差","core":"连乘除的近似由各自误差倍率相乘或相除决定。","boundary":"只有明确误差模型时才能给出总误差界。","prompt":"两个正因子各放大2%，积共放大{{0}}%；不是恰好4%。","blanks":[{"answer":"4.04","accept":[]}]}],"questions":[{"id":"ki-dq-001","lesson":"estimation-boundary","stem":"将7350÷148的结果与30、50、70、90比较，哪项最接近？","options":["70","50","90","30"],"answer":1,"explanation":"148×49=7252，148×50=7400，真商在49与50之间，整个区间都最接近50。","optionReviews":["错误。70与真商至少相差20。","正确。49至50都处于50的最近值区间40至60内。","错误。90离49至50更远。","错误。30与真商至少相差19。"]},{"id":"ki-dq-002","lesson":"estimation-boundary","stem":"某乘积的两个正因子各被近似成原值的102%，近似乘积比原乘积大多少？","options":["4.04%","2%","0.04%","4%"],"answer":0,"explanation":"误差倍率为1.02²=1.0404，减1得4.04%。乘法误差不能仅记录一个因子，也不能把交叉项无条件扔掉。","optionReviews":["正确。包含2%+2%以及0.04%的交叉项。","错误。只计入了一个因子的变化。","错误。只保留了交叉项，漏掉两个2%。","错误。遗漏两次变化的乘积项。"]}]},{"lessonId":"estimation-boundary","topicId":"estimation","courseRoute":"#course/data/topic/estimation","sections":[{"title":"有效位数由答案分界来决定","text":"看选项的间距，是为了判断可以容许多大误差，不是为了机械规定两位或三位有效数。比如5467÷219，219×24=5256、219×26=5694，真值在24与26之间；从15、25、35、45中选最近值，25已稳妥。可先将分子、分母取作5500与220得到25，但真正允许停止的证据，是原值范围没有跨过20或30这两个选择分界。","index":11,"domId":"ki-point-0003"},{"title":"两位初筛，三位复核，仍可能继续算","text":"选项首位不同，或首位相同而次位相隔较远时，先试两位有效数常能减少计算；连次位都接近时，可先试三位，但位数本身不保证正确。比如1.24与1.25的最近值分界为1.245。仅知x在1.243至1.247，仍不能选；若进一步得到1.2455≤x≤1.2465，则全区间在分界右侧，可以选1.25。即使已经保留三位，区间若仍跨界，也必须继续提高精度。","index":12,"domId":"ki-point-0004"}],"cards":[{"id":"ki-d-003","title":"误差范围决定何时停","core":"选项间距只用于设定精度目标，最终应让真值范围落在同一选项的判定区间。","boundary":"不能以“已算两位”代替误差证明。","prompt":"候选值1.24与1.25按绝对差选最近值，其分界是{{0}}。","blanks":[{"answer":"1.245","accept":[]}]},{"id":"ki-d-004","title":"首位次位只作初筛","core":"相邻选项很近时先多留有效位，再核对是否跨界。","boundary":"两位、三位都不是普遍有效的精度保证。","prompt":"已知1.2455≤x≤1.2465，在1.24与1.25中可选{{0}}；若只知1.243≤x≤1.247则{{1}}。","blanks":[{"answer":"1.25","accept":[]},{"answer":"不能确定","accept":["无法确定","信息不足"]}]}],"questions":[{"id":"ki-dq-003","lesson":"estimation-boundary","stem":"5467÷219若从15、25、35、45中选最接近的数，哪项正确？","options":["35","15","25","45"],"answer":2,"explanation":"原商位于24与26之间，而25相对15和35的分界为20和30，所以整个可能区间都选25。","optionReviews":["错误。原商小于26，未到30的分界。","错误。原商超过24，已在20的右侧。","正确。夹逼范围已足以分开选项。","错误。45与该范围相距更大。"]},{"id":"ki-dq-004","lesson":"estimation-boundary","stem":"候选值为1.24、1.25、1.30、1.35，按绝对差选最近值。已知1.243≤x≤1.247，后来缩小为1.2455≤x≤1.2465。哪种判断严谨？","options":["两位有效数对任何选项都足够","初始范围已经必选1.24","三位有效数对任何题都能保证答案","初始范围不能确定，缩小后可选1.25"],"answer":3,"explanation":"1.24与1.25的分界为1.245，初始范围跨界，缩小后的全区间在右侧，故可选1.25。位数是操作起点，区间是结束依据。","optionReviews":["错误。位数不能脱离选项距离和误差范围。","错误。初始范围含分界两侧，不能单选1.24。","错误。更接近的选项仍可能要求更多位。","正确。分别检查了两次范围与分界的关系。"]}]},{"lessonId":"estimation-boundary","topicId":"estimation","courseRoute":"#course/data/topic/estimation","sections":[{"title":"精确整数可以先看末位","text":"整数加减在模10下仍保持加减关系。若材料给的是精确整数，且候选答案个位各不相同，先算个位可能就能定位。例如2867+4598−1734，个位为7+8−4=11，结果个位为1；候选5731、5732、5733、5734中只有5731满足。尾数筛选只用于排除不相容选项，并没有独立求出结果的所有数位。","index":13,"domId":"ki-point-0005"},{"title":"粗材料先抓高位，再补进退位","text":"数据已舍入时，显示的末位未必是原值末位，不能按同余恢复真实精确答案。即使是精确数，粗算高位也要把低位进退位算进去。3980+2960−1040，先看千位3+2−1=4，但余下980+960−40=1900还要加回，故结果5900而非4000。遇到相近数相减，低位可能决定主要差额，不能只保留最高位就结束。","index":14,"domId":"ki-point-0006"}],"cards":[{"id":"ki-d-005","title":"尾数法的入口条件","core":"末位同余适合精确整数加减且候选末位可区分的情况。","boundary":"显示数已经舍入、选项末位相同或材料单位未统一时，不能仅靠尾数选定。","prompt":"2867+4598−1734的个位是{{0}}；3980+2960−1040的完整结果为{{1}}。","blanks":[{"answer":"1","accept":[]},{"answer":"5900","accept":[]}]}],"questions":[{"id":"ki-dq-005","lesson":"estimation-boundary","stem":"精确整数2867+4598−1734等于多少？","options":["5733","5731","5732","5734"],"answer":1,"explanation":"完整相加再相减得7465−1734=5731；也可先以模10算出末位1，在本组选项中唯一匹配。","optionReviews":["错误。末位3不满足同余关系。","正确。全算与尾数筛选一致。","错误。末位2不满足7+8−4的同余结果。","错误。末位4不满足同余关系。"]},{"id":"ki-dq-006","lesson":"estimation-boundary","stem":"两笔真实金额各自四舍五入到0.1万元后均显示1.5万元，现要求原始两笔金额之差的精确个位。哪项正确？","options":["原差必为0元","无法由显示数确定原差的精确个位","原差必为1000元","可把两个显示数的末位相减恢复原差末位"],"answer":1,"explanation":"每笔金额的舍入误差都可能不同，显示值相同并不推出原金额相同，也没有原始个位信息。不能把显示数的末位当原数末位。","optionReviews":["错误。两笔金额可以不同但落在同一舍入区间。","正确。舍入使原始末位信息丢失。","错误。1000元没有根据，也不是固定差。","错误。模10只适用于相应的精确整数，而不是恢复舍入前的末位。"]}]},{"lessonId":"estimation-boundary","topicId":"estimation","courseRoute":"#course/data/topic/estimation","sections":[{"title":"反向变动可直接比较","text":"将分母先规范为正数。两个正分数中，若一个分子更大、分母反而更小，它一定更大。例如47/83与45/86，第一项分子更大且分母更小，可先比47/83>45/83>45/86，不必做小数除法。正分母是这里不改变不等号方向的关键条件。若出现负分母，先把负号提到分子，再按统一符号处理。","index":15,"domId":"ki-point-0007"},{"title":"同向变动改看交叉乘积","text":"分子分母都变大，并不能凭某一项的变化判大小。对正分母b、d，a/b与c/d的大小等价于比较ad和bc。比如37/64与40/69，37×69=2553，40×64=2560，所以37/64略小。两者非常接近，粗保留一位小数都会看成0.6，显示相同不代表原分数相等。用交叉乘法既避免除法，也保留了精确关系。","index":16,"domId":"ki-point-0008"}],"cards":[{"id":"ki-d-006","title":"正分数比较的两条路","core":"分子更大且分母更小可直接比较；同向变化时比较交叉乘积。","boundary":"先统一分母符号；近似小数相同不能推出精确相等。","prompt":"比较37/64与40/69时，应比较37×{{0}}和40×{{1}}，较大的分数是{{2}}。","blanks":[{"answer":"69","accept":[]},{"answer":"64","accept":[]},{"answer":"40/69","accept":[]}]}],"questions":[{"id":"ki-dq-007","lesson":"estimation-boundary","stem":"下面两个精确比值的关系是什么：47/83与45/86？","options":["45/86较大","二者相等","47/83较大","必须求出无限小数才能比较"],"answer":2,"explanation":"47/83的分子47>45且正分母83<86，两个变化都使47/83的比值更大。","optionReviews":["错误。没有考虑47/83的分母更小。","错误。可以得到严格不等关系。","正确。分子和分母对大小的影响同向支持47/83较大。","错误。单调性或交叉乘积即可给出精确大小。"]},{"id":"ki-dq-008","lesson":"estimation-boundary","stem":"37/64与40/69哪项较大？","options":["二者取一位小数相同，因此无法比较","37/64","40/69","二者精确相等"],"answer":2,"explanation":"37×69=2553，40×64=2560。分母均正，交叉乘积较大的40/69更大。","optionReviews":["错误。粗显示值相同不妨碍原分数用精确乘积比较。","错误。分子较小和分母较小的效应不能只看一个。","正确。2560大于2553。","错误。交叉乘积不相等。"]}]},{"lessonId":"growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"先确定周期，再找相应基期","text":"同比是在相邻年份的同一统计期间之间比较，例如2026年第三季度对应2025年第三季度；环比是与紧邻的上一个相同类型统计周期比较，季度环比对应2026年第二季度。虚构业务量第三季度为132万件，上一季度120万件，上年第三季度110万件，则同比20%、环比10%。不能因为表里有上月数据就把季度环比的基期改成上月。","index":12,"domId":"ki-point-0009"},{"title":"累计与当期不能悄悄交换","text":"2026年1—9月累计的同比基期，应是2025年1—9月累计，不是2025年9月当月。月度、季度、年度和累计窗口必须按完整问句配对，统计对象与单位也应一致。材料若另行明确“上一观察窗口”等特殊定义，就按该定义找紧邻窗口；不要把日常对环比的印象套到所有材料。找基期的步骤是先标期间起止，再核对象和单位，最后才代增长公式。","index":13,"domId":"ki-point-0010"}],"cards":[{"id":"ki-d-007","title":"同比环比先配期间","core":"同比配上年同一时期，环比配紧邻的同类统计周期。","boundary":"累计与当期、季度与月份不能直接混用。","prompt":"2026年第三季度同比的基期是{{0}}，环比的基期是{{1}}。","blanks":[{"answer":"2025年第三季度","accept":[]},{"answer":"2026年第二季度","accept":[]}]}],"questions":[{"id":"ki-dq-009","lesson":"growth","stem":"同口径业务量：2026年第三季度132万件、第二季度120万件、2025年第三季度110万件。2026年第三季度同比与环比分别为多少？","options":["10%、20%","20%、20%","10%、10%","20%、10%"],"answer":3,"explanation":"同比用110作基期，132/110−1=20%；环比用120作基期，132/120−1=10%。","optionReviews":["错误。把同比和环比基期交换了。","错误。环比不能也用上年第三季度。","错误。同比不能也用本年第二季度。","正确。年份同季与本年相邻季度配对正确。"]},{"id":"ki-dq-010","lesson":"growth","stem":"问2026年1—9月累计运输量同比增长率，哪一数据应作为基期？","options":["2025年1—9月累计运输量","2026年1—8月累计运输量","2025年9月当月运输量","2026年8月当月运输量"],"answer":0,"explanation":"同比的同一时期必须保留整个1—9月累计窗口，不能换成单月或少一个月的累计。","optionReviews":["正确。对象与累计期间均可比。","错误。这是不同长度的本年累计，不是同比基期。","错误。单月与九个月累计长度不同。","错误。这是本年单月，不是上年同期。"]}]},{"lessonId":"growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"倒推时先认清给的是量还是率","text":"记现期为A、基期为B，带符号变化量为Δ。由于A=B+Δ，所以B=A−Δ；若给的是以正基期为分母的增长率r，由A=B(1+r)得B=A/(1+r)。比如现期396万元、增长10%，基期396/1.1=360万元；现期264万元、减少36万元，Δ=−36，所以基期264−(−36)=300万元。下降量的正值36与带符号变化量−36不要混写。","index":14,"domId":"ki-point-0011"},{"title":"下降用负率，零因子不能反除","text":"现期264万元、下降12%，应代r=−0.12，基期264/0.88=300万元，不是264/1.12。常规正数量模型要求B>0、r>−1才能从正现期反推。若现期0且增长率−100%，关系变成0=B×0，任意正基期都符合，不能做0/0求出唯一原值。若材料只报告舍入后的现期或率，倒推得到的也受原始精度限制。","index":15,"domId":"ki-point-0012"}],"cards":[{"id":"ki-d-008","title":"两条基期还原式","core":"给变化量用A−Δ；给增长率用A/(1+r)。下降时Δ与r为负。","boundary":"1+r不得为0；正基期普通数量题要检查r>−100%。","prompt":"现期264、减少36，对应带符号Δ={{0}}，基期为{{1}}。","blanks":[{"answer":"-36","accept":["−36"]},{"answer":"300","accept":[]}]},{"id":"ki-d-009","title":"下降不是除以更大的因子","core":"下降12%意味着现期占基期的88%。","boundary":"下降100%且现期为0时无法唯一倒推正基期。","prompt":"现期264、下降12%，基期应计算264÷{{0}}；现期0、下降100%时基期{{1}}。","blanks":[{"answer":"0.88","accept":[]},{"answer":"不能唯一确定","accept":["无法唯一确定","不能确定","信息不足"]}]}],"questions":[{"id":"ki-dq-011","lesson":"growth","stem":"某项现期396万元，比基期增长10%。基期为多少万元？","options":["356.4","435.6","386","360"],"answer":3,"explanation":"正基期B=396/(1+10%)=396/1.1=360万元。","optionReviews":["错误。现期乘0.9只是线性近似且本题可精算。","错误。乘1.1是把现期继续向后推。","错误。10%不是可直接减去的10万元。","正确。回代360×1.1=396。"]},{"id":"ki-dq-012","lesson":"growth","stem":"现期264万元，比基期减少36万元。基期为多少万元？","options":["36","300","264","228"],"answer":1,"explanation":"带符号Δ为−36，B=A−Δ=264+36=300万元。","optionReviews":["错误。36是减少量，不是原规模。","正确。300−36=264。","错误。忽略了已知的减少。","错误。把减少量当成正的增长量减去了。"]},{"id":"ki-dq-013","lesson":"growth","stem":"某正基期指标降幅恰为100%，现期恰为0。仅凭这两项信息，基期如何确定？","options":["必为0","必为100","必为1","不能唯一确定"],"answer":3,"explanation":"A=B(1−100%)=0，对任意正B都成立。0/0没有定义，不能借百分数中的100给基期赋值。","optionReviews":["错误。题设为正基期，且0不能作为普通增长率分母。","错误。100只是百分数记法，并非数量规模。","错误。没有理由将规模固定为1。","正确。不同正基期都产生同样的现期0和降幅100%。"]}]},{"lessonId":"growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"线性近似的误差可以精确写出","text":"当A>0、r>−1时，基期精确值B=A/(1+r)。把它近似成L=A(1−r)，有L/B=(1−r)(1+r)=1−r²，所以近似值不大于真值，相对真值的误差大小恰为r²。例如A=210、r=5%，B=200，L=199.5，少0.5，相对误差0.25%。r=−5%、A=190时也得到B=200、L=199.5，误差方向并不会因下降而反过来。","index":16,"domId":"ki-point-0013"},{"title":"小于阈值仍须核对选项","text":"若|r|≤5%，相对误差至多0.25%，只是误差界，不能自动宣布所有题都能这样做。精确值200若面对180、200、220等宽选项，近似199.5已经足够；面对199.6、199.8、200.0、200.2时，199.5会偏向错误选项，需要精算或使用误差修正。应以误差范围是否跨过决定答案的分界为准，不以“小增长率”四个字作保证。","index":17,"domId":"ki-point-0014"}],"cards":[{"id":"ki-d-010","title":"线性近似的相对误差","core":"A/(1+r)近似为A(1−r)，在A>0、r>−1下相对误差大小恰为r²，近似偏低。","boundary":"r可正可负；能否作答还要比较选项分界。","prompt":"|r|=5%时，该近似相对真值的误差为{{0}}%；A=210、r=5%时少算{{1}}。","blanks":[{"answer":"0.25","accept":[]},{"answer":"0.5","accept":[]}]}],"questions":[{"id":"ki-dq-014","lesson":"growth","stem":"现期210、增长5%，用210×(1−5%)近似基期。其相对精确基期值的误差大小为多少？","options":["2.5%","0.5%","0.25%","5%"],"answer":2,"explanation":"精确基期200，近似199.5，误差0.5/200=0.25%，也等于(0.05)²。","optionReviews":["错误。平方及百分数转换均不符。","错误。0.5是绝对误差，不能直接加百分号。","正确。平方后为0.0025，转成百分数是0.25%。","错误。这是原增长率，不是该近似的误差。"]},{"id":"ki-dq-015","lesson":"growth","stem":"现期210、增长5%，需在199.6、199.8、200.0、200.2中选最接近的基期值。哪种做法正确？","options":["精算210/1.05=200，选200.0","一律用199.5，选199.6","误差一定向上，应从199.5再减0.5","因增长率不超过5%，任何精度都可直接用线性近似"],"answer":0,"explanation":"线性近似199.5虽只有0.25%相对误差，但足以跨过近选项分界；精确商为200。","optionReviews":["正确。此题需要的精度高于粗近似能够保证的精度。","错误。199.5只是近似值，直接匹配导致误选。","错误。近似偏低，应向上修正；这里修正到200。","错误。增长率界不代表选项精度保证。"]}]},{"lessonId":"growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"和差先还原各自出发点","text":"多个对象的增速基数各不相同。求原规模之和或之差，应分别算A₁/(1+r₁)、A₂/(1+r₂)，再按设问合并。例如甲现期165、增长10%，基期150；乙现期216、下降10%，基期240。两者基期之和为390，甲减乙为−90。还没算完时也可由甲现期小且增长、乙现期大且下降，先判断甲基期更小，排除正的“甲减乙”答案。","index":18,"domId":"ki-point-0015"},{"title":"增长率不能先加起来","text":"两个部分现期都为120，甲增长20%、乙下降20%。各基期是100与150，总基期250，总现期240，合计反而下降4%。若先将20%与−20%相加成0，再用240除1，会把总基期误算成240。率的直接相加既不是合并增速，也不是总基期的还原式。预判只做排除或校验，不能把方向判断冒充精确和差。","index":19,"domId":"ki-point-0016"}],"cards":[{"id":"ki-d-011","title":"多个基期分别除","core":"先对每个现期除以各自的增长因子，再加总或作差。","boundary":"不能相加各组增长率后作为共同增长因子。","prompt":"甲现期165增10%、乙现期216降10%，基期和为{{0}}，甲基期减乙基期为{{1}}。","blanks":[{"answer":"390","accept":[]},{"answer":"-90","accept":["−90"]}]}],"questions":[{"id":"ki-dq-016","lesson":"growth","stem":"甲现期165、增长10%；乙现期216、下降10%，二者口径可比。基期之和与甲基期减乙基期分别为多少？","options":["390、−90","390、90","381、−51","381、0"],"answer":0,"explanation":"甲基期165/1.1=150，乙基期216/0.9=240，因此和390、差−90。","optionReviews":["正确。分别还原后再运算。","错误。和正确，但差的方向应为150−240。","错误。381是现期之和，−51是现期之差。","错误。未还原基期，且现期不同也不能凭增速抵消判差为0。"]},{"id":"ki-dq-017","lesson":"growth","stem":"两个不重叠部分的现期均为120，甲增长20%、乙下降20%。总体基期与总体增长率分别为多少？","options":["250、−4%","240、0%","250、0%","240、−4%"],"answer":0,"explanation":"基期分别100与150，合计250；现期合计240，增长率(240−250)/250=−4%。","optionReviews":["正确。总率须按总基期计算。","错误。将两个率相加造成错误基期及总率。","错误。基期正确，但总量已由250降到240。","错误。总率用250作分母，不能一边称基期240一边给−4%。"]}]},{"lessonId":"growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"正向推算同样保留符号","text":"给定基期B与带符号变化量Δ，现期A=B+Δ；给定以正基期定义的增长率r，则A=B(1+r)。例如基期480吨、下降12.5%，r=−0.125，现期480×0.875=420吨；带符号变化量为−60吨。减少量60吨与增长率−12.5%是不同形式的信息，不能把一个有单位的数当作百分数。","index":20,"domId":"ki-point-0017"},{"title":"先统一单位再加，先化小数再乘","text":"已知基期0.84亿元、增加1600万元，先换成8400万元，再加1600万元得10000万元，即1亿元。若给的是12.5%，代入乘数时用0.125，不是12.5；若给的是下降，则用1−0.125。正向结果可用“现期−基期=带符号变化量”校验。公式正确并不能挽救亿元和万元直接相加的单位错误。","index":21,"domId":"ki-point-0018"}],"cards":[{"id":"ki-d-012","title":"现期的两种生成方式","core":"量的变化直接加，率的变化乘增长因子，下降用负增长率。","boundary":"先统一数量单位，百分数代入时转成小数。","prompt":"基期480吨下降12.5%，现期{{0}}吨、带符号变化量{{1}}吨。","blanks":[{"answer":"420","accept":[]},{"answer":"-60","accept":["−60"]}]}],"questions":[{"id":"ki-dq-018","lesson":"growth","stem":"基期480吨，下降12.5%，现期及带符号变化量为多少？","options":["60吨、−420吨","420吨、−60吨","467.5吨、−12.5吨","540吨、60吨"],"answer":1,"explanation":"480×(1−0.125)=420，Δ=420−480=−60吨。","optionReviews":["错误。把减少量当现期，两个量混淆。","正确。现期与变化量的符号、单位一致。","错误。把百分数误当可直接相减的吨数。","错误。把下降算成增长。"]},{"id":"ki-dq-019","lesson":"growth","stem":"某项基期0.84亿元，增加1600万元，现期为多少亿元？","options":["1","1600.84","0.856","0.68"],"answer":0,"explanation":"1600万元=0.16亿元，0.84+0.16=1亿元。","optionReviews":["正确。先做单位转换再相加。","错误。将万元数字直接与亿元数字相加。","错误。把1600万元错换为0.016亿元。","错误。将增加误算成减少。"]}]},{"lessonId":"growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"数量变化与相对变化用单位分开","text":"当问“多了多少吨、多少万元”，求的是现期减基期的数量差；问“增长百分之几、几成”，求的是相对基期的比率。例如产量从40吨到100吨，增加60吨，增长率60/40=150%，也就是增长一倍半。1成=10%，但不能把60吨写成60%，更不能因为差额较大就省略分母。先把设问要的单位写在答案旁边，能避免量与率互换。","index":22,"domId":"ki-point-0019"},{"title":"达到几倍与增加几倍相差一个原量","text":"同一例子中，现期100吨是基期40吨的2.5倍，属于“达到原来的2.5倍”；新增60吨是原来40吨的1.5倍，属于“增加了1.5倍”。两句话都描述同一变化，但倍率相差1。若问“增长了几倍”，应明确采用(现期−基期)/基期这一含义；若材料另行定义则按定义。不能只看到“倍”字就把现期与增量混在一起。","index":23,"domId":"ki-point-0020"}],"cards":[{"id":"ki-d-013","title":"量、率与倍数的区别","core":"数量差带原计量单位，增长率以基期为分母；达到倍数比增加倍数多1。","boundary":"阅读完整表述，不能只凭“增长”或“倍”字猜公式。","prompt":"从40吨到100吨，增加{{0}}吨，增长{{1}}%，达到原来的{{2}}倍，增加了{{3}}倍。","blanks":[{"answer":"60","accept":[]},{"answer":"150","accept":[]},{"answer":"2.5","accept":[]},{"answer":"1.5","accept":[]}]}],"questions":[{"id":"ki-dq-020","lesson":"growth","stem":"某产品产量由40吨增至100吨，增加量和增长率分别是多少？","options":["100吨、250%","60吨、250%","60吨、150%","60吨、60%"],"answer":2,"explanation":"增加量100−40=60吨；增长率60/40=150%，分母是原产量40吨。","optionReviews":["错误。100是现期量，250%是达到原规模的比例。","错误。250%对应现期/基期，而非净增长率。","正确。数量单位与相对变化均正确。","错误。把新增量除以现期100，得到的不是普通增长率。"]},{"id":"ki-dq-021","lesson":"growth","stem":"仍以40吨增至100吨为例，哪种倍数表述准确？","options":["达到原来的2.5倍，增加了1.5倍","达到原来的1.5倍，增加了1.5倍","达到原来的1.5倍，增加了2.5倍","达到原来的2.5倍，增加了2.5倍"],"answer":0,"explanation":"达到倍数为100/40=2.5，增加倍数为(100−40)/40=1.5。","optionReviews":["正确。两者相差原来的1倍。","错误。“达到”应包含原来的1倍。","错误。两种倍率被倒置。","错误。“增加了”应扣掉原来的1倍。"]}]},{"lessonId":"share","topicId":"share-analysis","courseRoute":"#course/data/topic/share-analysis","sections":[{"title":"百分点直接相减或加回","text":"两个百分率的绝对差称为百分点差。若本期某率为18%，较上期降低4.5个百分点，上期率就是18%+4.5%=22.5%；若本期18%是较上期提高4.5个百分点，上期则13.5%。加减的是以百分数表示的率，不是把18乘以1.045或除以1.045。先看提高还是降低，再反向还原。","index":9,"domId":"ki-point-0021"},{"title":"相对提高需要再除原率","text":"某率由12%到15%，提高3个百分点；若问相对原率增长多少，则(15%−12%)/12%=25%。两个指标的数值、单位都不同。反推时若题目说“比上期提高25%”，应按乘数关系15%/1.25=12%，不能减25个百分点。材料用语不清时不能自行把“百分比”与“百分点”替换，答题应把所用解释说明白。","index":10,"domId":"ki-point-0022"}],"cards":[{"id":"ki-d-014","title":"百分点的逆推","core":"本期率较上期提高x个百分点，则上期率减回x个百分点；降低则加回。","boundary":"百分点是率的绝对差，相对增幅还需除以上期率。","prompt":"本期18%、较上期降低4.5个百分点，上期为{{0}}%；12%升至15%是提高{{1}}个百分点、相对增长{{2}}%。","blanks":[{"answer":"22.5","accept":[]},{"answer":"3","accept":[]},{"answer":"25","accept":[]}]}],"questions":[{"id":"ki-dq-022","lesson":"share","stem":"本期某项比率18%，比上期降低4.5个百分点，上期比率为多少？","options":["18.81%","13.5%","17.2249%","22.5%"],"answer":3,"explanation":"“降低4.5个百分点”表示本期率=上期率−4.5%，故上期=18%+4.5%=22.5%。","optionReviews":["错误。18%乘1.045对应另一种相对变化。","错误。反推降低时应加回而非继续减。","错误。18%除1.045不是百分点逆推。","正确。按百分点绝对差加回。"]},{"id":"ki-dq-023","lesson":"share","stem":"某率由12%升至15%，百分点变化和相对增幅分别为多少？","options":["3个百分点、25%","25个百分点、25%","3个百分点、3%","25个百分点、3%"],"answer":0,"explanation":"率的直接差为3个百分点；相对变化为3%/12%=25%。","optionReviews":["正确。绝对率差与相对变化分开计算。","错误。百分点差只有15−12=3。","错误。第二问还要除以上期率12%。","错误。25是相对增幅的百分数数值，不是百分点差。"]}]},{"lessonId":"growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"增长率的分母始终回到基期","text":"以正基期定义的增长率r=(A−B)/B，其中A是现期、B是基期。若只给现期A和带符号变化量Δ，先由B=A−Δ还原，再得r=Δ/(A−Δ)。例如现期552万元、增加92万元，基期460万元，增长率92/460=20%。92/552表示新增占现期的比例，约16.67%，并不是题目所问的增长率。","index":24,"domId":"ki-point-0023"},{"title":"减少量与负增量要同步","text":"现期360万元、减少40万元，应写Δ=−40，基期360−(−40)=400，增长率−40/400=−10%。若题目问“下降幅度”，则给正值10%，但完整带符号增长率是−10%。当基期为0时普通增长率分母为0，无定义；不能以“增加额等于现期”就写成100%，也不能偷偷换成现期分母。","index":25,"domId":"ki-point-0024"}],"cards":[{"id":"ki-d-015","title":"现期加增量先恢复分母","core":"r=Δ/(A−Δ)，其中Δ有正负号，分母A−Δ才是基期。","boundary":"零基期不定义普通增长率；下降幅度的正值与增长率的负值不同。","prompt":"现期552、增加92，增长率为92÷{{0}}={{1}}%；现期360、减少40，带符号增长率为{{2}}%。","blanks":[{"answer":"460","accept":[]},{"answer":"20","accept":[]},{"answer":"-10","accept":["−10"]}]}],"questions":[{"id":"ki-dq-024","lesson":"growth","stem":"现期552万元，比基期增加92万元，增长率是多少？","options":["16.67%","20%","120%","83.33%"],"answer":1,"explanation":"基期552−92=460，增长率92/460=20%。","optionReviews":["错误。92/552是新增占现期比例。","正确。分母还原为基期。","错误。552/460=120%是达到比例，应再减1。","错误。460/552不是增长率。"]},{"id":"ki-dq-025","lesson":"growth","stem":"现期360万元，比基期减少40万元，带符号增长率是多少？","options":["10%","−11.11%","−12.5%","−10%"],"answer":3,"explanation":"Δ=−40，基期360−(−40)=400，r=−40/400=−10%。","optionReviews":["错误。这是下降幅度正值，不是题目要求的带符号增长率。","错误。把现期360当作分母。","错误。把减少的40误减出现期，得到错误基期320。","正确。下降量、符号与基期分母一致。"]}]},{"lessonId":"rate-amount-order","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"快比较率，多比较量","text":"“增长最快”通常比较增长率，“增加最多”比较带单位的增加量。甲基期80件、增长25%，增加20件；乙基期500件、增长8%，增加40件。甲增长更快，乙增加更多，两个排序并不矛盾。不同对象的原规模不同，百分数不能直接当件数看；即使把增速都算得很精确，问错对象仍会选错。","index":9,"domId":"ki-point-0025"},{"title":"下降排序先声明符号","text":"若甲减少18件、乙减少30件，乙的减少量更大；而带符号变化量分别−18、−30，甲的带符号变化量更大。下降幅度是相对基期的正比例，还可能产生第三种排序。题目没有说明比较的是带符号变化、减少的绝对件数还是降幅时，应先把比较对象写清，不在计算途中为了方便而自行去掉负号。","index":10,"domId":"ki-point-0026"}],"cards":[{"id":"ki-d-016","title":"率排序不替代量排序","core":"增长快慢看比例，增加多少看数量差；规模不同，两种排序可相反。","boundary":"下降时须区分带符号变化量与减少量的正值。","prompt":"甲基期80增25%、乙基期500增8%，增长更快的是{{0}}，增加更多的是{{1}}。","blanks":[{"answer":"甲","accept":[]},{"answer":"乙","accept":[]}]}],"questions":[{"id":"ki-dq-026","lesson":"rate-amount-order","stem":"甲基期80件、增25%，乙基期500件、增8%。哪项同时正确？","options":["乙增长率较高，甲增长量较大","甲增长率较高，乙增长量较大","乙增长率和增长量都较高","甲增长率和增长量都较高"],"answer":1,"explanation":"甲增20件、率25%；乙增40件、率8%。快慢比较25%与8%，多少比较20与40。","optionReviews":["错误。把两种比较都倒置。","正确。率与量排序相反。","错误。乙增量大但增速8%较低。","错误。甲虽率高，但20件少于40件。"]},{"id":"ki-dq-027","lesson":"rate-amount-order","stem":"甲减少18件、乙减少30件。关于减少量与带符号变化量，哪项正确？","options":["乙减少量更大，甲带符号变化量更大","甲减少量更大，乙带符号变化量更大","乙两种量都更大","甲两种量都更大"],"answer":0,"explanation":"减少量的正值30>18；带符号变化量−18>−30，因此两种问法要反向区分。","optionReviews":["正确。按各自定义比较。","错误。正值和负数排序均相反。","错误。乙的−30小于甲的−18。","错误。甲只在带符号变化量上较大。"]}]},{"lessonId":"rate-amount-order","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"同一排序可以换三种表达","text":"在基期B>0的同口径模型中，r=A/B−1=Δ/B。由于统一减去1不改变排序，比较增长率可以改比现期/基期，也可以比增量/基期。例如甲900/300=3，乙1040/400=2.6，甲增长率200%、乙160%，甲更快。数值大的倍率可让A/B更好算，但其分母仍是各自基期。","index":11,"domId":"ki-point-0027"},{"title":"择简不是按倍率划定适用范围","text":"若增长较小，算差可能更轻便：306相对300增加6，510相对500增加10，6/300=10/500=2%，两项相同；直接比306/300与510/500也同为1.02。倍率是否超过2只影响哪种算式更省力，并不决定公式成立与否。不能把“超过某倍率用比值”记成另一种定义，也不能因两个现期相差很大就认定增速不同。","index":12,"domId":"ki-point-0028"}],"cards":[{"id":"ki-d-017","title":"三种比法排序等价","core":"正基期下，比较r、A/B或Δ/B得到同一顺序。","boundary":"对象、期间和各自基期必须配对；不要把别人的基期借过来。","prompt":"甲现期900、基期300，A/B={{0}}，增长率为{{1}}%。","blanks":[{"answer":"3","accept":[]},{"answer":"200","accept":[]}]},{"id":"ki-d-018","title":"大倍率小倍率都成立","core":"A/B与Δ/B的选择只为算术方便，不依赖倍率是否达到2。","boundary":"阈值不是公式适用边界。","prompt":"306/300与510/500的增长率均为{{0}}%；是否小于2倍{{1}}改变三种比法的等价性。","blanks":[{"answer":"2","accept":[]},{"answer":"不","accept":[]}]}],"questions":[{"id":"ki-dq-028","lesson":"rate-amount-order","stem":"甲现期900、基期300；乙现期1040、基期400。哪项增长率更高，且可怎样比较？","options":["二者相等；两个现期都超过基期","甲；但现期/基期只在倍率小于2时才可用","甲；可比3与2.6，等价于比200%与160%","乙；只看1040大于900即可"],"answer":2,"explanation":"正基期下，A/B=1+r，统一减1不改排序。甲比值3大于乙2.6，所以甲增速更高。","optionReviews":["错误。只知道都增长不代表增速相等。","错误。倍率大于2时等价关系仍成立。","正确。比值和增长率给出同一顺序。","错误。现期更大不等于增长率更大。"]},{"id":"ki-dq-029","lesson":"rate-amount-order","stem":"甲由300增至306，乙由500增至510。下列判断哪项正确？","options":["甲增速较高，因为基期较小","两者增速相同，差/基期或现期/基期都可比较","两者倍率都小于2，所以现期/基期不再等价于比较增速","乙增速较高，因为增量10大于6"],"answer":1,"explanation":"甲6/300=2%，乙10/500=2%；两者现期/基期也同为1.02。择简法不改变定义。","optionReviews":["错误。较小基期不足以单独定增速。","正确。两套表达完全一致。","错误。不存在倍率2这一数学适用限制。","错误。增量还要除以各自基期。"]}]},{"lessonId":"growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"倒数形式来自精确增量式","text":"现期为A、增长率为r，带符号变化量Δ=Ar/(1+r)。若r=1/n>0，则基期n份、现期n+1份、增加1份，所以Δ=A/(n+1)。例如增长率精确为1/6、现期350，增量350/7=50。若r=−1/n且n>1，则基期n份、现期n−1份、减少1份；现期280、下降1/8，减少量280/7=40，而带符号Δ=−40。","index":26,"domId":"ki-point-0029"},{"title":"倒数是近似时，结果也只是近似","text":"16.7%与1/6约16.6667%并不精确相等。现期350、增长率精确为16.7%时，精确增量为350×0.167/1.167=58450/1167，约50.0857；用350/7得到50只是速算近似。需要核对选项间距和精度，不得将“接近一个常用分数”写成等号。下降量习惯报正值，但若设问明确要增长量或带符号变化，负号仍要保留。","index":27,"domId":"ki-point-0030"}],"cards":[{"id":"ki-d-019","title":"倒数率换份数","core":"r=1/n时增量A/(n+1)；r=−1/n时减少量正值A/(n−1)。","boundary":"下降式要求n>1；近似倒数不能变成精确等式。","prompt":"现期350、增长1/6，增量{{0}}；现期280、下降1/8，减少量{{1}}，带符号Δ为{{2}}。","blanks":[{"answer":"50","accept":[]},{"answer":"40","accept":[]},{"answer":"-40","accept":["−40"]}]},{"id":"ki-d-020","title":"分数近似要注明","core":"常用分数可以辅助估算，但替换了原增长率便引入误差。","boundary":"选项接近时回到Ar/(1+r)。","prompt":"16.7%与1/6的关系是{{0}}；据此用A/7求增量一般是{{1}}值。","blanks":[{"answer":"近似相等","accept":["约等于"]},{"answer":"近似","accept":[]}]}],"questions":[{"id":"ki-dq-030","lesson":"growth","stem":"甲现期350，增长率精确为1/6；乙现期280，下降率精确为1/8。甲增加量与乙减少量正值分别为多少？","options":["50、−40","58.3333、35","70、35","50、40"],"answer":3,"explanation":"甲增量350/(6+1)=50；乙减少量280/(8−1)=40，若问乙带符号变化量才是−40。","optionReviews":["错误。乙此处明确问减少量正值，应为40。","错误。直接用现期乘率，误用了基期。","错误。没有根据增长与下降正确换出现期份数。","正确。分别使用现期份数7与7。"]},{"id":"ki-dq-031","lesson":"growth","stem":"现期350，增长率精确为16.7%，要求按给定数计算增量。哪项正确？","options":["增量约50.0857，350/7=50只能近似","增量精确等于50，因为16.7%=1/6","增量应算350/6","增量精确等于58.45"],"answer":0,"explanation":"代原率得350×167/1167=58450/1167≈50.0857。16.7%只是接近1/6，不能当作同一精确数。","optionReviews":["正确。区分原始精确率与替代分数。","错误。16.7%不等于循环小数16.666…%。","错误。即使率为1/6，现期对应7份也不是6份。","错误。58.45是350×16.7%，使用了现期作基期。"]}]},{"lessonId":"compound-growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"年均增量按真实变化段数分摊","text":"年均增加量=(终值−初值)/实际期间数，单位是每年多少原单位。例如2021年末96万吨、2026年末156万吨，经历2021→2022直到2025→2026共5段，平均每年增加(156−96)/5=12万吨。虽然时间轴有6个年末标签，变化却只有5段。不能把年均增量写成12%，也不能凭标签个数作分母。","index":9,"domId":"ki-point-0031"},{"title":"规划首年可能包含第一段","text":"若规划期为2027—2031年，题意以2026年末180万件作为起点，以2031年末255万件作为终点，则包含2027、2028、2029、2030、2031五个年度变化，年均增加15万件。若只给2027年末到2031年末，才是4段。先画清起点、终点与首年基期，比套“末年减首年”的口令稳妥，尤其不要遗漏规划第一年。","index":10,"domId":"ki-point-0032"}],"cards":[{"id":"ki-d-021","title":"年份标签与增长段数","core":"年均增量用净变化除实际间隔数；起止年末直接相减确定段数。","boundary":"规划期若以前一年年末为基期，要计入首年那一段。","prompt":"2021年末至2026年末共有{{0}}段；2027—2031规划若从2026年末起算，共有{{1}}段。","blanks":[{"answer":"5","accept":[]},{"answer":"5","accept":[]}]}],"questions":[{"id":"ki-dq-032","lesson":"compound-growth","stem":"2021年末产量96万吨，2026年末156万吨。这段期间年均增加量为多少？","options":["12万吨/年","10万吨/年","60万吨/年","12%"],"answer":0,"explanation":"五个年度间隔的净增加量为60万吨，年均60/5=12万吨。","optionReviews":["正确。按5段而非6个年份标签计算。","错误。以6个年份标签作分母。","错误。60是全期间净增加量，未均摊。","错误。设问为数量差，不是复合年均增长率。"]},{"id":"ki-dq-033","lesson":"compound-growth","stem":"2027—2031规划以2026年末180万件为基期，2031年末达到255万件，年均增加量为多少？","options":["75万件/年","15万件/年","5万件/年","18.75万件/年"],"answer":1,"explanation":"规划五年包含2026→2027这一段，总净增75万件，除5得15万件/年。","optionReviews":["错误。75是五年合计净增。","正确。第一年年度变化计入五段。","错误。5是期间数，不是年均增加量。","错误。除4会漏掉2027首年的增长段。"]}]},{"lessonId":"rate-amount-order","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"正增长同向比较可不必全算","text":"基期、现期为正且r>0时，Δ=A·r/(1+r)。对固定r，A越大增量越大；对固定A，r/(1+r)也随r增大。因此甲现期360、增长20%，乙现期330、增长10%，甲在现期与率两方面都大，可先判断甲增量更大；精算分别60与30。这个捷径利用的是正乘数，不是对任意负增长都成立。","index":13,"domId":"ki-point-0033"},{"title":"一大一小或负增长时回到式子","text":"甲现期660、增长10%，增量60；乙现期420、增长25%，增量84。现期大的一方反而增加较少，因为两个因素反向变化，只能计算或给严格界。下降更须谨慎：现期990、率−10%，Δ=−110；现期160、率−20%，Δ=−40。第一项现期更大、率也更高，却带符号变化量更小，所以不能把正增长的两因素捷径原样移用到负率。","index":14,"domId":"ki-point-0034"}],"cards":[{"id":"ki-d-022","title":"同向捷径的正增长前提","core":"正增长下，增量Ar/(1+r)随现期A与率r分别增大；一大一小需另算。","boundary":"出现负率时A乘上负因子，现期单调方向发生变化。","prompt":"现期660增10%与现期420增25%的增量分别为{{0}}、{{1}}，较大者是{{2}}项。","blanks":[{"answer":"60","accept":[]},{"answer":"84","accept":[]},{"answer":"第二","accept":[]}]}],"questions":[{"id":"ki-dq-034","lesson":"rate-amount-order","stem":"甲现期360、增长20%，乙现期330、增长10%，均为正基期。哪项增量更大？","options":["甲，增量60大于30","二者相等，因为率差10个百分点","信息不足，因为不能使用任何单调比较","乙，因为乙基期一定更大"],"answer":0,"explanation":"甲的A与r都较大，正增长下可直接判甲增量大；代式计算为360×0.2/1.2=60，330×0.1/1.1=30。","optionReviews":["正确。捷径与精算一致。","错误。率差不能推出增量相等。","错误。在完整正增长条件下，两因素同向足够判断。","错误。乙基期300与甲相同，乙增量还更小。"]},{"id":"ki-dq-035","lesson":"rate-amount-order","stem":"甲现期660、增长10%；乙现期420、增长25%，谁增加更多？","options":["甲，66大于105","二者都增加60","甲，660大于420","乙，84大于60"],"answer":3,"explanation":"两因素反向必须比较Ar/(1+r)，甲60、乙84，因此乙更多。","optionReviews":["错误。66与105均误用现期乘率，且66也小于105。","错误。乙420×25%/1.25=84。","错误。仅按现期规模排序。","正确。按各自基期计算。"]},{"id":"ki-dq-036","lesson":"rate-amount-order","stem":"甲现期990、增长率−10%；乙现期160、增长率−20%。谁的带符号变化量较大？","options":["乙，−40大于−110","甲，因为甲现期和增长率都较大","甲，110大于40","二者相等，因为都下降"],"answer":0,"explanation":"甲Δ=990×(−0.1)/0.9=−110；乙Δ=160×(−0.2)/0.8=−40，比较带符号数得到乙较大。","optionReviews":["正确。负数排序与公式均正确。","错误。正增长捷径不能直接用于两项负率。","错误。将带符号变化量改成了下降量绝对值。","错误。方向相同不代表变化量相等。"]}]},{"lessonId":"estimation-boundary","topicId":"estimation","courseRoute":"#course/data/topic/estimation","sections":[{"title":"常用单位分数先区分精确与近似","text":"单位分数1/n换百分数应乘100。分母只有2与5的质因子时能写成有限小数，其余这里显示近似值。1/2=50%，1/3≈33.3333%，1/4=25%，1/5=20%；1/6≈16.6667%，1/7≈14.2857%，1/8=12.5%，1/9≈11.1111%。这些对应可帮助把比例转成份数，遇到循环小数要保留约号，不把记忆用显示值当精确数。","index":17,"domId":"ki-point-0035"},{"title":"十分之一至二十分之一","text":"继续记忆：1/10=10%，1/11≈9.0909%，1/12≈8.3333%，1/13≈7.6923%；1/14≈7.1429%，1/15≈6.6667%，1/16=6.25%，1/17≈5.8824%；1/18≈5.5556%，1/19≈5.2632%，1/20=5%。此处循环小数均显示到百分数小数点后4位，有限小数可补零成同样格式。每个近似值都能由100÷分母复算，不靠孤立口诀。","index":18,"domId":"ki-point-0036"},{"title":"记忆表服务于计算精度","text":"若将1/3近似成33.3%，误差是33.333…%−33.3%=0.03333…个百分点，而不是0.03333%的相对误差；相对原比例的误差还要再除1/3，为0.1%。当两个候选只相隔0.01个百分点时，33.3%的表值不够分辨，须用原分数或更多位。用熟悉分数替换百分数时，也要检查原题给的是精确率还是舍入率，不能倒过来把16.7%硬说成1/6。","index":19,"domId":"ki-point-0037"}],"cards":[{"id":"ki-d-023","title":"单位分数速记一","core":"1/2至1/5依次为50%、约33.3333%、25%、20%。","boundary":"1/3是循环小数，表中显示值不精确。","prompt":"依次填1/2、1/3、1/4、1/5的百分数数值，保留4位小数且省略%：{{0}}、{{1}}、{{2}}、{{3}}。","blanks":[{"answer":"50.0000","accept":["50"]},{"answer":"33.3333","accept":[]},{"answer":"25.0000","accept":["25"]},{"answer":"20.0000","accept":["20"]}]},{"id":"ki-d-024","title":"单位分数速记二","core":"1/6至1/9依次约16.6667%、14.2857%、12.5%、11.1111%。","boundary":"其中1/8可精确写成有限小数，其余均为近似显示。","prompt":"依次填1/6、1/7、1/8、1/9的百分数数值，保留4位小数且省略%：{{0}}、{{1}}、{{2}}、{{3}}。","blanks":[{"answer":"16.6667","accept":[]},{"answer":"14.2857","accept":[]},{"answer":"12.5000","accept":["12.5"]},{"answer":"11.1111","accept":[]}]},{"id":"ki-d-025","title":"单位分数速记三","core":"1/10至1/13依次为10%、约9.0909%、约8.3333%、约7.6923%。","boundary":"循环小数参与高精度计算时仍应保留分数。","prompt":"依次填1/10、1/11、1/12、1/13的百分数数值，保留4位小数且省略%：{{0}}、{{1}}、{{2}}、{{3}}。","blanks":[{"answer":"10.0000","accept":["10"]},{"answer":"9.0909","accept":[]},{"answer":"8.3333","accept":[]},{"answer":"7.6923","accept":[]}]},{"id":"ki-d-026","title":"单位分数速记四","core":"1/14至1/17依次约7.1429%、6.6667%、6.25%、5.8824%。","boundary":"1/16=6.25%精确，另外三项为近似显示。","prompt":"依次填1/14、1/15、1/16、1/17的百分数数值，保留4位小数且省略%：{{0}}、{{1}}、{{2}}、{{3}}。","blanks":[{"answer":"7.1429","accept":[]},{"answer":"6.6667","accept":[]},{"answer":"6.2500","accept":["6.25"]},{"answer":"5.8824","accept":[]}]},{"id":"ki-d-027","title":"单位分数速记五","core":"1/18至1/20依次约5.5556%、5.2632%、5%。","boundary":"用表值仍要检查候选间距，不因记熟而忽略约号。","prompt":"依次填1/18、1/19、1/20的百分数数值，保留4位小数且省略%：{{0}}、{{1}}、{{2}}。","blanks":[{"answer":"5.5556","accept":[]},{"answer":"5.2632","accept":[]},{"answer":"5.0000","accept":["5"]}]}],"questions":[{"id":"ki-dq-037","lesson":"estimation-boundary","stem":"将1/2、1/3、1/4、1/5依次化成百分数，统一保留4位小数，哪组正确？","options":["20.0000%、33.3333%、40.0000%、50.0000%","50.0000%、33.3333%、25.0000%、20.0000%","50.0000%、30.0000%、25.0000%、20.0000%","50.0000%、33.3333%、20.0000%、25.0000%"],"answer":1,"explanation":"分别算100÷2、100÷3、100÷4、100÷5，第三个分数1/4是25%，不是20%。","optionReviews":["错误。多项混淆了分母与百分数。","正确。四项按分母顺序对应。","错误。1/3约33.3333%，并非30%。","错误。1/4与1/5的结果交换了。"]},{"id":"ki-dq-038","lesson":"estimation-boundary","stem":"1/6、1/7、1/8、1/9化成百分数，统一保留4位小数，哪组正确？","options":["16.6667%、14.0000%、12.5000%、9.0000%","16.6667%、14.2857%、12.5000%、11.1111%","6.0000%、7.0000%、8.0000%、9.0000%","16.6667%、14.2857%、8.0000%、11.1111%"],"answer":1,"explanation":"按100/n核算，1/8=12.5%精确，其余在指定小数位上四舍五入。","optionReviews":["错误。1/7与1/9被当作分母数字或粗错误值。","正确。四个分数与百分数逐项相符。","错误。把分母直接加百分号，并非分数换算。","错误。1/8不是8%。"]},{"id":"ki-dq-039","lesson":"estimation-boundary","stem":"1/10、1/11、1/12、1/13化成百分数，统一保留4位小数，哪组正确？","options":["10.0000%、9.0909%、7.6923%、8.3333%","10.0000%、9.0909%、8.3333%、7.6923%","10.0000%、11.0000%、12.0000%、13.0000%","1.0000%、0.9091%、0.8333%、0.7692%"],"answer":1,"explanation":"换百分数需乘100，分母越大相应单位分数越小。","optionReviews":["错误。1/12与1/13的对应值交换。","正确。逐项为100除相应分母。","错误。1/11、1/12、1/13的换算直接用了分母数字。","错误。整体少了10倍。"]},{"id":"ki-dq-040","lesson":"estimation-boundary","stem":"1/14、1/15、1/16、1/17化成百分数，统一保留4位小数，哪组正确？","options":["7.1429%、6.6667%、6.2500%、5.8824%","14.0000%、15.0000%、16.0000%、17.0000%","7.1429%、6.2500%、6.6667%、5.8824%","7.1429%、6.6667%、6.2500%、5.0000%"],"answer":0,"explanation":"100÷14约7.1429，100÷15约6.6667，100÷16=6.25，100÷17约5.8824。","optionReviews":["正确。四项顺序与精度均符合要求。","错误。把分母写成百分数。","错误。1/15和1/16的值交换。","错误。1/17不等于1/20对应的5%。"]},{"id":"ki-dq-041","lesson":"estimation-boundary","stem":"1/18、1/19、1/20化成百分数，统一保留4位小数，哪组正确？","options":["5.5556%、5.2632%、5.0000%","0.5556%、0.5263%、0.5000%","18.0000%、19.0000%、20.0000%","5.5556%、5.0000%、5.2632%"],"answer":0,"explanation":"分别求100/18、100/19、100/20并四舍五入；1/20=5%可精确写出。","optionReviews":["正确。三项逐项相符。","错误。整体少了10倍。","错误。使用分母代替了分数。","错误。1/19与1/20的值交换。"]},{"id":"ki-dq-042","lesson":"estimation-boundary","stem":"把精确比例1/3近似为33.3%，两者相差多少个百分点？","options":["约3.3333个百分点","0个百分点，因为二者精确相等","约0.03333个百分点","约0.33333个百分点"],"answer":2,"explanation":"1/3的百分数是33.333…%，减33.3%得0.03333…个百分点。小数显示值不等于原循环小数。","optionReviews":["错误。误差放大了100倍。","错误。33.3%只是有限位近似。","正确。直接比较两个百分数的数值差。","错误。误差放大了10倍。"]}]},{"lessonId":"share","topicId":"share-analysis","courseRoute":"#course/data/topic/share-analysis","sections":[{"title":"由部分、总体写出三个互逆关系","text":"同一时点、同一统计口径下，设部分量A、总体量B>0，比重p=A/B。知道B与p，用A=Bp；知道A与非零p，用B=A/p。例如72件线上事项属于240件全部事项，线上比重30%；若某类54件占全部18%，全部为54/0.18=300件；若全部460件中35%属某类，该类为161件。每一步都先确认分子确实包含在所用总体内。","index":11,"domId":"ki-point-0038"},{"title":"零比重不能用来唯一反推规模","text":"普通非负构成中应有0≤A≤B，所以p在0到1之间；但这个范围只是必要自查，不能代替对象核对。A=0、p=0时，任何正总体都可能，没有唯一的A/p；A>0却说p=0则条件彼此冲突。若A与B分别用万件和件，须统一单位再相除，不能看到结果落在0到100%之间就认定口径正确。","index":12,"domId":"ki-point-0039"}],"cards":[{"id":"ki-d-028","title":"部分总体互求","core":"p=A/B，A=Bp，B=A/p；比重的分母是包含该部分的总体。","boundary":"总体为正；反推总体需要非零比重。","prompt":"72占240的比重为{{0}}%；54占18%时总体为{{1}}；460的35%为{{2}}。","blanks":[{"answer":"30","accept":[]},{"answer":"300","accept":[]},{"answer":"161","accept":[]}]}],"questions":[{"id":"ki-dq-043","lesson":"share","stem":"同口径下，72占240的比重、54占总体18%时的总体、总体460的35%部分量，依次为何？","options":["30%、9.72、161","30%、300、131.43","30%、300、161","3%、300、16.1"],"answer":2,"explanation":"按A/B、A/p、Bp分别得到0.3、300、161。","optionReviews":["错误。反推总体应用54/0.18，而非相乘。","错误。已知总体和比重求部分应相乘。","正确。三个方向公式和百分数换算均正确。","错误。两处均漏了数量级。"]},{"id":"ki-dq-044","lesson":"share","stem":"某类数量A=0，其占正总体B的比重p=0。仅凭这些条件能否唯一确定B？","options":["不能；任意正B都与零部分相容","能，B必为100","能，直接算0/0得到1","能，B必为0"],"answer":0,"explanation":"当A=0时，0/B=0对任何正B成立；反推式A/p此时成为0/0，无定义。","optionReviews":["正确。缺少决定总体规模的信息。","错误。百分比的100基准不等于实际总体。","错误。0/0没有定义，不能约成1。","错误。题设总体为正，而且零部分不要求零总体。"]}]},{"lessonId":"profit-discount","topicId":"profit","courseRoute":"#course/quant/topic/profit","sections":[{"title":"先读指标定义，不替材料选分母","text":"“利润率”不是只有一个固定分母。统计材料中营业收入利润率常以利润总额/营业收入计，经营计算中的成本利润率则以相应利润/成本计；具体题目若另有定义，就按它的完整定义计算。例如明确给出收入720万元、成本600万元、利润120万元，并定义收入利润率为利润/收入、成本利润率为利润/成本，则分别为120/720=16又2/3%、120/600=20%。相同利润换了比较基础，两个率便不同。","index":9,"domId":"ki-point-0040"},{"title":"分母不同，分子也可能不同","text":"净资产收益率、总资产报酬率等指标还可能要求净利润、利润加利息等不同分子，不能只换分母而默认所有“利润”都一样。若题设净资产收益率=净利润/平均净资产，净利润90万元、平均净资产600万元，即15%；即使另有营业收入750万元，也不应改用750作分母。先完整抄出“哪种利润÷哪种基础”，再取数。只有一个含糊的“利润率”标签且无定义时，不应凭题目属于资料分析就一律选择收入或成本。","index":10,"domId":"ki-point-0041"}],"cards":[{"id":"ki-d-029","title":"利润指标先固定比较基础","core":"收入利润率与成本利润率的分母不同；采用题干或统计定义，不凭题型猜。","boundary":"不同利润指标的分子也须匹配，净利润不能无条件替换利润总额。","prompt":"按利润120、收入720、成本600计算，收入利润率为{{0}}%，成本利润率为{{1}}%。第一空可用分数表示。","blanks":[{"answer":"50/3","accept":["16又2/3","16⅔"]},{"answer":"20","accept":[]}]},{"id":"ki-d-030","title":"净资产收益率按题设配数","core":"若定义为净利润/平均净资产，就用净利润与平均净资产两项。","boundary":"未给明确利润率定义时，不能断言所有场景都以营业收入为分母。","prompt":"净利润90、平均净资产600，按上述定义净资产收益率为{{0}}%。","blanks":[{"answer":"15","accept":[]}]}],"questions":[{"id":"ki-dq-045","lesson":"profit-discount","stem":"题设明确：收入利润率=利润/营业收入，成本利润率=利润/成本。营业收入720万元、成本600万元、利润120万元，两率分别为多少？","options":["20%、16又2/3%","20%、20%","16又2/3%、16又2/3%","16又2/3%、20%"],"answer":3,"explanation":"同一利润120分别除营业收入720和成本600，得到1/6与1/5。","optionReviews":["错误。交换了收入基础与成本基础。","错误。收入利润率也误用了成本分母。","错误。成本利润率也误用了收入分母。","正确。两个分母按各自定义取数。"]},{"id":"ki-dq-046","lesson":"profit-discount","stem":"题设净资产收益率=净利润/平均净资产。净利润90万元、平均净资产600万元、营业收入750万元。该收益率为多少？","options":["15%","125%","12%","80%"],"answer":0,"explanation":"只用定义指定的两项：90/600=15%。营业收入不是本指标分母。","optionReviews":["正确。分子和分母均匹配题设定义。","错误。750/600没有使用净利润。","错误。90/750是另一种收入基础比率。","错误。600/750既非所需分子也非所需分母关系。"]},{"id":"ki-dq-047","lesson":"profit-discount","stem":"一道题只写“利润率”，既无公式、无统计口径说明，也无上下文约定。关于分母，哪项判断严谨？","options":["所有利润率一律除成本","资料分析的利润率一律除营业收入","需补足指标定义，不能唯一断定分母","所有利润率一律除总资产"],"answer":2,"explanation":"收入、成本、资产等均可能是不同利润指标的比较基础。定义不足时，不能由题型名称推出唯一分母。","optionReviews":["错误。成本基础只覆盖某一类指标。","错误。常见统计写法不能扩张为所有指标的规则。","正确。要先明确所求的具体指标。","错误。资产基础也不是所有利润率的共同分母。"]}]},{"lessonId":"share","topicId":"share-analysis","courseRoute":"#course/data/topic/share-analysis","sections":[{"title":"还原两个数量，再还原它们的比","text":"设现期部分A、总体B的增速分别为a、b。先得基期部分A/(1+a)、总体B/(1+b)，相除后基期比重p₀=(A/B)×(1+b)/(1+a)。例如现期部分144、总体600，比重24%；部分增20%、总体增25%，基期比重24%×1.25/1.20=25%。分母上的1+a来自部分的还原，分子上的1+b来自总体的还原，不能靠位置记忆而把两率互换。","index":13,"domId":"ki-point-0042"},{"title":"下降与方向可交叉检查","text":"只要对应基期为正、增长因子可除，下降也用同一关系。若现期比重20%，部分下降20%、总体下降10%，基期比重20%×0.9/0.8=22.5%。部分降得更快，比重确应由22.5%降到20%，方向与结果相符。若把因子颠倒会得到约17.78%，反而与方向冲突。零部分基期无法定义普通部分增速，此时应直接用两期数量求比重，不能硬套一个不存在的a。","index":14,"domId":"ki-point-0043"}],"cards":[{"id":"ki-d-031","title":"基期比重由现期反推","core":"p₀=p₁(1+b)/(1+a)，a属部分、b属总体。","boundary":"对应增长率须有定义；正基期与可除的增长因子不可省略。","prompt":"现期比重24%、部分增20%、总体增25%，基期比重为{{0}}%；公式中分母增长因子为{{1}}。","blanks":[{"answer":"25","accept":[]},{"answer":"1.2","accept":[]}]}],"questions":[{"id":"ki-dq-048","lesson":"share","stem":"现期部分144、总体600，部分同比增20%、总体同比增25%，基期比重为多少？","options":["20%","25%","23.04%","24%"],"answer":1,"explanation":"p₀=(144/600)×1.25/1.2=25%。部分增得慢于总体，因此现期比重低于基期，符合方向。","optionReviews":["错误。只还原部分而没有还原总体。","正确。按部分和总体分别还原。","错误。把1.2与1.25上下颠倒。","错误。忽略了两个量不同的增速。"]},{"id":"ki-dq-049","lesson":"share","stem":"现期比重20%，对应正基期下，部分下降20%、总体下降10%。基期比重为多少？","options":["17.7778%","22.5%","20%","10%"],"answer":1,"explanation":"将a=−20%、b=−10%代入，p₀=20%×0.9/0.8=22.5%。","optionReviews":["错误。将分子分母的增长因子互换。","正确。下降也以1加带符号增长率计算。","错误。只有增速相同等条件才保持比重不变。","错误。把两项降幅差直接当成比重差。"]}]},{"lessonId":"share","topicId":"share-analysis","courseRoute":"#course/data/topic/share-analysis","sections":[{"title":"同样有两个时期，设问对象可能不同","text":"看到去年、今年和百分数还不能立即认定是比重题。要有某部分属于总体的关系，并确认所问比例以哪一量为分母。虚构事项表中，去年总量800、线上200，今年总量1000、线上300。若问线上件数同比增长率，应算(300−200)/200=50%，这是线上量自身的增长；若问线上占全部多少，才用线上量除各期总量。","index":15,"domId":"ki-point-0044"},{"title":"一期水平、方向、百分点是三层问题","text":"在上述表中，去年线上比重200/800=25%，今年300/1000=30%。问“今年占多少”答30%；问“是否提高”答提高；问“提高几个百分点”答30%−25%=5个百分点；问“比重相对去年增长多少”则5%/25%=20%。先把设问改写成这几类之一，再选择计算，避免把线上量增长50%当作比重提高50个百分点。","index":16,"domId":"ki-point-0045"}],"cards":[{"id":"ki-d-032","title":"识别两期比重设问","core":"先确认部分/总体关系，再区分某期比重、方向、百分点差与比重相对增幅。","boundary":"出现两个年份和百分号并不足以认定为比重题。","prompt":"线上200/总800变为线上300/总1000，今年比重{{0}}%，提高{{1}}个百分点，比重相对增长{{2}}%。","blanks":[{"answer":"30","accept":[]},{"answer":"5","accept":[]},{"answer":"20","accept":[]}]}],"questions":[{"id":"ki-dq-050","lesson":"share","stem":"去年总事项800件、线上200件，今年总事项1000件、线上300件。问“线上件数同比增长百分之几”，应求什么？","options":["今年线上比重，分母用1000","线上量的增长率，分母用200","总体的增长率，分母用800","比重的百分点差，直接用300−200"],"answer":1,"explanation":"所问对象是线上件数自身，两期线上量300与200比较，增长50%；总事项数据在这项设问中不作分母。","optionReviews":["错误。300/1000回答今年占比，不是线上量同比。","正确。以同一部分的基期数量为比较基础。","错误。这会回答全部事项的增长，而非线上量。","错误。数量差100件不是比重差。"]},{"id":"ki-dq-051","lesson":"share","stem":"同一表：去年线上200/总800，今年线上300/总1000。今年线上比重、比重的百分点变化、比重相对增幅依次为多少？","options":["25%、提高5个百分点、增长20%","30%、提高5个百分点、增长5%","30%、提高50个百分点、增长50%","30%、提高5个百分点、增长20%"],"answer":3,"explanation":"两期占比25%与30%。直接差5个百分点；相对基期占比增长5%/25%=20%。","optionReviews":["错误。25%是去年占比，不是今年。","错误。相对增幅仍需除去年占比25%。","错误。50%是线上量增长率，不是两期占比变化。","正确。三种问法分别计算。"]}]},{"lessonId":"share","topicId":"share-analysis","courseRoute":"#course/data/topic/share-analysis","sections":[{"title":"部分跑赢总体，比重才会上升","text":"对应基期部分与总体均正，且现期总体正时，现期比重/基期比重=(1+a)/(1+b)。因此a>b比重升，a=b不变，a<b比重降。这里比的是带符号的增长率：部分下降5%、总体下降15%，−5%大于−15%，部分虽然减少，比重仍升。例如原部分80、总体200，现期76与170，比例从40%升至约44.71%。","index":17,"domId":"ki-point-0046"},{"title":"方向能判不等于幅度已知","text":"只给部分与总体增长率，通常可以判断方向，不能凭a−b直接写百分点变化，还需要某一期比重等信息。若基期部分为0、现期部分15，总体由100到150，比例可直接算成0%到10%；但部分增长率15/0无定义，无法用a与b比较。正基期条件是增速推导的入口，不是说零部分时所有比重都不能计算。","index":18,"domId":"ki-point-0047"}],"cards":[{"id":"ki-d-033","title":"用带符号增速判比重方向","core":"在相应正基期和正现期总体条件下，部分增速大于总体增速则比重升。","boundary":"零部分基期时a无定义，需直接算比重；a−b不等于百分点差。","prompt":"部分下降5%、总体下降15%，因为−5%{{0}}−15%，所以比重{{1}}。","blanks":[{"answer":"大于","accept":[">"]},{"answer":"上升","accept":["提高","升高"]}]}],"questions":[{"id":"ki-dq-052","lesson":"share","stem":"对应正基期下，部分下降5%、总体下降15%，比重如何变化？","options":["上升","仅凭两率连方向也无法判断","下降","不变"],"answer":0,"explanation":"−5%>−15%，比例乘数0.95/0.85>1，所以比重上升。两个量都下降不等于比重下降。","optionReviews":["正确。部分收缩慢于总体。","错误。条件充分时可判方向，只是不能定具体百分点。","错误。把部分数量下降误当作占比下降。","错误。只有两率相同等条件才不变。"]},{"id":"ki-dq-053","lesson":"share","stem":"基期部分0、总体100；现期部分15、总体150。哪种判断正确？","options":["比重提高15个百分点，部分增长率为15%","比重从0%升至10%，但部分普通增长率无定义","基期部分为0，所以两个比重都无法求","部分增长100%，比重不变"],"answer":1,"explanation":"两期总体均正，直接求比重为0/100=0与15/150=10%；但部分基期0使其增长率分母为0。","optionReviews":["错误。15是现期部分数量，不是所需百分点或增长率。","正确。区分比重可算与部分增速无定义。","错误。比重分母是总体，不是部分。","错误。零基期不能定义为增长100%，且比重已变。"]}]},{"lessonId":"share","topicId":"share-analysis","courseRoute":"#course/data/topic/share-analysis","sections":[{"title":"现期作差式来自还原关系","text":"设现期比重p₁=A/B，基期p₀=p₁(1+b)/(1+a)，两者相减得p₁−p₀=p₁(a−b)/(1+a)。例如现期部分198、总体550，比重36%；部分增20%、总体增10%，变化为36%×10%/1.2=3个百分点。直接还原得到基期部分165、总体500、比重33%，作差也为3个百分点；不是两项增速差10个百分点。","index":19,"domId":"ki-point-0048"},{"title":"先看结果是什么量，再写单位","text":"公式得到的是比例小数差，乘100后才是百分点数值。若现期比重30%、部分下降10%、总体下降4%，差为0.30×(−0.10+0.04)/0.90=−0.02，即下降2个百分点。比重相对增长率另为(a−b)/(1+b)，在此例为−6.25%，不能把它写成下降6.25个百分点。增速差、比重差与比重相对变化是三个不同量。","index":20,"domId":"ki-point-0049"}],"cards":[{"id":"ki-d-034","title":"两期比重差的分母","core":"p₁−p₀=p₁(a−b)/(1+a)，分母为部分增长因子。","boundary":"结果的比例小数乘100表示百分点；不能直接用a−b。","prompt":"现期比重36%、部分增20%、总体增10%，比重提高{{0}}个百分点；公式分母为{{1}}。","blanks":[{"answer":"3","accept":[]},{"answer":"1.2","accept":[]}]}],"questions":[{"id":"ki-dq-054","lesson":"share","stem":"现期部分198、总体550，部分增20%、总体增10%，比重比基期提高多少个百分点？","options":["3.6","10","3","9.0909"],"answer":2,"explanation":"现期比重0.36，差0.36×(0.20−0.10)/1.20=0.03，对应3个百分点。","optionReviews":["错误。漏除了部分增长因子1.2。","错误。10是两个数量增速之差，不是比重差。","正确。也可还原165/500=33%，36%−33%=3个百分点。","错误。约9.09%是比重相对增幅，不是百分点。"]},{"id":"ki-dq-055","lesson":"share","stem":"现期比重30%，部分下降10%、总体下降4%，对应正基期。两期比重变化为多少？","options":["下降2个百分点","下降6.25个百分点","提高2个百分点","下降6个百分点"],"answer":0,"explanation":"代入0.30×(−0.10−(−0.04))/(1−0.10)=−0.02，基期比重32%，现期30%。","optionReviews":["正确。比重差−0.02对应下降2个百分点。","错误。−6.25%是比重相对变化，单位不能改成百分点。","错误。部分降得快于总体，比重应下降。","错误。−6个百分点是两项增速直接作差。"]}]},{"lessonId":"average","topicId":"average-analysis","courseRoute":"#course/data/topic/average-analysis","sections":[{"title":"平均数的分母就是份数","text":"平均数=总量/总份数，写全“平均每什么有多少”才能选对分母与单位。甲批12项任务、每项平均耗时18分钟，乙批28项、每项8分钟，合并总耗时12×18+28×8=440分钟，任务40项，均值11分钟/项。18与8不能直接平均成13，因为每个批次不是相同份数，28项的低均值批次权重更大。","index":12,"domId":"ki-point-0050"},{"title":"直接平均的成立条件不要写过头","text":"两组份数相同时，加权均值等于两组均值的算术平均；两组均值本来相同时，即使份数不同，合并后也保持共同均值。例如6人平均每人4件、9人也平均每人4件，合并仍为4件/人。人数、人次、件数不是同一种份数，平均每人的分母不能换成访问人次。份数必须为正且口径可加，否则先澄清总量与份数含义。","index":13,"domId":"ki-point-0051"}],"cards":[{"id":"ki-d-035","title":"平均数与加权份数","core":"合并均值先恢复各组总量，再除合并份数，权重由各组份数决定。","boundary":"份数相等是可直接平均的充分条件；均值相等也是例外，不能说不等份数必不相等。","prompt":"12项每项18分钟与28项每项8分钟，合并总耗时{{0}}分钟，均值{{1}}分钟/项。","blanks":[{"answer":"440","accept":[]},{"answer":"11","accept":[]}]}],"questions":[{"id":"ki-dq-056","lesson":"average","stem":"甲12项任务平均18分钟/项，乙28项平均8分钟/项，合并均值为多少？","options":["26分钟/项","440分钟/项","13分钟/项","11分钟/项"],"answer":3,"explanation":"总耗时216+224=440分钟，任务总数40，平均11分钟/项。","optionReviews":["错误。将两个均值相加。","错误。440是总耗时，尚未除40项。","错误。直接平均18与8，忽略不同任务数。","正确。按任务数加权且单位完整。"]},{"id":"ki-dq-057","lesson":"average","stem":"甲组6人平均4件/人，乙组9人平均4件/人，统计口径一致，合并均值是多少？","options":["8件/人，两个均值相加","4件/人，但仅因为6与9份数相等","不能确定，因为人数不相等","4件/人，均值相同使结果与权重无关"],"answer":3,"explanation":"总量6×4+9×4=60件，总人数15，均值4。均值相同即使份数不同也可确定共同值。","optionReviews":["错误。均值不能相加当作合并均值。","错误。结论虽为4，但6与9并不相等，给出的理由错误。","错误。份数已知，而且相同均值本就不受权重影响。","正确。共同均值乘总份数后再相除仍是共同值。"]}]},{"lessonId":"average","topicId":"average-analysis","courseRoute":"#course/data/topic/average-analysis","sections":[{"title":"现期均值要让分子分母处于同一时期","text":"现期平均数等于现期总量A除现期份数B，要求份数B>0、分子分母口径匹配。虚构景点本季度消费总额840万元，接待21000人次、涉及15000名不同游客。平均每接待人次消费=8400000/21000=400元/人次；若问每名不同游客的季度消费，则用15000人作分母，得560元/人。两个答案都能有意义，但回答不同的设问，不能相互替换。","index":14,"domId":"ki-point-0052"},{"title":"总量、份数、单位三项一起检查","text":"先判断分子计量什么，再判断“每什么”给了哪一种份数，最后完成单位换算。例如全年服务费200万元、全年8000服务人次，全年每服务人次费用为2000000/8000=250元/人次；即使表内另有12月500人次，也不能拿单月份数去除全年总费。人数与人次、户与件、全年与年末等口径有时会按特定统计定义搭配，题目若明确了定义应遵从，不能自行混成同一指标。","index":15,"domId":"ki-point-0053"}],"cards":[{"id":"ki-d-036","title":"同一期的总量除同一期份数","core":"现期均值A/B，分子分母各自的时期、对象与单位须匹配。","boundary":"人次不等于不同人数；每人次和每人的均值可不同。","prompt":"840万元对应21000人次与15000名游客，每人次{{0}}元，每名游客{{1}}元。","blanks":[{"answer":"400","accept":[]},{"answer":"560","accept":[]}]}],"questions":[{"id":"ki-dq-058","lesson":"average","stem":"本季度消费840万元，接待21000人次、涉及15000名不同游客。平均每人次与平均每名游客的消费分别是多少？","options":["560元/人次、400元/人","0.04元/人次、0.056元/人","400元/人次、400元/人","400元/人次、560元/人"],"answer":3,"explanation":"840万元换成8400000元；分别除21000人次与15000人得400和560，分母不能交换。","optionReviews":["错误。将人次与人数的分母交换。","错误。遗漏万元到元的10000倍换算。","错误。平均每名游客应使用15000，不能继续用人次。","正确。单位换算和两个份数均匹配。"]},{"id":"ki-dq-059","lesson":"average","stem":"全年服务费200万元、全年服务8000人次，另知12月服务500人次。求全年每服务人次费用，应为多少？","options":["0.025元/人次","4000元/人次","16元/人次","250元/人次"],"answer":3,"explanation":"全年总费2000000元对应全年8000人次，均值250元/人次；12月人数不匹配全年总费。","optionReviews":["错误。没有把万元换成元。","错误。用全年费用除12月500人次，期间错配。","错误。8000/500=16是两个人次数的比值，不是费用均值。","正确。使用同一全年的总量与份数。"]}]},{"lessonId":"average","topicId":"average-analysis","courseRoute":"#course/data/topic/average-analysis","sections":[{"title":"基期平均数要同时还原总量与份数","text":"设现期总量A、份数B的增长率分别a、b。基期均值=[A/(1+a)]/[B/(1+b)]=(A/B)×(1+b)/(1+a)。例如现期总消费806400元、服务1680人次，总消费增20%、人次增5%，现期均值480元/人次；基期均值480×1.05/1.2=420元/人次。分别还原得672000元与1600人次，再相除也为420。","index":16,"domId":"ki-point-0054"},{"title":"用增速归属和方向避免颠倒","text":"a始终属于总量，b始终属于份数，不是按题目出现次序随意命名。现期均值630、总量下降10%、份数下降20%时，基期均值630×0.8/0.9=560。份数下降更快，均值从560升到630，方向可以作为复核。前提是两期指标定义相同且增长因子可除，不能将本期平均数直接减总量增速或把两个增速先相减当作均值。","index":17,"domId":"ki-point-0055"}],"cards":[{"id":"ki-d-037","title":"基期平均数的还原因子","core":"基期均值=现期均值×份数增长因子/总量增长因子。","boundary":"先明确a属于总量、b属于份数；对应基期与增长率必须有效。","prompt":"现期均值480、总量增20%、份数增5%，基期均值为{{0}}；分母因子是{{1}}。","blanks":[{"answer":"420","accept":[]},{"answer":"1.2","accept":[]}]}],"questions":[{"id":"ki-dq-060","lesson":"average","stem":"现期消费806400元、服务1680人次，消费总量增20%、服务人次增5%，基期每人次均值是多少？","options":["420元/人次","480元/人次","548.5714元/人次","400元/人次"],"answer":0,"explanation":"现期均值480，基期480×1.05/1.2=420；等价于672000/1600。","optionReviews":["正确。总量与份数都还原。","错误。480是现期均值。","错误。把1.2与1.05颠倒。","错误。只还原总量，未还原份数。"]},{"id":"ki-dq-061","lesson":"average","stem":"现期每份均值630，总量下降10%、份数下降20%，对应正基期。基期均值为多少？","options":["630","708.75","700","560"],"answer":3,"explanation":"基期均值630×(1−20%)/(1−10%)=560，现期份数下降更快使均值上升。","optionReviews":["错误。忽略总量与份数降速不同。","错误。将0.9/0.8倒用为反推因子。","错误。只还原总量，没有还原份数。","正确。增长因子按所属量放置。"]}]},{"lessonId":"average","topicId":"average-analysis","courseRoute":"#course/data/topic/average-analysis","sections":[{"title":"平均水平、均值差与均值增幅是三问","text":"平均、每人、每户、每件等表述，提示先查“总量/份数”关系；再看设问究竟求某期均值、两期均值的数量差，还是相对变化。某产品每件收入由36元升至45元，现期水平45元/件，增加9元/件，增长25%。这三个答案分别来自现期比值、两期均值作差、差额除基期均值，不能只因都含“每件”就用同一结果作答。","index":18,"domId":"ki-point-0056"},{"title":"单位帮助识别，但不能只抓每字","text":"例如总产量增长21%、设备数增长10%、现期单台产量55吨，问“单台产量增长百分之几”，应求均值增长率1.21/1.10−1=10%，不是现期55吨，也不是增加5吨。反推基期单台50吨，增加5吨，三者吻合。“每逢”“每当”等语句未必描述统计均值；只有确实建立了总量和相应份数关系，才进入平均数模型。","index":19,"domId":"ki-point-0057"}],"cards":[{"id":"ki-d-038","title":"均值题先判所求量","core":"均值水平带每份数量单位；绝对增量仍带同单位；增长率用相对基期比例。","boundary":"每字只是阅读线索，不是平均数题的充分条件。","prompt":"每件由36元到45元，现期水平{{0}}元/件，增加{{1}}元/件，增长{{2}}%。","blanks":[{"answer":"45","accept":[]},{"answer":"9","accept":[]},{"answer":"25","accept":[]}]}],"questions":[{"id":"ki-dq-062","lesson":"average","stem":"某项每件收入由36元变成45元，现期均值、均值绝对增加量、均值增长率分别为何？","options":["36元/件、9元/件、20%","45元/件、9个百分点、25%","45元/件、25元/件、9%","45元/件、9元/件、25%"],"answer":3,"explanation":"水平为45，差为45−36=9，率为9/36=25%。差额与水平共享元/件单位。","optionReviews":["错误。36是基期，20%又误用现期作分母。","错误。9是元/件的变化，不能写成百分点。","错误。把数值差与相对率混写。","正确。三个对象与单位逐一匹配。"]},{"id":"ki-dq-063","lesson":"average","stem":"总产量增21%、设备数增10%，现期单台产量55吨。问“单台产量增长百分之几”，应答什么？","options":["5吨/台","55吨/台","11%","10%"],"answer":3,"explanation":"均值乘数1.21/1.10=1.1，增长率10%。基期均值50，差5吨/台，但不是本设问要的率。","optionReviews":["错误。这是均值的绝对增加量。","错误。这是现期均值水平。","错误。21%−10%是率差，未除份数增长因子。","正确。先识别所求是均值增长率。"]}]},{"lessonId":"average","topicId":"average-analysis","courseRoute":"#course/data/topic/average-analysis","sections":[{"title":"均值方向看总量与份数谁跑得快","text":"在两期总量、份数都为正的普通模型中，均值的现期/基期=(1+a)/(1+b)。总量增速大于份数增速，均值上升；小于则下降；相等则不变。例如总量下降8%、份数下降20%，因−8%>−20%，均值乘数0.92/0.80=1.15，均值上升15%。总量减少并不足以说明每份也减少。","index":20,"domId":"ki-point-0058"},{"title":"正值条件与同速例外","text":"若总量与份数都下降12%，两者各乘0.88，比值完全不变，不能说减少了24%。两期均值为正时，上下方向与相对增长符号一致；其他指标可能出现负总量、负均值或定义改变，不能照搬这一正数量直觉。只问方向时通常无须知道现期均值具体多少；要算每份增加几元等绝对变化，则还需要均值规模信息。","index":21,"domId":"ki-point-0059"}],"cards":[{"id":"ki-d-039","title":"均值方向用带符号增速","core":"正数量下a>b均值升，a=b不变，a<b下降。","boundary":"双下降仍可能均值上升；负均值等特殊情况需重新分析。","prompt":"总量下降8%、份数下降20%，均值{{0}}，相对变化为{{1}}%。","blanks":[{"answer":"上升","accept":["提高","升高"]},{"answer":"15","accept":[]}]}],"questions":[{"id":"ki-dq-064","lesson":"average","stem":"两期总量和份数均为正，总量下降8%、份数下降20%，平均每份数量如何变化？","options":["上升15%","下降12%","上升12%","下降28%"],"answer":0,"explanation":"均值倍率0.92/0.8=1.15，虽然总量下降，份数下降更快，均值提高15%。","optionReviews":["正确。方向与准确幅度均由比值确定。","错误。直接作差且符号错误。","错误。12个百分点只是两项增速的差，未除0.8。","错误。把两种下降率直接相加。"]},{"id":"ki-dq-065","lesson":"average","stem":"两期总量和份数均为正，二者都下降12%，均值怎样变化？","options":["不变","下降24%","下降12%","上升12%"],"answer":0,"explanation":"两者同乘0.88，均值的乘数0.88/0.88=1。","optionReviews":["正确。同速变化会在比值中抵消。","错误。两个率不能相加作为均值变化。","错误。只看总量而忽略份数也下降。","错误。没有一项相对另一项增长更快。"]}]},{"lessonId":"average","topicId":"average-analysis","courseRoute":"#course/data/topic/average-analysis","sections":[{"title":"均值绝对变化从两期作差得出","text":"在两期总量与份数均为正、指标口径一致的普通模型下，设现期均值M=A/B，总量和份数增速为a、b，基期均值为M(1+b)/(1+a)。所以现期减基期=M(a−b)/(1+a)。例如现期每件52元，总量增30%、件数增25%，均值差52×0.05/1.30=2元/件，基期50元/件。绝对变化仍以元/件计，不是5个百分点，也不是2%。","index":22,"domId":"ki-point-0060"},{"title":"下降时差额可以为负","text":"现期均值80元/件，总量下降20%、件数下降10%，均值差80×(−0.20+0.10)/0.80=−10元/件，即每件减少10元。基期均值90，回代80−90=−10。若问“增加量”可能允许负数；若明确问减少多少，应报告正值10并写减少。均值增长率另用(a−b)/(1+b)，其分母不同，不能因为形式相近就互换。","index":23,"domId":"ki-point-0061"}],"cards":[{"id":"ki-d-040","title":"均值差保留均值单位","core":"ΔM=M现(a−b)/(1+a)，结果与均值同单位。","boundary":"分母用总量增长因子；不要与均值增长率的份数因子混淆。","prompt":"现期均值52、总量增30%、份数增25%，均值增加{{0}}；分母因子为{{1}}。","blanks":[{"answer":"2","accept":[]},{"answer":"1.3","accept":[]}]}],"questions":[{"id":"ki-dq-066","lesson":"average","stem":"现期每件收入52元，收入总量增长30%、件数增长25%。每件收入比基期增加多少元？","options":["2.08","5","2","4"],"answer":2,"explanation":"ΔM=52×(0.30−0.25)/1.30=2元，基期52−2=50元。","optionReviews":["错误。52×0.05/1.25=2.08是误用均值增长率因子乘现期均值。","错误。5是两个增速之差的百分点数值，没有元单位意义。","正确。绝对差公式分母为总量增长因子1.3。","错误。4%是均值增长率，不是增加4元。"]},{"id":"ki-dq-067","lesson":"average","stem":"现期均值80元/件，总量下降20%、件数下降10%。现期均值减基期均值是多少？","options":["−10元/件","−11.1111元/件","−8元/件","10元/件"],"answer":0,"explanation":"80×(−0.20−(−0.10))/(1−0.20)=−10，基期均值90。","optionReviews":["正确。保留带符号的绝对变化。","错误。误除份数因子0.9，将相对率结构套在现期均值上。","错误。漏除总量增长因子0.8。","错误。10是减少量正值，非现期减基期。"]}]},{"lessonId":"average","topicId":"average-analysis","courseRoute":"#course/data/topic/average-analysis","sections":[{"title":"均值增长率的分母来自份数","text":"用现期均值除以基期均值，得到(1+a)/(1+b)，减1后均值增长率为(a−b)/(1+b)。例如总量增长17.6%、份数增长5%，均值增长(0.176−0.05)/1.05=12%。12.6个百分点是两个数量增速的差，不能直接作为均值增幅；除数也不是总量因子1.176。","index":24,"domId":"ki-point-0062"},{"title":"负增长同样按因子相除","text":"总量下降12%、份数下降20%时，均值增长率=(-0.12+0.20)/0.80=10%。常规推导需要两期份数为正、相关增长率有定义，基期均值非零；在正总量模型下这些条件通常可检查。若份数下降100%，现期均值的分母会成为0，不能把公式强行计算成某个无穷大的增长率。单位应写百分比，而不是每份多少的绝对单位。","index":25,"domId":"ki-point-0063"}],"cards":[{"id":"ki-d-041","title":"均值相对变化的分母","core":"均值增长率=(a−b)/(1+b)，b属于份数。","boundary":"要求份数增长因子为正、基期均值非零；绝对差另有公式。","prompt":"总量增17.6%、份数增5%，均值增长{{0}}%；公式分母为{{1}}。","blanks":[{"answer":"12","accept":[]},{"answer":"1.05","accept":[]}]}],"questions":[{"id":"ki-dq-068","lesson":"average","stem":"总量增长17.6%、份数增长5%，对应正数量口径。平均每份增长率为多少？","options":["22.6%","12.6%","12%","10.7143%"],"answer":2,"explanation":"均值增长率=(17.6%−5%)/(1+5%)=12%，也可由1.176/1.05−1计算。","optionReviews":["错误。两个率相加不能表示均值增长。","错误。只减两率，遗漏分母因子。","正确。用份数增长因子1.05作分母。","错误。错误地除以总量因子1.176。"]},{"id":"ki-dq-069","lesson":"average","stem":"总量下降12%、份数下降20%，平均每份数量的增长率是多少？","options":["10%","8%","−32%","−8%"],"answer":0,"explanation":"带符号率a=−0.12、b=−0.20，(a−b)/(1+b)=0.08/0.8=10%。","optionReviews":["正确。份数下降更快，均值增长10%。","错误。8个百分点只是两项增速差。","错误。相加两个降幅不对应比值增长。","错误。差的符号和份数因子均处理错误。"]}]},{"lessonId":"compound-growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"两段相接必须相乘增长因子","text":"第一段现期成为第二段基期时，累计增长因子为(1+r₁)(1+r₂)，累计率R=r₁+r₂+r₁r₂。例如先增长6%、再增长9%，总因子1.06×1.09=1.1554，总增幅15.54%。直接加成15%漏掉0.54个百分点，因为第二段的9%也作用在第一段新增部分上。两段必须指标可比且首尾接续，不能把两个独立分组这样相乘。","index":11,"domId":"ki-point-0064"},{"title":"交叉项的大小决定能否忽略","text":"用r₁+r₂近似时，累计率的绝对误差恰为|r₁r₂|；换成百分点数值要乘100。两率即使都小于10%，乘积仍可能足以改变近选项的答案。一正一负时乘积为负，简单相加会偏高：先增4%后降4%，累计1.04×0.96−1=−0.16%，不是回到原值。是否略掉交叉项只由所需精度决定，不由某个口头阈值保证。","index":12,"domId":"ki-point-0065"}],"cards":[{"id":"ki-d-042","title":"连续两段的交叉项","core":"R=r₁+r₂+r₁r₂；忽略乘积项的累计率误差为|r₁r₂|。","boundary":"两段须首尾相接；小于10%也不自动允许忽略乘积项。","prompt":"先增6%再增9%，累计增{{0}}%，直接相加会少{{1}}个百分点。","blanks":[{"answer":"15.54","accept":[]},{"answer":"0.54","accept":[]}]},{"id":"ki-d-043","title":"等幅升降不抵消","core":"一增一降的相同百分率形成负的交叉项。","boundary":"百分率的分母依次变化，不是原基期不动。","prompt":"先增4%再降4%，累计增长率为{{0}}%。","blanks":[{"answer":"-0.16","accept":["−0.16"]}]}],"questions":[{"id":"ki-dq-070","lesson":"compound-growth","stem":"先增长6%、再在新基数上增长9%，两段累计增幅为多少？","options":["15.54%","0.54%","16.54%","15%"],"answer":0,"explanation":"累计因子1.06×1.09=1.1554，减1得15.54%，其中交叉项为0.54个百分点。","optionReviews":["正确。包含两率之和与交叉项。","错误。只算交叉项，未加两个原率。","错误。总因子与百分数换算不符。","错误。漏掉交叉项，面对近选项会误选。"]},{"id":"ki-dq-071","lesson":"compound-growth","stem":"一个正数量先增加4%，再减少4%，两段累计增长率是多少？","options":["−8%","0%","0.16%","−0.16%"],"answer":3,"explanation":"1.04×0.96−1=−0.0016=−0.16%，降幅的基数已经是增加后的数量。","optionReviews":["错误。不能把增4%当作降4%再相加。","错误。忽略了第二次变化的基数已变。","错误。交叉项符号应为负。","正确。等幅升降留下负的乘积项。"]}]},{"lessonId":"compound-growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"复合年均率是等效乘数","text":"在n个等长年度、正初值B与正终值A下，年均复合增长率r满足(1+r)ⁿ=A/B，所以r=(A/B)^(1/n)−1，取正的增长因子。甲三年由250到332.75，终初比1.331=1.1³，年均10%；乙三年由200到345.6，比值1.728=1.2³，年均20%。这里n相同，直接比较1.331与1.728就能判断乙年均更快，不必先求两个开方结果。","index":13,"domId":"ki-point-0066"},{"title":"期间不同，累计倍数不能直接排年均","text":"若甲两年增长到原来的1.44倍，乙三年增长到1.728倍，甲年均√1.44−1=20%，乙年均³√1.728−1也为20%，累计倍数更大并不代表年均更高。年均复合率也不是各实际年度率的算术平均，更不是累计率除n。先数实际增长段，保证每段长度一致；出现零初值、负初值或跨符号终值时，普通正数量的复合模型不能直接套用。","index":14,"domId":"ki-point-0067"}],"cards":[{"id":"ki-d-044","title":"年均复合率从终初比开方","core":"r=(A/B)^(1/n)−1，n为实际等长增长段数。","boundary":"正初值与正终值；n相同时才能仅凭终初比排序。","prompt":"三年终初比1.331，对应年均{{0}}%；三年终初比1.728，对应年均{{1}}%。","blanks":[{"answer":"10","accept":[]},{"answer":"20","accept":[]}]},{"id":"ki-d-045","title":"累计增长不等于年均增长","core":"期间不同须分别开相应次方，较大累计比值可能对应相同或较小年均率。","boundary":"不要把累计增幅直接除年度数。","prompt":"两年终初比1.44与三年终初比1.728，年均率分别为{{0}}%、{{1}}%。","blanks":[{"answer":"20","accept":[]},{"answer":"20","accept":[]}]}],"questions":[{"id":"ki-dq-072","lesson":"compound-growth","stem":"甲三年由250增至332.75，乙三年由200增至345.6，正数量口径下二者年均复合增长率及排序如何？","options":["甲11.0333%、乙24.2667%，乙更高","甲20%、乙10%，甲更高","甲与乙相同，因为都经历三年","甲10%、乙20%，乙更高"],"answer":3,"explanation":"甲终初比1.331=1.1³，乙1.728=1.2³，故分别10%、20%。相同期间可直接按终初比排序。","optionReviews":["错误。把累计率33.1%、72.8%分别除3，不是复合年均率。","错误。两个终初比的对应年均率颠倒。","错误。期间相同并不意味着终初倍数相同。","正确。复合率与等长期间比较均正确。"]},{"id":"ki-dq-073","lesson":"compound-growth","stem":"甲两年终值/初值=1.44，乙三年终值/初值=1.728。哪项年均复合增长率更高？","options":["甲更高，因为44%/2大于72.8%/3","无法比较，即使能开方也不能确定","两者相同，都是20%","乙更高，因为1.728大于1.44"],"answer":2,"explanation":"1.2²=1.44，1.2³=1.728，所以两者等效年度因子都是1.2。不同期间不能直接比较累计比值。","optionReviews":["错误。累计率除期间数不是年均复合率，所述算术大小也不成立。","错误。所给正比值与期间数足以求唯一正增长因子。","正确。分别按2段与3段还原。","错误。忽略期间数不同。"]}]},{"lessonId":"mixed-growth","topicId":"growth-analysis","courseRoute":"#course/data/topic/growth-analysis","sections":[{"title":"总增速的权重在基期","text":"将不重叠、无遗漏、同口径的两组基期量记作X、Y，增速a、b，则总增量Xa+Yb，总基期X+Y，因此总体率R=(Xa+Yb)/(X+Y)。例如基期80与240、增速25%与5%，各增20与12，总率32/320=10%，不是简单平均15%。权重80/320与240/320表示共同出发点的结构，不能改用增长后的数量。","index":12,"domId":"ki-point-0068"},{"title":"范围与中点有不同的严格条件","text":"正基期使两个权重为正且和为1。a与b不同时，总率严格在两率之间，更接近基期权重较大的那组；两率相同时，总率等于共同率。对恰好两组，总率等于算术中点(a+b)/2，当且仅当基期量相等或两增速相等，因为两种平均之差=(X−Y)(a−b)/[2(X+Y)]。所以“总体率绝不在中点”错误，“任意两组都在中点”也错误。","index":13,"domId":"ki-point-0069"},{"title":"只给现期，先把各组还原","text":"若甲乙现期都为240，增速分别20%与60%，两组现期相等但基期分别200与150。总现期480、总基期350，总率130/350=13/35≈37.1429%，小于算术中点40%。如果直接以两个240作权重就会误得40%。先除各自的1+增长率，再用基期权重，或直接以总现期/总基期−1计算，两条路径等价。","index":14,"domId":"ki-point-0070"},{"title":"能否合并比套公式更先一步","text":"两组若有重复或遗漏，二者总量就不是所求总体；不能只因为计算结果在两率之间便认定模型适用。出现负基期会产生负权重，也不能继续保证范围结论。若材料的增速只是舍入显示，两率显示相同并不保证原始率精确相同；只有按显示值计算或给定精确率时才可以据此断言总体等于共同率。范围判断一般不给唯一值，缺少权重时不能编造精确总率。","index":15,"domId":"ki-point-0071"}],"cards":[{"id":"ki-d-046","title":"混合增长的正确权重","core":"总体增长率按各组基期数量加权，不是现期数量或组数加权。","boundary":"各组须不重不漏、口径相同且基期均正。","prompt":"基期80与240、增速25%与5%，总体增速为{{0}}%；权重应取{{1}}期。","blanks":[{"answer":"10","accept":[]},{"answer":"基","accept":[]}]},{"id":"ki-d-047","title":"中点特例不遗漏","core":"对两个正基期组，总率等于两率算术中点，当且仅当基期相等或两增速相等。","boundary":"不同增速和不同正基期下，总率不在算术中点；增速相同则退化为共同值。","prompt":"两组基期相等、增速−10%和30%，总率为{{0}}%；基期不同但都增7%，总率为{{1}}%。","blanks":[{"answer":"10","accept":[]},{"answer":"7","accept":[]}]},{"id":"ki-d-048","title":"现期相等不等于基期相等","core":"只给现期与率，先逐项除增长因子恢复基期。","boundary":"不能把现期占比直接当作混合增速权重。","prompt":"现期均240、增速20%与60%，基期分别为{{0}}、{{1}}，总体率为{{2}}。第三空用分数表示。","blanks":[{"answer":"200","accept":[]},{"answer":"150","accept":[]},{"answer":"13/35","accept":[]}]}],"questions":[{"id":"ki-dq-074","lesson":"mixed-growth","stem":"两组互不重叠且覆盖总体，基期分别80与240，增速分别25%与5%，总体增速是多少？","options":["15%","20%","30%","10%"],"answer":3,"explanation":"基期增量分别20与12，合计32，总基期320，总率10%，更靠近基期较大的5%一组。","optionReviews":["错误。是两率简单平均，忽略基数差异。","错误。20是第一组绝对增量，不能直接当总率。","错误。两率相加不是混合增速。","正确。按基期权重计算。"]},{"id":"ki-dq-075","lesson":"mixed-growth","stem":"均为互斥且穷尽的正基期两组：情形一基期各120、增速−10%与30%；情形二基期50与200、两组均增7%。两种总体率依次为何？","options":["20%、7%","两种都无法确定","10%、14%","10%、7%"],"answer":3,"explanation":"情形一等基期，率为(−10%+30%)/2=10%；情形二增速相同，加权后仍为7%。这两个情形都是中点等式成立的例外条件。","optionReviews":["错误。两率之和20%还需按等权除2。","错误。每个情形都有充分条件确定总率。","错误。共同率7%不因有两组变成14%。","正确。分别检验等基期与等增速两条条件。"]},{"id":"ki-dq-076","lesson":"mixed-growth","stem":"两组互斥穷尽，现期均240，甲增20%、乙增60%，对应正基期。总体增速是多少？","options":["80%","50%","约37.1429%","40%"],"answer":2,"explanation":"基期200与150，合计350；总现期480，总率(480−350)/350=13/35≈37.1429%。","optionReviews":["错误。将两率相加。","错误。50%既非基期加权结果，也无法由所给数据推出。","正确。先还原基期再合并。","错误。以相等现期当成相等基期，错误使用中点。"]},{"id":"ki-dq-077","lesson":"mixed-growth","stem":"甲乙两个业务分组有部分相同业务同时计入，题目要全机构总增速，未给交集数量及其变化。哪项判断正确？","options":["只要两组基期为正，就必可直接加权","先把两组率平均即可消除交集","只要算出的率在两组率之间，就说明没有重复","不能直接用甲乙基期量加权求全机构增速"],"answer":3,"explanation":"重复业务导致甲乙基期与增量的相加重复计数。不重不漏是把合计视为总体的前提，率的范围不能证明分组无重叠。","optionReviews":["错误。正权重只保证代数平均性质，不保证对应真实总体。","错误。平均率不会自动修正重复计数。","错误。范围性质与集合是否重叠是两回事。","正确。需要交集与完整覆盖等信息后才能构造真实总体。"]}]},{"lessonId":"remainders","topicId":"counting","courseRoute":"#course/quant/topic/counting","sections":[{"title":"末位与末两位各负责什么","text":"十进制整数是否为偶数看个位是否为0、2、4、6、8；能否被5整除看个位是0或5；能否被4整除看末两位组成的数是否为4的倍数。这是因为10是2和5的倍数，100是4的倍数。例如2740末位0，末两位40，因此同时被2、5、4整除。 适用与误用：判断4不能只看个位；负整数可先取绝对值检查。","index":9,"domId":"ki-point-0072"},{"title":"数位和把大数变小","text":"因为10除以9与3都余1，所以非负整数与其各位数字之和有相同的模9、模3余数。负整数可先取绝对值检查整除性；不应据此认为负整数本身与其通常数位和的余数相同。数位和为9的倍数必能被9整除，也必能被3整除；只被3整除则不一定被9整除。例如5274的数位和是18，故两者都满足。 适用与误用：数位和法适用于3、9等明确规则，不能将它推广为判断4或5的一般办法。","index":10,"domId":"ki-point-0073"},{"title":"合并整除条件要看最小公倍数","text":"同时被若干正整数整除，就是该数为这些除数最小公倍数的倍数。若除数两两互质，各质因子没有重复，最小公倍数才等于乘积。例如同时被4和9整除可推出被36整除；同时被8和12整除则只必然推出被24整除，不能直接乘成96。 适用与误用：两两互质是乘积结论的条件，不是可省略的修饰；不互质时使用最小公倍数。","index":11,"domId":"ki-point-0074"}],"cards":[{"id":"ki-q-001","title":"末位与末两位各负责什么","core":"十进制整数是否为偶数看个位是否为0、2、4、6、8；能否被5整除看个位是0或5；能否被4整除看末两位组成的数是否为4的倍数。这是因为10是2和5的倍数，100是4的倍数。例如2740末位0，末两位40，因此同时被2、5、4整除。","boundary":"判断4不能只看个位；负整数可先取绝对值检查。","prompt":"判断十进制整数能否被4整除，只需检查{{0}}。","blanks":[{"answer":"末两位组成的数","accept":[]}]},{"id":"ki-q-002","title":"数位和把大数变小","core":"因为10除以9与3都余1，所以非负整数与其各位数字之和有相同的模9、模3余数。负整数可先取绝对值检查整除性；不应据此认为负整数本身与其通常数位和的余数相同。数位和为9的倍数必能被9整除，也必能被3整除；只被3整除则不一定被9整除。例如5274的数位和是18，故两者都满足。","boundary":"数位和法适用于3、9等明确规则，不能将它推广为判断4或5的一般办法。","prompt":"同时被9和3整除时，可检查数位和是否为{{0}}的倍数。","blanks":[{"answer":"9","accept":[]}]},{"id":"ki-q-003","title":"合并整除条件要看最小公倍数","core":"同时被若干正整数整除，就是该数为这些除数最小公倍数的倍数。若除数两两互质，各质因子没有重复，最小公倍数才等于乘积。例如同时被4和9整除可推出被36整除；同时被8和12整除则只必然推出被24整除，不能直接乘成96。","boundary":"两两互质是乘积结论的条件，不是可省略的修饰；不互质时使用最小公倍数。","prompt":"合并不互质的整除条件时，应使用各除数的{{0}}。","blanks":[{"answer":"最小公倍数","accept":["lcm","LCM"]}]},{"id":"ki-q-052","title":"被2整除看个位","core":"十进制整数个位为0、2、4、6、8时且仅当能被2整除。","boundary":"只能据此判断偶数性质，不代表能被4整除。","prompt":"个位为0、2、4、6、8的整数一定能被{{0}}整除。","blanks":[{"answer":"2","accept":[]}]},{"id":"ki-q-053","title":"被5整除的两个末位","core":"整数的个位是0或5时且仅当能被5整除。","boundary":"末位5不保证被2整除；末位0则同时被2、5整除。","prompt":"被5整除的整数，个位一定是{{0}}。","blanks":[{"answer":"0或5","accept":["0、5","0和5"]}]},{"id":"ki-q-054","title":"被3整除用数位和","core":"十进制整数能被3整除，当且仅当其数位和能被3整除。","boundary":"数位和被3整除未必能被9整除，如数位和12。","prompt":"判断能否被3整除，可检查{{0}}能否被3整除。","blanks":[{"answer":"各位数字之和","accept":["数位和"]}]},{"id":"ki-q-055","title":"互质时才能直接乘除数","core":"若若干正除数两两互质且都整除整数N，它们的乘积必整除N。","boundary":"若不互质，应使用最小公倍数，直接取乘积可能过大。","prompt":"若各除数都整除N，想直接推出其乘积整除N，须满足除数{{0}}。","blanks":[{"answer":"两两互质","accept":["两两互素"]}]}],"questions":[{"id":"ki-qq-001","lesson":"remainders","stem":"整数2740一定同时被下面哪组数整除？","options":["3、4、5","2、3、5","4、5、9","2、4、5"],"answer":3,"explanation":"2740的末位是0，所以被2和5整除；末两位40是4的倍数。数位和13既不是3也不是9的倍数。","optionReviews":["含3，数位和13排除。","含3，而2740除以3余1。","含9，数位和13排除。","正确，三个整除条件都满足。"]},{"id":"ki-qq-002","lesson":"remainders","stem":"下列哪个整数能同时被3和9整除？","options":["5274","5275","5276","5278"],"answer":0,"explanation":"5274的数位和是18；5275、5276、5278的数位和分别是19、20、22，都不能被9整除。","optionReviews":["正确，数位和18是9的倍数。","数位和19，不符合。","数位和20，不符合。","数位和22，不符合。"]},{"id":"ki-qq-003","lesson":"remainders","stem":"正整数N同时被8和12整除。以下哪一个数必定整除N？","options":["48","36","24","96"],"answer":2,"explanation":"8=2³，12=2²×3，最小公倍数为2³×3=24。N=24就能否定另外三项。","optionReviews":["取N=24即不成立。","36含有额外的因子3。","正确，N一定为24的整数倍。","乘积重复计算公因子4。"]},{"id":"ki-qq-052","lesson":"remainders","stem":"正整数N同时被5和8整除。以下哪一数必定整除N？","options":["40","200","100","80"],"answer":0,"explanation":"5和8互质，最小公倍数等于乘积40。N=40已满足两个原条件，但不能被另外三项整除。","optionReviews":["正确，互质除数的乘积40必整除N。","N=40时不被200整除。","N=40时不被100整除。","N=40时不被80整除。"]}]},{"lessonId":"remainders","topicId":"counting","courseRoute":"#course/quant/topic/counting","sections":[{"title":"线性式先移去常数项","text":"若y=ax+b且a、x都是整数，a不为0，则y-b=ax，所以y-b一定能被a整除。检查候选值时先移去常数b，再看商是否为符合题设的整数。例如每箱7支、另有4支，y=7x+4，合法总数减4后应为7的倍数。 适用与误用：整数约束必须真实存在；x若代表箱数还需非负，单有同余关系不能替代范围条件。","index":12,"domId":"ki-point-0075"},{"title":"减常数的形式要加回去","text":"若y=ax-b，移项得到y+b=ax，因此被a整除的是y+b。比如一项编码y=9x-5，x为正整数，恢复到9的倍数需要给y加5，而非再减5。 适用与误用：正负号依据等式移动，不能只记“看到常数就减”；还要核对x的整数与取值范围。","index":13,"domId":"ki-point-0076"}],"cards":[{"id":"ki-q-004","title":"线性式先移去常数项","core":"若y=ax+b且a、x都是整数，a不为0，则y-b=ax，所以y-b一定能被a整除。检查候选值时先移去常数b，再看商是否为符合题设的整数。例如每箱7支、另有4支，y=7x+4，合法总数减4后应为7的倍数。","boundary":"整数约束必须真实存在；x若代表箱数还需非负，单有同余关系不能替代范围条件。","prompt":"由整数关系y=7x+4得到，y-4一定是{{0}}的倍数。","blanks":[{"answer":"7","accept":[]}]},{"id":"ki-q-005","title":"减常数的形式要加回去","core":"若y=ax-b，移项得到y+b=ax，因此被a整除的是y+b。比如一项编码y=9x-5，x为正整数，恢复到9的倍数需要给y加5，而非再减5。","boundary":"正负号依据等式移动，不能只记“看到常数就减”；还要核对x的整数与取值范围。","prompt":"y=9x-5且x为整数时，应检查y{{0}}能否被9整除。","blanks":[{"answer":"+5","accept":[]}]}],"questions":[{"id":"ki-qq-004","lesson":"remainders","stem":"若x为非负整数，y=7x+4，下面哪个值可作为y？","options":["56","54","55","53"],"answer":3,"explanation":"53-4=49=7×7，所以x=7合法；54、55、56减4后分别为50、51、52，都不是7的倍数。","optionReviews":["减4得52，不被7整除。","减4得50，不被7整除。","减4得51，不被7整除。","正确，x=(53-4)/7=7。"]},{"id":"ki-qq-005","lesson":"remainders","stem":"x为正整数，y=9x-5。以下哪个y合法？","options":["41","38","40","36"],"answer":2,"explanation":"40+5=45，x=5为正整数；36、38、41加5分别为41、43、46，均不能被9整除。","optionReviews":["加5得46，不符合。","加5得43，不符合。","正确，对应x=5。","加5得41，不是9的倍数。"]}]},{"lessonId":"remainders","topicId":"counting","courseRoute":"#course/quant/topic/counting","sections":[{"title":"最简比等于共享整数份数","text":"A、B为整数，B非零，且A/B=m/n已经约到互质整数比时，存在整数k使A=km、B=kn。于是A+B=k(m+n)，A-B=k(m-n)。例如甲乙人数比5:8、总人数91，十三份为91，每份7人，甲35人、乙56人。 适用与误用：先约分再谈整数份数；若未约分，k可能不是整数。人数要求k为正，不能把代数可行的负数当人数。","index":14,"domId":"ki-point-0077"},{"title":"差值约束和零差边界","text":"由最简比A:B=m:n可将差写成k(m-n)，能用差反求份数。例如A:B=7:4且A-B=39，三份为39，每份13，A=91。若m=n且比已最简，两者相等，差只能为0；此时不能用差除以m-n，因为分母为0。 适用与误用：差的方向要与比的顺序一致；差为0并不能唯一确定两个相等量的大小。","index":15,"domId":"ki-point-0078"}],"cards":[{"id":"ki-q-006","title":"最简比等于共享整数份数","core":"A、B为整数，B非零，且A/B=m/n已经约到互质整数比时，存在整数k使A=km、B=kn。于是A+B=k(m+n)，A-B=k(m-n)。例如甲乙人数比5:8、总人数91，十三份为91，每份7人，甲35人、乙56人。","boundary":"先约分再谈整数份数；若未约分，k可能不是整数。人数要求k为正，不能把代数可行的负数当人数。","prompt":"整数A、B的最简比为5:8时，A+B必是{{0}}的整数倍。","blanks":[{"answer":"13","accept":[]}]},{"id":"ki-q-007","title":"差值约束和零差边界","core":"由最简比A:B=m:n可将差写成k(m-n)，能用差反求份数。例如A:B=7:4且A-B=39，三份为39，每份13，A=91。若m=n且比已最简，两者相等，差只能为0；此时不能用差除以m-n，因为分母为0。","boundary":"差的方向要与比的顺序一致；差为0并不能唯一确定两个相等量的大小。","prompt":"A:B=7:4且A-B=39时，一份等于{{0}}。","blanks":[{"answer":"13","accept":[]}]},{"id":"ki-q-056","title":"最简整数比的共同倍数","core":"若整数A、B满足最简比A:B=m:n，B非零且m、n互质，可写A=km、B=kn，k为整数。","boundary":"若比未约简，系数未必为整数；人数模型另需正数。","prompt":"最简整数比A:B=m:n，可表示A=km、B={{0}}。","blanks":[{"answer":"kn","accept":[]}]},{"id":"ki-q-057","title":"相等时差不能拿来除零","core":"两正整数最简比1:1则两数相等，差为0；只知差0不能确定两数大小。","boundary":"不能用k=差/(m-n)把0/0当成0或1。","prompt":"两数比1:1且差0，只凭这些条件能否确定各数大小？{{0}}。","blanks":[{"answer":"不能","accept":[]}]}],"questions":[{"id":"ki-qq-006","lesson":"remainders","stem":"两队人数之比为5:8，总人数为91。乙队有多少人？","options":["56人","35人","65人","49人"],"answer":0,"explanation":"总份数13，每份91÷13=7人，乙队8×7=56人。","optionReviews":["正确，8份共56人。","35是甲队人数。","65把份数和人数混用。","49对应7份，不是乙的8份。"]},{"id":"ki-qq-007","lesson":"remainders","stem":"两个正整数之比为7:4，较大数比其较小数大39，较大数是多少？","options":["91","78","52","117"],"answer":0,"explanation":"差为7-4=3份，所以k=39÷3=13，较大数7k=91。","optionReviews":["正确，7×13=91。","78是6份。","52是较小数4k。","117是9份，较大数应取7份，即7×13=91。"]},{"id":"ki-qq-053","lesson":"remainders","stem":"两个正整数A、B满足A:B=1:1且A-B=0。只凭这些条件，A是多少？","options":["5","10","无法唯一确定","1"],"answer":2,"explanation":"A=B即可满足，(1,1)、(5,5)、(10,10)等都合法，故不能唯一确定A。","optionReviews":["5也是一个可能值，并非唯一。","10同样只是可能值。","正确，比例和零差未给出尺度。","1只是一个可能值。"]}]},{"lessonId":"profit-bases","topicId":"profit","courseRoute":"#course/quant/topic/profit","sections":[{"title":"让未知数连接最多的条件","text":"设未知数的目的是把条件转成少而清楚的等式。可以直接设所求量，也可以设一份、其中一个量或共同变化量。例如两种纪念品件数比5:7、合计96件，设一份为x，则5x+7x=96，比同时设两种件数再写比例更省步骤；乙有56件。 适用与误用：“求谁设谁”并非必须；选择仍应保留单位、非负性和整数约束，不能为了简短删条件。","index":9,"domId":"ki-point-0079"}],"cards":[{"id":"ki-q-008","title":"让未知数连接最多的条件","core":"设未知数的目的是把条件转成少而清楚的等式。可以直接设所求量，也可以设一份、其中一个量或共同变化量。例如两种纪念品件数比5:7、合计96件，设一份为x，则5x+7x=96，比同时设两种件数再写比例更省步骤；乙有56件。","boundary":"“求谁设谁”并非必须；选择仍应保留单位、非负性和整数约束，不能为了简短删条件。","prompt":"两个量按5:7分配时，设共同的{{0}}通常能减少未知数。","blanks":[{"answer":"一份","accept":[]}]}],"questions":[{"id":"ki-qq-008","lesson":"profit-bases","stem":"甲乙两类纪念品的件数比为5:7，共96件。设一份为x，哪条关系与乙类件数配对正确？","options":["5x+7x=96；乙56件","x=96；乙672件","5x+7x=96；乙40件","7x-5x=96；乙336件"],"answer":0,"explanation":"共同份数满足12x=96，所以x=8，乙为7x=56件。","optionReviews":["正确，一条等式同时用到比例和总数。","把总量误作一份。","方程对，但40是甲的5份。","把合计误作差值。"]}]},{"lessonId":"work","topicId":"work-process","courseRoute":"#course/quant/topic/work-process","sections":[{"title":"只在尺度不影响目标时赋值","text":"若所有量同比例扩大，所求比值或完成时间不变，就可选一个方便尺度计算。例如甲乙效率比2:3，合作完成同一工作时，甲承担的比例恒为2/(2+3)=2/5，把总工作量取5份、50份都得到40%。 适用与误用：便利赋值不是随意改条件；先看目标是否随总量改变，人数、价格等固定绝对信息也不能丢。","index":9,"domId":"ki-point-0080"},{"title":"固定绝对差决定比例尺度","text":"当比例之外还有确定的差、和或某一绝对量，尺度由该条件确定，不能任选。例如效率比2:3且乙每天比甲多6件，一份就是6件，甲每天12件、乙18件，合作完成150件需5天。 适用与误用：不能把甲乙效率直接当作2件/天和3件/天，那会违反每天相差6件的条件；份数与实际单位要换算。","index":10,"domId":"ki-point-0081"}],"cards":[{"id":"ki-q-009","title":"只在尺度不影响目标时赋值","core":"若所有量同比例扩大，所求比值或完成时间不变，就可选一个方便尺度计算。例如甲乙效率比2:3，合作完成同一工作时，甲承担的比例恒为2/(2+3)=2/5，把总工作量取5份、50份都得到40%。","boundary":"便利赋值不是随意改条件；先看目标是否随总量改变，人数、价格等固定绝对信息也不能丢。","prompt":"效率比2:3、全程同时合作时，甲完成总量的比例为{{0}}。","blanks":[{"answer":"40%","accept":[]}]},{"id":"ki-q-010","title":"固定绝对差决定比例尺度","core":"当比例之外还有确定的差、和或某一绝对量，尺度由该条件确定，不能任选。例如效率比2:3且乙每天比甲多6件，一份就是6件，甲每天12件、乙18件，合作完成150件需5天。","boundary":"不能把甲乙效率直接当作2件/天和3件/天，那会违反每天相差6件的条件；份数与实际单位要换算。","prompt":"效率比2:3且每天相差6件时，一份效率是{{0}}件/天。","blanks":[{"answer":"6","accept":[]}]}],"questions":[{"id":"ki-qq-009","lesson":"work","stem":"甲乙效率恒定且互不干扰，效率比2:3，同时开工并一起完工。甲完成总工作量的比例是多少？","options":["60%","40%","20%","50%"],"answer":1,"explanation":"同一工作时长下工作量之比等于效率比，甲的份额为2÷(2+3)=40%。","optionReviews":["60%是乙的份额。","正确，总共5份，甲占2份。","把2直接当成20%，没有总份数依据。","误当效率相等。"]},{"id":"ki-qq-010","lesson":"work","stem":"甲乙效率比2:3，乙每天比甲多做6件。两人同时合作做150件，多少天完成？","options":["30天","10天","5天","15天"],"answer":2,"explanation":"一份效率为6件/天，甲12、乙18，合效率30件/天，150÷30=5天。","optionReviews":["直接把2+3=5当件/天，忽略相差6件。","少算了一半合效率。","正确，所有绝对条件均保留。","对应错误合效率10件/天。"]}]},{"lessonId":"work","topicId":"work-process","courseRoute":"#course/quant/topic/work-process","sections":[{"title":"工作量、效率和时间单位配套","text":"效率指每单位时间完成多少工作，在效率恒定的时段，工作量W=v×t。知道任意两个量可求第三个。例如一台设备每小时完成14件，连续工作3.5小时，完成49件。先把分钟、小时或不同工件口径统一，再相乘。 适用与误用：效率变化就分时段累计；不可把14件/小时与210分钟直接乘成2940件。","index":11,"domId":"ki-point-0082"},{"title":"共同工作合并效率而非工期","text":"同一任务可以并行、效率恒定且互不干扰时，多人合效率等于各自效率之和。例如甲每日9件、乙每日6件，合作每日15件，做75件需5天。若甲乙是前后相接的工序或共同使用一台限制设备，不能直接相加。 适用与误用：工期相加不是合作工期；工作单位必须相同，返工、干扰与瓶颈须另算。","index":12,"domId":"ki-point-0083"}],"cards":[{"id":"ki-q-011","title":"工作量、效率和时间单位配套","core":"效率指每单位时间完成多少工作，在效率恒定的时段，工作量W=v×t。知道任意两个量可求第三个。例如一台设备每小时完成14件，连续工作3.5小时，完成49件。先把分钟、小时或不同工件口径统一，再相乘。","boundary":"效率变化就分时段累计；不可把14件/小时与210分钟直接乘成2940件。","prompt":"恒定效率下，工作量等于效率乘以{{0}}。","blanks":[{"answer":"时间","accept":[]}]},{"id":"ki-q-012","title":"共同工作合并效率而非工期","core":"同一任务可以并行、效率恒定且互不干扰时，多人合效率等于各自效率之和。例如甲每日9件、乙每日6件，合作每日15件，做75件需5天。若甲乙是前后相接的工序或共同使用一台限制设备，不能直接相加。","boundary":"工期相加不是合作工期；工作单位必须相同，返工、干扰与瓶颈须另算。","prompt":"可加效率模型中，两人合效率为{{0}}之和。","blanks":[{"answer":"各自效率","accept":[]}]}],"questions":[{"id":"ki-qq-011","lesson":"work","stem":"设备每小时加工14件合格件，效率不变，运行210分钟共完成多少件？","options":["42件","2940件","49件","98件"],"answer":2,"explanation":"210分钟=3.5小时，工作量14×3.5=49件。","optionReviews":["对应3小时，少了半小时。","把分钟直接与每小时效率相乘。","正确，时间单位已统一。","把3.5小时翻倍了。"]},{"id":"ki-qq-012","lesson":"work","stem":"甲每天做9件，乙每天做6件，同类产品可独立并行加工。合作完成75件要多少天？","options":["8天","5天","12.5天","3天"],"answer":1,"explanation":"合作效率9+6=15件/天，75÷15=5天。","optionReviews":["将不相关数量相加。","正确，5天分别完成45和30件。","12.5天是乙单做工期。","需每天25件，超过合效率。"]}]},{"lessonId":"work","topicId":"work-process","courseRoute":"#course/quant/topic/work-process","sections":[{"title":"用工期公倍数连接分段工作","text":"同一任务甲独做15天、乙独做20天，取总量60份，效率分别为4份/天和3份/天。甲先做3天完成12份，剩48份由两人合作，每天7份，需48/7天；总历时3+48/7=69/7天。公倍数只是换单位，总任务并没有改变。 适用与误用：只在工期代表稳定独做效率时可如此反推；非整数工期可取其他便利量，不必硬找整数最小公倍数。","index":13,"domId":"ki-point-0084"}],"cards":[{"id":"ki-q-013","title":"用工期公倍数连接分段工作","core":"同一任务甲独做15天、乙独做20天，取总量60份，效率分别为4份/天和3份/天。甲先做3天完成12份，剩48份由两人合作，每天7份，需48/7天；总历时3+48/7=69/7天。公倍数只是换单位，总任务并没有改变。","boundary":"只在工期代表稳定独做效率时可如此反推；非整数工期可取其他便利量，不必硬找整数最小公倍数。","prompt":"甲15天、乙20天独做同一任务，可取总量60份，两人日效率分别为4份和{{0}}份。","blanks":[{"answer":"3","accept":[]}]},{"id":"ki-q-058","title":"分阶段保留剩余工作量","core":"先独做后合作时，先算已做量，再以剩余量除合作效率；若问总时间还要加先做时间。","boundary":"问剩余时间与总历时不同，不能重复扣或漏扣先做量。","prompt":"先独做t天、效率a，总量W，后续合效率a+b，则合作时间为{{0}}。","blanks":[{"answer":"(W-at)/(a+b)","accept":[]}]}],"questions":[{"id":"ki-qq-013","lesson":"work","stem":"甲独做15天、乙独做20天完成同一任务，效率恒定可相加。甲先独做3天，再两人合作，后续合作需几天？","options":["60/7天","12天","48/7天","69/7天"],"answer":2,"explanation":"设总量60，甲日做4，乙日做3。甲先完成12，剩48，合作48÷7=48/7天。题问后续合作时间，不含先做3天。","optionReviews":["未扣除先做的12份。","这是甲独自完成剩余工作的时间。","正确，剩余量除以合效率。","这是总历时，不是后续合作时间。"]}]},{"lessonId":"work","topicId":"work-process","courseRoute":"#course/quant/topic/work-process","sections":[{"title":"效率份数随阶段累计","text":"效率比已知时，先把效率记为相应份数。甲乙效率比3:5，甲先做4小时，随后两人合作6小时，完成的总工作量为3×4+(3+5)×6=60份。乙只在后6小时工作，完成30份，因此占总任务一半。 适用与误用：只有比值不能确定60份等于多少实际件数；各人的开工、停工时间分别记录，不能把全程当所有人都在。","index":14,"domId":"ki-point-0085"}],"cards":[{"id":"ki-q-014","title":"效率份数随阶段累计","core":"效率比已知时，先把效率记为相应份数。甲乙效率比3:5，甲先做4小时，随后两人合作6小时，完成的总工作量为3×4+(3+5)×6=60份。乙只在后6小时工作，完成30份，因此占总任务一半。","boundary":"只有比值不能确定60份等于多少实际件数；各人的开工、停工时间分别记录，不能把全程当所有人都在。","prompt":"效率比3:5，甲先做4小时、两人再做6小时时，总工作量为{{0}}份。","blanks":[{"answer":"60","accept":[]}]}],"questions":[{"id":"ki-qq-014","lesson":"work","stem":"甲乙效率比3:5，甲先独做4小时，再合作6小时恰好完成。乙完成了总量的多少？","options":["1/3","2/5","5/8","1/2"],"answer":3,"explanation":"甲先做12份，合作阶段做48份，总量60份；乙做5×6=30份，占1/2。","optionReviews":["乙并非只占20份。","只看比例却忽略各自时长。","5/8只适用于两人同工时，不适用于全程。","正确，乙30份除总量60份。"]}]},{"lessonId":"profit-discount","topicId":"profit","courseRoute":"#course/quant/topic/profit","sections":[{"title":"两种利润率的分母不同","text":"单件利润是售价减去成本。成本利润率把利润与成本比较，销售利润率把利润与售价比较。例如成本80元、售价100元，利润20元，前者20/80=25%，后者20/100=20%。二者不能因为都叫利润率而混用。 适用与误用：题目若只写利润率，需要从定义或上下文确认分母；成本或售价为0时相应比率无定义。","index":11,"domId":"ki-point-0086"},{"title":"折扣率不是降价幅度","text":"折扣率等于成交价除以原价，八折对应乘0.8，降价幅度为1-0.8=20%。例如标价250元打八折，成交200元，少付50元。两次打折应连乘各次折扣率，而不是把折数简单相加减。 适用与误用：折扣只描述相对标价的变化，不直接决定盈利；是否盈利仍要与成本比较。","index":12,"domId":"ki-point-0087"},{"title":"单价乘件数再累计利润","text":"同一单价下总销售额等于售价乘件数；总利润等于各件利润之和，统一成本售价时为(售价-成本)×件数。例如每件成本36元、售价45元，卖出24件，销售额1080元，总成本864元，总利润216元。 适用与误用：不同批次价格或成本不同就分别累计；销售额不是利润，固定费用题设给出时还要扣除。","index":13,"domId":"ki-point-0088"}],"cards":[{"id":"ki-q-015","title":"两种利润率的分母不同","core":"单件利润是售价减去成本。成本利润率把利润与成本比较，销售利润率把利润与售价比较。例如成本80元、售价100元，利润20元，前者20/80=25%，后者20/100=20%。二者不能因为都叫利润率而混用。","boundary":"题目若只写利润率，需要从定义或上下文确认分母；成本或售价为0时相应比率无定义。","prompt":"成本80元、售价100元时，成本利润率25%，销售利润率为{{0}}。","blanks":[{"answer":"20%","accept":[]}]},{"id":"ki-q-016","title":"折扣率不是降价幅度","core":"折扣率等于成交价除以原价，八折对应乘0.8，降价幅度为1-0.8=20%。例如标价250元打八折，成交200元，少付50元。两次打折应连乘各次折扣率，而不是把折数简单相加减。","boundary":"折扣只描述相对标价的变化，不直接决定盈利；是否盈利仍要与成本比较。","prompt":"八折的折扣率是80%，相对原价的降价幅度是{{0}}。","blanks":[{"answer":"20%","accept":[]}]},{"id":"ki-q-017","title":"单价乘件数再累计利润","core":"同一单价下总销售额等于售价乘件数；总利润等于各件利润之和，统一成本售价时为(售价-成本)×件数。例如每件成本36元、售价45元，卖出24件，销售额1080元，总成本864元，总利润216元。","boundary":"不同批次价格或成本不同就分别累计；销售额不是利润，固定费用题设给出时还要扣除。","prompt":"每件利润9元、共售24件且无其他费用，总利润为{{0}}元。","blanks":[{"answer":"216","accept":[]}]},{"id":"ki-q-059","title":"单件利润","core":"售价与成本用同一件商品、同一货币单位比较，单件利润=售价-成本。","boundary":"售价不是利润；另有税费、运输费等时按题设纳入相应成本。","prompt":"单件利润等于售价减去{{0}}。","blanks":[{"answer":"成本","accept":[]}]},{"id":"ki-q-060","title":"成本利润率分母","core":"成本利润率=(售价-成本)/成本，要求分母成本非零。","boundary":"销售利润率的分母是售价，两种率不能互换。","prompt":"成本利润率=利润÷{{0}}。","blanks":[{"answer":"成本","accept":[]}]},{"id":"ki-q-061","title":"折扣率公式","core":"折扣率=折后成交价/原价；降价比例=1-折扣率。","boundary":"原价非零；八折折扣率80%，不是降价80%。","prompt":"折扣率=折后价÷{{0}}。","blanks":[{"answer":"原价","accept":[]}]},{"id":"ki-q-062","title":"同单价的总销售额","core":"总销售额=单件售价×实际销售件数。","boundary":"不同价格要分批累计；不能用总销售额代替扣除成本后的利润。","prompt":"同单价下总价=单价×{{0}}。","blanks":[{"answer":"件数","accept":[]}]}],"questions":[{"id":"ki-qq-015","lesson":"profit-discount","stem":"某物品成本80元、售价100元。按“利润÷售价”定义的利润率是多少？","options":["125%","25%","20%","80%"],"answer":2,"explanation":"利润100-80=20元；题目指定售价作分母，20÷100=20%。","optionReviews":["这是售价与成本之比。","这是成本利润率。","正确，使用了售价分母。","这是成本占售价的比例。"]},{"id":"ki-qq-016","lesson":"profit-discount","stem":"一件商品标价250元，按八折出售。成交价和降价幅度分别是多少？","options":["50元，80%","200元，80%","50元，20%","200元，20%"],"answer":3,"explanation":"成交价250×0.8=200元，降价50元，占原价50/250=20%。","optionReviews":["成交价与降价幅度都错。","成交价对，把折扣率当成降价幅度。","50元是少付金额，不是成交价。","正确，两种比例已区分。"]},{"id":"ki-qq-017","lesson":"profit-discount","stem":"每件成本36元、售价45元，卖出24件且无其他费用。总利润是多少？","options":["1080元","216元","864元","9元"],"answer":1,"explanation":"每件利润45-36=9元，总利润9×24=216元；也可1080-864=216元。","optionReviews":["1080元是销售额。","正确，已按件数累计。","864元是总成本。","9元只是单件利润。"]},{"id":"ki-qq-054","lesson":"profit-discount","stem":"一件商品成本120元、售价150元，按成本作分母的利润率是多少？","options":["25%","20%","125%","80%"],"answer":0,"explanation":"利润30元，成本利润率30/120=25%；20%则是按售价为分母的销售利润率。","optionReviews":["正确，利润30除成本120。","这是销售利润率。","这是售价相对成本的比例，未减去本金。","这是成本占售价的比例。"]},{"id":"ki-qq-055","lesson":"profit-discount","stem":"某商品每件成本34元、售价52元，售出18件且无其他费用。总销售额是多少？","options":["612元","936元","324元","52元"],"answer":1,"explanation":"销售额52×18=936元；612是总成本，324是总利润，不能用它们替代销售额。","optionReviews":["这是总成本34×18。","正确，总售价乘18件。","这是总利润(52-34)×18。","这是单价，未乘件数。"]}]},{"lessonId":"profit-discount","topicId":"profit","courseRoute":"#course/quant/topic/profit","sections":[{"title":"累进分段每一档只算本段","text":"阶梯累进价格需要把用量切成不重叠的档段。例如每月前8立方米每立方米2元，超过8至15的部分每立方米3元，超过15的部分每立方米5元，另收固定费4元。用量18立方米时账单为8×2+7×3+3×5+4=56元。 适用与误用：只把超出部分放入高档；用量恰在边界时，下一档数量为0。固定费只按题设次数收取。","index":14,"domId":"ki-point-0089"},{"title":"先分清全量按档与超额计费","text":"“达到某档后全部用量用该单价”与“仅超出部分加价”不同。例如用量不超过10件时每件4元，超过10件后全部按每件6元计费，买12件即12×6=72元。若改为前10件4元、超过部分6元，则为52元。起步价还需检查是否已经包含前段数量。 适用与误用：不要只看单价表就认定累进；规则文字决定是否全量重算，起步价内的用量也不能重复收费。","index":15,"domId":"ki-point-0090"}],"cards":[{"id":"ki-q-018","title":"累进分段每一档只算本段","core":"阶梯累进价格需要把用量切成不重叠的档段。例如每月前8立方米每立方米2元，超过8至15的部分每立方米3元，超过15的部分每立方米5元，另收固定费4元。用量18立方米时账单为8×2+7×3+3×5+4=56元。","boundary":"只把超出部分放入高档；用量恰在边界时，下一档数量为0。固定费只按题设次数收取。","prompt":"用量18、边界8和15时，第三档用量为{{0}}立方米。","blanks":[{"answer":"3","accept":[]}]},{"id":"ki-q-019","title":"先分清全量按档与超额计费","core":"“达到某档后全部用量用该单价”与“仅超出部分加价”不同。例如用量不超过10件时每件4元，超过10件后全部按每件6元计费，买12件即12×6=72元。若改为前10件4元、超过部分6元，则为52元。起步价还需检查是否已经包含前段数量。","boundary":"不要只看单价表就认定累进；规则文字决定是否全量重算，起步价内的用量也不能重复收费。","prompt":"超过10件后全部按每件6元计费，12件的费用为{{0}}元。","blanks":[{"answer":"72","accept":[]}]}],"questions":[{"id":"ki-qq-018","lesson":"profit-discount","stem":"某服务按累进计费：前8单位每单位2元，超过8至15部分3元，超过15部分5元，另收固定费4元。用18单位应付多少？","options":["52元","94元","44元","56元"],"answer":3,"explanation":"三档量分别8、7、3，总费用16+21+15+4=56元。","optionReviews":["这是不含固定费的分段费用。","把全部18单位按5元计价后加4元。","漏算或少算一档，不能对应三个完整区间。","正确，各段及固定费均计入。"]},{"id":"ki-qq-019","lesson":"profit-discount","stem":"某加工点规定：订单不超过10件时每件4元；超过10件时该订单全部件数按每件6元收费，无其他费用。12件应付多少？","options":["72元","64元","52元","48元"],"answer":0,"explanation":"题设为全量按档，不是累进。12件超过10件，所以12×6=72元。","optionReviews":["正确，全部12件用6元单价。","未按任何完整档位规则计算。","误按前10件4元、后2件6元累计。","仍按低档4元算全量。"]}]},{"lessonId":"geometry-scale","topicId":"geometry","courseRoute":"#course/quant/topic/geometry","sections":[{"title":"圆周长量的是边界长度","text":"半径r的圆绕一周长度为C=2πr，也可写πd，其中直径d=2r。例如半径7厘米，周长14π厘米。周长是一维长度，半径扩大两倍，周长也扩大两倍。 适用与误用：不要把半径当直径；周长单位是厘米等长度单位，不是平方厘米。","index":9,"domId":"ki-point-0091"},{"title":"弧长按圆心角分整圆","text":"同圆内弧长与所对圆心角成正比。角度用度时，弧长l=2πr×θ/360。例如r=10厘米、θ=72°，占整圆1/5，弧长为4π厘米。 适用与误用：公式中的360对应角度制；弧度制用l=rθ。扇形周长还含两条半径，不能只算弧长。","index":10,"domId":"ki-point-0092"},{"title":"圆面积随半径平方变化","text":"圆所占平面大小为S=πr²。例如半径6米，面积36π平方米；若半径加倍到12米，面积变为144π平方米，是原来的4倍。平方来自两个方向同时放大。 适用与误用：面积与周长不是同一量；给直径时先除2，平方单位必须与半径单位一致。","index":11,"domId":"ki-point-0093"},{"title":"三角形底与对应高成一组","text":"三角形面积为S=bh/2，其中h是选定底边所在直线到对顶点的垂直距离。例如底13厘米、对应高8厘米，面积为52平方厘米。斜边长不是高，钝角三角形的高可落在底边延长线上。 适用与误用：必须配对同一条底和相应高；换底后不能沿用原来的高。","index":12,"domId":"ki-point-0094"},{"title":"菱形用两条对角线求面积","text":"菱形的两条对角线相互垂直并互相平分，可把它分成四个直角三角形，合并得S=d1d2/2。例如两条对角线12厘米、16厘米，面积为96平方厘米。 适用与误用：两条数据应当是完整对角线长度，不是半条；一般平行四边形的对角线不垂直，不能无条件照搬。","index":13,"domId":"ki-point-0095"},{"title":"封闭圆柱表面积包括两底和侧面","text":"半径r、高h的封闭直圆柱，两个圆底面积为2πr²；侧面展开为长2πr、宽h的矩形，面积2πrh。总表面积2πr²+2πrh。例如r=3分米、h=7分米，总表面积18π+42π=60π平方分米。 适用与误用：题目若无盖只算一个底，无上下底只算侧面；高是两底面之间的垂直距离。","index":14,"domId":"ki-point-0096"},{"title":"球表面积只看半径平方","text":"球面面积为S=4πr²。例如半径5厘米，球表面积100π平方厘米，恰为同半径圆面积的4倍。这里的球面是三维物体的边界，其面积仍是平方单位。 适用与误用：球表面积不是体积；直径给出时先折成半径，不能用4πr³/3代替。","index":15,"domId":"ki-point-0097"},{"title":"锥体积是同底同高柱体的三分之一","text":"任何锥体的体积都可用V=Sh/3，S是底面积，h是顶点到底面所在平面的垂直距离。例如底面积54平方米、高8米，体积144立方米；对应柱体为432立方米。圆锥也可先用πr²算底面积。 适用与误用：斜高不等于垂直高；面积和高单位须配套，结果为立方单位，圆锥与棱锥均适用。","index":16,"domId":"ki-point-0098"},{"title":"球体积随半径立方变化","text":"半径r的球体积为V=4πr³/3。例如r=3米，体积4π×27/3=36π立方米。半径扩大2倍，体积扩大8倍，而球面面积扩大4倍，两种尺度不能混淆。 适用与误用：体积用立方单位；直径的立方须先除以8，即V=πd³/6，不能把直径直接替换r。","index":17,"domId":"ki-point-0099"}],"cards":[{"id":"ki-q-020","title":"圆周长量的是边界长度","core":"半径r的圆绕一周长度为C=2πr，也可写πd，其中直径d=2r。例如半径7厘米，周长14π厘米。周长是一维长度，半径扩大两倍，周长也扩大两倍。","boundary":"不要把半径当直径；周长单位是厘米等长度单位，不是平方厘米。","prompt":"半径为r的圆，周长C={{0}}。","blanks":[{"answer":"2πr","accept":["2*pi*r","2π×r"]}]},{"id":"ki-q-021","title":"弧长按圆心角分整圆","core":"同圆内弧长与所对圆心角成正比。角度用度时，弧长l=2πr×θ/360。例如r=10厘米、θ=72°，占整圆1/5，弧长为4π厘米。","boundary":"公式中的360对应角度制；弧度制用l=rθ。扇形周长还含两条半径，不能只算弧长。","prompt":"角度制下弧长l=2πr×{{0}}。","blanks":[{"answer":"θ/360","accept":[]}]},{"id":"ki-q-022","title":"圆面积随半径平方变化","core":"圆所占平面大小为S=πr²。例如半径6米，面积36π平方米；若半径加倍到12米，面积变为144π平方米，是原来的4倍。平方来自两个方向同时放大。","boundary":"面积与周长不是同一量；给直径时先除2，平方单位必须与半径单位一致。","prompt":"半径为r的圆，面积S={{0}}。","blanks":[{"answer":"πr²","accept":["πr^2","pi*r^2"]}]},{"id":"ki-q-023","title":"三角形底与对应高成一组","core":"三角形面积为S=bh/2，其中h是选定底边所在直线到对顶点的垂直距离。例如底13厘米、对应高8厘米，面积为52平方厘米。斜边长不是高，钝角三角形的高可落在底边延长线上。","boundary":"必须配对同一条底和相应高；换底后不能沿用原来的高。","prompt":"三角形面积等于底乘对应垂直高再除以{{0}}。","blanks":[{"answer":"2","accept":[]}]},{"id":"ki-q-024","title":"菱形用两条对角线求面积","core":"菱形的两条对角线相互垂直并互相平分，可把它分成四个直角三角形，合并得S=d1d2/2。例如两条对角线12厘米、16厘米，面积为96平方厘米。","boundary":"两条数据应当是完整对角线长度，不是半条；一般平行四边形的对角线不垂直，不能无条件照搬。","prompt":"菱形面积等于两条对角线乘积的{{0}}。","blanks":[{"answer":"一半","accept":[]}]},{"id":"ki-q-025","title":"封闭圆柱表面积包括两底和侧面","core":"半径r、高h的封闭直圆柱，两个圆底面积为2πr²；侧面展开为长2πr、宽h的矩形，面积2πrh。总表面积2πr²+2πrh。例如r=3分米、h=7分米，总表面积18π+42π=60π平方分米。","boundary":"题目若无盖只算一个底，无上下底只算侧面；高是两底面之间的垂直距离。","prompt":"封闭直圆柱总表面积为2πr²加{{0}}。","blanks":[{"answer":"2πrh","accept":[]}]},{"id":"ki-q-026","title":"球表面积只看半径平方","core":"球面面积为S=4πr²。例如半径5厘米，球表面积100π平方厘米，恰为同半径圆面积的4倍。这里的球面是三维物体的边界，其面积仍是平方单位。","boundary":"球表面积不是体积；直径给出时先折成半径，不能用4πr³/3代替。","prompt":"半径为r的球，表面积S={{0}}。","blanks":[{"answer":"4πr²","accept":["4πr^2","4*pi*r^2"]}]},{"id":"ki-q-027","title":"锥体积是同底同高柱体的三分之一","core":"任何锥体的体积都可用V=Sh/3，S是底面积，h是顶点到底面所在平面的垂直距离。例如底面积54平方米、高8米，体积144立方米；对应柱体为432立方米。圆锥也可先用πr²算底面积。","boundary":"斜高不等于垂直高；面积和高单位须配套，结果为立方单位，圆锥与棱锥均适用。","prompt":"锥体积等于底面积乘垂直高再除以{{0}}。","blanks":[{"answer":"3","accept":[]}]},{"id":"ki-q-028","title":"球体积随半径立方变化","core":"半径r的球体积为V=4πr³/3。例如r=3米，体积4π×27/3=36π立方米。半径扩大2倍，体积扩大8倍，而球面面积扩大4倍，两种尺度不能混淆。","boundary":"体积用立方单位；直径的立方须先除以8，即V=πd³/6，不能把直径直接替换r。","prompt":"球体积V={{0}}。","blanks":[{"answer":"4πr³/3","accept":["4πr^3/3","4*pi*r^3/3"]}]}],"questions":[{"id":"ki-qq-020","lesson":"geometry-scale","stem":"半径为7厘米的圆，周长是多少？","options":["14π平方厘米","14π厘米","49π厘米","7π厘米"],"answer":1,"explanation":"直径是14厘米，周长πd=14π厘米；49π是该圆面积的数值。","optionReviews":["数值对，但周长不能用面积单位。","正确，长度公式与单位都对。","套用了面积公式。","只用πr，少乘了周长公式中的因子2。"]},{"id":"ki-qq-021","lesson":"geometry-scale","stem":"半径10厘米、圆心角72°的扇形，其弧长是多少？","options":["4π厘米","20π厘米","2π厘米","(20+4π)厘米"],"answer":0,"explanation":"72/360=1/5，圆周长20π，弧长20π÷5=4π厘米。","optionReviews":["正确，整周长乘所占角度比例。","这是整圆周长。","少算了一半弧长。","这是扇形周长，不是弧长。"]},{"id":"ki-qq-022","lesson":"geometry-scale","stem":"圆的直径为12米，其面积是多少？","options":["12π平方米","36π平方米","144π平方米","24π平方米"],"answer":1,"explanation":"半径12÷2=6米，面积π×6²=36π平方米。","optionReviews":["将直径直接作面积系数。","正确，先把直径折成半径。","把直径12当成半径再平方。","混用周长公式。"]},{"id":"ki-qq-023","lesson":"geometry-scale","stem":"三角形一条底边长13厘米，对应该底的高为8厘米，面积是多少？","options":["169平方厘米","52平方厘米","104平方厘米","21平方厘米"],"answer":1,"explanation":"底高乘积104，三角形取其一半，面积52平方厘米。","optionReviews":["把底边平方，未使用高。","正确，用对应底高。","漏除以2，算成平行四边形面积。","把底和高相加。"]},{"id":"ki-qq-024","lesson":"geometry-scale","stem":"菱形两条完整对角线分别长12厘米和16厘米，面积是多少？","options":["96平方厘米","400平方厘米","192平方厘米","48平方厘米"],"answer":0,"explanation":"四个小直角三角形各面积6×8÷2=24，总面积96。","optionReviews":["正确，12×16÷2=96。","两条对角线平方相加不是面积公式。","漏了除以2。","只算了菱形的一半。"]},{"id":"ki-qq-025","lesson":"geometry-scale","stem":"封闭直圆柱半径3分米、高7分米，总表面积是多少？","options":["51π平方分米","60π平方分米","63π平方分米","42π平方分米"],"answer":1,"explanation":"两底合计2×9π=18π，侧面2×3π×7=42π，总计60π平方分米。","optionReviews":["只计了一个底面，适用于无盖情形。","正确，两个底面与侧面齐全。","把体积πr²h当作表面积系数。","42π仅是圆柱侧面积，没有计入两个圆形底面。"]},{"id":"ki-qq-026","lesson":"geometry-scale","stem":"球的半径为5厘米，其表面积是多少？","options":["20π平方厘米","500π/3平方厘米","25π平方厘米","100π平方厘米"],"answer":3,"explanation":"表面积4π×5²=100π平方厘米。","optionReviews":["将r平方漏掉。","用球体积的系数并配错单位。","只算同半径圆的面积。","正确，球面是同半径圆面积的4倍。"]},{"id":"ki-qq-027","lesson":"geometry-scale","stem":"某棱锥底面积54平方米，垂直高8米，体积是多少？","options":["72立方米","216立方米","144立方米","432立方米"],"answer":2,"explanation":"V=54×8÷3=144立方米。","optionReviews":["额外多除了一次2。","误用1/2系数。","正确，使用锥体积系数1/3。","这是同底同高柱体的体积。"]},{"id":"ki-qq-028","lesson":"geometry-scale","stem":"一个球直径6米，其体积是多少？","options":["288π立方米","36π立方米","72π立方米","12π立方米"],"answer":1,"explanation":"半径3米，体积(4/3)π×3³=36π立方米。","optionReviews":["把直径6直接当半径。","正确，半径与立方计算都对。","体积多算一倍。","遗漏r的三次方。"]}]},{"lessonId":"geometry-scale","topicId":"geometry","courseRoute":"#course/quant/topic/geometry","sections":[{"title":"平面割补需要记下加减的部分","text":"复杂面积可以拆成互不重叠的小块相加，也可放进标准大图形后减去缺口。例如11米×8米矩形去掉一角4米×3米的小矩形，余下面积88-12=76平方米；也能拆成11×5与7×3两块，55+21=76。平移、旋转保留每块面积。 适用与误用：合并面积时要避免重叠，补进去的部分必须扣回；同面积不代表相同周长。","index":18,"domId":"ki-point-0100"},{"title":"体积分块守恒不能推成表面积守恒","text":"立体可以用大块减缺口、分成棱柱相加或平移重组求体积。例如8×5×4厘米的长方体沿一角挖去3×2×4厘米的长方体，剩160-24=136立方厘米。把剩余分为8×3×4和5×2×4也得136。 适用与误用：体积相加要求各块内部不重叠；拼接后接触面会变内部面，所以表面积通常不能按体积守恒直接处理。","index":19,"domId":"ki-point-0101"}],"cards":[{"id":"ki-q-029","title":"平面割补需要记下加减的部分","core":"复杂面积可以拆成互不重叠的小块相加，也可放进标准大图形后减去缺口。例如11米×8米矩形去掉一角4米×3米的小矩形，余下面积88-12=76平方米；也能拆成11×5与7×3两块，55+21=76。平移、旋转保留每块面积。","boundary":"合并面积时要避免重叠，补进去的部分必须扣回；同面积不代表相同周长。","prompt":"补成大图形后，原图面积等于大图面积{{0}}补入部分面积。","blanks":[{"answer":"减去","accept":[]}]},{"id":"ki-q-030","title":"体积分块守恒不能推成表面积守恒","core":"立体可以用大块减缺口、分成棱柱相加或平移重组求体积。例如8×5×4厘米的长方体沿一角挖去3×2×4厘米的长方体，剩160-24=136立方厘米。把剩余分为8×3×4和5×2×4也得136。","boundary":"体积相加要求各块内部不重叠；拼接后接触面会变内部面，所以表面积通常不能按体积守恒直接处理。","prompt":"可加体积分块时，各部分内部应当{{0}}。","blanks":[{"answer":"不重叠","accept":[]}]}],"questions":[{"id":"ki-qq-029","lesson":"geometry-scale","stem":"11米×8米的长方形去掉角上一块4米×3米长方形，剩余面积是多少？","options":["84平方米","100平方米","64平方米","76平方米"],"answer":3,"explanation":"外框88平方米，缺口12平方米，剩76；拆成11×5和7×3也得76。","optionReviews":["只减4而不是减去面积12。","把挖去改成补入。","多扣了缺口。","正确，缺口只减一次。"]},{"id":"ki-qq-030","lesson":"geometry-scale","stem":"一个8厘米×5厘米×4厘米长方体沿角挖去3厘米×2厘米×4厘米的一块，剩余体积是多少？","options":["136立方厘米","96立方厘米","124立方厘米","184立方厘米"],"answer":0,"explanation":"总体积160，挖去24，余136；也可96+40=136。","optionReviews":["正确，两个不重叠剩余块体积相加相符。","只算了8×3×4的其中一块。","误算被挖去体积。","把挖去部分加回去了。"]}]},{"lessonId":"geometry-scale","topicId":"geometry","courseRoute":"#course/quant/topic/geometry","sections":[{"title":"三角形第三边在严格区间内","text":"若两边为a、b，第三边c必须满足|a-b|<c<a+b。这同时包含两边之和超过第三边、任两边之差小于第三边。例如两边4和7时，3<c<11；若第三边要求整数，可取4至10，共7种。 适用与误用：两端都不能取等号；等号对应三点共线的退化形状，不是题目通常指的三角形。","index":20,"domId":"ki-point-0102"},{"title":"勾股定理先找斜边","text":"直角三角形两条直角边a、b和斜边c满足a²+b²=c²，斜边在直角对面且最长。例如两直角边9和40，斜边平方为81+1600=1681，所以斜边41。已知斜边求直角边则做平方差。 适用与误用：需要题设直角或另有证据证明直角；不能把任意三角形的两边平方和当第三边平方。","index":21,"domId":"ki-point-0103"},{"title":"勾股数组要按同一倍数伸缩","text":"3、4、5和5、12、13等整数组满足勾股关系，可将三边同时乘同一正数得到相似直角三角形。例如5:12:13同比例放大3倍得到15:36:39。数组只帮助识别与计算，不会把不满足边角条件的图形自动变直角。 适用与误用：不能只放大一两条边；最长边对应斜边，并可用平方检验避免记错数组。","index":22,"domId":"ki-point-0104"},{"title":"三十、六十、九十度的对边比例","text":"30°、60°、90°三角形中，对应三角的边比依次是1:√3:2。因此30°所对短直角边是斜边一半，60°所对的另一条直角边是短边的√3倍。例如短边7，则长直角边7√3、斜边14。 适用与误用：1:√3:2按30°、60°、90°的对边排列，不按图上左右顺序；斜边始终对90°。","index":23,"domId":"ki-point-0105"},{"title":"四十五度直角三角形两腰相等","text":"45°、45°、90°三角形为等腰直角三角形，两直角边与斜边比1:1:√2。例如两直角边都是6厘米，斜边6√2厘米；若给斜边，则各直角边等于斜边除以√2。 适用与误用：√2对应斜边；不能把两条相等的边当成斜边与直角边，也不要误用30°三角形的倍半关系。","index":24,"domId":"ki-point-0106"}],"cards":[{"id":"ki-q-031","title":"三角形第三边在严格区间内","core":"若两边为a、b，第三边c必须满足|a-b|<c<a+b。这同时包含两边之和超过第三边、任两边之差小于第三边。例如两边4和7时，3<c<11；若第三边要求整数，可取4至10，共7种。","boundary":"两端都不能取等号；等号对应三点共线的退化形状，不是题目通常指的三角形。","prompt":"已知两边4和7，第三边c的范围是{{0}}。","blanks":[{"answer":"3<c<11","accept":[]}]},{"id":"ki-q-032","title":"勾股定理先找斜边","core":"直角三角形两条直角边a、b和斜边c满足a²+b²=c²，斜边在直角对面且最长。例如两直角边9和40，斜边平方为81+1600=1681，所以斜边41。已知斜边求直角边则做平方差。","boundary":"需要题设直角或另有证据证明直角；不能把任意三角形的两边平方和当第三边平方。","prompt":"直角三角形直角边a、b和斜边c满足{{0}}。","blanks":[{"answer":"a²+b²=c²","accept":["a^2+b^2=c^2"]}]},{"id":"ki-q-033","title":"勾股数组要按同一倍数伸缩","core":"3、4、5和5、12、13等整数组满足勾股关系，可将三边同时乘同一正数得到相似直角三角形。例如5:12:13同比例放大3倍得到15:36:39。数组只帮助识别与计算，不会把不满足边角条件的图形自动变直角。","boundary":"不能只放大一两条边；最长边对应斜边，并可用平方检验避免记错数组。","prompt":"5:12:13三边都扩大3倍后，斜边为{{0}}。","blanks":[{"answer":"39","accept":[]}]},{"id":"ki-q-034","title":"三十、六十、九十度的对边比例","core":"30°、60°、90°三角形中，对应三角的边比依次是1:√3:2。因此30°所对短直角边是斜边一半，60°所对的另一条直角边是短边的√3倍。例如短边7，则长直角边7√3、斜边14。","boundary":"1:√3:2按30°、60°、90°的对边排列，不按图上左右顺序；斜边始终对90°。","prompt":"30°、60°、90°的对边依次成比{{0}}。","blanks":[{"answer":"1:√3:2","accept":["1:根号3:2"]}]},{"id":"ki-q-035","title":"四十五度直角三角形两腰相等","core":"45°、45°、90°三角形为等腰直角三角形，两直角边与斜边比1:1:√2。例如两直角边都是6厘米，斜边6√2厘米；若给斜边，则各直角边等于斜边除以√2。","boundary":"√2对应斜边；不能把两条相等的边当成斜边与直角边，也不要误用30°三角形的倍半关系。","prompt":"等腰直角三角形直角边为a时，斜边是{{0}}。","blanks":[{"answer":"a√2","accept":["a*sqrt(2)","a根号2"]}]}],"questions":[{"id":"ki-qq-031","lesson":"geometry-scale","stem":"一个三角形两边长为4和7，第三边长为整数。第三边有多少种可能？","options":["7种","6种","8种","9种"],"answer":0,"explanation":"第三边应严格大于3且严格小于11，整数4、5、6、7、8、9、10，共7种。","optionReviews":["正确，严格区间内有7个整数。","漏掉了一个合法端内整数。","把一个等号端点也算进来。","把3和11两个退化端点都算入。"]},{"id":"ki-qq-032","lesson":"geometry-scale","stem":"直角三角形两条直角边长9厘米与40厘米，斜边长多少？","options":["31厘米","41厘米","1681厘米","49厘米"],"answer":1,"explanation":"斜边c=√(9²+40²)=√1681=41厘米。","optionReviews":["直接相减，未使用平方关系。","正确，41²=1681。","这是斜边平方，不是斜边长度。","直接相加，是周长中的两边和。"]},{"id":"ki-qq-033","lesson":"geometry-scale","stem":"直角三角形两条直角边为15和36，哪组完整边长与之对应？","options":["15、36、41","15、36、51","15、36、39","15、36、37"],"answer":2,"explanation":"15=5×3、36=12×3，斜边13×3=39；平方检验225+1296=1521=39²。","optionReviews":["41²不等于1521。","51是两直角边之和，会退化而非成三角形。","正确，同一勾股数组同比例扩展。","37²不等于1521。"]},{"id":"ki-qq-034","lesson":"geometry-scale","stem":"在30°、60°、90°三角形中，30°所对边长7厘米。另一直角边和斜边分别是多少？","options":["14厘米、7√3厘米","7√2厘米、14厘米","7厘米、7√2厘米","7√3厘米、14厘米"],"answer":3,"explanation":"短边7对应比中的1，60°对边为7√3，斜边为2×7=14。","optionReviews":["颠倒两条边，斜边反而不是最长。","7²+(7√2)²=147，不等于14²。","这是45°直角三角形的形式。","正确，边角配对与勾股关系都成立。"]},{"id":"ki-qq-035","lesson":"geometry-scale","stem":"等腰直角三角形一条直角边长6厘米，斜边长是多少？","options":["12厘米","6√2厘米","3√2厘米","6厘米"],"answer":1,"explanation":"两直角边均6，斜边平方36+36=72，斜边6√2。","optionReviews":["把两直角边长度直接相加。","正确，斜边为直角边的√2倍。","这是把给定6误当斜边后求直角边。","斜边应大于每条直角边。"]}]},{"lessonId":"geometry-scale","topicId":"geometry","courseRoute":"#course/quant/topic/geometry","sections":[{"title":"同底时用高的比例比较面积","text":"两三角形有相同底长b时，面积分别为bh1/2和bh2/2，约去公共因子得S1:S2=h1:h2。例如同底且高为5厘米和8厘米，面积比5:8。高必须是到相同底所在直线的垂直距离。 适用与误用：共享一个顶点或底边看起来接近，不等于同底；斜线长度不能替代高。","index":25,"domId":"ki-point-0107"},{"title":"同高时用底的比例比较面积","text":"两三角形到各自底的垂直高相同，面积比等于底边长度比。例如同高的两三角形底为6米、15米，面积比6:15=2:5。可以不先求公共高的具体数值。 适用与误用：必须确认的是对应高相等，不是任意两条边相等；不同方向选底仍应分别配对各自高。","index":26,"domId":"ki-point-0108"},{"title":"平面相似的面积取长度比平方","text":"全图形按同一尺度放大时，每个方向的长度都乘k，面积就乘k²。例如相似图形对应边乙:甲=3:2，若甲面积18，乙面积18×(3/2)²=40.5。周长只乘k，不应也平方。 适用与误用：仅一条边变长但角度或其他方向不成比例时，不能套相似面积规律；先核对相似及比例方向。","index":27,"domId":"ki-point-0109"},{"title":"全尺寸相似才用立方体积比","text":"立体的长、宽、高等全部线性尺寸按k放大，体积才乘k³。例如两个相似容器的对应长度小:大=2:5，体积比8:125。若只将长方体的高变成原来2倍而底面积不变，体积只变2倍，不是8倍。 适用与误用：“高的比”或“半径的比”单独一项不够证明立体全尺寸相似；圆柱半径与高都需同比例变化。","index":28,"domId":"ki-point-0110"}],"cards":[{"id":"ki-q-036","title":"同底时用高的比例比较面积","core":"两三角形有相同底长b时，面积分别为bh1/2和bh2/2，约去公共因子得S1:S2=h1:h2。例如同底且高为5厘米和8厘米，面积比5:8。高必须是到相同底所在直线的垂直距离。","boundary":"共享一个顶点或底边看起来接近，不等于同底；斜线长度不能替代高。","prompt":"同底三角形的面积比等于对应的{{0}}。","blanks":[{"answer":"高比","accept":[]}]},{"id":"ki-q-037","title":"同高时用底的比例比较面积","core":"两三角形到各自底的垂直高相同，面积比等于底边长度比。例如同高的两三角形底为6米、15米，面积比6:15=2:5。可以不先求公共高的具体数值。","boundary":"必须确认的是对应高相等，不是任意两条边相等；不同方向选底仍应分别配对各自高。","prompt":"同高三角形的面积比等于对应的{{0}}。","blanks":[{"answer":"底比","accept":[]}]},{"id":"ki-q-038","title":"平面相似的面积取长度比平方","core":"全图形按同一尺度放大时，每个方向的长度都乘k，面积就乘k²。例如相似图形对应边乙:甲=3:2，若甲面积18，乙面积18×(3/2)²=40.5。周长只乘k，不应也平方。","boundary":"仅一条边变长但角度或其他方向不成比例时，不能套相似面积规律；先核对相似及比例方向。","prompt":"相似图形对应长度比为k时，面积比为{{0}}。","blanks":[{"answer":"k²","accept":["k^2"]}]},{"id":"ki-q-039","title":"全尺寸相似才用立方体积比","core":"立体的长、宽、高等全部线性尺寸按k放大，体积才乘k³。例如两个相似容器的对应长度小:大=2:5，体积比8:125。若只将长方体的高变成原来2倍而底面积不变，体积只变2倍，不是8倍。","boundary":"“高的比”或“半径的比”单独一项不够证明立体全尺寸相似；圆柱半径与高都需同比例变化。","prompt":"全尺寸相似立体的对应长度比k，体积比是{{0}}。","blanks":[{"answer":"k³","accept":["k^3"]}]}],"questions":[{"id":"ki-qq-036","lesson":"geometry-scale","stem":"两个三角形共用同一条底边，对应高分别为5厘米、8厘米。面积比S甲:S乙是多少？","options":["5:8","1:1","25:64","8:5"],"answer":0,"explanation":"同底的公共底长与1/2约去，面积比直接等于5:8。","optionReviews":["正确，同底只比较对应高。","忽略了高不同。","这是误套相似图形的平方比。","将顺序颠倒。"]},{"id":"ki-qq-037","lesson":"geometry-scale","stem":"两个同高三角形的底分别为6米和15米，面积比是多少？","options":["2:5","5:2","4:25","1:3"],"answer":0,"explanation":"共同的高与1/2消去，6:15约为2:5。","optionReviews":["正确，只需约分底比。","比例顺序反了。","把一维底比错误平方。","6:15不等于1:3。"]},{"id":"ki-qq-038","lesson":"geometry-scale","stem":"甲乙两个相似图形，对应边乙:甲=3:2，甲面积18平方厘米。乙面积是多少？","options":["40.5平方厘米","36平方厘米","27平方厘米","60.75平方厘米"],"answer":0,"explanation":"乙相对甲的长度倍数3/2，面积倍数9/4，18×9/4=40.5。","optionReviews":["正确，面积乘长度比平方。","随意乘2，不是9/4。","只乘长度倍数。","多乘了一次3/2，误用了立方。"]},{"id":"ki-qq-039","lesson":"geometry-scale","stem":"两个全尺寸相似立体，对应长度小:大=2:5，体积比是多少？","options":["2:5","16:625","4:25","8:125"],"answer":3,"explanation":"三个方向都按2:5缩放，体积比(2/5)³=8/125。","optionReviews":["只比较长度，遗漏另外两个方向。","错误使用了长度比的四次方，体积比应当取三次方。","这是面积比。","正确，体积使用立方比。"]}]},{"lessonId":"count","topicId":"counting","courseRoute":"#course/quant/topic/counting","sections":[{"title":"分类计数先保证不重不漏","text":"完成同一目标有几个互斥的类别时，把每类方案数相加。例如只选一张卡片，可从4张红卡或6张蓝卡中选，卡片彼此可区分，一共4+6=10种。若类别之间重叠，要先处理重复，分类遗漏也会少算。 适用与误用：分类相加针对择一完成的路径，不是把连续做两件事的步骤相加。","index":12,"domId":"ki-point-0111"},{"title":"分步相乘时随前一步更新选择数","text":"完成一个结果需依次作多步选择，各步选择数相乘。如果后一步数量随前一步变化，可以逐支相乘再相加。例如用1、2、3、4组成两位且不重复的编号，首位4种，次位剩3种，共12种。 适用与误用：“每步相乘”不意味着次位仍有4种；有禁选、资源消耗、分支不同等条件时要更新可选数。","index":13,"domId":"ki-point-0112"},{"title":"有序岗位用排列，无序成组用组合","text":"从n个不同对象取m个，不同顺序算新结果时，排列数A(n,m)=n!/(n-m)!；只看成员集合时，组合数C(n,m)=n!/[m!(n-m)!]。例如5人中选2名普通成员有10种，选组长和副组长则有20种。 适用与误用：是否有顺序由实际结果决定，不由题目写“选”还是“排”决定；组长、副组长岗位不同，即便只是两个人也要区分交换。","index":14,"domId":"ki-point-0113"}],"cards":[{"id":"ki-q-040","title":"分类计数先保证不重不漏","core":"完成同一目标有几个互斥的类别时，把每类方案数相加。例如只选一张卡片，可从4张红卡或6张蓝卡中选，卡片彼此可区分，一共4+6=10种。若类别之间重叠，要先处理重复，分类遗漏也会少算。","boundary":"分类相加针对择一完成的路径，不是把连续做两件事的步骤相加。","prompt":"互不重叠且覆盖全部情况的分类，方案数应当{{0}}。","blanks":[{"answer":"相加","accept":[]}]},{"id":"ki-q-041","title":"分步相乘时随前一步更新选择数","core":"完成一个结果需依次作多步选择，各步选择数相乘。如果后一步数量随前一步变化，可以逐支相乘再相加。例如用1、2、3、4组成两位且不重复的编号，首位4种，次位剩3种，共12种。","boundary":"“每步相乘”不意味着次位仍有4种；有禁选、资源消耗、分支不同等条件时要更新可选数。","prompt":"用4个不同数字组成两位不重复编号，共4×{{0}}种。","blanks":[{"answer":"3","accept":[]}]},{"id":"ki-q-042","title":"有序岗位用排列，无序成组用组合","core":"从n个不同对象取m个，不同顺序算新结果时，排列数A(n,m)=n!/(n-m)!；只看成员集合时，组合数C(n,m)=n!/[m!(n-m)!]。例如5人中选2名普通成员有10种，选组长和副组长则有20种。","boundary":"是否有顺序由实际结果决定，不由题目写“选”还是“排”决定；组长、副组长岗位不同，即便只是两个人也要区分交换。","prompt":"从5人中选组长和副组长，属于{{0}}，不能将交换两岗位视为相同结果。","blanks":[{"answer":"排列","accept":[]}]},{"id":"ki-q-063","title":"有序抽取的排列公式","core":"从n个不同对象不重复取m个并区分顺序，方案数A(n,m)=n!/(n-m)!。","boundary":"要求0≤m≤n；重复抽取或完全不区分顺序要换模型。","prompt":"n个不同对象不重复有序取m个，排列数A(n,m)={{0}}。","blanks":[{"answer":"n!/(n-m)!","accept":[]}]},{"id":"ki-q-064","title":"无序抽取的组合公式","core":"从n个不同对象不重复选m个，只记录成员集合，方案数C(n,m)=n!/[m!(n-m)!]。","boundary":"不区分顺序，所以需将排列数除m!；对象本身相同不能照搬。","prompt":"无序组合数C(n,m)=A(n,m)÷{{0}}。","blanks":[{"answer":"m!","accept":[]}]}],"questions":[{"id":"ki-qq-040","lesson":"count","stem":"桌上有4张不同红卡、6张不同蓝卡，只选其中1张，共多少种选法？","options":["10种","24种","2种","60种"],"answer":0,"explanation":"选红卡与选蓝卡互斥且穷尽，总数4+6=10。","optionReviews":["正确，两类不重不漏。","4×6对应同时各选一张。","只数颜色，丢失卡片的可区分性。","将相加结果再无依据放大。"]},{"id":"ki-qq-041","lesson":"count","stem":"只用数字1、2、3、4组成两位编号，每个数字最多用一次，共多少种编号？","options":["6种","8种","16种","12种"],"answer":3,"explanation":"首位4种，每选定一位后次位只剩3种，所以4×3=12。","optionReviews":["将顺序不同错误合并。","并非每个首位只有2个后续选择。","允许重复时才有4×4=16。","正确，每一步的可选数均已更新。"]},{"id":"ki-qq-042","lesson":"count","stem":"5名不同成员中，选2名普通代表与选组长、副组长，各有多少种方法？","options":["20种、10种","10种、10种","20种、20种","10种、20种"],"answer":3,"explanation":"普通代表只看两人集合，C(5,2)=10；两个不同岗位有序，A(5,2)=5×4=20。","optionReviews":["把两个任务的顺序要求颠倒了。","第二个任务漏计岗位交换。","第一个任务把同一代表集合重复算两遍。","正确，无序10，有序20。"]}]},{"lessonId":"count","topicId":"counting","courseRoute":"#course/quant/topic/counting","sections":[{"title":"相邻捆块还要排列块内成员","text":"要求若干特定对象连续在一起，可以把它们合成一个大块，与其他对象一起排；再乘块内允许的排列数。例如5个不同人中甲乙相邻，将甲乙视为一块，外部4!种、内部2!种，共48种。 适用与误用：块内若另有顺序限制应相应减少；多个重叠相邻条件不能不加分析地各自捆块相乘。","index":15,"domId":"ki-point-0114"},{"title":"不相邻先排其他人再选空隙","text":"让m个指定对象两两不相邻，先排其余n个对象，再从n+1个空隙中选择m个位置，每个空隙最多放一个指定对象，最后排指定对象。例：4名不同男生与3名不同女生且女生互不相邻，有4!×C(5,3)×3!=1440种。 适用与误用：前后两端也算空隙；指定对象多于空隙时无解。对象不同需计内部排列，同类相同则不要多乘阶乘。","index":16,"domId":"ki-point-0115"},{"title":"正整数分配用内部空位插板","text":"n个相同对象分给m个有标签的组，每组至少1个，可把n个对象排成一行，在内部n-1个空位选m-1处放隔板，因此有C(n-1,m-1)种。例如11个相同球给4个有标签盒且都非空，有C(10,3)=120种。 适用与误用：要求n≥m≥1、对象相同、组有标签、每组至少1个。允许空组要先改模型；无标签组不能直接用此公式。","index":17,"domId":"ki-point-0116"}],"cards":[{"id":"ki-q-043","title":"相邻捆块还要排列块内成员","core":"要求若干特定对象连续在一起，可以把它们合成一个大块，与其他对象一起排；再乘块内允许的排列数。例如5个不同人中甲乙相邻，将甲乙视为一块，外部4!种、内部2!种，共48种。","boundary":"块内若另有顺序限制应相应减少；多个重叠相邻条件不能不加分析地各自捆块相乘。","prompt":"6人排一行、甲乙相邻，先按5个单位排列，再乘甲乙内部的{{0}}种次序。","blanks":[{"answer":"2","accept":[]}]},{"id":"ki-q-044","title":"不相邻先排其他人再选空隙","core":"让m个指定对象两两不相邻，先排其余n个对象，再从n+1个空隙中选择m个位置，每个空隙最多放一个指定对象，最后排指定对象。例：4名不同男生与3名不同女生且女生互不相邻，有4!×C(5,3)×3!=1440种。","boundary":"前后两端也算空隙；指定对象多于空隙时无解。对象不同需计内部排列，同类相同则不要多乘阶乘。","prompt":"先排n个其他对象，含两端共有{{0}}个空隙。","blanks":[{"answer":"n+1","accept":[]}]},{"id":"ki-q-045","title":"正整数分配用内部空位插板","core":"n个相同对象分给m个有标签的组，每组至少1个，可把n个对象排成一行，在内部n-1个空位选m-1处放隔板，因此有C(n-1,m-1)种。例如11个相同球给4个有标签盒且都非空，有C(10,3)=120种。","boundary":"要求n≥m≥1、对象相同、组有标签、每组至少1个。允许空组要先改模型；无标签组不能直接用此公式。","prompt":"n个相同对象分给m个有标签组且每组至少1个，方案数为{{0}}。","blanks":[{"answer":"C(n-1,m-1)","accept":["组合C(n-1,m-1)"]}]}],"questions":[{"id":"ki-qq-043","lesson":"count","stem":"6名不同人员排成一行，其中甲乙必须相邻，其余无约束，共多少种排法？","options":["240种","720种","120种","360种"],"answer":0,"explanation":"捆甲乙后成为5个单位，有5!=120种；甲乙、乙甲两种内序，所以240种。","optionReviews":["正确，外部排列乘块内排列。","720是无相邻限制的6!。","漏乘块内2种次序。","不能将全部排列任意取一半。"]},{"id":"ki-qq-044","lesson":"count","stem":"5名不同人员排一行，要求甲乙不相邻。按先排其余3人再插空，排法数是多少？","options":["48种","72种","36种","120种"],"answer":1,"explanation":"其他3人有3!种排法，形成4个空隙，选2个放甲乙有C(4,2)种，甲乙再换序2!种，合计6×6×2=72。","optionReviews":["这是甲乙相邻的排法数4!×2。","正确，含两端4空隙并计甲乙顺序。","漏乘甲乙的内部顺序。","这是没有限制的全部5!种。"]},{"id":"ki-qq-045","lesson":"count","stem":"9个完全相同的小球放入甲乙丙3个有标签盒，每盒至少1个，共多少种分配？","options":["21种","27种","55种","28种"],"answer":3,"explanation":"9个球内部有8个空位，选2处插板，C(8,2)=28；也等于正整数解a+b+c=9的数量。","optionReviews":["少计了部分正整数分配。","27比正整数解枚举得到的28少1，漏掉了合法分配；不能把球视为可区分对象后再任意缩减。","这是允许空盒时C(11,2)的数量。","正确，C(8,2)=28。"]}]},{"lessonId":"count","topicId":"counting","courseRoute":"#course/quant/topic/counting","sections":[{"title":"至少一个常用全部减一个都没有","text":"目标集合的数量等于完整范围的数量减去其补集数量。例如6个人中有2名专业人员，选3人且至少有1名专业人员，可用C(6,3)-C(4,3)=20-4=16；补集是3人全来自其余4人。 适用与误用：全部与补集必须用同一结果定义；不能全部按有序岗位计，补集却按无序集合计。","index":18,"domId":"ki-point-0117"},{"title":"补事件的概率与原事件和为一","text":"在同一完整样本空间内，事件E与“E不发生”互斥且穷尽，所以P(E)=1-P(E的补事件)。例如独立掷两次公平六面骰，至少一次6点的概率是1-(5/6)²=11/36；不需分别处理一次与两次6点。 适用与误用：补集的定义要否定整个事件；不放回抽取时补事件内各步通常不独立，不能照搬边际概率乘积。","index":19,"domId":"ki-point-0118"}],"cards":[{"id":"ki-q-046","title":"至少一个常用全部减一个都没有","core":"目标集合的数量等于完整范围的数量减去其补集数量。例如6个人中有2名专业人员，选3人且至少有1名专业人员，可用C(6,3)-C(4,3)=20-4=16；补集是3人全来自其余4人。","boundary":"全部与补集必须用同一结果定义；不能全部按有序岗位计，补集却按无序集合计。","prompt":"“至少有一个专业人员”的补集是{{0}}。","blanks":[{"answer":"没有专业人员","accept":[]}]},{"id":"ki-q-047","title":"补事件的概率与原事件和为一","core":"在同一完整样本空间内，事件E与“E不发生”互斥且穷尽，所以P(E)=1-P(E的补事件)。例如独立掷两次公平六面骰，至少一次6点的概率是1-(5/6)²=11/36；不需分别处理一次与两次6点。","boundary":"补集的定义要否定整个事件；不放回抽取时补事件内各步通常不独立，不能照搬边际概率乘积。","prompt":"求“至少一次成功”概率，可用1减去{{0}}的概率。","blanks":[{"answer":"一次也不成功","accept":[]}]}],"questions":[{"id":"ki-qq-046","lesson":"count","stem":"6名不同人员中有2名专业人员，从中无序选3人，至少含1名专业人员，有多少种选法？","options":["4种","12种","20种","16种"],"answer":3,"explanation":"全部20种，完全不含专业人员有C(4,3)=4种，剩16种。","optionReviews":["这是不含专业人员的补集数量。","只计恰有1名专业人员，漏计2名都选。","这是未加限制的全部数量。","正确，全部减补集，不重不漏。"]},{"id":"ki-qq-047","lesson":"count","stem":"袋中有5个红球和3个蓝球，各球等可能被取出，不放回抽2个。至少有1个红球的概率是多少？","options":["15/16","5/8","3/28","25/28"],"answer":3,"explanation":"补事件是两个都是蓝球，概率C(3,2)/C(8,2)=3/28，所求1-3/28=25/28。","optionReviews":["把不同抽取模型的数值混用，未计不放回条件。","这是一次抽红概率，不是两次至少一红。","这是全蓝补事件概率。","正确，同一无序样本空间作补集。"]}]},{"lessonId":"probability","topicId":"probability-guarantee","courseRoute":"#course/quant/topic/probability-guarantee","sections":[{"title":"等可能应落实到基本结果","text":"有限样本中，各基本结果等可能时，P(E)=E所含基本结果数÷总基本结果数。例如2张红卡、1张蓝卡逐张等可能抽一张，红卡概率2/3；红蓝两种颜色并不是各占1/2。若基本结果概率不同，应按各自权重相加，不能只数类别。 适用与误用：先确定等可能的是球、卡、顺序还是类别；“有两种结果”不自动意味着各一半。","index":9,"domId":"ki-point-0119"},{"title":"或事件一般要扣去交集","text":"若A与B不可能同时发生，P(A或B)=P(A)+P(B)；若可能同时发生，相加会把交集数两遍，需要减去P(A且B)。例如公平骰子，A为偶数{2,4,6}，B为大于4{5,6}，并集{2,4,5,6}概率4/6=2/3，不能算5/6。 适用与误用：互斥不是独立；互斥事件的概率可以相加，非互斥事件必须处理重叠。","index":10,"domId":"ki-point-0120"},{"title":"分步概率使用条件概率","text":"事件连续发生的一般乘法为P(A且B)=P(A)P(B|A)。不放回时第一次结果会改变第二次样本。例如袋里4红3蓝，连续不放回抽两球都红，概率4/7×3/6=2/7，而不是(4/7)²。 适用与误用：除非已知独立，否则不能将第二步条件概率换成原来的边际概率；P(A)=0时P(B|A)的通常商式无定义。","index":11,"domId":"ki-point-0121"},{"title":"独立才可直接乘边际概率","text":"A、B独立的一般定义是P(A且B)=P(A)P(B)。当P(A)>0时，才可等价写成P(B|A)=P(B)，表示知道A发生不改变B的概率；P(A)=0时通常不能使用这一条件概率商式。例如一次公平硬币和一次公平骰子相互独立，硬币正面且骰子6点的概率为1/2×1/6=1/12。 适用与误用：独立并不表示互斥；两个正概率独立事件可以同时发生。放回并重新充分混匀常可建立独立模型，但仍以题设为准。","index":12,"domId":"ki-point-0122"}],"cards":[{"id":"ki-q-048","title":"等可能应落实到基本结果","core":"有限样本中，各基本结果等可能时，P(E)=E所含基本结果数÷总基本结果数。例如2张红卡、1张蓝卡逐张等可能抽一张，红卡概率2/3；红蓝两种颜色并不是各占1/2。若基本结果概率不同，应按各自权重相加，不能只数类别。","boundary":"先确定等可能的是球、卡、顺序还是类别；“有两种结果”不自动意味着各一半。","prompt":"2张红卡、1张蓝卡逐张等可能抽取，抽红概率为{{0}}。","blanks":[{"answer":"2/3","accept":[]}]},{"id":"ki-q-049","title":"或事件一般要扣去交集","core":"若A与B不可能同时发生，P(A或B)=P(A)+P(B)；若可能同时发生，相加会把交集数两遍，需要减去P(A且B)。例如公平骰子，A为偶数{2,4,6}，B为大于4{5,6}，并集{2,4,5,6}概率4/6=2/3，不能算5/6。","boundary":"互斥不是独立；互斥事件的概率可以相加，非互斥事件必须处理重叠。","prompt":"一般情况下P(A或B)=P(A)+P(B)-{{0}}。","blanks":[{"answer":"P(A且B)","accept":[]}]},{"id":"ki-q-050","title":"分步概率使用条件概率","core":"事件连续发生的一般乘法为P(A且B)=P(A)P(B|A)。不放回时第一次结果会改变第二次样本。例如袋里4红3蓝，连续不放回抽两球都红，概率4/7×3/6=2/7，而不是(4/7)²。","boundary":"除非已知独立，否则不能将第二步条件概率换成原来的边际概率；P(A)=0时P(B|A)的通常商式无定义。","prompt":"分步一般乘法P(A且B)=P(A)×{{0}}。","blanks":[{"answer":"P(B|A)","accept":[]}]},{"id":"ki-q-051","title":"独立才可直接乘边际概率","core":"A、B独立的一般定义是P(A且B)=P(A)P(B)。当P(A)>0时，才可等价写成P(B|A)=P(B)，表示知道A发生不改变B的概率；P(A)=0时通常不能使用这一条件概率商式。例如一次公平硬币和一次公平骰子相互独立，硬币正面且骰子6点的概率为1/2×1/6=1/12。","boundary":"独立并不表示互斥；两个正概率独立事件可以同时发生。放回并重新充分混匀常可建立独立模型，但仍以题设为准。","prompt":"已知A、B独立时，P(A且B)=P(A)×{{0}}。","blanks":[{"answer":"P(B)","accept":[]}]},{"id":"ki-q-065","title":"有限等可能的古典概率","core":"有限基本结果都等可能时，概率=有利基本结果数/所有基本结果数。","boundary":"若结果概率不等，需用权重，不得仅数类别；分子分母的有序无序口径相同。","prompt":"有限等可能模型下P(E)=有利结果数÷{{0}}。","blanks":[{"answer":"全部结果数","accept":[]}]},{"id":"ki-q-066","title":"互斥事件的概率相加","core":"A、B不可能同时发生时，P(A或B)=P(A)+P(B)。","boundary":"非互斥事件要扣交集；独立不是互斥的同义词。","prompt":"A、B互斥时，P(A或B)=P(A){{0}}P(B)。","blanks":[{"answer":"+","accept":[]}]}],"questions":[{"id":"ki-qq-048","lesson":"probability","stem":"3张外形相同的卡中2张标红、1张标蓝，每张被抽到的概率相等。抽到红色的概率是多少？","options":["1/2","1/3","2/3","1"],"answer":2,"explanation":"三个等可能基本结果是三张具体卡，两个有利结果，所以2/3。","optionReviews":["错误地把颜色类别当等可能结果。","只计一张红卡。","正确，逐张卡等可能计数。","仍有蓝卡，红色不是必然。"]},{"id":"ki-qq-049","lesson":"probability","stem":"公平六面骰掷一次，出现偶数或大于4的点数，概率是多少？","options":["2/3","1/3","1/2","5/6"],"answer":0,"explanation":"偶数3种，大于4有2种，交集只有6共1种，所以(3+2-1)/6=4/6=2/3。","optionReviews":["正确，交集6只计一次。","漏计并集中的部分点数。","只算偶数概率。","直接相加，重复计入6。"]},{"id":"ki-qq-050","lesson":"probability","stem":"袋中4红3蓝共7球，各球等可能，不放回连续抽2球。两球都是红色的概率是多少？","options":["4/7","1/2","16/49","2/7"],"answer":3,"explanation":"第一球红概率4/7，已抽红后剩3红6球，第二球红概率3/6，乘积2/7。","optionReviews":["只算第一球红。","只算在第一球已红条件下第二球红。","把两次错误看作独立。","正确，条件概率反映不放回。"]},{"id":"ki-qq-051","lesson":"probability","stem":"独立掷一次公平硬币与一次公平六面骰，硬币正面且骰子为6点的概率是多少？","options":["1/6","1/3","1/8","1/12"],"answer":3,"explanation":"共有2×6=12个等可能组合，只有(正面,6)符合；也可相乘1/2×1/6。","optionReviews":["只算骰子6点，漏掉正面条件。","将两个概率误做无关运算。","不是12个等可能组合的正确计数。","正确，独立事件的交集概率是边际概率乘积。"]},{"id":"ki-qq-056","lesson":"probability","stem":"公平六面骰掷一次，事件A为点数1或2，事件B为点数5或6。A或B发生的概率是多少？","options":["1/3","1/9","2/3","1"],"answer":2,"explanation":"A、B互斥，各概率2/6，两者并集为1、2、5、6，共4/6=2/3。","optionReviews":["只算其中一个事件。","这是两个概率相乘，但互斥交集实际为0。","正确，互斥并集相加。","遗漏了3、4都不在并集中。"]}]},{"lessonId":"rotation","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"同一零件如何发生位置变化","text":"先给重复零件编号，再把“零件在何处”和“零件朝哪边”分开记录。平移给所有点加同一个向量，朝向不变；环形位移按轨道的编号递推；旋转让各点绕指定中心转过同角，必须写清顺逆时针；反射则把点映到反射轴另一侧的等距离位置，会改变有方向标记的手性。例如标记点从(1,0)到(0,1)，若箭头同时由右转上，符合绕原点逆时针90°；若点到(-1,0)且右箭头转左，关于纵轴反射也可能成立。只看一个点无法区分某些变换，应拿第二个不在对称位置的标记和后续图一起核验。元素不变是先查位置变换的理由，不是排除数量规律的证明。","index":9,"domId":"ki-point-0123"}],"cards":[{"id":"ki-j-001","title":"同一零件如何发生位置变化","core":"先给重复零件编号，再把“零件在何处”和“零件朝哪边”分开记录。平移给所有点加同一个向量，朝向不变；环形位移按轨道的编号递推；旋转让各点绕指定中心转过同角，必须写清顺逆时针；反射则把点映到反射轴另一侧的等距离位置，会改变有方向标记的手性。例如标记点从(1,0)到(0,1)，若箭头同时由右转上，符合绕原点逆时针90°；若点到(-1,0)且右箭头转左，关于纵轴反射也可能成立。只看一个点无法区分某些变换，应拿第二个不在对称位置的标记和后续图一起核验。元素不变是先查位置变换的理由，不是排除数量规律的证明。","boundary":"元素相同只是检索线索，仍须验证所有图和选项；不能排除计数等规律。","prompt":"重复零件先分别记录{{0}}和朝向。所有点同加(2,0)且朝向不变是{{1}}；沿8格轨道递推是环移；绕点变换要交代中心、角度、{{2}}；翻转要明确{{3}}。","blanks":[{"answer":"坐标","accept":[]},{"answer":"平移","accept":[]},{"answer":"方向","accept":[]},{"answer":"反射轴","accept":[]}]}],"questions":[{"id":"ki-jq-001","lesson":"rotation","stem":"平面坐标采用右向x正、上向y正。图甲两点为P(1,0)、Q(2,1)，箭头向右；图乙为P′(0,1)、Q′(-1,2)，箭头向上。规定只在“整体平移、绕原点旋转、关于纵轴反射、保持朝向的环形移位”中选择。哪份诊断完整正确？","options":["整体平移(-1,1)，箭头另行改变即可","关于纵轴反射；只要P位置改变就够","绕原点逆时针90°；两点坐标与箭头均吻合","环形移位；中心和步长都不必确定"],"answer":2,"explanation":"逆时针90°把(x,y)变成(-y,x)，所以P→(0,1)、Q→(-1,2)，右箭头转上。平移的两点位移分别是(-1,1)、(-3,1)，不相同；纵轴反射给(-1,0)、(-2,1)。环移须先指定轨道，不能用名称代替验证。","optionReviews":["两点位移不一致，不能整体平移。","关于纵轴反射后的点并非题设位置。","坐标、朝向、中心、转角和方向全部一致。","题中没有可支持该说法的统一轨道与步长。"]}]},{"lessonId":"rotation","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"把不同轨道分开计算","text":"给方格边缘顺时针编号0至7、内圈顺时针编号0至3，就把视觉移动转成模运算。外圈每次顺时针前进3格是x→(x+3) mod 8，周期为8/gcd(8,3)=8；内圈逆时针1格是y→(y-1) mod 4，周期4。两个标记同时复原要等两周期的最小公倍数8步。跨过末格是否回到首格必须由题设或全序列确认。分轨适用于标记确实各守其轨的情况；若标记互换轨道，就不能继续用两个独立递推式。","index":10,"domId":"ki-point-0124"}],"cards":[{"id":"ki-j-002","title":"把不同轨道分开计算","core":"给方格边缘顺时针编号0至7、内圈顺时针编号0至3，就把视觉移动转成模运算。外圈每次顺时针前进3格是x→(x+3) mod 8，周期为8/gcd(8,3)=8；内圈逆时针1格是y→(y-1) mod 4，周期4。两个标记同时复原要等两周期的最小公倍数8步。跨过末格是否回到首格必须由题设或全序列确认。分轨适用于标记确实各守其轨的情况；若标记互换轨道，就不能继续用两个独立递推式。","boundary":"先分圈是一种省力尝试，不能强行要求所有题都分内外圈。","prompt":"外圈8格从6顺时针走3格到{{0}}；内圈4格从0逆时针走1格到{{1}}。两者周期分别8和4，首次共同回原位是{{2}}步。分轨须先确认标记不{{3}}。","blanks":[{"answer":"1","accept":[]},{"answer":"3","accept":[]},{"answer":"8","accept":[]},{"answer":"换轨","accept":[]}]}],"questions":[{"id":"ki-jq-002","lesson":"rotation","stem":"外圈按顺时针编号0至7，内圈按顺时针编号0至3，均越界循环。黑点初在外圈6，每步顺时针3格；白点初在内圈0，每步逆时针1格。以下“下一位置(黑,白)；各自周期；共同周期”哪项正确？","options":["(9,-1)；无周期；无周期","(1,1)；8与4；8","(1,3)；3与1；3","(1,3)；8与4；8"],"answer":3,"explanation":"外圈(6+3) mod 8=1，内圈(0-1) mod 4=3。求回原位须使3t为8的倍数、t为4的倍数，最小t=8。移动步长和周期不是同一量。","optionReviews":["忽略了题设的越界循环。","白点逆时针应减1，不是加1。","把步长当周期，无法同时回到原位。","两轨方向、循环和周期都满足。"]}]},{"lessonId":"overlay","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"叠加图先转成同位线段集合","text":"把底板上每一条可能出现的小线段取名，只有位置和端点相同才算同一成员。A={a,b,c}、B={b,c,d}时，并集保留出现过的所有线段且重复只画一次，得到{a,b,c,d}；交集留下{b,c}；A减B只留下{a}；异或删掉共同部分，留下{a,d}。线段只是端点相接时，仍是两个不同成员。先对齐坐标，才有资格逐位比较。不要把“并集去重”和“重合消失”混为一谈，后者是异或。","index":9,"domId":"ki-point-0125"}],"cards":[{"id":"ki-j-003","title":"叠加图先转成同位线段集合","core":"把底板上每一条可能出现的小线段取名，只有位置和端点相同才算同一成员。A={a,b,c}、B={b,c,d}时，并集保留出现过的所有线段且重复只画一次，得到{a,b,c,d}；交集留下{b,c}；A减B只留下{a}；异或删掉共同部分，留下{a,d}。线段只是端点相接时，仍是两个不同成员。先对齐坐标，才有资格逐位比较。不要把“并集去重”和“重合消失”混为一谈，后者是异或。","boundary":"先把图对齐，再建立同一套线段单位；笔画相接不等于同一线段。","prompt":"A={a,b,c}，B={b,c,d}。并集去重后{{0}}；交集{{1}}；A-B为{{2}}；异或{{3}}。这些运算先要求线段位置{{4}}。","blanks":[{"answer":"{a,b,c,d}","accept":[]},{"answer":"{b,c}","accept":[]},{"answer":"{a}","accept":[]},{"answer":"{a,d}","accept":[]},{"answer":"对齐","accept":[]}]}],"questions":[{"id":"ki-jq-003","lesson":"overlay","stem":"四条标准线段a、b、c、d的位置已固定。A={a,b,c}，B={b,c,d}。某输出把两图共同线段消去、只保留单独出现的线段。哪项同时正确给出“并集、交集、A-B、该输出”？","options":["{a,b,c,d}；{a,d}；{a}；{b,c}","{a,d}；{b,c}；{a}；{a,b,c,d}","{a,b,c,d}；{b,c}；{a}；{a,d}","{a,b,c,d}；{b,c}；{d}；{a,d}"],"answer":2,"explanation":"并集去重但不删共同线段；交集只留共同成员；差集有方向；题设的重合消失是对称差A△B={a,d}。四个结果都必须以同位线段为单位。","optionReviews":["把共同成员与独有成员弄反。","把并集与异或对调。","四个集合均正确且区分去重与消重。","{d}是B-A，不是A-B。"]}]},{"lessonId":"rotation","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"先变换输入，再做统一叠合","text":"复合规则可以写成T(A)与B做某种集合运算。以四个方向位置N、E、S、W为底板，先把A顺时针90°，映射N→E→S→W→N，再与B做异或。A={N}、B={E,W}便得到{W}；另一组A={S}、B={N,W}得到{N}。不旋转直接异或分别会得到三个成员，解释不了结果。候选变换来自朝向差异，但必须在另一组也使用相同输入顺序、相同旋转和相同运算，不能每组临时换规则。 若朝向提示反射，可先关于竖轴把E、W互换而保持N、S，再做集合运算；例如A={N,E}先变{N,W}，与B={N,S}异或得{W,S}。反射不能被简单当成一次旋转，因为有向标记的手性不同。","index":11,"domId":"ki-point-0126"}],"cards":[{"id":"ki-j-004","title":"先变换输入，再做统一叠合","core":"复合规则可以写成T(A)与B做某种集合运算。以四个方向位置N、E、S、W为底板，先把A顺时针90°，映射N→E→S→W→N，再与B做异或。A={N}、B={E,W}便得到{W}；另一组A={S}、B={N,W}得到{N}。不旋转直接异或分别会得到三个成员，解释不了结果。候选变换来自朝向差异，但必须在另一组也使用相同输入顺序、相同旋转和相同运算，不能每组临时换规则。 若朝向提示反射，可先关于竖轴把E、W互换而保持N、S，再做集合运算；例如A={N,E}先变{N,W}，与B={N,S}异或得{W,S}。反射不能被简单当成一次旋转，因为有向标记的手性不同。","boundary":"不能仅因某幅看起来特别便断定要旋转它；比较顺序属于启发式。","prompt":"复合叠合应写成先做{{0}}再做集合运算。若一组猜测“先把A顺时针90°后异或”，还必须用{{1}}检验同一输入顺序与同一操作，不能每组随意改。 若E与W互换而N、S保留，是关于{{2}}反射，不是直接叠合。","blanks":[{"answer":"坐标变换","accept":[]},{"answer":"其他组","accept":[]},{"answer":"竖轴","accept":["纵轴"]}]}],"questions":[{"id":"ki-jq-004","lesson":"rotation","stem":"四位置N、E、S、W按顺时针排列。已知第1组A={N}、B={E,W}，输出{W}；第2组A={S}、B={N,W}，输出{N}。下列哪一条在两组都成立？","options":["A逆时针90°后与B取交集","A顺时针90°后与B异或","不变换，A与B取并集","第1组旋转A，第2组旋转B即可，运算可不同"],"answer":1,"explanation":"顺时针90°后，两个A分别变成{E}和{W}，与各自B异或后分别得到{W}、{N}。逆时针后取交集不能贯穿两组，直接并集也不符合输出。允许每组任意改变输入与运算的做法，不是统一可检验的规则。","optionReviews":["逆时针时第一组交集虽为{W}，但第二组A变{E}，与B交集为空，不能贯穿两组。","同一旋转和同一异或运算贯穿两组。","直接并集均有三段而不是单段。","任意改输入与运算会失去规则的一致性。"]},{"id":"ki-jq-extra-reflection","lesson":"rotation","stem":"四方向N、E、S、W为固定底板。规则先将A关于竖轴反射（E↔W，N、S不变），再与B异或。A={N,E}，B={N,S}，输出是什么？","options":["{N}","{W,S}","{E,S}","{N,W,S}"],"answer":1,"explanation":"反射先给A′={N,W}，与B共同的N消去，剩W、S。若直接异或会得E、S，不能跳过预处理。","optionReviews":["这是交集而不是异或。","先反射再异或，两个操作顺序正确。","这是没做反射的直接异或。","保留了应该在异或中消去的N。"]}]},{"lessonId":"overlay","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"逐格真值表比只数黑块更可靠","text":"统一格号后，把黑记1、白记0。若同色输出白、异色输出黑，四行就是00→0、01→1、10→1、11→0，这是异或。黑块数量相同可以提示尝试平移，但只比较总数会漏掉所在格。例如1100与0110各有两个黑格，异或是1010；既不能凭“两黑”认定只是移动，也不能从只观察到的00与11推定整个真值表。已经出现的每种输入都须核对，未出现的组合不能假称已验证。","index":10,"domId":"ki-point-0127"}],"cards":[{"id":"ki-j-005","title":"逐格真值表比只数黑块更可靠","core":"统一格号后，把黑记1、白记0。若同色输出白、异色输出黑，四行就是00→0、01→1、10→1、11→0，这是异或。黑块数量相同可以提示尝试平移，但只比较总数会漏掉所在格。例如1100与0110各有两个黑格，异或是1010；既不能凭“两黑”认定只是移动，也不能从只观察到的00与11推定整个真值表。已经出现的每种输入都须核对，未出现的组合不能假称已验证。","boundary":"黑块数是否规律不能独自决定题型；黑白运算需同格对照并验证全部四种输入组合中已出现的情况。","prompt":"固定四格A=1100、B=0110，逐格“同色白异色黑”得到{{0}}，规则是{{1}}。黑格总数相同只能提示试移动，不能替代{{2}}。","blanks":[{"answer":"1010","accept":[]},{"answer":"异或","accept":[]},{"answer":"逐格核验","accept":[]}]}],"questions":[{"id":"ki-jq-005","lesson":"overlay","stem":"按从左到右的同位四格运算，A=1100，B=0110。已知真值表00→0、01→1、10→1、11→0。哪项正确说明输出及判断依据？","options":["1010；四种输入都能按同位真值表检验","1100；两图黑格数相同所以必为平移","1110；只要至少一图为黑就输出黑","0100；只保留两图都黑的位置"],"answer":0,"explanation":"四位置输入依次为10、11、01、00，输出1、0、1、0。1110是并集，0100是交集；总黑格数无法单独判定位置规则。","optionReviews":["输出与四行真值表逐格一致。","仅凭数量相同不能推出平移。","使用了或运算而非题设异或。","使用了且运算而非题设异或。"]}]},{"lessonId":"figure-features","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"对称检验必须连同内部标记","text":"轴对称要求沿某条直线反射后整幅图重合，中心对称要求绕某点转180°重合；两者可以同时存在，也可以只存在一种。长4宽2的非正方形矩形有水平、竖直两条对称轴，也有中心对称。若在中心右侧(1,0)添加唯一黑点，水平反射保持它，竖直反射和半周转都把它送到没有黑点的(-1,0)，所以整幅只剩水平轴。先看等腰轮廓能节省搜索，但轴的数量和方向、轴是否穿过内部标记，都要实际映射检验。","index":9,"domId":"ki-point-0128"}],"cards":[{"id":"ki-j-006","title":"对称检验必须连同内部标记","core":"轴对称要求沿某条直线反射后整幅图重合，中心对称要求绕某点转180°重合；两者可以同时存在，也可以只存在一种。长4宽2的非正方形矩形有水平、竖直两条对称轴，也有中心对称。若在中心右侧(1,0)添加唯一黑点，水平反射保持它，竖直反射和半周转都把它送到没有黑点的(-1,0)，所以整幅只剩水平轴。先看等腰轮廓能节省搜索，但轴的数量和方向、轴是否穿过内部标记，都要实际映射检验。","boundary":"轮廓像等腰图形不保证整幅轴对称；内部标记也须被映射保持。","prompt":"非正方形矩形原有{{0}}条对称轴且有中心对称。只在中心右侧(1,0)放唯一黑点后，整幅只保留{{1}}轴，不再{{2}}对称。外形对称不能忽略{{3}}。","blanks":[{"answer":"2","accept":[]},{"answer":"水平","accept":[]},{"answer":"中心","accept":[]},{"answer":"内部标记","accept":[]}]}],"questions":[{"id":"ki-jq-006","lesson":"figure-features","stem":"矩形顶点为(-2,-1)、(2,-1)、(2,1)、(-2,1)。先不加标记，再仅在(1,0)放一个黑点。下列哪项描述两幅图的整体对称性正确？","options":["原图有4轴；加点后仅竖直1轴","原图仅轴对称；加点后轴数不变","原图中心对称；加点后仍中心对称，因为轮廓没变","原图轴、中心兼有且有2轴；加点后仅水平1轴，无中心对称"],"answer":3,"explanation":"非正方形矩形的两轴是x轴和y轴。点(1,0)关于x轴仍是自身，关于y轴或原点则变成(-1,0)，后者没有标记。必须把点也作为图形的一部分。","optionReviews":["长宽不同的矩形对角线不是对称轴。","原图有中心对称，且新增标记会减少轴数。","内部黑点破坏了半周旋转的不变性。","两种对称、轴数、方向及内部标记的检验都正确。"]}]},{"lessonId":"figure-features","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"曲直分类与连接方式分开看","text":"先按全部可见线条分三类：只有直线、只有曲线、两者混合。再按题内统一单位数数量。正方形外框是4条直线段；圆周按一条闭合曲线计；半圆弧加直径是一条连续弧和一条直线段，二者在两个端点连接。这里曲直分类不能告诉你最少笔画：圆和半圆加直径均可一笔，正方形也可一笔。遇到相交或相切还要另记接触类型，不能因为看见圆弧就认定题目只考曲线数量。","index":10,"domId":"ki-point-0129","diagramSvg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 180\" role=\"img\" aria-label=\"原创示意图\"><rect width=\"480\" height=\"180\" fill=\"white\"/><g fill=\"none\" stroke=\"#1e293b\" stroke-width=\"3\"><rect x=\"30\" y=\"35\" width=\"90\" height=\"90\"/><circle cx=\"235\" cy=\"80\" r=\"45\"/><path d=\"M350 110 A45 45 0 0 1 440 110\"/><line x1=\"350\" y1=\"110\" x2=\"440\" y2=\"110\"/><text x=\"70\" y=\"155\" fill=\"#1e293b\" stroke=\"none\">A</text><text x=\"230\" y=\"155\" fill=\"#1e293b\" stroke=\"none\">B</text><text x=\"390\" y=\"155\" fill=\"#1e293b\" stroke=\"none\">C</text></g></svg>"}],"cards":[{"id":"ki-j-007","title":"曲直分类与连接方式分开看","core":"先按全部可见线条分三类：只有直线、只有曲线、两者混合。再按题内统一单位数数量。正方形外框是4条直线段；圆周按一条闭合曲线计；半圆弧加直径是一条连续弧和一条直线段，二者在两个端点连接。这里曲直分类不能告诉你最少笔画：圆和半圆加直径均可一笔，正方形也可一笔。遇到相交或相切还要另记接触类型，不能因为看见圆弧就认定题目只考曲线数量。","boundary":"存在圆弧只提示曲直属性，最终规律也可能是交点、切点或笔画。","prompt":"正方框属{{0}}，圆周属{{1}}，半圆弧加直径属{{2}}。在“每一段连续圆弧算一条曲线”的口径下，半圆图含1弧、1直线且在{{3}}个端点相接。","blanks":[{"answer":"全直线","accept":[]},{"answer":"全曲线","accept":[]},{"answer":"直曲混合","accept":[]},{"answer":"2","accept":[]}]}],"questions":[{"id":"ki-jq-007","lesson":"figure-features","stem":"图中A为正方框，B为完整圆周，C为半圆弧及其直径。约定按连续圆弧计曲线、按边界直线段计直线。哪一组“类别；C的直线/曲线数及连接”正确？","options":["A全曲、B全曲、C混合；C的两部分彼此分离","A全直、B全曲、C混合；C为1直1曲、两端相接","A全直、B全曲、C混合；C为2直2曲、一个交叉点","A全直、B混合、C全曲；C为0直1曲"],"answer":1,"explanation":"正方框无曲线，圆周无直线；半圆直径是直线，圆弧是曲线。弧两端与直径两端一一重合，属于端点连接，不是内部交叉。该判断独立于笔画数。","optionReviews":["正方框由直线构成，C并不分离。","分类、数量与连接位置都正确。","未按题定单位计数，且接触是两个端点。","圆周没有直线，直径也不能漏数。"]}]},{"lessonId":"figure-features","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"封闭区域要有完整边界","text":"先说清数的是薄线围出的有界小面，还是实心剪影内部的白色孔洞。一个矩形加对角线，内部被分成两个有界面，不再把整矩形额外算一个第三面；一个黑色圆环只有一个白色孔洞，黑色粗边本身不是许多额外小面。开口的门形线内部可通向无限外部，不能算封闭区。线宽只是画法，不应凭抗锯齿或粗边的阴影制造区域；边界若真有断口，即使很小也不封闭。","index":11,"domId":"ki-point-0130","diagramSvg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 180\" role=\"img\" aria-label=\"原创示意图\"><rect width=\"480\" height=\"180\" fill=\"white\"/><g fill=\"none\" stroke=\"#1e293b\" stroke-width=\"3\"><rect x=\"20\" y=\"35\" width=\"110\" height=\"85\"/><line x1=\"20\" y1=\"35\" x2=\"130\" y2=\"120\"/><circle cx=\"250\" cy=\"80\" r=\"38\" stroke-width=\"18\"/><path d=\"M370 120 V35 H455 V120\"/><text x=\"70\" y=\"155\" fill=\"#1e293b\" stroke=\"none\">甲</text><text x=\"245\" y=\"155\" fill=\"#1e293b\" stroke=\"none\">乙</text><text x=\"410\" y=\"155\" fill=\"#1e293b\" stroke=\"none\">丙</text></g></svg>"}],"cards":[{"id":"ki-j-008","title":"封闭区域要有完整边界","core":"先说清数的是薄线围出的有界小面，还是实心剪影内部的白色孔洞。一个矩形加对角线，内部被分成两个有界面，不再把整矩形额外算一个第三面；一个黑色圆环只有一个白色孔洞，黑色粗边本身不是许多额外小面。开口的门形线内部可通向无限外部，不能算封闭区。线宽只是画法，不应凭抗锯齿或粗边的阴影制造区域；边界若真有断口，即使很小也不封闭。","boundary":"线条粗细不应产生虚假的额外区域；开口部分和图外无限区域通常不计。","prompt":"薄线矩形加一条对角线得到{{0}}个有界小面；实心圆环有{{1}}个白色孔洞；开口门形线内部{{2}}算封闭区域。","blanks":[{"answer":"2","accept":[]},{"answer":"1","accept":[]},{"answer":"不能","accept":[]}]}],"questions":[{"id":"ki-jq-008","lesson":"figure-features","stem":"甲是薄线矩形加一条连接对角顶点的对角线；乙是实心黑色圆环；丙是底边缺失的门形折线。分别数“甲的有界最小区域、乙的白色孔洞、丙的封闭区域”，结果是？","options":["2、0、0","3、2、1","1、1、1","2、1、0"],"answer":3,"explanation":"甲对角线把内部恰分成两个最小区域，不重复计整个矩形。乙中央白区被完整黑环包围，有一个洞；丙开口使内部连到外部，无封闭区域。","optionReviews":["乙中央白孔是一个实际封闭空腔。","重复计甲整体，把粗边及开口也错误计入。","漏掉甲分割，误把丙开口当闭合。","按指定口径为2、1、0。"]}]},{"lessonId":"figure-features","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"面数相同再查形状与面积","text":"面数一致时，可把各区域的边长或角度列出来，再比较全等和相似。一个6×2矩形在距左边2处竖切，得2×2正方形与4×2矩形，面积4与8；两个四边形并不相似，因为长宽比是1与2。面积最大的4×2区域全是直边，有两条对称轴。若改在距左边3处切，则两块都是3×2矩形，互相全等也相似。不能把“都叫矩形”当全等，也不能靠画出来的一点视觉大小差决定面积。 本例最小区域是面积4的2×2正方形，全直边且有4条对称轴；最大区域面积8，有2条轴。最大与最小都应由尺寸而非视觉缩放确定。","index":12,"domId":"ki-point-0131","diagramSvg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 180\" role=\"img\" aria-label=\"原创示意图\"><rect width=\"480\" height=\"180\" fill=\"white\"/><g fill=\"none\" stroke=\"#1e293b\" stroke-width=\"3\"><rect x=\"20\" y=\"40\" width=\"180\" height=\"60\"/><line x1=\"80\" y1=\"40\" x2=\"80\" y2=\"100\"/><rect x=\"270\" y=\"40\" width=\"180\" height=\"60\"/><line x1=\"360\" y1=\"40\" x2=\"360\" y2=\"100\"/><text x=\"100\" y=\"145\" fill=\"#1e293b\" stroke=\"none\">甲：2+4</text><text x=\"335\" y=\"145\" fill=\"#1e293b\" stroke=\"none\">乙：3+3</text></g></svg>"}],"cards":[{"id":"ki-j-009","title":"面数相同再查形状与面积","core":"面数一致时，可把各区域的边长或角度列出来，再比较全等和相似。一个6×2矩形在距左边2处竖切，得2×2正方形与4×2矩形，面积4与8；两个四边形并不相似，因为长宽比是1与2。面积最大的4×2区域全是直边，有两条对称轴。若改在距左边3处切，则两块都是3×2矩形，互相全等也相似。不能把“都叫矩形”当全等，也不能靠画出来的一点视觉大小差决定面积。 本例最小区域是面积4的2×2正方形，全直边且有4条对称轴；最大区域面积8，有2条轴。最大与最小都应由尺寸而非视觉缩放确定。","boundary":"面貌相似不等于全等；面积比较须有图形依据，不能仅凭渲染误差判断。","prompt":"6×2矩形沿x=2分割，区域面积为4、{{0}}，二者{{1}}相似。大区域是全直边矩形，有{{2}}条轴。沿x=3切出的两块{{3}}。 最小的2×2区是正方形，有{{4}}条对称轴。","blanks":[{"answer":"8","accept":[]},{"answer":"不","accept":[]},{"answer":"2","accept":[]},{"answer":"全等","accept":[]},{"answer":"4","accept":["四"]}]}],"questions":[{"id":"ki-jq-009","lesson":"figure-features","stem":"甲：6×2矩形在x=2竖分；乙：同样矩形在x=3竖分，左边均为x=0。哪项正确？","options":["甲两区都是矩形所以全等；大区面积8","甲两区面积相等，大区是曲直混合；乙仅形状类别相同","甲两区不相似，大区面积8有2轴，小区面积4有4轴；乙两区全等、也相似","甲两区相似而不全等；乙两区既不相似也不全等"],"answer":2,"explanation":"甲是2×2与4×2，长宽比不同，故不相似，更不全等；大区面积8，是有两条轴的非正方矩形。乙两块均3×2，边长完全相同。 甲小区是正方形，有4条轴，是面积最小区。","optionReviews":["边长不同，不能由共同上位类别推出全等。","甲面积分别4、8且所有边为直线。","尺寸、面积、相似、全等及大区属性均正确。","甲不相似，乙则全等。"]}]},{"lessonId":"figure-features","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"交点按位置计，不按线对计","text":"先区分三种几何接触：两线穿越是交叉，圆与切线只接触是相切，两线端头接在一起是端点相接。题目若把三者都计入，取所有接触位置的去重集合；若只数内部交叉，就排除切点和端接点。三条不同线共过一个点有三对线，却只有一个交点位置。把图转成笔画问题时，还要确认接触处是否允许通行：普通平面交叉默认顶点，高架桥式跨越标志则表示不连通。","index":13,"domId":"ki-point-0132","diagramSvg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 180\" role=\"img\" aria-label=\"独立绘制的图形示意\"><rect width=\"480\" height=\"180\" fill=\"white\"/><g fill=\"none\" stroke=\"#1e293b\" stroke-width=\"3\"><path d=\"M46 85 H134 M90 129 V41 M46 129 L134 41 M134 85 L156 63\"/><circle cx=\"330\" cy=\"90\" r=\"28\"/><path d=\"M280 62 H380\"/><g fill=\"#1e293b\" stroke=\"none\"><text x=\"55\" y=\"160\">线段接触</text><text x=\"290\" y=\"160\">圆与切线</text></g></g></svg>"}],"cards":[{"id":"ki-j-010","title":"交点按位置计，不按线对计","core":"先区分三种几何接触：两线穿越是交叉，圆与切线只接触是相切，两线端头接在一起是端点相接。题目若把三者都计入，取所有接触位置的去重集合；若只数内部交叉，就排除切点和端接点。三条不同线共过一个点有三对线，却只有一个交点位置。把图转成笔画问题时，还要确认接触处是否允许通行：普通平面交叉默认顶点，高架桥式跨越标志则表示不连通。","boundary":"相切点与相交点是否合计要保持题内一致；不能把参与线条对数当交点位置数。","prompt":"三线共过同一点按位置只计{{0}}个交点，不是3个。圆与切线为{{1}}，折线端头接合为{{2}}。先定口径，再对位置{{3}}。","blanks":[{"answer":"1","accept":[]},{"answer":"相切","accept":[]},{"answer":"端点相接","accept":[]},{"answer":"去重","accept":[]}]}],"questions":[{"id":"ki-jq-010","lesson":"figure-features","stem":"三线段分别连接(-2,0)与(2,0)、(0,-2)与(0,2)、(-2,-2)与(2,2)，另有线段连接(2,0)与(3,1)。独立地，单位圆与y=1相切。依次求“前四线段全部接触位置数、仅内部交叉位置数、圆与切线接触点数”。","options":["2、2、0","4、3、1","3、1、2","2、1、1"],"answer":3,"explanation":"前三线都共过原点，位置只算1；第四线只在(2,0)与第一线端接，再添1处。内部交叉只有原点。单位圆与y=1接于(0,1)，只有1个切点。","optionReviews":["端点连接不是内部交叉，切点也真实存在。","把原点的三对线相交当成三处位置。","前四线仅两处接触，切线只接一点。","接触类型和位置去重均正确。"]}]},{"lessonId":"figure-features","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"线条数量不是笔画数量","text":"计数前固定单位：“直线段”可以按拐点与分叉拆分，“连续共线长线”可跨过中间交点，两种口径不能混用。圆也可按一整条闭曲线计，而非按任意标出的点切成很多弧。笔画则问不抬笔且每条边不重走的路径，需要把端点、交叉和允许通行的切点建成顶点。矩形加一条对角线有5条边界直线段、0条曲线，却仅需1笔；两外切圆按每圆一条曲线计为2曲线，切点度数4，也只需1笔。视觉上看到几根长线，并不能直接给最少笔数。","index":14,"domId":"ki-point-0133","diagramSvg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 180\" role=\"img\" aria-label=\"独立绘制的图形示意\"><rect width=\"480\" height=\"180\" fill=\"white\"/><g fill=\"none\" stroke=\"#1e293b\" stroke-width=\"3\"><rect x=\"35\" y=\"45\" width=\"95\" height=\"75\"/><path d=\"M35 45 L130 120\"/><circle cx=\"275\" cy=\"85\" r=\"35\"/><circle cx=\"345\" cy=\"85\" r=\"35\"/><g fill=\"#1e293b\" stroke=\"none\"><text x=\"70\" y=\"155\">甲</text><text x=\"305\" y=\"155\">乙</text></g></g></svg>"}],"cards":[{"id":"ki-j-011","title":"线条数量不是笔画数量","core":"计数前固定单位：“直线段”可以按拐点与分叉拆分，“连续共线长线”可跨过中间交点，两种口径不能混用。圆也可按一整条闭曲线计，而非按任意标出的点切成很多弧。笔画则问不抬笔且每条边不重走的路径，需要把端点、交叉和允许通行的切点建成顶点。矩形加一条对角线有5条边界直线段、0条曲线，却仅需1笔；两外切圆按每圆一条曲线计为2曲线，切点度数4，也只需1笔。视觉上看到几根长线，并不能直接给最少笔数。","boundary":"直线段、连续直线和边数是不同口径，须用整题验证；笔画不是按可见长线条数直接数。","prompt":"矩形加对角线按边界边计有{{0}}条直线，最少{{1}}笔。两外切圆按每圆一曲线计为{{2}}条曲线；若切点可通行且不重走，仍可{{3}}笔。","blanks":[{"answer":"5","accept":[]},{"answer":"1","accept":[]},{"answer":"2","accept":[]},{"answer":"1","accept":[]}]}],"questions":[{"id":"ki-jq-011","lesson":"figure-features","stem":"约定不重复任何边、接触处可通行；每个圆整体记一条曲线。甲为矩形外框加一条对角线，乙为两外切圆。下列“甲(直线,曲线,最少笔画)；乙(直线,曲线,最少笔画)”正确的是？","options":["(5,0,5)；(0,2,2)","(4,1,1)；(0,2,2)","(5,0,1)；(0,2,1)","(6,0,2)；(0,1,1)"],"answer":2,"explanation":"甲4条框边加1条对角线，两对角端点度3，其余度2，奇点2，故一笔。乙切点有4条局部边接入，其他无奇点且连通，能先绕一圆再绕另一圆，一笔闭合。","optionReviews":["把线条条数直接当笔画数。","对角线是直线，外切圆不必抬笔。","按统一几何单位计数，并正确转成图论。","对角线不是两条，两个圆也不能当一条圆曲线。"]}]},{"lessonId":"figure-features","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"最少笔画按每个连通分支计算","text":"在有限无向图中，约定一条边恰走一次、顶点可以重复、抬笔另起算新一笔。一个有边的连通分支若没有奇点，可以从某点出发最后回到它；恰有2奇点，则开放路径必须从一个奇点到另一个。若有o>2个奇点，最少o/2笔，因为每条开放路径最多容纳两个奇端点，并可用欧拉分解达到。对多个有边分支，逐支算max(1,o/2)再求和；孤立的无边点按题设是否需要“点一下”另计。不能对整图先把奇点加总再除2。例如独立圆环、独立线段、独立四臂星形分别需1、1、2笔，合计4，虽然总奇点仅6。","index":15,"domId":"ki-point-0134","diagramSvg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 180\" role=\"img\" aria-label=\"独立绘制的图形示意\"><rect width=\"480\" height=\"180\" fill=\"white\"/><g fill=\"none\" stroke=\"#1e293b\" stroke-width=\"3\"><circle cx=\"65\" cy=\"80\" r=\"28\"/><path d=\"M155 80 H230 M360 80 L330 45 M360 80 L390 45 M360 80 L330 115 M360 80 L390 115\"/><g fill=\"#1e293b\" stroke=\"none\"><text x=\"45\" y=\"150\">圆环</text><text x=\"175\" y=\"150\">线段</text><text x=\"330\" y=\"150\">四臂星</text></g></g></svg>"}],"cards":[{"id":"ki-j-012","title":"最少笔画按每个连通分支计算","core":"在有限无向图中，约定一条边恰走一次、顶点可以重复、抬笔另起算新一笔。一个有边的连通分支若没有奇点，可以从某点出发最后回到它；恰有2奇点，则开放路径必须从一个奇点到另一个。若有o>2个奇点，最少o/2笔，因为每条开放路径最多容纳两个奇端点，并可用欧拉分解达到。对多个有边分支，逐支算max(1,o/2)再求和；孤立的无边点按题设是否需要“点一下”另计。不能对整图先把奇点加总再除2。例如独立圆环、独立线段、独立四臂星形分别需1、1、2笔，合计4，虽然总奇点仅6。","boundary":"约定每条边恰画一次、允许经过同一顶点；不连通图不能只看总奇点数。","prompt":"连通有边图0奇点可一笔{{0}}；2奇点可从奇点到奇点一笔{{1}}；每分支最少max(1,奇点数/2)。独立圆环、线段、四臂星形合计{{2}}笔，不能用全图6/2算。","blanks":[{"answer":"闭合","accept":[]},{"answer":"开放","accept":[]},{"answer":"4","accept":[]}]}],"questions":[{"id":"ki-jq-012","lesson":"figure-features","stem":"图由互不接触的三部分组成：一个圆环、一条线段、一个四臂星形（四端点接同一中心）。禁止重走边，允许重复到达顶点。哪项同时正确？","options":["线段可从内部出发一笔闭合，星形因中心度4所以1笔；总3笔","圆环0奇点不需画；线段1笔；星形2笔；总3笔","圆环0奇点闭合1笔；线段2奇点开放1笔；星形4奇点2笔；总4笔","全图6奇点，因此总3笔，连通性不影响"],"answer":2,"explanation":"圆环、线段、星形每支的奇点数分别0、2、4，按max(1,o/2)得1、1、2。圆环无奇点表示可闭合，不表示无边不用画。四臂中心偶度并不能抵消四个奇端点。","optionReviews":["线段两个端点是奇点，四臂星形也有四个奇端点。","零奇点仍有边，至少需要一笔。","闭合/开放条件及分支求和都正确。","把不连通分支之间不存在的路径当成可连接。"]}]},{"lessonId":"figure-features","topicId":"plane-figures","courseRoute":"#course/reasoning/topic/plane-figures","sections":[{"title":"连通部分与内部孔洞互不替代","text":"连通部分的判断是能否沿图上实际存在的墨迹从一处走到另一处。两个黑环用黑桥相连，就是一个墨迹分支；远处独立圆盘是第二支。两个环内部仍有两个孔洞，所以“2部分”和“2洞”来自不同指标。若桥有真正白缝，两个环重新分离。剪影或粗线图很适合先查这一点，但题目也可能考面积、对称或孔数，不能仅凭生活物品外形固定选指标；看起来挨近也不能代替实际接触。","index":16,"domId":"ki-point-0135","diagramSvg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 180\" role=\"img\" aria-label=\"独立绘制的图形示意\"><rect width=\"640\" height=\"180\" fill=\"white\"/><g fill=\"none\" stroke=\"#1e293b\" stroke-width=\"3\"><g stroke-width=\"12\"><circle cx=\"50\" cy=\"75\" r=\"25\"/><circle cx=\"125\" cy=\"75\" r=\"25\"/><path d=\"M75 75 H100\"/><circle cx=\"400\" cy=\"75\" r=\"25\"/><circle cx=\"475\" cy=\"75\" r=\"25\"/><path d=\"M425 75 H431 M444 75 H450\"/></g><circle cx=\"215\" cy=\"75\" r=\"23\" fill=\"#1e293b\"/><circle cx=\"565\" cy=\"75\" r=\"23\" fill=\"#1e293b\"/><g fill=\"#1e293b\" stroke=\"none\"><text x=\"70\" y=\"145\">开缝前</text><text x=\"425\" y=\"145\">开缝后</text></g></g></svg>"}],"cards":[{"id":"ki-j-013","title":"连通部分与内部孔洞互不替代","core":"连通部分的判断是能否沿图上实际存在的墨迹从一处走到另一处。两个黑环用黑桥相连，就是一个墨迹分支；远处独立圆盘是第二支。两个环内部仍有两个孔洞，所以“2部分”和“2洞”来自不同指标。若桥有真正白缝，两个环重新分离。剪影或粗线图很适合先查这一点，但题目也可能考面积、对称或孔数，不能仅凭生活物品外形固定选指标；看起来挨近也不能代替实际接触。","boundary":"仅视觉贴近不算相连；内部空洞影响面数，不一定改变部分数。","prompt":"两个黑环由实心桥接通，旁边另有分离圆盘，墨迹共有{{0}}个连通分支；环内仍有{{1}}个孔洞。把桥切出白缝后，分支变{{2}}个。剪影只提供检索{{3}}，不是规律结论。","blanks":[{"answer":"2","accept":[]},{"answer":"2","accept":[]},{"answer":"3","accept":[]},{"answer":"线索","accept":[]}]}],"questions":[{"id":"ki-jq-013","lesson":"figure-features","stem":"两个实心黑圆环由一条实心黑桥连接，桥不堵塞环内孔；另有一个不接触它们的实心圆盘。随后仅在桥中间开一道贯穿白缝，其他位置不变。下列“开缝前分支数、孔洞数、开缝后分支数”正确的是？","options":["1、2、2","3、2、3","2、3、2","2、2、3；剪影外形只提示搜索，连通仍据桥和白缝核实"],"answer":3,"explanation":"桥把两黑环连为一支，圆盘是另一支，故2支；每环内部各一白洞，共2洞。白缝切断唯一通路后，两环与圆盘分别独立，成为3支。粗轮廓的孔与墨迹的连通不是同一计数。 “看起来像剪影”不直接决定规律，真正的连接与断开才是本题证据。","optionReviews":["圆盘始终与两环分离，至少有两支。","开缝前两环通过桥已相连。","圆盘无白洞，切断桥会增加分支。","连通变化和孔洞计数均正确。"]}]},{"lessonId":"cube-net","topicId":"spatial-figures","courseRoute":"#course/reasoning/topic/spatial-figures","sections":[{"title":"折回后用三组相反法向核对","text":"给自绘展开图的中央面A设朝外法向+z，右邻B折起后为+x，B右邻C继续折后为-z，左邻D为-x，上邻E为+y，下邻F为-y。法向相反的一对互不共棱，所以相对面是A/C、B/D、E/F；其余面互为相邻且共一棱。一个立方体顶点会聚三面，必从每对相对面各取一个，例如A、B、E可会聚，A、C、E不行。平面上远近或隔一格只是局部提示，须沿展开图邻接折叠，不能当不依赖布局的定律。","index":9,"domId":"ki-point-0136","diagramSvg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 180\" role=\"img\" aria-label=\"原创示意图\"><rect width=\"480\" height=\"180\" fill=\"white\"/><g fill=\"none\" stroke=\"#1e293b\" stroke-width=\"3\"><rect x=\"125\" y=\"55\" width=\"55\" height=\"55\"/><rect x=\"180\" y=\"55\" width=\"55\" height=\"55\"/><rect x=\"235\" y=\"55\" width=\"55\" height=\"55\"/><rect x=\"70\" y=\"55\" width=\"55\" height=\"55\"/><rect x=\"125\" y=\"0\" width=\"55\" height=\"55\"/><rect x=\"125\" y=\"110\" width=\"55\" height=\"55\"/><g fill=\"#1e293b\" stroke=\"none\" font-size=\"20\"><text x=\"145\" y=\"90\">A</text><text x=\"200\" y=\"90\">B</text><text x=\"255\" y=\"90\">C</text><text x=\"90\" y=\"90\">D</text><text x=\"145\" y=\"35\">E</text><text x=\"145\" y=\"145\">F</text></g></g></svg>"}],"cards":[{"id":"ki-j-014","title":"折回后用三组相反法向核对","core":"给自绘展开图的中央面A设朝外法向+z，右邻B折起后为+x，B右邻C继续折后为-z，左邻D为-x，上邻E为+y，下邻F为-y。法向相反的一对互不共棱，所以相对面是A/C、B/D、E/F；其余面互为相邻且共一棱。一个立方体顶点会聚三面，必从每对相对面各取一个，例如A、B、E可会聚，A、C、E不行。平面上远近或隔一格只是局部提示，须沿展开图邻接折叠，不能当不依赖布局的定律。","boundary":"平面中隔一格或看似距离远，不可脱离展开图拓扑直接套用。","prompt":"把A、B、C、D、E、F折成面法向+z、+x、-z、-x、+y、-y，相对面为A/{{0}}、B/{{1}}、E/{{2}}。同一角点三面须两两{{3}}，相对面{{4}}共棱。","blanks":[{"answer":"C","accept":[]},{"answer":"D","accept":[]},{"answer":"F","accept":[]},{"answer":"相邻","accept":[]},{"answer":"不","accept":[]}]}],"questions":[{"id":"ki-jq-014","lesson":"cube-net","stem":"自绘展开图为横排D-A-B-C，E接在A上边、F接在A下边。折成正方体。哪项给出全部相对面，并正确判断可共顶点的三面？","options":["A/B、C/D、E/F；A、C、E可以共顶点","A/D、B/C、E/F；D、B、F可以共顶点","A/C、B/D、E/F；A、B、E可以共顶点","A/C、B/D、E/F；A、C、E可以共顶点"],"answer":2,"explanation":"从A向四周折起并继续把C折回，可得三组相反法向。A、B、E分别来自三组，能在一个角点相遇；A与C相对，不可能同时属于某个顶点。","optionReviews":["A与B在展开图直接共边，必是相邻。","A与D、B与C均直接共棱，不是相对。","折叠法向和三面邻接关系都吻合。","相对面A与C不共任何顶点。"]}]},{"lessonId":"cube-net","topicId":"spatial-figures","courseRoute":"#course/reasoning/topic/spatial-figures","sections":[{"title":"固定参照面后再看环绕顺序","text":"立体朝向会变，但把同一个参照面及其独特角标对齐后，周界邻面次序就有可比性。沿图示A面外侧观看，以其左上角为起点，顺时针扫上、右、下、左四边，依次邻接E、B、F、D。整体转动立方体可以让面内方位改变，却不能在同一外侧观察约定下把周界次序倒成镜像。核对时先定A，再对齐同一角标和起点，最后查四边。若一张从面内看、一张从面外看，表观顺逆会翻转，必须先统一观察方向。","index":10,"domId":"ki-point-0137","diagramSvg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 180\" role=\"img\" aria-label=\"A面左上角带唯一星标的正方体展开图\"><rect width=\"480\" height=\"180\" fill=\"white\"/><g fill=\"none\" stroke=\"#1e293b\" stroke-width=\"3\"><rect x=\"125\" y=\"55\" width=\"55\" height=\"55\"/><rect x=\"180\" y=\"55\" width=\"55\" height=\"55\"/><rect x=\"235\" y=\"55\" width=\"55\" height=\"55\"/><rect x=\"70\" y=\"55\" width=\"55\" height=\"55\"/><rect x=\"125\" y=\"0\" width=\"55\" height=\"55\"/><rect x=\"125\" y=\"110\" width=\"55\" height=\"55\"/><g fill=\"#1e293b\" stroke=\"none\" font-size=\"20\"><text x=\"145\" y=\"90\">A</text><text x=\"200\" y=\"90\">B</text><text x=\"255\" y=\"90\">C</text><text x=\"90\" y=\"90\">D</text><text x=\"145\" y=\"35\">E</text><text x=\"145\" y=\"145\">F</text></g></g><polygon points=\"135,60 137,65 142,65 138,68 140,73 135,70 130,73 132,68 128,65 133,65\" fill=\"#d97706\" stroke=\"#92400e\" stroke-width=\"1\"/></svg>"}],"cards":[{"id":"ki-j-015","title":"固定参照面后再看环绕顺序","core":"立体朝向会变，但把同一个参照面及其独特角标对齐后，周界邻面次序就有可比性。沿图示A面外侧观看，以其左上角为起点，顺时针扫上、右、下、左四边，依次邻接E、B、F、D。整体转动立方体可以让面内方位改变，却不能在同一外侧观察约定下把周界次序倒成镜像。核对时先定A，再对齐同一角标和起点，最后查四边。若一张从面内看、一张从面外看，表观顺逆会翻转，必须先统一观察方向。","boundary":"观看立体图的视角会改变表观顺逆时针；需要以同一面法向与观察约定统一方向。","prompt":"周界法先找同一{{0}}，对齐同一角标和起点，再统一从外侧的{{1}}方向。外侧看A的上右下左邻面E、B、F、D，不能在不改观察约定时反成E、D、F、B，因为那是{{2}}。","blanks":[{"answer":"参照面","accept":[]},{"answer":"环绕","accept":[]},{"answer":"镜像","accept":[]}]}],"questions":[{"id":"ki-jq-015","lesson":"cube-net","stem":"展开图仍为横排D-A-B-C，E在A上、F在A下。A左上角有唯一星标。一个候选立方体把A及星标与原图按“从A外侧观看，星在左上”对齐。沿A的上、右、下、左边，邻面次序必须是？","options":["B、F、D、E，星标也无需对齐","C、B、F、D","E、D、F、B","E、B、F、D"],"answer":3,"explanation":"一旦同一面、同一角标和同一外侧视向固定，上右下左就是E、B、F、D。E、D、F、B是镜像反序；B、F、D、E改变了起点却未同步对齐角标；C与A相对，不能作为沿A边邻接的面。","optionReviews":["不对齐角标会把不同面内旋转混在一起。","C与A相对，不能沿A边邻接。","反转左右邻接，不能由保持约定的整体旋转得到。","基准、起点及环绕方向一致。"]}]},{"lessonId":"t35-spatial-transform","topicId":"spatial-figures","courseRoute":"#course/reasoning/topic/spatial-figures","sections":[{"title":"截面上的所有边必须共面","text":"截面是一个平面切入实体后得到的二维交集，不是把立体表面几条看似合适的线拼起来。单位立方体用x+y+z=1切，三个截点(1,0,0)、(0,1,0)、(0,0,1)都满足同一方程，连成三角形；每条边同时落在该平面和一个立方体表面上。点(0,0.4,0.6)也在其中，(0,0.4,0.5)则不在。切面仅擦到顶点可能只得一点，贴着棱可能只得线段，这类退化交集不应假称正常多边形截面。核图先验证共面，再查边界连通和实体范围。","index":9,"domId":"ki-point-0138"}],"cards":[{"id":"ki-j-016","title":"截面上的所有边必须共面","core":"截面是一个平面切入实体后得到的二维交集，不是把立体表面几条看似合适的线拼起来。单位立方体用x+y+z=1切，三个截点(1,0,0)、(0,1,0)、(0,0,1)都满足同一方程，连成三角形；每条边同时落在该平面和一个立方体表面上。点(0,0.4,0.6)也在其中，(0,0.4,0.5)则不在。切面仅擦到顶点可能只得一点，贴着棱可能只得线段，这类退化交集不应假称正常多边形截面。核图先验证共面，再查边界连通和实体范围。","boundary":"不能把不同高度或不同方向的数次切割结果拼成一个截面；切向接触的退化情形须另列。","prompt":"三个点确定的截平面为x+y+z=1时，候选点必须满足{{0}}才能拼接同一截面。只碰到一个顶点是{{1}}交集，不是非退化三角形。","blanks":[{"answer":"同一平面方程","accept":[]},{"answer":"退化","accept":[]}]}],"questions":[{"id":"ki-jq-016","lesson":"t35-spatial-transform","stem":"单位立方体内的切平面经过(1,0,0)、(0,1,0)、(0,0,1)。某人准备再取一个表面点与已有截边拼接。哪一项点与理由正确？","options":["(0,0.4,0.6)，三个坐标之和为1，处于同一切平面","(0,0.4,0.5)，只要都在立方体表面就可拼接","(0,0,0)，切面仅接一个顶点也算上述三角截面","(1,1,0)，各坐标均在0至1就必属于截面"],"answer":0,"explanation":"原三点确定平面x+y+z=1。点(0,0.4,0.6)坐标和为1，且在x=0表面；原点、(0,0.4,0.5)、(1,1,0)的坐标和分别为0、0.9、2，均不在该切平面。属于实体或表面是必要但不充分的检查。","optionReviews":["共面、位于表面及范围均符合。","坐标和为0.9，不在原平面。","原点不在此平面，且单点接触是退化情况。","坐标和为2，实体内并不等于切面内。"]}]},{"lessonId":"t35-spatial-transform","topicId":"spatial-figures","courseRoute":"#course/reasoning/topic/spatial-figures","sections":[{"title":"长方体截面最多六条边","text":"完整长方体是有六个平面面的凸多面体。切平面穿过内部且不与原表面共面时，与任一个面的交集至多贡献一条截边，所以多边形截面最多六边。靠近顶角可切出三角形；与一对相对面平行的切法可得矩形；适当方向还能得梯形、其他四边形、五边形或六边形。以单位立方体为例，z=1/2给正方形，x+y+z=1/2给三角形，x+y+z=3/2给六边形，x+2y+3z=5/2给五边形。正方形归入矩形是包含式分类，若选项要互斥须另作约定。上限来自凸体和平面条件，不是任意复杂物体都六边。 另一个可复算的梯形例是x+2y+2z=3/2，其四顶点为(0,3/4,0)、(0,0,3/4)、(1,1/4,0)、(1,0,1/4)，两条x=常数的边平行且长短不同。平面z=1/4+x/4+y/4则截出非矩形平行四边形，表明矩形不是四边形的全部。 若切平面恰与原来的一个面重合，应单独视为那个四边形面，而非强套“共面面只贡献一边”的论证；它同样不突破六边上限。","index":10,"domId":"ki-point-0139"}],"cards":[{"id":"ki-j-017","title":"长方体截面最多六条边","core":"完整长方体是有六个平面面的凸多面体。切平面穿过内部且不与原表面共面时，与任一个面的交集至多贡献一条截边，所以多边形截面最多六边。靠近顶角可切出三角形；与一对相对面平行的切法可得矩形；适当方向还能得梯形、其他四边形、五边形或六边形。以单位立方体为例，z=1/2给正方形，x+y+z=1/2给三角形，x+y+z=3/2给六边形，x+2y+3z=5/2给五边形。正方形归入矩形是包含式分类，若选项要互斥须另作约定。上限来自凸体和平面条件，不是任意复杂物体都六边。 另一个可复算的梯形例是x+2y+2z=3/2，其四顶点为(0,3/4,0)、(0,0,3/4)、(1,1/4,0)、(1,0,1/4)，两条x=常数的边平行且长短不同。平面z=1/4+x/4+y/4则截出非矩形平行四边形，表明矩形不是四边形的全部。 若切平面恰与原来的一个面重合，应单独视为那个四边形面，而非强套“共面面只贡献一边”的论证；它同样不突破六边上限。","boundary":"常见形状列表不是完整目录；正方形是矩形的特殊情况，分类需说明约定。","prompt":"完整长方体一面至多贡献{{0}}条非重合截边，共六面故最多{{1}}边；既可能三角、矩形、梯形，也可能{{2}}边和六边。正方形按包含式分类{{3}}矩形。","blanks":[{"answer":"1","accept":[]},{"answer":"6","accept":[]},{"answer":"五","accept":[]},{"answer":"属于","accept":[]}]}],"questions":[{"id":"ki-jq-017","lesson":"t35-spatial-transform","stem":"对单位立方体作非退化平面截切。四个平面分别为①z=1/2，②x+y+z=1/2，③x+2y+3z=5/2，④x+y+z=3/2。哪项是正确的形状说明及上界？","options":["①正方形，②三角，③六边，④五边；只可能这四种形状","四个都是四边形，因为长方体底面是四边形","①正方形也是矩形，②三角，③五边，④六边；上界六边","①不是矩形，②三角，③五边，④六边；上界七边"],"answer":2,"explanation":"①与水平底面平行；②截三条同顶点棱。③在立方体12棱上有5个不同截点，④有6个；凸截面顶点依次相连即为五、六边形。未列出的其他四边形和梯形也可能出现，四例不是完整目录。","optionReviews":["③④的顶点数颠倒，形状列表也非穷尽。","截面不是底面投影，可穿过超过四个面。","具体例和六面的边数上限都正确。","正方形是矩形特例，且完整长方体最多六边。"]},{"id":"ki-jq-extra-trapezoid","lesson":"t35-spatial-transform","stem":"单位立方体被平面x+2y+2z=3/2切，截点为P(0,3/4,0)、Q(0,0,3/4)、R(1,1/4,0)、S(1,0,1/4)。四点按P-Q-S-R连成截面。哪项判断正确？","options":["PQ与RS长度相同，截面必是正方形","因有四个点，所以不可能存在梯形截面","切到四个面，便可再任意添加三个不共面截点成为七边形","PQ与RS平行且长短不同，截面为梯形；完整长方体仍至多六边"],"answer":3,"explanation":"PQ向量(0,-3/4,3/4)，RS向量(0,-1/4,1/4)，相互平行，长度比3:1。另两边不是平行边，因此是梯形。截面仍来自一个平面，不能任意加点突破六面上限。","optionReviews":["平行边长度比3:1，不是等长，当然非正方形。","四边形恰可有一组平行边而为梯形。","不共面的点无法属于同一截面，上界也不许七边。","向量、长度及上界均有充分依据。"]}]},{"lessonId":"t35-spatial-transform","topicId":"spatial-figures","courseRoute":"#course/reasoning/topic/spatial-figures","sections":[{"title":"三角截面锐角性来自三个正点积","text":"完整长方体的非退化三角截面截去一个顶角，三顶点分别在该角的三条互相垂直棱上。以这个角为原点，记P=(a,0,0)、Q=(0,b,0)、R=(0,0,c)，a,b,c均正。P处向量PQ与PR点积为a²，Q处为b²，R处为c²，全部正，所以三角都是锐角。例a=1、b=2、c=3时，三边平方为5、10、13，最长13仍小于另两项之和15，也能交叉验证锐角。不能把结论推广到任意棱锥、斜平行六面体，或零面积的退化截切。","index":11,"domId":"ki-point-0140"}],"cards":[{"id":"ki-j-018","title":"三角截面锐角性来自三个正点积","core":"完整长方体的非退化三角截面截去一个顶角，三顶点分别在该角的三条互相垂直棱上。以这个角为原点，记P=(a,0,0)、Q=(0,b,0)、R=(0,0,c)，a,b,c均正。P处向量PQ与PR点积为a²，Q处为b²，R处为c²，全部正，所以三角都是锐角。例a=1、b=2、c=3时，三边平方为5、10、13，最长13仍小于另两项之和15，也能交叉验证锐角。不能把结论推广到任意棱锥、斜平行六面体，或零面积的退化截切。","boundary":"仅针对完整正方体或长方体的非退化平面三角截面，不能推广到任意多面体。","prompt":"三截点P(a,0,0)、Q(0,b,0)、R(0,0,c)须a,b,c均{{0}}。三顶角两边点积为a²、b²、c²，故全为{{1}}角；适用对象是完整{{2}}的非退化三角截面。","blanks":[{"answer":"正","accept":[]},{"answer":"锐","accept":[]},{"answer":"长方体","accept":[]}]}],"questions":[{"id":"ki-jq-018","lesson":"t35-spatial-transform","stem":"在边长均为4的正方体内，截平面经过P(1,0,0)、Q(0,2,0)、R(0,0,3)。下列哪项正确给出P、Q、R处的两边点积及角形，并符合适用范围？","options":["点积1、4、9，三角全锐；任何多面体三角截面都如此","点积1、4、9，三角全锐；此结论针对完整长方体的非退化三角截面","点积0、4、9，有一直角；因为原棱互相垂直","点积-1、-4、-9，三角全钝；所有截面都如此"],"answer":1,"explanation":"P处(-1,2,0)·(-1,0,3)=1；Q处(1,-2,0)·(0,-2,3)=4；R处(1,0,-3)·(0,2,-3)=9。正点积对应锐角，互相垂直的是原棱而不是截面三边。","optionReviews":["算式正确但错误推广到任意多面体。","计算及对象限制都正确。","把原来的直角搬到斜截边上。","实际点积正，且三角形不可能三角全钝。"]}]},{"lessonId":"t35-spatial-transform","topicId":"spatial-figures","courseRoute":"#course/reasoning/topic/spatial-figures","sections":[{"title":"有限圆柱的斜切还要查底面裁断","text":"考虑实心正圆柱x²+y²≤1、0≤z≤4。z=2与底平行，截面为半径1圆；x=0平面平行轴且穿入内部，得到宽2高4矩形。z=2+x/2的高度范围在1.5至2.5，侧面交线不碰上下底，截面是完整椭圆。若改为z=0.2+x/2，部分理论椭圆落到z<0，实际截面被底面裁去，边界含z=0上的直线弦及曲线，不是完整椭圆。“斜切得椭圆”必须同时核对正圆柱、非平行轴及未被有限高度截断；切平面只相切时还可能退化。","index":12,"domId":"ki-point-0141"}],"cards":[{"id":"ki-j-019","title":"有限圆柱的斜切还要查底面裁断","core":"考虑实心正圆柱x²+y²≤1、0≤z≤4。z=2与底平行，截面为半径1圆；x=0平面平行轴且穿入内部，得到宽2高4矩形。z=2+x/2的高度范围在1.5至2.5，侧面交线不碰上下底，截面是完整椭圆。若改为z=0.2+x/2，部分理论椭圆落到z<0，实际截面被底面裁去，边界含z=0上的直线弦及曲线，不是完整椭圆。“斜切得椭圆”必须同时核对正圆柱、非平行轴及未被有限高度截断；切平面只相切时还可能退化。","boundary":"有限圆柱的任意斜切并非总是完整椭圆；与底面相交可出现带直线段的混合边界。","prompt":"正圆柱内，切面平行底得{{0}}；平行轴且过内部得{{1}}；斜面与侧面交线未被上下底裁断才得完整{{2}}。被底截断时可能有曲线与{{3}}混合边界。","blanks":[{"answer":"圆","accept":[]},{"answer":"矩形","accept":[]},{"answer":"椭圆","accept":[]},{"answer":"直线段","accept":[]}]}],"questions":[{"id":"ki-jq-019","lesson":"t35-spatial-transform","stem":"实心正圆柱x²+y²≤1、0≤z≤4，被①z=2、②x=0、③z=2+x/2、④z=0.2+x/2四平面切。依次正确描述是？","options":["圆、三角形、完整椭圆、完整椭圆","矩形、圆、完整椭圆、完整椭圆","圆、矩形、圆、无法判断是否裁断","圆、矩形、完整椭圆、被底截断的曲直混合截面"],"answer":3,"explanation":"①水平，②轴向；③在x∈[-1,1]时z∈[1.5,2.5]，完整保留。④当x<-0.4时z<0，被实体底面排除；在x=-0.4处出现截面直线弦。","optionReviews":["轴向截面不是三角形，④被底面截断。","水平与轴向形状倒置。","③斜切一般是椭圆，④用高度范围可以判定。","方向与有限高度限制都已核对。"]}]},{"lessonId":"t35-spatial-transform","topicId":"spatial-figures","courseRoute":"#course/reasoning/topic/spatial-figures","sections":[{"title":"圆锥切法要说明锥顶和边界","text":"取实心正圆锥0≤z≤4、半径r(z)=2-z/2，顶点在(0,0,4)。水平面z=2给半径1圆；通过锥轴的y=0平面含顶点且穿内部，截面是底边4、高4的等腰三角形。斜面z=2+x/4不经过顶点，且侧面相交曲线完整处在底与顶之间，得到椭圆。若任意加大斜率或把切面下移，可能与底面相交而出现直线弦，不能一概说椭圆。有限实心锥的二维截面和无限双锥表面上定义的抛物线、双曲线是不同讨论对象，应用时别换对象。","index":13,"domId":"ki-point-0142"}],"cards":[{"id":"ki-j-020","title":"圆锥切法要说明锥顶和边界","core":"取实心正圆锥0≤z≤4、半径r(z)=2-z/2，顶点在(0,0,4)。水平面z=2给半径1圆；通过锥轴的y=0平面含顶点且穿内部，截面是底边4、高4的等腰三角形。斜面z=2+x/4不经过顶点，且侧面相交曲线完整处在底与顶之间，得到椭圆。若任意加大斜率或把切面下移，可能与底面相交而出现直线弦，不能一概说椭圆。有限实心锥的二维截面和无限双锥表面上定义的抛物线、双曲线是不同讨论对象，应用时别换对象。","boundary":"有限实心圆锥的截面和无限圆锥曲面的圆锥曲线不是同一概念；任意斜切不保证完整椭圆。","prompt":"有限正圆锥中，平行底且穿内部得{{0}}；切面过锥顶并穿内部可得{{1}}；不经顶的适当斜切且未被底裁断可得{{2}}。任意斜切{{3}}保证完整椭圆。","blanks":[{"answer":"圆","accept":[]},{"answer":"三角形","accept":[]},{"answer":"椭圆","accept":[]},{"answer":"不","accept":[]}]}],"questions":[{"id":"ki-jq-020","lesson":"t35-spatial-transform","stem":"正圆锥顶点(0,0,4)，底为z=0、半径2圆盘。①z=2；②y=0；③z=2+x/4。哪项描述正确并保留必要条件？","options":["①圆；②三角形；③双曲线，因为圆锥斜切总得双曲线","①半径2圆；②矩形；③只要斜就完整椭圆","①圆；②过顶的椭圆；③三角形，是否过顶不重要","①半径1圆；②过顶的三角形；③未触底的完整椭圆；任意斜切不能照此套用"],"answer":3,"explanation":"半高处半径缩为1。轴截面两腰在锥面母线上、底边在底盘上。③斜率1/4小且高度在1.5至2.5的包围区间，未到上下端，因此形成闭合椭圆。有限实体的底面裁断仍须单独检查。","optionReviews":["把无限锥曲线名称当有限截面通则。","错用底半径，轴截面不是矩形，且斜切有条件。","过顶穿内部才会出现两条母线围成三角形。","三种方向、锥顶及有限边界都正确。"]}]},{"lessonId":"t35-spatial-transform","topicId":"spatial-figures","courseRoute":"#course/reasoning/topic/spatial-figures","sections":[{"title":"圆台的轴截面才稳定为等腰梯形","text":"实心正圆台0≤z≤4，半径从底部3线性减到顶部1，即r(z)=3-z/2。z=2的截面是半径2圆；包含整个旋转轴的平面y=0得到两条平行底边长6和2、腰对称的等腰梯形。斜面z=2+x/5不包含轴，且整个交线离上下底有余量，可以得到完整椭圆。其他不经轴的竖直或斜切，若撞到底盘就会有直线段与曲线共同组成边界，不能都叫等腰梯形或椭圆。这里默认正圆台、大小底不等及非退化切入。","index":14,"domId":"ki-point-0143"}],"cards":[{"id":"ki-j-021","title":"圆台的轴截面才稳定为等腰梯形","core":"实心正圆台0≤z≤4，半径从底部3线性减到顶部1，即r(z)=3-z/2。z=2的截面是半径2圆；包含整个旋转轴的平面y=0得到两条平行底边长6和2、腰对称的等腰梯形。斜面z=2+x/5不包含轴，且整个交线离上下底有余量，可以得到完整椭圆。其他不经轴的竖直或斜切，若撞到底盘就会有直线段与曲线共同组成边界，不能都叫等腰梯形或椭圆。这里默认正圆台、大小底不等及非退化切入。","boundary":"只有轴截面等特定条件才保证等腰梯形；有限圆台其他切法会受上下底面截断。","prompt":"正圆台平行底切得{{0}}；包含旋转轴切得{{1}}；适当斜切、侧面交线不被上下底裁断可得{{2}}。离轴切面不能仅凭“圆台”就断定梯形。","blanks":[{"answer":"圆","accept":[]},{"answer":"等腰梯形","accept":[]},{"answer":"椭圆","accept":[]}]}],"questions":[{"id":"ki-jq-021","lesson":"t35-spatial-transform","stem":"正圆台0≤z≤4，r(z)=3-z/2。①z=2；②y=0；③z=2+x/5。下列说明正确的是？","options":["①半径2圆；②上底2下底6等腰梯形；③未被底面裁断时为完整椭圆","①半径3圆；②任意四边形；③必为三角形","①圆；②等腰梯形；所有不经轴的切面仍都是等腰梯形","①圆；②矩形；③任意斜面均为完整椭圆"],"answer":0,"explanation":"中高半径为2。轴截面由两条母线和两底直径围成等腰梯形，底长是半径的两倍。③因|x|≤3而z∈[1.4,2.6]，交线不达0或4，可形成完整椭圆。","optionReviews":["半径、轴截面尺寸及斜切限制均正确。","中高半径为2且轴截面不是任意形状。","离轴切面可能带曲线，形状不能统一叫梯形。","上下底大小不等，轴截面不是矩形。"]}]},{"lessonId":"definition","topicId":"definition-analysis","courseRoute":"#course/reasoning/topic/definition-analysis","sections":[{"title":"术语拆字只是建立理解假设","text":"遇到“共享工作坊”这类日常词组合，可以先用“共享”想到多方共同使用、用“工作坊”想到作业空间，再回到题设核验。若题设专门规定为“两家以上独立机构共同使用同一生产空间，且各自独立经营”，决定归类的是四个限制，不是我们对词名的直觉。比如两家企业同厂房生产并分别接单符合；一家机构给内部部门共用会议室不符合主体范围。术语若是专业约定或题目自定义，拆字更不能覆盖正文定义。","index":12,"domId":"ki-point-0144"}],"cards":[{"id":"ki-j-022","title":"术语拆字只是建立理解假设","core":"遇到“共享工作坊”这类日常词组合，可以先用“共享”想到多方共同使用、用“工作坊”想到作业空间，再回到题设核验。若题设专门规定为“两家以上独立机构共同使用同一生产空间，且各自独立经营”，决定归类的是四个限制，不是我们对词名的直觉。比如两家企业同厂房生产并分别接单符合；一家机构给内部部门共用会议室不符合主体范围。术语若是专业约定或题目自定义，拆字更不能覆盖正文定义。","boundary":"专业词、约定俗成词和题设自定义含义不能仅按字面拆词。","prompt":"拆词能帮助生成{{0}}，正式分类以{{1}}为准。“共享工作坊”若要求多家独立机构，单家内部部门共用房间即使字面像共享也{{2}}。","blanks":[{"answer":"理解假设","accept":[]},{"answer":"题设定义","accept":[]},{"answer":"不符合","accept":[]}]}],"questions":[{"id":"ki-jq-022","lesson":"definition","stem":"本题把“共享工作坊”定义为：两家及以上独立机构共同使用同一生产空间，并各自独立经营。哪项属于该定义？","options":["一家公司的两个部门轮流用会议室","两家公司合并成一家后统一经营同一车间","两家独立修理企业共用车间，分别接单和结算","两家公司各自在不同厂房生产，只共用同一品牌"],"answer":2,"explanation":"两家独立修理企业共用车间并分别接单结算，同时满足全部限定。不同厂房只共品牌缺少共同生产空间；合并后统一经营不再满足多家独立机构及各自独立经营；同一公司内部部门共用会议室也不符合主体和空间限制。拆词不能替换完整定义。","optionReviews":["两个部门不是两家独立机构，会议室也非题设生产空间。","合并后仅一家机构且统一经营。","所有题设限定明确满足。","没有共同使用同一生产空间。"]}]},{"lessonId":"definition","topicId":"definition-analysis","courseRoute":"#course/reasoning/topic/definition-analysis","sections":[{"title":"把定义的且、或和缺失信息写清","text":"定义不是关键词袋，要保存逻辑结构。例如“会员互助”规定已登记成员自愿无偿地为其他成员投入时间或捐赠物资，可写成登记∧自愿∧无偿∧面向成员∧(时间∨物资)。括号中满足一种即可，外部条件却都要满足。案例明确说收取报酬，与无偿冲突可排除；只说身份没有交代是否登记，则是未知，不能自动填成不登记，也不能靠愿望补全。只有全部限制及连接方式有支持，才能确认属于。 条件也可由明确语义推出，不必每个词原样复述：“捐物”已经说明投入物资，“已登记会员”说明主体为已登记成员；这与没有任何身份线索时擅自补全登记不同。","index":13,"domId":"ki-point-0145"}],"cards":[{"id":"ki-j-023","title":"把定义的且、或和缺失信息写清","core":"定义不是关键词袋，要保存逻辑结构。例如“会员互助”规定已登记成员自愿无偿地为其他成员投入时间或捐赠物资，可写成登记∧自愿∧无偿∧面向成员∧(时间∨物资)。括号中满足一种即可，外部条件却都要满足。案例明确说收取报酬，与无偿冲突可排除；只说身份没有交代是否登记，则是未知，不能自动填成不登记，也不能靠愿望补全。只有全部限制及连接方式有支持，才能确认属于。 条件也可由明确语义推出，不必每个词原样复述：“捐物”已经说明投入物资，“已登记会员”说明主体为已登记成员；这与没有任何身份线索时擅自补全登记不同。","boundary":"关键词都出现不等于逻辑结构满足；单一题目仍需比较选项信息完备程度。","prompt":"条件清单应保留{{0}}或{{1}}关系。明确收费与“无偿”是{{2}}，未交代登记情况是{{3}}；全部必要项满足才可确认。","blanks":[{"answer":"且","accept":[]},{"answer":"或","accept":[]},{"answer":"冲突","accept":[]},{"answer":"信息缺失","accept":[]}]}],"questions":[{"id":"ki-jq-023","lesson":"definition","stem":"“会员互助”要求：已登记成员，自愿、无偿，为其他成员投入时间或物资。甲：已登记，自愿无偿给另一成员捐物；乙：自愿无偿给成员服务，但未交代是否登记；丙：已登记，给成员服务并收取报酬。哪份判断准确？","options":["甲符合；乙明确不登记所以不符；丙仅信息缺失","甲、乙均必符合，因为没说不登记；丙也属于互助","甲符合；乙登记条件信息不足；丙与无偿明确冲突","甲不符合，因为时间和物资必须同时投入；乙、丙符合"],"answer":2,"explanation":"时间或物资是相容或，甲投入物资即满足这一项。乙的缺失不能补成真或假；丙已明确收费，应判冲突而非未知。 甲的“捐物”已能语义推出投入物资，不要求机械出现同一个关键词。","optionReviews":["乙没有“不登记”事实，丙收费也不是缺失。","把没有反证当成条件已被证实。","完整保留合取、析取、未知和冲突。","误把或改成且，且忽视收费限制。"]}]},{"lessonId":"definition","topicId":"definition-analysis","courseRoute":"#course/reasoning/topic/definition-analysis","sections":[{"title":"按角色拆开目的、办法和结果","text":"复杂定义可画成一条事件链：谁在什么条件和原因下，用什么办法，作用于谁，为了什么，实际造成什么。例“暴雨后道路封闭，社区居民用自备船转移被困居民，目的是避险，最终全部抵达安置点”：实施者是社区居民，受助者是被困居民，自备船是方式，避险是目的；暴雨是原因，道路封闭是适用前提，抵达安置点是结果。意图不保证成功，所以没达到目的不能自动说没有这一目的。主体也不能被工具或受助者替换。","index":14,"domId":"ki-point-0146"}],"cards":[{"id":"ki-j-024","title":"按角色拆开目的、办法和结果","core":"复杂定义可画成一条事件链：谁在什么条件和原因下，用什么办法，作用于谁，为了什么，实际造成什么。例“暴雨后道路封闭，社区居民用自备船转移被困居民，目的是避险，最终全部抵达安置点”：实施者是社区居民，受助者是被困居民，自备船是方式，避险是目的；暴雨是原因，道路封闭是适用前提，抵达安置点是结果。意图不保证成功，所以没达到目的不能自动说没有这一目的。主体也不能被工具或受助者替换。","boundary":"并非每个定义都具备七类条件，不应人为补足不存在的限制。","prompt":"居民因暴雨在封路后用船帮助被困者避险，最终安全抵达。主体{{0}}，客体{{1}}，方式{{2}}，目的{{3}}，原因{{4}}，前提{{5}}，结果{{6}}。","blanks":[{"answer":"居民","accept":[]},{"answer":"被困者","accept":[]},{"answer":"用船","accept":[]},{"answer":"避险","accept":[]},{"answer":"暴雨","accept":[]},{"answer":"封路","accept":[]},{"answer":"安全抵达","accept":[]}]}],"questions":[{"id":"ki-jq-024","lesson":"definition","stem":"定义案例：因暴雨，道路封闭后，社区居民用自备船帮助被困居民，旨在转移避险，最后全部抵达安置点。以下七角色映射正确的是？","options":["主体社区居民；客体被困居民；方式用船；目的抵达；原因暴雨；前提封路；结果原本想避险","主体社区居民；客体被困居民；方式用船；目的避险；原因暴雨；前提封路；结果抵达","主体自备船；客体社区居民；方式避险；目的抵达；原因封路；前提暴雨；结果用船","主体被困居民；客体自备船；方式社区居民；目的暴雨；原因避险；前提抵达；结果封路"],"answer":1,"explanation":"社区居民是主体，被困居民是客体，用船是方式，避险是目的，暴雨是原因，封路是前提，全部抵达安置点是结果。工具不能替代主体，也不能把已发生的抵达与原先意图混置。","optionReviews":["“旨在避险”是目的，“全部抵达”是已发生结果。","七角色和事件方向全匹配。","工具不是行为主体，目的也不是实施方式。","主体客体和因果角色大幅错置。"]}]},{"lessonId":"definition","topicId":"definition-analysis","courseRoute":"#course/reasoning/topic/definition-analysis","sections":[{"title":"不知道身份与身份不合格不同","text":"主体限定行为由谁实施，客体限定行为作用于谁。假设“公共检查”仅指有资质的市级检查员对公共营业场所依法检查。某人检查餐馆但没说明资质，属于身份信息待补；明确是无资质私人，则主体冲突；有资质检查员检查私人自住卧室，则客体冲突。不能用“做了检查”反推一定具有资格，也不能把没提资格判成没有资格。分类时把未知、符合、冲突分别标记，避免两个完全不同的排除理由混在一起。","index":15,"domId":"ki-point-0147"}],"cards":[{"id":"ki-j-025","title":"不知道身份与身份不合格不同","core":"主体限定行为由谁实施，客体限定行为作用于谁。假设“公共检查”仅指有资质的市级检查员对公共营业场所依法检查。某人检查餐馆但没说明资质，属于身份信息待补；明确是无资质私人，则主体冲突；有资质检查员检查私人自住卧室，则客体冲突。不能用“做了检查”反推一定具有资格，也不能把没提资格判成没有资格。分类时把未知、符合、冲突分别标记，避免两个完全不同的排除理由混在一起。","boundary":"题干不限制实施者时不能新增身份要求；有些主体范围可由行为自然推知。","prompt":"主体限定实施者的{{0}}，客体限定作用{{1}}。未交代资格是{{2}}；明确无资质是{{3}}，不能混为一类。","blanks":[{"answer":"资格","accept":[]},{"answer":"对象","accept":[]},{"answer":"未知","accept":[]},{"answer":"冲突","accept":[]}]}],"questions":[{"id":"ki-jq-025","lesson":"definition","stem":"“公共检查”限定有资质的市级检查员对公共营业场所检查。甲仅被描述为“某人检查一家餐馆”，身份未补充；乙明确是无资质私人，检查餐馆；丙是有资质检查员，检查个人自住卧室。哪项判断正确？","options":["甲必有资质；乙和丙只是没说清","甲主体未知；乙主体冲突；丙客体冲突","三者都符合，只要有检查行为","甲主体冲突；乙主体未知；丙客体符合"],"answer":1,"explanation":"甲没有证实资格也没有明确否定，只能记未知。乙明确不在合格实施者范围，丙检查对象不属公共营业场所，分别对应不同条件冲突。","optionReviews":["不能由行为反推资质，另外两案有明确冲突。","未知与两类冲突区分正确。","遗漏定义对实施者和对象的硬限制。","把信息缺失和明确不合格颠倒。"]}]},{"lessonId":"definition","topicId":"definition-analysis","courseRoute":"#course/reasoning/topic/definition-analysis","sections":[{"title":"语言标记要回到句义中核对","text":"“通过、借助、按某程序”常引出怎么做；“为了、旨在、以便”常引出想达到什么。句子“为减少取水损耗，合作社通过滴灌给果树供水，但本月实际损耗上升”，滴灌是手段，减损是目的，上升是结果。目的和手段可以同句出现，也可被其他插入语隔开。标记词只是定位帮助，仍要查语义，比如“为了研究‘通过率’”中的“通过”是名词组成部分，不能机械当手段标记。","index":16,"domId":"ki-point-0148"}],"cards":[{"id":"ki-j-026","title":"语言标记要回到句义中核对","core":"“通过、借助、按某程序”常引出怎么做；“为了、旨在、以便”常引出想达到什么。句子“为减少取水损耗，合作社通过滴灌给果树供水，但本月实际损耗上升”，滴灌是手段，减损是目的，上升是结果。目的和手段可以同句出现，也可被其他插入语隔开。标记词只是定位帮助，仍要查语义，比如“为了研究‘通过率’”中的“通过”是名词组成部分，不能机械当手段标记。","boundary":"介词或关联词须结合语义判断，不能一见某词就固定归类。","prompt":"为减损通过滴灌供水，实际损耗上升：手段是{{0}}，目的是{{1}}，结果是{{2}}。目的与手段可以在{{3}}句话出现。","blanks":[{"answer":"滴灌","accept":[]},{"answer":"减损","accept":[]},{"answer":"损耗上升","accept":[]},{"answer":"同一","accept":[]}]}],"questions":[{"id":"ki-jq-026","lesson":"definition","stem":"“为减少取水损耗，合作社通过滴灌向果树供水，但本月实际损耗上升。”对本句的分析哪项正确？","options":["减损是手段；滴灌是目的；损耗上升表明合作社没有减损目的","滴灌是手段；减损是目的；损耗上升是结果，同句兼有三种角色","既然目的没实现，整句没有任何可识别的手段","只要有“通过”二字，后面所有内容都是结果"],"answer":1,"explanation":"实施动作是用滴灌供水，意图是减少损耗，实际结果却与意图相反。失败的结果不抹除原先目的和已采用的手段。","optionReviews":["交换手段目的，并错误地由失败否认目的。","角色与意图/事实的区分正确。","方法确已采用，成功与否不影响它作为手段。","标记词不能包办整个后文的语义角色。"]}]},{"lessonId":"definition","topicId":"definition-analysis","courseRoute":"#course/reasoning/topic/definition-analysis","sections":[{"title":"先把原因和后果画成箭头","text":"“由于、缘于”通常标原因，“导致、使得”通常把原因接到结果，句序改变也不应改变箭头。比如“电缆老化导致短路，短路引发停机”可规范为老化→短路→停机。若定义要求首故障直接造成后故障，应区分直接一跳与经过中介的多跳；也不能从停机存在就反推一定短路，因为停机还可能另有原因。定义题是在给定因果事实中做归类，不是单凭相伴出现就新创因果。","index":17,"domId":"ki-point-0149"}],"cards":[{"id":"ki-j-027","title":"先把原因和后果画成箭头","core":"“由于、缘于”通常标原因，“导致、使得”通常把原因接到结果，句序改变也不应改变箭头。比如“电缆老化导致短路，短路引发停机”可规范为老化→短路→停机。若定义要求首故障直接造成后故障，应区分直接一跳与经过中介的多跳；也不能从停机存在就反推一定短路，因为停机还可能另有原因。定义题是在给定因果事实中做归类，不是单凭相伴出现就新创因果。","boundary":"原因通常不等于唯一原因或充分条件；题干只给相关时不能升级为因果。","prompt":"“由于A，B发生；B又导致C”应写A→{{0}}→{{1}}。已知结果C不能自动反推{{2}}，且“直接导致”要求不能漏掉{{3}}。","blanks":[{"answer":"B","accept":[]},{"answer":"C","accept":[]},{"answer":"A","accept":[]},{"answer":"中介","accept":[]}]}],"questions":[{"id":"ki-jq-027","lesson":"definition","stem":"题设事实：电缆老化直接造成短路；短路直接造成停机。本题定义“次生故障”为某故障直接引发的另一故障。哪项表述最准确？","options":["短路是老化的直接后果；停机是短路的直接后果，不能仅凭停机反推老化","凡有停机都必有短路，结果足以唯一定位原因","老化是停机的直接后果，因为它们在同一句","停机是老化的直接后果，中间有无短路无关"],"answer":0,"explanation":"先保留老化→短路→停机的方向与直接连接。老化到停机有中介，不符合本题“直接”的限定；题设没说其他停机原因被排除。","optionReviews":["箭头方向、直接性和反推限制均正确。","肯定结果不能唯一确定原因。","因果方向被倒置。","漏掉短路中介，擅自把间接改成直接。"]}]},{"lessonId":"definition","topicId":"definition-analysis","courseRoute":"#course/reasoning/topic/definition-analysis","sections":[{"title":"适用前提与触发条件不要写反","text":"先问一个条件是“做这件事离不开它”，还是“它一出现就必须做”。规则“冷屋仅在高温预警有效时开放”给开放O→预警V，预警是必要条件，并不单靠V推出开放。另有“室温达到32℃就开放”给高温H→开放O，这是充分触发。把两条合起来还可得H→V，所以若同时出现H真、V假，规则组会冲突，需要核查材料而不是删掉一条。至于“本周试点”只交代时间范围，除非明确说仅在本周，不能自作必要条件或触发器。","index":18,"domId":"ki-point-0150"}],"cards":[{"id":"ki-j-028","title":"适用前提与触发条件不要写反","core":"先问一个条件是“做这件事离不开它”，还是“它一出现就必须做”。规则“冷屋仅在高温预警有效时开放”给开放O→预警V，预警是必要条件，并不单靠V推出开放。另有“室温达到32℃就开放”给高温H→开放O，这是充分触发。把两条合起来还可得H→V，所以若同时出现H真、V假，规则组会冲突，需要核查材料而不是删掉一条。至于“本周试点”只交代时间范围，除非明确说仅在本周，不能自作必要条件或触发器。","boundary":"“当……时”常表示情境，并非总是严格必要条件；应以完整定义的逻辑为准。","prompt":"“仅在预警有效时开放”写O→{{0}}，预警是{{1}}条件；“达到32℃就开放”写H→{{2}}，H是充分触发。“本周试点”本身不等于{{3}}。","blanks":[{"answer":"V","accept":[]},{"answer":"必要","accept":[]},{"answer":"O","accept":[]},{"answer":"仅本周可开","accept":[]}]}],"questions":[{"id":"ki-jq-028","lesson":"definition","stem":"冷屋规则：仅在预警有效时开放；室温达到32℃就开放；该方案本周试点。以O=开放、V=预警有效、H=达到32℃，哪项翻译正确？","options":["O→V，O→H；只要预警就一定开放","H→V，非本周→不开放；不需要保留开放这个中间环节","O→V，H→O；“本周试点”本身不推出非本周禁止开放","V→O，O→H；本周每时每刻都必须开放"],"answer":2,"explanation":"“仅在V时O”表示O需要V，方向O→V；“H就O”表示H足以触发O，方向H→O。H→V可由联立推出，但不是把原规则删简后就能乱补时间禁令。","optionReviews":["第二箭头反向，且由必要条件误推充分。","前半是派生关系，后半擅加本周以外的禁止。","必要前提、充分触发、时间背景都保留准确。","两个箭头都写反，并把试点当每时开放。"]}]},{"lessonId":"analogy","topicId":"analogy-analysis","courseRoute":"#course/reasoning/topic/analogy-analysis","sections":[{"title":"语义、集合逻辑、句法逐层搜索","text":"类比先问词义是否相近、相反或有引申联系；再问两个概念是包含、交叉、因果还是某种角色对应；必要时把词连成短句，查谁对谁做什么。比如“迅捷—快速”主要是近义，“松树—植物”是下位类归上位类，“修复—仪器”组合成动宾关系。一个词对可能同时带多种性质，应选能稳定解释全部词项、且能区分选项的关系，不要只因可连成一句话就放弃更精确的逻辑。语义、逻辑、语法是搜索层次，不是绝对不可跨越的时间顺序。","index":9,"domId":"ki-point-0151"}],"cards":[{"id":"ki-j-043","title":"语义、集合逻辑、句法逐层搜索","core":"类比先问词义是否相近、相反或有引申联系；再问两个概念是包含、交叉、因果还是某种角色对应；必要时把词连成短句，查谁对谁做什么。比如“迅捷—快速”主要是近义，“松树—植物”是下位类归上位类，“修复—仪器”组合成动宾关系。一个词对可能同时带多种性质，应选能稳定解释全部词项、且能区分选项的关系，不要只因可连成一句话就放弃更精确的逻辑。语义、逻辑、语法是搜索层次，不是绝对不可跨越的时间顺序。","boundary":"三层是常见检索框架，不是对一切语言关系的穷尽分类。","prompt":"“迅捷—快速”先查{{0}}层；“松树—植物”查概念{{1}}层；“修复—仪器”可用{{2}}结构补充验证。应让同一关系覆盖题干{{3}}词项。","blanks":[{"answer":"语义","accept":[]},{"answer":"逻辑","accept":[]},{"answer":"动宾","accept":[]},{"answer":"全部","accept":[]}]}],"questions":[{"id":"ki-jq-043","lesson":"analogy","stem":"按最突出的可验证关系，为①迅捷—快速，②松树—植物，③修复—仪器，依次选关系说明。","options":["①反义；②整体组成；③组合为主谓","①近义；②交叉；③组合为偏正","①语法并列；②因果；③组合为并列","①近义；②种属包含；③组合为动宾"],"answer":3,"explanation":"迅捷与快速表达相近含义；松树属于植物而非植物的一个零件；修复是动作，仪器是该动作承受对象。三组分别展示语义、逻辑和句法的搜索。","optionReviews":["①不反义，②非组成，③动作不作主语。","②为包含不是交叉，③仪器是宾语。","三项均未符合其显著关系。","三个层次及各自关系都吻合。"]}]},{"lessonId":"analogy","topicId":"analogy-analysis","courseRoute":"#course/reasoning/topic/analogy-analysis","sections":[{"title":"互斥后还要检查是否穷尽","text":"先固定讨论全集和分类标准，再判断两类能否同时属于、是否存在第三类。所有申请在截止时只能是“已提交”或“未提交”，二者互斥且穷尽，是矛盾；纯色卡只有红、蓝、绿三色时，红卡与蓝卡互斥但仍有绿卡，是反对。若把“红色物体”放到允许混色的全集，红与蓝甚至可能交叉，所以全集不能省。并列类还可以比较次序：同一棵树的幼苗阶段先于成树阶段，这是另一个细节；它不使两个阶段自动成为穷尽一生的矛盾分类。","index":10,"domId":"ki-point-0152"}],"cards":[{"id":"ki-j-044","title":"互斥后还要检查是否穷尽","core":"先固定讨论全集和分类标准，再判断两类能否同时属于、是否存在第三类。所有申请在截止时只能是“已提交”或“未提交”，二者互斥且穷尽，是矛盾；纯色卡只有红、蓝、绿三色时，红卡与蓝卡互斥但仍有绿卡，是反对。若把“红色物体”放到允许混色的全集，红与蓝甚至可能交叉，所以全集不能省。并列类还可以比较次序：同一棵树的幼苗阶段先于成树阶段，这是另一个细节；它不使两个阶段自动成为穷尽一生的矛盾分类。","boundary":"全集必须一致；第三类是否存在要看题目讨论范围，而非脱离语境。","prompt":"互斥且穷尽全集叫{{0}}；互斥但有第三类叫{{1}}。幼苗到成树还可比{{2}}，但先后次序不能代替全集检验。","blanks":[{"answer":"矛盾","accept":[]},{"answer":"反对","accept":[]},{"answer":"时间先后","accept":[]}]}],"questions":[{"id":"ki-jq-044","lesson":"analogy","stem":"全集一为截止时的全部申请，状态仅分已提交/未提交；全集二为只涂红蓝绿之一的卡片；同一棵树先幼苗后成树。哪项关系组合正确？","options":["已/未提交为矛盾；红/蓝卡为反对；幼苗/成树还有时间先后","红/蓝在任何全集下必互斥，无需检查混色","已/未提交为反对；红/蓝卡为矛盾；时间先后必使类别穷尽","两组都交叉，因为都属于各自全集"],"answer":0,"explanation":"已/未提交没有第三状态，且不同时成立；纯色红蓝之外还有绿色。幼苗和成树先后是二级属性，树的一生还有其他阶段，不能据此断为矛盾。","optionReviews":["互斥、穷尽与并列后的细节都区分正确。","允许混色时同一物体可能既含红又含蓝。","交换了穷尽条件，且错误推广时间关系。","共同上位类不意味着有共同成员。"]}]},{"lessonId":"analogy","topicId":"analogy-analysis","courseRoute":"#course/reasoning/topic/analogy-analysis","sections":[{"title":"“是一种”与“是一个部分”分开","text":"种属关系是分类：松树是一种植物，因此任何松树个体都落在植物集合。组成关系是构造：树根是树的一个部分，却不能说树根是一种树。试着分别代入“X属于Y这一类”和“X构成Y的一部分”，通常能识别方向。分类上下位交换会改变关系；组成也要查部分到整体的方向。不要只看二者都“有关”或都能用“有”来造句，例如植物有松树这一种与树有树根表达的是完全不同的有。","index":11,"domId":"ki-point-0153"}],"cards":[{"id":"ki-j-045","title":"“是一种”与“是一个部分”分开","core":"种属关系是分类：松树是一种植物，因此任何松树个体都落在植物集合。组成关系是构造：树根是树的一个部分，却不能说树根是一种树。试着分别代入“X属于Y这一类”和“X构成Y的一部分”，通常能识别方向。分类上下位交换会改变关系；组成也要查部分到整体的方向。不要只看二者都“有关”或都能用“有”来造句，例如植物有松树这一种与树有树根表达的是完全不同的有。","boundary":"汉语“是”有多种含义，单凭一句顺口的话不够，要检验集合包含或部分关系。","prompt":"松树—植物是{{0}}；树根—树是{{1}}。前者可用“是一种”，后者可用“是其中{{2}}”，且箭头方向要保持一致。","blanks":[{"answer":"种属","accept":[]},{"answer":"组成","accept":[]},{"answer":"一部分","accept":[]}]}],"questions":[{"id":"ki-jq-045","lesson":"analogy","stem":"“松树—植物”与“树根—树”分别是什么关系？以下哪项给出了正确检验及方向？","options":["两者都是组成，且交换前后项不影响关系","两者都是种属，只要前项比后项小","前者种属：松树是一种植物；后者组成：树根是树的一部分","前者组成：松树是每株植物的一部分；后者种属：树根是一种树"],"answer":2,"explanation":"松树归类到植物集合，树根则在结构上构成树。种属看所有X是否都是Y，组成看X是否作为部件存在于Y中，不能靠大小作判据。","optionReviews":["两种关系不同，且方向不能随意交换。","物理大小不是分类包含的定义。","分类测试、部分测试与方向均正确。","把类的成员与物体部件对调。"]}]},{"lessonId":"analogy","topicId":"analogy-analysis","courseRoute":"#course/reasoning/topic/analogy-analysis","sections":[{"title":"交叉需要三个区域都有成员","text":"两集合交叉，不能只证明有共同成员，还须各自留下独有部分。设摄影班P与编程班C，共同报名6人，只报摄影4人，只报编程3人，则P∩C、P-C、C-P均非空，确为交叉。对应三句是有的P是C、有的P不是C、有的C不是P。若只知道有人两班都报，仍可能P完全包含于C，尚不能定交叉。常识范围不清时，用明确成员或计数支持这三块比凭名称猜测可靠。","index":12,"domId":"ki-point-0154"}],"cards":[{"id":"ki-j-046","title":"交叉需要三个区域都有成员","core":"两集合交叉，不能只证明有共同成员，还须各自留下独有部分。设摄影班P与编程班C，共同报名6人，只报摄影4人，只报编程3人，则P∩C、P-C、C-P均非空，确为交叉。对应三句是有的P是C、有的P不是C、有的C不是P。若只知道有人两班都报，仍可能P完全包含于C，尚不能定交叉。常识范围不清时，用明确成员或计数支持这三块比凭名称猜测可靠。","boundary":"仅证明存在共同对象不够，可能是一方包含另一方；四个有的中交集陈述互为对称，并非四个独立条件。","prompt":"严格交叉要{{0}}、甲独有和乙独有都非空。只证明有人两者兼有，还不能排除一类{{1}}另一类。P独有4、共6、C独有3时，两班人数为{{2}}和{{3}}。","blanks":[{"answer":"交集","accept":[]},{"answer":"包含于","accept":[]},{"answer":"10","accept":[]},{"answer":"9","accept":[]}]}],"questions":[{"id":"ki-jq-046","lesson":"analogy","stem":"摄影班与编程班共有6人，只报摄影4人，只报编程3人。哪项正确描述两集合，并给出足以证明该关系的证据？","options":["反对，因为两个班的名称不同","交叉，因为共同6、摄影独有4、编程独有3均为正","矛盾，因为全体报名者都在至少一班","摄影包含于编程，因为两班有人共同报名"],"answer":1,"explanation":"P人数10、C人数9，共同6说明不互斥，两边独有4和3又排除了任一方包含另一方。因此三个非空区域同时确认交叉。","optionReviews":["名称不同不足以判关系，实际还有共同成员。","三个必要区域都有明确成员。","矛盾要求互斥，两班有6个共同成员。","摄影独有4人已经否定摄影包含于编程。"]}]},{"lessonId":"analogy","topicId":"analogy-analysis","courseRoute":"#course/reasoning/topic/analogy-analysis","sections":[{"title":"对应关系先给两端命名","text":"对应不是一个笼统筐，应明确每一端的角色和方向。手电筒→照明是工具到主要功能；黏土→陶砖是原料到制成品；正方形→四边是对象到定义性属性。暴雨→河流涨水在给定事实中是事件到后果，而排版→印刷→装订是制作流程先后，不能把后三步说成同义词。主要功能也不代表唯一功能，材料可能有多种产品，因果关系还依赖情境。把角色写清，才能防止选项用产品→材料或后果→原因来反向匹配。","index":13,"domId":"ki-point-0155"}],"cards":[{"id":"ki-j-047","title":"对应关系先给两端命名","core":"对应不是一个笼统筐，应明确每一端的角色和方向。手电筒→照明是工具到主要功能；黏土→陶砖是原料到制成品；正方形→四边是对象到定义性属性。暴雨→河流涨水在给定事实中是事件到后果，而排版→印刷→装订是制作流程先后，不能把后三步说成同义词。主要功能也不代表唯一功能，材料可能有多种产品，因果关系还依赖情境。把角色写清，才能防止选项用产品→材料或后果→原因来反向匹配。","boundary":"同一对词可能有多种宽泛关系，择优时优先方向明确、语义紧密且全组一致的关系。","prompt":"手电筒→照明：工具到{{0}}；黏土→陶砖：{{1}}到制品；正方形→四边：对象到{{2}}；暴雨→涨水：事件到{{3}}；排版→印刷→装订：{{4}}。","blanks":[{"answer":"功能","accept":[]},{"answer":"原料","accept":[]},{"answer":"属性","accept":[]},{"answer":"后果","accept":[]},{"answer":"先后流程","accept":[]}]}],"questions":[{"id":"ki-jq-047","lesson":"analogy","stem":"下列哪份关系标注全部正确？①手电筒—照明；②黏土—陶砖；③正方形—四边；④题设已确认暴雨造成河涨；⑤排版—印刷—装订。","options":["①唯一功能；②唯一产品；③可有可无属性；④没有条件的必然；⑤同一动作","①工具/功能；②原料/制品；③对象/属性；④原因事件/后果；⑤先后流程","①工具/功能；②制品/原料；③对象/属性；④原因/后果；⑤先后流程","①制品/原料；②工具/功能；③整体/部分；④后果/原因；⑤近义"],"answer":1,"explanation":"逐一识别角色而不是泛称对应。②的方向是原料先、制品后；③四边是正方形定义性属性；④依本题因果事实判断，不能推广成所有暴雨必涨水；⑤为多步骤时序。","optionReviews":["把主要对应扩大成唯一、无条件或同一。","五类角色及方向均准确。","②把原料制品方向反了。","多处反向或错误归类。"]}]},{"lessonId":"analogy","topicId":"analogy-analysis","courseRoute":"#course/reasoning/topic/analogy-analysis","sections":[{"title":"一级关系相同后再比较细节","text":"属性可以是定义性必然，也可以只是常见：正方形有四边不可缺，纸张是白色却可被彩纸反例否定。流程也要看是否同主体，例如作者撰写再自行修改，与作者写作后由编辑校订，动作都先后却执行者不同。因果还可比较自然作用与人为干预：暴雨使河涨属自然过程，按命令开闸使下游涨水含人为操作。这些是一级关系一致时用于进一步择优的事实细节，不能为了凑题把常见特征说成必然，或把所有人为行为都说成有目的结果必成功。","index":14,"domId":"ki-point-0156"}],"cards":[{"id":"ki-j-048","title":"一级关系相同后再比较细节","core":"属性可以是定义性必然，也可以只是常见：正方形有四边不可缺，纸张是白色却可被彩纸反例否定。流程也要看是否同主体，例如作者撰写再自行修改，与作者写作后由编辑校订，动作都先后却执行者不同。因果还可比较自然作用与人为干预：暴雨使河涨属自然过程，按命令开闸使下游涨水含人为操作。这些是一级关系一致时用于进一步择优的事实细节，不能为了凑题把常见特征说成必然，或把所有人为行为都说成有目的结果必成功。","boundary":"自然、人为等二级特征只在候选关系同等且题干支持时用于择优；不要无限制造细分。","prompt":"四边对正方形是{{0}}属性，白色对纸是{{1}}属性；流程另比执行{{2}}是否相同；因果可比自然过程与{{3}}。","blanks":[{"answer":"必然","accept":[]},{"answer":"常见","accept":[]},{"answer":"主体","accept":[]},{"answer":"人为干预","accept":[]}]}],"questions":[{"id":"ki-jq-048","lesson":"analogy","stem":"哪项细分判断全部可靠？","options":["纸必白，正方形偶尔四边；所有流程必同主体；暴雨属于人为","只要都是先后动作，就无需比较实施者","只要结果一样，自然降雨和人工开闸在因果成因类型上完全相同","正方形四边为定义性属性、纸白色为常见属性；作者写后自改同主体、作者写后编辑校订不同主体；暴雨涨水自然、人工开闸涨水含人为干预"],"answer":3,"explanation":"定义性属性无例外，常见属性允许反例；先后并未说明实施者是否一致；涨水这个结果相同，也保留自然与人为原因类型的差异。","optionReviews":["把定义性与常见性颠倒，并错误识别主体和成因。","先后关系一致时主体仍可用于择优。","结果同一不消除原因类型的差别。","三个细分维度均有明确事实依据。"]}]},{"lessonId":"analogy","topicId":"analogy-analysis","courseRoute":"#course/reasoning/topic/analogy-analysis","sections":[{"title":"造成了什么与为了什么不同","text":"因果描述事实之间的产生关系，例如暴雨实际造成路面湿滑。手段目的描述行动指向的意图，例如铺设防滑垫是为了降低滑倒风险，即使后来仍有人滑倒，原目的也可能存在。用“造成”与“旨在”分别组织句子能帮助区分，但必须符合事实；不能把“修堤—防洪”自动改写成修堤已经完全消除洪水。相反，暴雨不具有让道路湿滑的行为意图。目的可能未实现，已发生的因果后果也不一定是行为者想要的。","index":15,"domId":"ki-point-0157"}],"cards":[{"id":"ki-j-049","title":"造成了什么与为了什么不同","core":"因果描述事实之间的产生关系，例如暴雨实际造成路面湿滑。手段目的描述行动指向的意图，例如铺设防滑垫是为了降低滑倒风险，即使后来仍有人滑倒，原目的也可能存在。用“造成”与“旨在”分别组织句子能帮助区分，但必须符合事实；不能把“修堤—防洪”自动改写成修堤已经完全消除洪水。相反，暴雨不具有让道路湿滑的行为意图。目的可能未实现，已发生的因果后果也不一定是行为者想要的。","boundary":"采取手段不保证实现目的；同一行动既可有目标也可有结果，依题干关系确定。","prompt":"“暴雨造成路滑”主要是{{0}}；“铺防滑垫旨在减摔”主要是{{1}}。目的未实现，{{2}}据此认定没有该目的。","blanks":[{"answer":"因果","accept":[]},{"answer":"手段目的","accept":[]},{"answer":"不能","accept":[]}]}],"questions":[{"id":"ki-jq-049","lesson":"analogy","stem":"已知一场暴雨实际使路面湿滑；管理者随后铺防滑垫，目的是减少滑倒，但仍有一人滑倒。哪项分析正确？","options":["“旨在”表明目的已经完全实现，所以没有人可能滑倒","暴雨为了路滑，属于手段目的；铺垫与减摔必是同义","暴雨—湿滑是因果；铺垫—减摔是手段目的，个别滑倒不抹除原目的","只要有人滑倒，就证明管理者并不想减少滑倒"],"answer":2,"explanation":"暴雨后的湿滑是已确认后果，铺垫则是出于风险控制意图的行动。结果失败或未完全达标不等于意图不存在。","optionReviews":["意图陈述不是成功事实。","给自然现象虚构意图，并误判词义关系。","实际后果与行为意图准确区分。","不能由目的未完全实现推出目的不存在。"]}]},{"lessonId":"analogy","topicId":"analogy-analysis","courseRoute":"#course/reasoning/topic/analogy-analysis","sections":[{"title":"主关系覆盖全部词项再择优","text":"先写出能同时解释全部词项的结构，再看选项是否同方向复现。例“黏土—陶杯—餐具”可写为原料→成品→成品的上位类，而不是只看到后两词有关。木材—木桌—家具与面粉—面包—食品都满足这一层；若题目还明确要求成品为可重复使用器具，则前者保留，后者因食品不是器具而排除。二级依据须来自明确题意或稳定事实，不能为了唯一答案临时发明偏好。部件→整体→类别是另一结构，不能在一级关系尚不相同时就被“都很常见”救回。","index":16,"domId":"ki-point-0158"}],"cards":[{"id":"ki-j-050","title":"主关系覆盖全部词项再择优","core":"先写出能同时解释全部词项的结构，再看选项是否同方向复现。例“黏土—陶杯—餐具”可写为原料→成品→成品的上位类，而不是只看到后两词有关。木材—木桌—家具与面粉—面包—食品都满足这一层；若题目还明确要求成品为可重复使用器具，则前者保留，后者因食品不是器具而排除。二级依据须来自明确题意或稳定事实，不能为了唯一答案临时发明偏好。部件→整体→类别是另一结构，不能在一级关系尚不相同时就被“都很常见”救回。","boundary":"一级关系本身有歧义时，应回看整个选项集合，不能锁死早期猜测。","prompt":"类比先建立覆盖{{0}}词项的一级关系并查{{1}}；多个匹配时，才比范围、主体或属性等{{2}}特征。二级标准不能{{3}}。","blanks":[{"answer":"全部","accept":[]},{"answer":"方向","accept":[]},{"answer":"二级","accept":[]},{"answer":"临时编造","accept":[]}]}],"questions":[{"id":"ki-jq-050","lesson":"analogy","stem":"题干“黏土—陶杯—餐具”。本题明确要求一级为“原料→成品→成品类别”，二级为“成品是可重复使用的器具”。哪组最合要求？","options":["家具—木桌—木材","木材—木桌—家具","面粉—面包—食品","车轮—汽车—交通工具"],"answer":1,"explanation":"木材制成木桌，木桌属于家具，且为可重复使用的器具，符合两级标准。面粉—面包—食品仅符合一级结构，食品不满足器具限定；车轮—汽车—交通工具首步是部件到整体；家具—木桌—木材则方向倒置。","optionReviews":["上位类、成品、材料的方向反了。","两级标准及方向均符合。","虽同一级结构，但不符合题目明示的器具限定。","车轮不是制造汽车的原料，而是组成部件。"]}]},{"lessonId":"analogy","topicId":"analogy-analysis","courseRoute":"#course/reasoning/topic/analogy-analysis","sections":[{"title":"近似词义之外还要看评价和场合","text":"词语即使描述相近行为，也可能评价相反。节俭与吝啬都涉及少花费，前者通常赞许合理节约，后者批评过度不舍；果断与武断都涉及决断，前者赞许及时明确，后者批评缺乏根据。若本题专比较“一褒一贬的相近行为”，这两对可匹配，但不能因此认定它们完全同义。还要查评价对象和语体，如“令尊”用于尊称对方父亲，不宜称自己父亲。评价色彩只是进一步区分的维度，不是忽略核心词义和使用对象的许可。 反义也可带评价差异，如慷慨与吝啬意义相反，通常前褒后贬；不能把一褒一贬本身当作近义或反义的充分判据。","index":17,"domId":"ki-point-0159"}],"cards":[{"id":"ki-j-051","title":"近似词义之外还要看评价和场合","core":"词语即使描述相近行为，也可能评价相反。节俭与吝啬都涉及少花费，前者通常赞许合理节约，后者批评过度不舍；果断与武断都涉及决断，前者赞许及时明确，后者批评缺乏根据。若本题专比较“一褒一贬的相近行为”，这两对可匹配，但不能因此认定它们完全同义。还要查评价对象和语体，如“令尊”用于尊称对方父亲，不宜称自己父亲。评价色彩只是进一步区分的维度，不是忽略核心词义和使用对象的许可。 反义也可带评价差异，如慷慨与吝啬意义相反，通常前褒后贬；不能把一褒一贬本身当作近义或反义的充分判据。","boundary":"褒贬是语境中的语言评价，不等同于事物让人喜欢或不喜欢。","prompt":"节俭偏{{0}}义，吝啬偏{{1}}义；近似行为还需核查评价对象、使用{{2}}和语体，不能仅靠情感标签代替词义。 慷慨与吝啬在核心词义上为{{3}}；对方父亲尊称{{4}}，自己父亲可谦称{{5}}。","blanks":[{"answer":"褒","accept":[]},{"answer":"贬","accept":[]},{"answer":"场合","accept":[]},{"answer":"反义","accept":[]},{"answer":"令尊","accept":[]},{"answer":"家父","accept":[]}]}],"questions":[{"id":"ki-jq-051","lesson":"analogy","stem":"本题只比较“描述相近行为，但前词褒义、后词贬义”的模式，以“节俭—吝啬”为参照。哪项匹配该模式，且对使用限制的说明正确？","options":["节约—节省；二词必为一褒一贬","破坏—毁坏；二词都贬也能当一褒一贬","询问—打听；只要含义相关，褒贬必相反","果断—武断；仍要分别核查决断方式与场合，不能说两词完全同义"],"answer":3,"explanation":"果断通常褒，武断通常贬，分别评价决断迅速合理与凭主观轻断，符合题定模式。其余没有明确的一褒一贬结构。词义对象不同，仍要受本题指定比较层次约束。","optionReviews":["节约、节省没有稳定的一褒一贬对立。","两词都贬不满足明示模式。","含义相关不推出评价相反。","情感模式吻合，同时保留词义及场合边界。"]},{"id":"ki-jq-extra-register","lesson":"analogy","stem":"一封正式往来信中，作者要称对方父亲，并提及自己的父亲。下列称呼与词义判断哪项都恰当？","options":["只要是正式信，所有褒义词都可以互换，不必看词义","称自己父亲“令尊”、对方父亲“家父”；慷慨与吝啬完全同义","称谁都用“令尊”即可，称呼对象与场合无关","称对方父亲“令尊”、自己父亲“家父”；慷慨与吝啬为反义且通常前褒后贬"],"answer":3,"explanation":"令尊敬称对方之父，家父为自己父亲的谦称，受对象与正式语境限制。慷慨与吝啬核心意义相反，还带常见褒贬差异；两个维度应同时核查。","optionReviews":["语体相同不表示词义可任意互换。","称谓对象倒置，并误判反义。","敬称有确定对象，不能不分自他。","对象、场合、语体及反义评价均正确。"]}]},{"lessonId":"analogy","topicId":"analogy-analysis","courseRoute":"#course/reasoning/topic/analogy-analysis","sections":[{"title":"句法要看组合后的实际角色","text":"若语义和逻辑关系不足以稳定区分，把词组装进最短自然句。雪花飘落是主语—谓语，修缮古桥是动词—宾语，青色琉璃是修饰语—中心词，江河与湖海是并列。不要仅凭两个词都是名词就说并列，也不要只凭顺序判断主谓；“古桥修缮”可能是标题式名物化表达，需统一自然用法。句法是补充核验，不能压过题干中更明确的种属或因果关系。","index":18,"domId":"ki-point-0160"}],"cards":[{"id":"ki-j-052","title":"句法要看组合后的实际角色","core":"若语义和逻辑关系不足以稳定区分，把词组装进最短自然句。雪花飘落是主语—谓语，修缮古桥是动词—宾语，青色琉璃是修饰语—中心词，江河与湖海是并列。不要仅凭两个词都是名词就说并列，也不要只凭顺序判断主谓；“古桥修缮”可能是标题式名物化表达，需统一自然用法。句法是补充核验，不能压过题干中更明确的种属或因果关系。","boundary":"句法通常不是必须最后才看的僵化顺序；明显结构可以快速识别，但仍须比较语义合理性。","prompt":"雪花—飘落为{{0}}，修缮—古桥为{{1}}，青色—琉璃为{{2}}，江河—湖海为{{3}}。句法通常用于语义逻辑后仍难区分时的补充。","blanks":[{"answer":"主谓","accept":[]},{"answer":"动宾","accept":[]},{"answer":"偏正","accept":[]},{"answer":"并列","accept":[]}]}],"questions":[{"id":"ki-jq-052","lesson":"analogy","stem":"把四对词按通常自然组合分析：①雪花—飘落；②修缮—古桥；③青色—琉璃；④江河—湖海。哪份分析正确？","options":["①主谓；②动宾；③偏正；④并列","①动宾；②主谓；③并列；④偏正","①主谓；②偏正；③动宾；④因果","①偏正；②动宾；③主谓；④并列"],"answer":0,"explanation":"雪花做飘落的主体，古桥承受修缮动作，青色修饰琉璃，江河与湖海并列指水域。按组合后的句法角色判定，而非看词性相似或字数。","optionReviews":["四种结构均匹配自然组合。","主客和修饰关系多处对调。","古桥是动作对象，青色不是对琉璃实施的动作。","飘落不是修饰成分，青色琉璃也不构成主谓陈述。"]}]},{"lessonId":"analogy","topicId":"analogy-analysis","courseRoute":"#course/reasoning/topic/analogy-analysis","sections":[{"title":"拆内部结构后要回到成语义","text":"外部关系不明显时，可试着看成语内部的词素。取长补短可分取长与补短，两组为动宾，长与短还构成反义；推陈出新也有推陈与出新两组动作结构，陈与新相反。东张西望却是东西成对、张望近义，排列为方位+动作+方位+动作，结构不同。拆过的成语或反复出现的同字能提示这种搜索，但不能按字面胡乱拆：例如胸有成竹是比喻事先有把握，不是某人胸腔真的藏竹。最终必须让拆分解释符合固定词义。","index":19,"domId":"ki-point-0161"}],"cards":[{"id":"ki-j-053","title":"拆内部结构后要回到成语义","core":"外部关系不明显时，可试着看成语内部的词素。取长补短可分取长与补短，两组为动宾，长与短还构成反义；推陈出新也有推陈与出新两组动作结构，陈与新相反。东张西望却是东西成对、张望近义，排列为方位+动作+方位+动作，结构不同。拆过的成语或反复出现的同字能提示这种搜索，但不能按字面胡乱拆：例如胸有成竹是比喻事先有把握，不是某人胸腔真的藏竹。最终必须让拆分解释符合固定词义。","boundary":"不能任意重排、断字或忽略成语约定含义来凑关系。","prompt":"“取长补短”内部分成两组{{0}}，长短反义；“推陈出新”中陈新也{{1}}。拆分结果须回到成语的{{2}}验证，重复字只作{{3}}。","blanks":[{"answer":"动宾","accept":[]},{"answer":"反义","accept":[]},{"answer":"固定词义","accept":[]},{"answer":"提示","accept":[]}]}],"questions":[{"id":"ki-jq-053","lesson":"analogy","stem":"本题按“两组动宾组合，宾语词素彼此反义，且拆分符合成语固定义”匹配“取长补短”。哪项最合适？","options":["和风细雨","推陈出新","莺歌燕舞","东张西望"],"answer":1,"explanation":"推陈、出新为两个动作组合，陈旧与新颖反义，整体含去旧创新义。东张西望为东西方位相反、张望动作相近的交错结构；和风细雨是两组偏正；莺歌燕舞为两组主谓。","optionReviews":["和风、细雨都是修饰加名词。","内部结构与固定词义均可匹配。","莺歌、燕舞分别是鸟作主语的主谓结构。","词素位置和关系不同，不是宾语陈列反义的两组动宾。"]}]},{"lessonId":"logic","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"先统一符号再按关系推导","text":"同一个陈述从头到尾只能用同一个符号，不要把“报名”中途换成“缴费”。设R=报名、T=到场、E=可入场、C=持卡。“报名且到场者可入场”是(R∧T)→E，“只有持卡才可入场”是E→C。已知R和T都真，可先得到E，再得到C，翻回自然语言就是此人持卡。最后仍要核对题目说的是可入场、已经入场还是必须入场，三个句子的含义不同。符号化保存而不是删掉否定、量词、时间和连接词。","index":9,"domId":"ki-point-0162"}],"cards":[{"id":"ki-j-054","title":"先统一符号再按关系推导","core":"同一个陈述从头到尾只能用同一个符号，不要把“报名”中途换成“缴费”。设R=报名、T=到场、E=可入场、C=持卡。“报名且到场者可入场”是(R∧T)→E，“只有持卡才可入场”是E→C。已知R和T都真，可先得到E，再得到C，翻回自然语言就是此人持卡。最后仍要核对题目说的是可入场、已经入场还是必须入场，三个句子的含义不同。符号化保存而不是删掉否定、量词、时间和连接词。","boundary":"符号化要保留论域、时间与量词，不能把不同事件误当同一个命题。","prompt":"先让符号含义保持{{0}}，再按句义写箭头、且、或、{{1}}；由(R∧T)→E、E→C及R∧T推出{{2}}，最后翻回原话。","blanks":[{"answer":"一致","accept":[]},{"answer":"否定","accept":[]},{"answer":"C","accept":[]}]}],"questions":[{"id":"ki-jq-054","lesson":"logic","stem":"R=报名，T=到场，E=可入场，C=持卡。已知“报名且到场者可入场”“只有持卡才可入场”，小周已报名且到场。哪份翻译与推导正确？","options":["(R∧T)→E，E→C，所以小周持卡","(R∧T)→C，C→E，所以持卡者都报名","(R∨T)→E，C→E，所以小周不持卡","R→T，C→E，所以小周已实际入场"],"answer":0,"explanation":"第一句合取作前件，第二句持卡是可入场的必要条件。小周满足前件后逐步推出E与C，不能把“可”改成“已实际”。","optionReviews":["同符号同含义，连接关系及翻回语言都准确。","删改原规则后还做了不合法逆推。","把且改或、必要箭头反向，并无否定依据。","报名与到场不是本题给出的条件关系，可入场也非已入场。"]}]},{"lessonId":"logic","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"充分在箭头左，必要在箭头右","text":"“只要考核通过就可准入”把通过T作为足够条件，写T→E；“只有交材料才可准入”说明准入E离不开材料M，写E→M。必要条件是门槛，不是自动触发器。“每个实习生都是职员”写I→W，但可能没有任何实习生，普遍包含并不带来存在断言。“想获补贴必须登记”写S→R，获补贴是需要登记的事。例登记为真仍可能因其他原因拿不到补贴；补贴为真则必须已登记。判断方向时可以把句子改成“有了左边就保证右边”，而非按词语在句中先后排列。","index":10,"domId":"ki-point-0163"}],"cards":[{"id":"ki-j-055","title":"充分在箭头左，必要在箭头右","core":"“只要考核通过就可准入”把通过T作为足够条件，写T→E；“只有交材料才可准入”说明准入E离不开材料M，写E→M。必要条件是门槛，不是自动触发器。“每个实习生都是职员”写I→W，但可能没有任何实习生，普遍包含并不带来存在断言。“想获补贴必须登记”写S→R，获补贴是需要登记的事。例登记为真仍可能因其他原因拿不到补贴；补贴为真则必须已登记。判断方向时可以把句子改成“有了左边就保证右边”，而非按词语在句中先后排列。","boundary":"除非句要看后半句是否有否定，不能只记某个固定词对应某个方向。","prompt":"“只要T就E”写{{0}}；“只有M才E”写{{1}}；“每个I都是W”写I→W但不保证{{2}}；“要S必须R”写{{3}}。","blanks":[{"answer":"T→E","accept":[]},{"answer":"E→M","accept":[]},{"answer":"I存在","accept":[]},{"answer":"S→R","accept":[]}]}],"questions":[{"id":"ki-jq-055","lesson":"logic","stem":"符号T=考核通过，E=准入，M=交材料，I=实习生，W=职员，S=获补贴，R=登记。四句依次是：只要T就E；只有M才E；每个I都是W；想S必须R。哪项翻译及存在判断全正确？","options":["E→T；E→M；I→W且不保证I存在；R→S","T→E；E→M；I→W且不保证I存在；S→R","E→T；M→E；W→I且必有I；R→S","T→E；M→E；I→W且必有I；S→R"],"answer":1,"explanation":"充分条件到结果是T→E；只有后的条件放在必要位置E→M。全称包含只限制I类成员，不承诺有成员。获补贴需要登记，所以S→R。","optionReviews":["第一和第四个箭头反了。","四种句式与存在边界均正确。","充分必要方向多处反转，并擅加存在。","必要箭头反向，全称也不自带存在。"]}]},{"lessonId":"logic","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"除非先补完整否则句","text":"“除非A，否则B”先读作“如果没有A，就B”，写¬A→B，逆否等价¬B→A，也可写A∨B。这不表示A一真就一定没有B，除非另给互斥条件。遇到否定后件必须保留：“除非获准，否则不得入内”令P=获准、E=入内，得到¬P→¬E，逆否为E→P。“入内的必要前提是登记”同样把目标指向门槛E→R。把句式补齐、固定命题含义后再消除双重否定，比记“除非一定前推后”可靠。","index":11,"domId":"ki-point-0164"}],"cards":[{"id":"ki-j-056","title":"除非先补完整否则句","core":"“除非A，否则B”先读作“如果没有A，就B”，写¬A→B，逆否等价¬B→A，也可写A∨B。这不表示A一真就一定没有B，除非另给互斥条件。遇到否定后件必须保留：“除非获准，否则不得入内”令P=获准、E=入内，得到¬P→¬E，逆否为E→P。“入内的必要前提是登记”同样把目标指向门槛E→R。把句式补齐、固定命题含义后再消除双重否定，比记“除非一定前推后”可靠。","boundary":"不能把“除非A否则B”误记成B→A；带不字的版本另算。","prompt":"“除非A否则B”写{{0}}，逆否为{{1}}。“除非P否则不得E”写¬P→¬E，等价{{2}}；“E的必要前提R”写{{3}}。","blanks":[{"answer":"¬A→B","accept":[]},{"answer":"¬B→A","accept":[]},{"answer":"E→P","accept":[]},{"answer":"E→R","accept":[]}]}],"questions":[{"id":"ki-jq-056","lesson":"logic","stem":"令U=完成更新，A=报警，P=获准，E=入内，R=登记。①除非完成更新，否则报警；②除非获准，否则不得入内；③入内的必要前提是登记。哪项正确？","options":["①U→¬A；②P→E；③R→E","①¬U→¬A；②¬P→E；③R→E","①A→¬U；②E→¬P；③E→R","①¬U→A且¬A→U；②¬P→¬E且E→P；③E→R"],"answer":3,"explanation":"①先补“如果不更新则报警”，再取逆否；②后件本来带否定，逆否后E→P；③必要前提在箭头右端。更新不必排除报警，获准也未必保证能入内。","optionReviews":["把充分必要和除非互斥化，均超出原句。","两句后件否定处理错误，③方向也反。","把①作了不合法的逆向因果，②还反转否定。","补句、保留否定、逆否及必要方向都准确。"]}]},{"lessonId":"logic","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"肯前否后有效，否前肯后不定","text":"条件句A→B只有A真B假时为假。已知它真，若A真就排除唯一假行而得到B真，这是肯前；若B假就只能A假，这是否后。若只知道A假，B可真可假；若只知道B真，A也可真可假。例“刷卡成功就开门”，没刷卡成功也可能由管理员开门，门开了也可能不是靠刷卡。不能把“暂不能确定”写成“反面已经成立”，额外规则如“开门仅能刷卡”才可能缩小合法模型。","index":12,"domId":"ki-point-0165"}],"cards":[{"id":"ki-j-057","title":"肯前否后有效，否前肯后不定","core":"条件句A→B只有A真B假时为假。已知它真，若A真就排除唯一假行而得到B真，这是肯前；若B假就只能A假，这是否后。若只知道A假，B可真可假；若只知道B真，A也可真可假。例“刷卡成功就开门”，没刷卡成功也可能由管理员开门，门开了也可能不是靠刷卡。不能把“暂不能确定”写成“反面已经成立”，额外规则如“开门仅能刷卡”才可能缩小合法模型。","boundary":"推不出不等于推出相反结论；额外条件可能使原本不能确定的问题可确定。","prompt":"A→B为真时，A真推出{{0}}；B假推出{{1}}；只知A假时B{{2}}；只知B真时A{{3}}。","blanks":[{"answer":"B真","accept":[]},{"answer":"A假","accept":[]},{"answer":"不定","accept":[]},{"answer":"不定","accept":[]}]}],"questions":[{"id":"ki-jq-057","lesson":"logic","stem":"仅已知A→B为真，没有其他条件。以下四种信息对应的结论哪项全正确？①再知A真；②再知B假；③再知A假；④再知B真。","options":["①B不定；②A不定；③B假；④A假","①B真；②A真；③B假；④A真","①B假；②A假；③B真；④A真","①B真；②A假；③B不定；④A不定"],"answer":3,"explanation":"合法赋值(A,B)为(0,0)、(0,1)、(1,1)。①只留(1,1)，②只留(0,0)；③有前两行，④有后两行，所以都不唯一。","optionReviews":["肯前和否后本来能确定，③④却不能。","②违背否后，③④分别犯否前与肯后误推。","①与原规则冲突，③④擅自指定。","恰与合法真值行筛选相符。"]}]},{"lessonId":"logic","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"且的整体为真才保证每项","text":"合取A∧B要求两个命题同时真，真值只有(1,1)一行。已知整体真，可以拆出A也真、B也真；但仅知A真不能确认B。例“报名且缴费”才完成确认，已报名而缴费未知，只能说确认尚不能确定；若明确未缴费，则整体一定假。要判断“和”是否真在连接命题：“甲和乙合搬一箱”描述联合动作，不宜粗暴拆成甲独搬和乙独搬两个真命题。","index":13,"domId":"ki-point-0166"}],"cards":[{"id":"ki-j-058","title":"且的整体为真才保证每项","core":"合取A∧B要求两个命题同时真，真值只有(1,1)一行。已知整体真，可以拆出A也真、B也真；但仅知A真不能确认B。例“报名且缴费”才完成确认，已报名而缴费未知，只能说确认尚不能确定；若明确未缴费，则整体一定假。要判断“和”是否真在连接命题：“甲和乙合搬一箱”描述联合动作，不宜粗暴拆成甲独搬和乙独搬两个真命题。","boundary":"日常“和”可能连接名词而不是两个命题，需看句子结构。","prompt":"且连接的两项必须{{0}}；整体A∧B真可分别推出{{1}}。只知A真而B未知，整体{{2}}；已知B假则整体假。","blanks":[{"answer":"同真","accept":[]},{"answer":"每一项","accept":[]},{"answer":"不定","accept":[]}]}],"questions":[{"id":"ki-jq-058","lesson":"logic","stem":"活动确认条件为“已报名且已缴费”。现知道小陈已报名，尚不知道是否缴费；小李已报名且未缴费。哪项判断及合取真值说明正确？","options":["只要报名真就确认；小陈、小李均确认","合取允许只一项真，所以缴费没有作用","小陈没有交代缴费，等于明确没缴费，两人都不确认","只有报名/缴费均真才确认；小陈不定，小李不确认；已确认者两项都真"],"answer":3,"explanation":"合取需要报名、缴费均真。已报名只确定报名这一项；未知不是假，所以小陈是否确认仍不定。小李的缴费项明确为假，整体为假。反过来，确认整体真足以拆出这两个条件。","optionReviews":["把且改成或，漏掉必要缴费条件。","合取不允许仅一项真。","把没有信息当成明确否定。","同真、整体拆项和单项不足都正确。"]}]},{"lessonId":"logic","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"相容或允许同时成立","text":"通常逻辑“或”按相容析取处理，A∨B只排除两项都假，允许(1,0)、(0,1)、(1,1)。因此知道甲或乙有钥匙，不能直接指定甲有，也不能因甲有就说乙没有。若题干另说“恰好一人”“二者不能同时”，才增加¬(A∧B)，排除(1,1)，变为不相容或。自然语言里“任选一项”的操作规则有时意指恰一，应用前应读限定，不能靠日常语感擅改真值。","index":14,"domId":"ki-point-0167"}],"cards":[{"id":"ki-j-059","title":"相容或允许同时成立","core":"通常逻辑“或”按相容析取处理，A∨B只排除两项都假，允许(1,0)、(0,1)、(1,1)。因此知道甲或乙有钥匙，不能直接指定甲有，也不能因甲有就说乙没有。若题干另说“恰好一人”“二者不能同时”，才增加¬(A∧B)，排除(1,1)，变为不相容或。自然语言里“任选一项”的操作规则有时意指恰一，应用前应读限定，不能靠日常语感擅改真值。","boundary":"恰好一项属于不相容析取，需要再加不能同时成立。","prompt":"相容A或B表示{{0}}一项真，允许{{1}}真；仅知或句不能指定哪项。恰好一项还需排除{{2}}。","blanks":[{"answer":"至少","accept":[]},{"answer":"两项都","accept":[]},{"answer":"同时成立","accept":[]}]}],"questions":[{"id":"ki-jq-059","lesson":"logic","stem":"命题“A或B”为真，且题目说明这里是相容或。哪项列出全部可行情形并正确区分“恰一项”？","options":["可行10、01、11；不能指定A；恰一项需再删去11","可行00、10、01；11不许出现","只有11；至少一项等于两项都真","可行10、01；知道A真便能否定B，无需其他条件"],"answer":0,"explanation":"相容析取的唯一假行是00。无附加条件时，10与01使任何单项都非必真，11又表明可以两项都真；恰好一个才删除11。","optionReviews":["真值集合、不能指定及排他附加条件都正确。","允许了两项全假却排除了合法全真。","把至少一个误当都。","直接把相容或偷换成不相容或。"]}]},{"lessonId":"logic","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"否定整个分支后才能锁定另一边","text":"析取A∨B已真，若完整分支A假，唯一剩下的是B真；B假也同理推出A真。肯定一边不会排除另一边，因为相容或允许都真。分支若本身有结构，要先查其整体真假。例如(P∨Q)∨R与¬P不能推出R，可能Q真而R假；若给¬(P∨Q)，才真正否定左分支并推出R。否定某个子句是否足够，要按左分支的且或结构判断，不能只看到一个“非”就划掉整块。","index":15,"domId":"ki-point-0168"}],"cards":[{"id":"ki-j-060","title":"否定整个分支后才能锁定另一边","core":"析取A∨B已真，若完整分支A假，唯一剩下的是B真；B假也同理推出A真。肯定一边不会排除另一边，因为相容或允许都真。分支若本身有结构，要先查其整体真假。例如(P∨Q)∨R与¬P不能推出R，可能Q真而R假；若给¬(P∨Q)，才真正否定左分支并推出R。否定某个子句是否足够，要按左分支的且或结构判断，不能只看到一个“非”就划掉整块。","boundary":"必须确认否定的是完整分支，不可只否定其局部。","prompt":"A∨B且¬A推出{{0}}，与¬B推出{{1}}；仅A真不能推出¬B。对(P∨Q)∨R，只给¬P仍不能锁定{{2}}，因为{{3}}还可能真。","blanks":[{"answer":"B","accept":[]},{"answer":"A","accept":[]},{"answer":"R","accept":[]},{"answer":"Q","accept":[]}]}],"questions":[{"id":"ki-jq-060","lesson":"logic","stem":"以下四个判断中，哪项组合全正确？①A∨B，¬A，所以B；②A∨B，¬B，所以A；③(P∨Q)∨R，¬P，所以R；④A∨B，A，所以¬B。均按相容或。","options":["①③有效，②④无效","①②有效，③④无效","四个都有效，因为否定和肯定都能删去一边","①②③均有效，仅④无效"],"answer":1,"explanation":"①②是有效否定分支推理。③反例P假Q真R假使前提真而结论假，说明局部否定不够。④反例A真B真合法，却使¬B假。","optionReviews":["②本来有效，③缺少对Q的否定。","两条有效推理及两个反例均区分正确。","相容或不能因肯定一项而排斥另一项。","把左分支内部的P当成整个左分支。"]}]},{"lessonId":"logic","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"否定往里推时更换且或","text":"否定“A且B”表示至少一项失败，等价¬A∨¬B，而不是两项全失败；否定“A或B”表示一项也不能真，等价¬A∧¬B。嵌套逐层处理：¬[A∧(B∨¬C)]先得¬A∨¬(B∨¬C)，再得¬A∨(¬B∧C)，这里¬¬C消成C。例“不同时满足实名且缴费”允许只缺一项，不能要求未实名且未缴费。每次推动否定只作用于它覆盖的括号，括号外其他条件不要跟着反。","index":16,"domId":"ki-point-0169"}],"cards":[{"id":"ki-j-061","title":"否定往里推时更换且或","core":"否定“A且B”表示至少一项失败，等价¬A∨¬B，而不是两项全失败；否定“A或B”表示一项也不能真，等价¬A∧¬B。嵌套逐层处理：¬[A∧(B∨¬C)]先得¬A∨¬(B∨¬C)，再得¬A∨(¬B∧C)，这里¬¬C消成C。例“不同时满足实名且缴费”允许只缺一项，不能要求未实名且未缴费。每次推动否定只作用于它覆盖的括号，括号外其他条件不要跟着反。","boundary":"否定“都满足”只需至少一项失败，不能误写成两项都失败。","prompt":"¬(A∧B)等价{{0}}；¬(A∨B)等价{{1}}；¬[A∧(B∨¬C)]化为{{2}}，双重否定¬¬C化成{{3}}。","blanks":[{"answer":"¬A∨¬B","accept":[]},{"answer":"¬A∧¬B","accept":[]},{"answer":"¬A∨(¬B∧C)","accept":[]},{"answer":"C","accept":[]}]}],"questions":[{"id":"ki-jq-061","lesson":"logic","stem":"按相容或，以下三式的等价结果依次是哪项？①¬(A∧B)；②¬(A∨B)；③¬[A∧(B∨¬C)]。","options":["①¬A∧¬B；②¬A∨¬B；③¬A∧(¬B∨C)","①¬A∨¬B；②¬A∧¬B；③¬A∨(¬B∧¬C)","①¬A∨¬B；②¬A∧¬B；③¬A∨(¬B∧C)","①A∨B；②A∧B；③A∨(B∧C)"],"answer":2,"explanation":"外层否定把且换或、把或换且，同时分别否定各分项。③再处理内层括号，B变¬B，¬C再否定变C。正确结果允许¬A单独为真或¬B与C同真。","optionReviews":["第一、二式连接词错误，嵌套也误换。","最后一步漏消¬¬C，写反了C。","两条德摩根及嵌套双重否定均正确。","没有对各分项取反。"]}]},{"lessonId":"arrangement","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"先排明显冲突，再完整试代","text":"确定条件可直接筛掉选项，例如C固定最后、A在B前；剩余少时把一个完整候选代回所有条件往往更省。真假混合也可用同样方式：四人排列且恰有一句为真，逐候选计算每句话真假数，再查是否等于1。不能因候选满足第一条就停止；满足一个固定条件但违反相对顺序或真话数量仍无效。排除与试代可交替使用，信息确定并不禁止代入，真假混合也不必一定穷举，选择推导成本较小的路线。","index":9,"domId":"ki-point-0170"}],"cards":[{"id":"ki-j-062","title":"先排明显冲突，再完整试代","core":"确定条件可直接筛掉选项，例如C固定最后、A在B前；剩余少时把一个完整候选代回所有条件往往更省。真假混合也可用同样方式：四人排列且恰有一句为真，逐候选计算每句话真假数，再查是否等于1。不能因候选满足第一条就停止；满足一个固定条件但违反相对顺序或真话数量仍无效。排除与试代可交替使用，信息确定并不禁止代入，真假混合也不必一定穷举，选择推导成本较小的路线。","boundary":"题干信息确定并不排斥代入，真假混合也非只能代入；根据成本选方法。","prompt":"明显违反确定条件可直接{{0}}；候选少或真假混合可{{1}}；每次都须检查{{2}}原条件。","blanks":[{"answer":"排除","accept":[]},{"answer":"整体代入","accept":[]},{"answer":"全部","accept":[]}]}],"questions":[{"id":"ki-jq-062","lesson":"arrangement","stem":"四人A、B、C、D各占一位，要求C最后且A在B前。另有两句话“D第一”“B第二”，恰好一句真。哪份排列合法？","options":["A、D、B、C","D、C、A、B","D、A、B、C","B、A、D、C"],"answer":2,"explanation":"排列D、A、B、C满足C最后和A在B前，且D第一真、B第二假，恰好一句真。B、A、D、C违反A在B前；D、C、A、B违反C最后；A、D、B、C使两句话都假。完整代入不能漏掉真假数量约束。","optionReviews":["两句话都假，不满足恰一真。","C在第二而非最后。","所有位置、先后和真假数量约束均满足。","A在B后，违反先后约束。"]}]},{"lessonId":"arrangement","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"可能找实例，必然查全部模型","text":"先固定合法模型集合，再读设问。“可能”只需构造一个合法实例；“不可能”须排除该候选的所有合法实现；“必然”要求每个合法模型都满足。例三人排序只限A在B前，合法ABC、ACB、CAB。C居中可能，由ACB见证；B第一不可能，因为它前面必须有A；C最后并非必然。补条件题把新条件联立再筛模型：若另加B在C前，只剩ABC。一次失败尝试不能证明不可能，一个成功实例也不能证明必然。","index":10,"domId":"ki-point-0171"}],"cards":[{"id":"ki-j-063","title":"可能找实例，必然查全部模型","core":"先固定合法模型集合，再读设问。“可能”只需构造一个合法实例；“不可能”须排除该候选的所有合法实现；“必然”要求每个合法模型都满足。例三人排序只限A在B前，合法ABC、ACB、CAB。C居中可能，由ACB见证；B第一不可能，因为它前面必须有A；C最后并非必然。补条件题把新条件联立再筛模型：若另加B在C前，只剩ABC。一次失败尝试不能证明不可能，一个成功实例也不能证明必然。","boundary":"试代法适合候选有限的场景；一个失败尝试不能证明整体不可能。","prompt":"可能只需{{0}}个合法模型；不可能须在{{1}}合法模型中都不发生；补条件先与旧条件{{2}}再检验目标。一次失败不能证明不可能。","blanks":[{"answer":"一","accept":[]},{"answer":"全部","accept":[]},{"answer":"联立","accept":[]}]}],"questions":[{"id":"ki-jq-063","lesson":"arrangement","stem":"A、B、C排成一列，仅要求A在B前。以下“可能情形、不可能情形、补充B在C前后的结果”哪项全正确？","options":["C最后必然；B第一不可能；新增条件不影响模型","C居中不可能；B第一可能；新增条件后ACB","找不到一次C居中的尝试即可证不可能；新增条件可忽略旧条件","C居中可能；B第一不可能；新增条件后唯一ABC"],"answer":3,"explanation":"合法模型是ABC、ACB、CAB，所以ACB展示C居中可能，三者B均非第一。新增B<C与A<B联成A<B<C，仅ABC。不是每个模型C都最后。","optionReviews":["ACB和CAB里C不最后，新增条件会筛模型。","ACB即反例，且B不能第一。","失败一次不能穷尽可能，新旧约束须同时满足。","实例、全模型排除及补条件联立都准确。"]}]},{"lessonId":"arrangement","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"固定点与连锁约束一起启动","text":"先将确定位置落表，再找能把它传给更多对象的连接。例四位中A在第2、C紧接A右侧，可直接把C填第3；剩余1、4给B、D，而D在B前就迫使D第1、B第4。A的位置只是一条短信息，却通过“紧接”产生强传播；一段很长但不限制位置的背景不如它有用。把每次推导都写回同一位置表并查冲突，避免在不同草稿里让一个人占两个位置或把尚未确定的格子当作已定。","index":11,"domId":"ki-point-0172"}],"cards":[{"id":"ki-j-064","title":"固定点与连锁约束一起启动","core":"先将确定位置落表，再找能把它传给更多对象的连接。例四位中A在第2、C紧接A右侧，可直接把C填第3；剩余1、4给B、D，而D在B前就迫使D第1、B第4。A的位置只是一条短信息，却通过“紧接”产生强传播；一段很长但不限制位置的背景不如它有用。把每次推导都写回同一位置表并查冲突，避免在不同草稿里让一个人占两个位置或把尚未确定的格子当作已定。","boundary":"信息多不必然最有用，关键是能否限制模型并与其他条件连接。","prompt":"已定A第2优先落表，“C紧接A右”推出C第{{0}}，剩余1、4且D在B前得D第{{1}}、B第{{2}}。所有结果回填{{3}}结构表。","blanks":[{"answer":"3","accept":[]},{"answer":"1","accept":[]},{"answer":"4","accept":[]},{"answer":"同一","accept":[]}]}],"questions":[{"id":"ki-jq-064","lesson":"arrangement","stem":"A、B、C、D排在1至4号位，每人一位。A在2号，C紧接A右边，D在B左边。正确排列及推导路线是？","options":["D、A、C、B；从A固定位置推出C，再分配D、B并回填同表","A、D、C、B；信息字数最多的条件必须最先用","B、A、C、D；只需检查A和C，不必查D在B前","D、C、A、B；先猜D第一，再忽略A的位置"],"answer":0,"explanation":"A2使C3，剩余位置只有1与4。D<B故D1、B4，所有条件验证后唯一DACB。切入口看能传播约束而不是字数。","optionReviews":["固定点、强连接和统一回填都应用正确。","A不在2，且字数不是推理效率标准。","D4在B1右侧，违反第三条件。","A在3而非2，C也不是紧接其右。"]}]},{"lessonId":"arrangement","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"分支要互斥穷尽并保留全部结果","text":"分支选择要覆盖所有可能又不重复，不能凭喜好挑一个。若题设第一位是A或C，且每人仅出现一次，可分A第一、C第一两支。四人中再给C紧接在B前且B在D前：A第一支只剩ACBD；C第一支剩CBAD、CBDA。任何分支内有条件冲突都剔除，但不能因为已有一个成功方案就不查另一支。三个合法方案共有的才是必然结论；“A第一”只是一个分支的特征，不应升为全局事实。","index":12,"domId":"ki-point-0173"}],"cards":[{"id":"ki-j-065","title":"分支要互斥穷尽并保留全部结果","core":"分支选择要覆盖所有可能又不重复，不能凭喜好挑一个。若题设第一位是A或C，且每人仅出现一次，可分A第一、C第一两支。四人中再给C紧接在B前且B在D前：A第一支只剩ACBD；C第一支剩CBAD、CBDA。任何分支内有条件冲突都剔除，但不能因为已有一个成功方案就不查另一支。三个合法方案共有的才是必然结论；“A第一”只是一个分支的特征，不应升为全局事实。","boundary":"不能只保留自己偏好的假设；未列尽的分支会制造伪唯一答案。","prompt":"分支必须{{0}}且{{1}}；支内传递条件，遇{{2}}剔除；所有存活支共有才是{{3}}结论。例中ACBD、CBAD、CBDA共{{4}}种。","blanks":[{"answer":"互斥","accept":[]},{"answer":"穷尽","accept":[]},{"answer":"矛盾","accept":[]},{"answer":"必然","accept":[]},{"answer":"3","accept":[]}]}],"questions":[{"id":"ki-jq-065","lesson":"arrangement","stem":"四人A、B、C、D各排一位。第一位是A或C；C紧接B之前；B在D之前。按第一位分支，以下结果哪项正确？","options":["C第一仅CBAD，A第一无解，共1种","A第一、C第一、D第一都必须列为合法分支，共至少4种","A第一仅ACBD，C第一有CBAD与CBDA，共3种；B不在第4是共有结论，A第一不是必然","只保留ACBD，因为先找到合法方案就可结束，故A必第一"],"answer":2,"explanation":"A第一后，CB块只能在2、3，D4；C第一使B2，A、D可在3、4交换且D仍在B后。两分支穷尽题设可行首位，共三种，不能只挑一支。 三个方案中的B均不在第4，属于共有结论，而A在第1只属于一支。","optionReviews":["漏了CBDA，也误删ACBD。","D第一违反首位只能A或C的原条件。","分支完备、方案数与共同/特有结论区分正确。","一个合法模型只证明可能，不证明必然。"]}]},{"lessonId":"arrangement","topicId":"formal-logic","courseRoute":"#course/reasoning/topic/formal-logic","sections":[{"title":"位置箭头与属性表保持一致","text":"排序可写位置1、2、3，先后写pos甲<pos乙，紧邻则另写pos乙=pos甲+1，二者不可混用。多属性一一匹配用交叉表：已确定打勾，明确排除打叉，空格保留未知。例甲乙丙三人各占一位、各管红蓝绿项目，丙在2且管蓝，乙管红，甲在乙左侧。剩余位置1与3迫使甲1乙3，剩余项目绿归甲。甲虽在乙左侧，却隔着丙；若误当紧挨，会把本来合法的唯一模型误判无解。","index":13,"domId":"ki-point-0174"}],"cards":[{"id":"ki-j-066","title":"位置箭头与属性表保持一致","core":"排序可写位置1、2、3，先后写pos甲<pos乙，紧邻则另写pos乙=pos甲+1，二者不可混用。多属性一一匹配用交叉表：已确定打勾，明确排除打叉，空格保留未知。例甲乙丙三人各占一位、各管红蓝绿项目，丙在2且管蓝，乙管红，甲在乙左侧。剩余位置1与3迫使甲1乙3，剩余项目绿归甲。甲虽在乙左侧，却隔着丙；若误当紧挨，会把本来合法的唯一模型误判无解。","boundary":"表格只负责保存条件，不能把未填格自动当否定；顺序约束不等于相邻约束。","prompt":"“甲在乙左”写pos甲{{0}}pos乙；“紧挨左”才要求相差{{1}}。交叉表空格表示{{2}}。例丙2管蓝、乙管红时，甲1乙3且甲管{{3}}。","blanks":[{"answer":"<","accept":[]},{"answer":"1","accept":[]},{"answer":"未知","accept":[]},{"answer":"绿","accept":[]}]}],"questions":[{"id":"ki-jq-066","lesson":"arrangement","stem":"甲、乙、丙各占1、2、3号位，并各负责红、蓝、绿之一，均一一对应。丙在2号负责蓝，乙负责红，甲在乙左侧（未要求紧邻）。哪项正确？","options":["1甲绿、2丙蓝、3乙红；甲乙不相邻仍符合左侧","1甲红、2丙蓝、3乙绿；空白项目格可以直接当否定","条件无解，因为甲乙必须相邻","1乙红、2丙蓝、3甲绿；左侧可以随意理解"],"answer":0,"explanation":"丙固定2号，甲<乙使甲1乙3。项目按已知蓝给丙、红给乙，唯一剩绿给甲。甲与乙位置差2，但原条件只要求小于，不要求紧邻。","optionReviews":["位置约束、属性匹配及不等于紧邻都正确。","与乙红的明确条件冲突，空格也不是否定。","擅自添加了紧邻限制。","甲3不在乙1左侧。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"把事实、判断与连接分开","text":"结论是作者希望读者接受的判断，证据是题干用来支持它的事实；论证连接解释为什么该事实能支持那个判断，常含隐含前提。例：某馆延长开放后，晚间入馆人数增加，负责人据此断言居民全年阅读量提高。人数增加是证据，全年阅读量提高是结论，缺失连接包括新增入馆是否意味着新增阅读、是否仅把白天阅读移至晚上。加强信息让这条推断更可信，削弱信息降低它的支持程度；削弱不等于证明结论必定错误。","index":19,"domId":"ki-point-0175"}],"cards":[{"id":"ki-ja-001","title":"把事实、判断与连接分开","core":"将题干压缩为因为证据、所以结论，再检查连接。","boundary":"角色取决于推理用途，不取决于句子是否听起来客观。","prompt":"测试分数提高所以工作差错减少：分数提高是{{0}}，差错减少是{{1}}，测试能力迁移到实际工作是待查的{{2}}；加强削弱评价{{3}}。","blanks":[{"answer":"证据","accept":[]},{"answer":"结论","accept":[]},{"answer":"论证连接","accept":[]},{"answer":"支持关系","accept":[]}]}],"questions":[{"id":"ki-jaq-001","lesson":"argument","stem":"学生速读训练后限时阅读测试分数提高，学校据此认为理解复杂论文的能力提高。哪项分析正确？","options":["两句都是陈述句，所以不存在论证","测试得分是证据，论文理解提高是结论；测验是否测得该能力是关键连接，决定支持关系","测试得分提高是结论，论文理解提高是证据","一名学生不喜欢训练即可证明结论错误"],"answer":1,"explanation":"准确识别证据、结论、隐含连接及其支持关系。","optionReviews":["陈述句也可分别承担论据和结论角色。","准确识别证据、结论、隐含连接及其支持关系。","颠倒了证据与结论的推理角色。","个人喜好不能直接反驳能力变化。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"跟着设问锁定目标主张","text":"先读设问，确认评价最终主张、某人观点还是局部推理。再寻找被其他句子支持且回答设问的判断。因此、可见只是线索，也可能引出中间结论。例：故障次数减少，因此停机时间缩短；可见应全面换设备。若问采购建议，目标是全面更换，停机缩短是中间结论。开头可能先给结论，结尾可能只是举例；位置只能辅助搜索，推理角色才是依据。","index":20,"domId":"ki-point-0176"}],"cards":[{"id":"ki-ja-002","title":"跟着设问锁定目标主张","core":"先确认设问对象，再区分中间和最终结论。","boundary":"同一句话在上一层可为结论，在下一层可为证据。","prompt":"定位主张先看{{0}}；因此后可能只是{{1}}；首尾位置辅助搜索，最终依据是{{2}}。","blanks":[{"answer":"设问","accept":[]},{"answer":"中间结论","accept":[]},{"answer":"推理角色","accept":[]}]}],"questions":[{"id":"ki-jaq-002","lesson":"argument","stem":"报告写道：故障减少，因此试验线停机缩短；由此可见，应立即全面换设备。末尾附有每月故障记录。题目要求削弱更换建议，应锁定哪项？","options":["故障减少，因为它在开头","末尾故障记录，因为最后一句必是结论","停机缩短，因为因此后必为最终结论","全面更换建议；停机缩短是中间结论"],"answer":3,"explanation":"设问指向采购建议；停机缩短承担中间结论角色。","optionReviews":["开头是依据，不是设问目标。","位置不能替代推理角色分析。","标志词不能独自判定最终结论。","设问指向采购建议；停机缩短承担中间结论角色。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"按任务、范围、缺口、影响作答","text":"先区分任务：加强提高支持度，削弱降低支持度，解释消解表面冲突，必要假设寻找不可缺少的条件。再压缩结论和证据，保留对象、时间、量词与比较组。例：甲楼今年换窗后能耗比去年低，据此认为换窗降低能耗。缺口是今年与去年是否还发生其他能耗变化。随后逐项比较改变了测量、可比性、因果解释还是结论本身，以及影响多大。不能凭出现研究或他因的标签判强弱。","index":21,"domId":"ki-point-0177"}],"cards":[{"id":"ki-ja-003","title":"按任务、范围、缺口、影响作答","core":"任务明确后，压缩范围，预判缺口，比较影响。","boundary":"解释不一定加强特定因果主张，加强项也未必是必要假设。","prompt":"先确定{{0}}；压缩时保留{{1}}和比较对象；预判推理{{2}}；再比较改变的{{3}}及程度。","blanks":[{"answer":"任务类型","accept":[]},{"answer":"范围","accept":[]},{"answer":"缺口","accept":[]},{"answer":"环节","accept":[]}]}],"questions":[{"id":"ki-jaq-003","lesson":"argument","stem":"甲楼今年换窗后取暖能耗比去年低，报告认为换窗降低了能耗。问最能削弱，哪组过程正确？","options":["只比较选项是否带有研究二字","确定削弱任务，保留甲楼跨年比较，查其他能耗变化；今年停业少供暖三个月比窗户颜色变化更能削弱","改作解释题，比较乙楼是否喜欢窗户","改作必要假设题，删除年份限制"],"answer":1,"explanation":"保留任务和范围，识别时长这一缺口，并比较其实际影响。","optionReviews":["证据标签不能替代内容分析。","保留任务和范围，识别时长这一缺口，并比较其实际影响。","更改任务和比较对象。","必要假设与削弱不同，年份是关键范围。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"反例必须进入结论范围","text":"检查对象、时间、量词与条件。例：今年所有完成培训的新员工都通过考试，是受限全称命题；今年完成培训的新员工中有一人未通过，即足以反驳。去年未培训的老员工不属于范围。若结论只是培训者平均成绩较高或通过概率较高，允许部分人表现差，一个例外不能推翻总体平均或概率。甲组平均80分仍可有人50分，应使用对应群体数据。","index":22,"domId":"ki-point-0178"}],"cards":[{"id":"ki-ja-004","title":"反例必须进入结论范围","core":"合法反例可击破全称，个体例外不自动否定统计判断。","boundary":"反例须满足原命题全部适用条件。","prompt":"先对齐对象、时间、量词与{{0}}；一个合法反例击破{{1}}，不能自动推翻{{2}}或概率结论。","blanks":[{"answer":"条件","accept":[]},{"answer":"全称","accept":[]},{"answer":"平均","accept":[]}]}],"questions":[{"id":"ki-jaq-004","lesson":"argument","stem":"甲称本月完成实训的所有新员工都合格；乙称这些员工平均分高于未完成组。已知本月一名完成实训的新员工不合格，但其组平均分仍较高。判断正确的是？","options":["该例在范围内，反驳甲，但不推翻乙","必须所有人不合格才能反驳甲","任何年份的任何员工不合格都能反驳甲","一人不合格同时推翻甲乙"],"answer":0,"explanation":"该个体为全称甲的合法反例，却与乙的平均结论兼容。","optionReviews":["该个体为全称甲的合法反例，却与乙的平均结论兼容。","全称否定只须至少一个反例。","忽略时间、人群和实训条件。","混淆个体例外与平均判断。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"没有展开论据时直接检验主张","text":"题干可能只有断言，没有完整证据链，不应虚构作者依据。先把主张改写为可检验条件，再找相反事实、合法反例或使结果失败的机制。例：当前版本X在同电池同设置下让每款兼容设备更省电。可靠重复测试中一款适用设备更耗电，就是全称反例；如果发现X持续调用传感器，还能解释失败机制。旧版本、不兼容设备或不同电池均可能偏离范围；平均主张则需要对应总体证据。","index":23,"domId":"ki-point-0179"}],"cards":[{"id":"ki-ja-005","title":"没有展开论据时直接检验主张","core":"没有论据时直接检验断言，不猜作者理由。","boundary":"对象、版本时间和程度限制仍必须保留。","prompt":"缺少显式论据，直接检验{{0}}；寻找反例、相反事实或失败{{1}}，仍核对对象、时间与{{2}}。","blanks":[{"answer":"主张本身","accept":[]},{"answer":"机制","accept":[]},{"answer":"程度","accept":[]}]}],"questions":[{"id":"ki-jaq-005","lesson":"argument","stem":"某人只断言：当前X模式同电池同设置下让每款兼容设备续航更久。哪项直接反驳？","options":["用户希望改进图标","猜测他喜欢蓝色界面","旧版不兼容设备续航缩短","一款兼容设备在当前版同条件重复测试中续航缩短，记录显示额外传感器耗电"],"answer":3,"explanation":"范围内反例与耗电机制直接检验并反驳全称断言。","optionReviews":["图标意见不涉及续航。","虚构动机且无关续航。","版本与兼容范围不匹配。","范围内反例与耗电机制直接检验并反驳全称断言。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"检查指标到结论的转换","text":"证据与结论可能换对象、指标或概念。下载次数不等于活跃用户数，活跃用户数也不等于盈利。逐段写出转换所需关系。例：安装量翻倍推出持续用户数翻倍，若增长来自同批用户多设备重复安装，持续用户未增，就揭示代理指标失真。仅说没有必然关系只是指出缺口，可靠失真事实更具体。跨年龄、地区、场景还要检查适用范围。","index":24,"domId":"ki-point-0180"}],"cards":[{"id":"ki-ja-006","title":"检查指标到结论的转换","core":"识别证据指标与目标指标之间的转换。","boundary":"不等同不代表完全无关，应评价具体支持程度。","prompt":"由安装量推出持续用户数，要查两种{{0}}的转换；重复安装导致指标{{1}}，降低支持。","blanks":[{"answer":"指标","accept":[]},{"answer":"失真","accept":[]}]}],"questions":[{"id":"ki-jaq-006","lesson":"argument","stem":"平台由课程播放次数翻倍推出完课人数翻倍。哪项直接揭示转换问题？","options":["平台换了标志","讲师参加论坛","日志表明增长全为同批学员重复播放片头，完课人数未增长","有人喜欢白天学习"],"answer":2,"explanation":"播放次数与完课人数不同，重复片头具体揭示代理指标失真。","optionReviews":["标志变化无关学习指标。","论坛活动无关转换。","播放次数与完课人数不同，重复片头具体揭示代理指标失真。","时间喜好不说明完成情况。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"先查证据是否站得住","text":"检查来源、抽样、记录、测量及事实可靠性。例：机构在手机挂号平台调查，发现老人都熟练使用线上挂号，便推论全市老人。即使回答准确，样本仅含活跃用户，仍遗漏不会使用者，代表性不足。把访问次数记录为人数则是记录测量错误。关键论据被否定或样本不代表目标总体，支撑力下降，但不能据此断言全市老人都不会使用线上挂号。","index":25,"domId":"ki-point-0181"}],"cards":[{"id":"ki-ja-007","title":"先查证据是否站得住","core":"真实性不保证代表性，二者分别检查。","boundary":"证据失效不自动证明相反结论。","prompt":"核查来源、抽样、记录、{{0}}及事实可靠性；只调查活跃用户推论全市，缺乏{{1}}。","blanks":[{"answer":"测量","accept":[]},{"answer":"代表性","accept":[]}]}],"questions":[{"id":"ki-jaq-007","lesson":"argument","stem":"某市以线上预约平台弹窗调查受访老人，发现九成表示会线上预约，据此推断全市老人中九成都熟悉该操作。独立核查确认回答记录准确，但问卷只向本月成功预约三次以上者展示。应如何评价？","options":["有数字就无需核查来源和抽样","由抽样偏差可断言全市老人都不会预约","记录准确就保证总体推断","记录虽真，但样本仅覆盖高频成功预约者，不能据此认定能代表全市老人，降低了总体结论的支撑"],"answer":3,"explanation":"记录准确解决的是回答是否被如实记录，不能解决谁被调查。抽样仅覆盖高频成功预约者，存在选择偏差，未证明能代表全市老人；题设并未说明被遗漏的不熟练者数量，也不能据此证明相反全称。","optionReviews":["数字外观不保证数据可靠。","证据失效不等于相反全称成立。","记录准确不能弥补抽样范围偏差。","分别检验了记录真实性与抽样代表性，并限定了削弱效果。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"相关背后的方向与共同变化","text":"A与B相关不能确定A导致B。倒因是B反过来促使A出现，如压力低使人更愿参加跑步社团；他因是C同时影响两者或独立造成B，如工作稳定同时促进参团并减压。还需检查原因是否先于结果、自愿参加者是否原本不同、上线措施时是否同步调整人员或流程。例：自愿训练者成绩提高，可能来自较强学习动力或同期额外辅导。替代解释需要具体证据，不能只想到一种可能就断言原措施无效。","index":26,"domId":"ki-point-0182"}],"cards":[{"id":"ki-ja-008","title":"相关背后的方向与共同变化","core":"检查反向作用、第三因素、时序、选择和同期措施。","boundary":"替代解释削弱识别能力，不必证明措施毫无效果。","prompt":"结果促进原因叫{{0}}；第三因素叫{{1}}；自愿参加者基线不同查{{2}}；效果早于措施查{{3}}；同期减负查{{4}}。","blanks":[{"answer":"倒因","accept":[]},{"answer":"他因","accept":[]},{"answer":"选择偏差","accept":[]},{"answer":"时间先后","accept":[]},{"answer":"共同变化","accept":[]}]}],"questions":[{"id":"ki-jaq-008","lesson":"argument","stem":"以参跑步社团者压力低推断入社减压。哪组核查正确？","options":["倒因就是任何第三因素","压力低使人愿入社是倒因；工作稳定同时促进两者是他因；自愿者基线不同是选择偏差；还查减压是否早于入社及同期减少加班","自愿参加消除偏差，任何替代解释都证明跑步无效","只要入社后压力低就不必看基线与同期变化"],"answer":1,"explanation":"分别正确识别倒因、他因、选择、时序与共同变化。","optionReviews":["反向因果与共同原因不同。","分别正确识别倒因、他因、选择、时序与共同变化。","自愿参加可能引入偏差，替代解释不证明零效果。","前后观察仍可能受基线和共同变化影响。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"比较证据作用而非题型名称","text":"加强削弱没有固定类型强弱排序。先看是否命中关键推理，再比可靠性、覆盖范围和对全部观察的解释力。未经核实的反例传闻未必强于可靠的适用机制。区分降低支持、提供反证和足以推翻：遗漏变量降低因果支持；可靠相反观察提供反证；受限全称的范围内确证反例足以推翻。例：每台设备都因改造降耗，可被一台合规设备可靠增耗推翻；所有设备同期缩短运行则削弱改造归因，但单凭这个变化不能证明改造没有贡献。","index":27,"domId":"ki-point-0183"}],"cards":[{"id":"ki-ja-009","title":"比较证据作用而非题型名称","core":"相关性是入口，可靠性、范围和解释力决定分量。","boundary":"不存在反例永远强于机制等固定排序。","prompt":"先看关键环节{{0}}，再看可靠性、覆盖及能否解释{{1}}；降低支持、提供反证和足以{{2}}不可混同。","blanks":[{"answer":"相关程度","accept":[]},{"answer":"全部观察","accept":[]},{"answer":"推翻","accept":[]}]}],"questions":[{"id":"ki-jaq-009","lesson":"argument","stem":"结论为“本次试验每一台合规设备改造后等长统计期的总能耗都低于各自改造前，且这一下降由改造造成”。甲：听说别市旧型号偶有增耗。乙：独立复测确认，本次一台合规设备改造后等长统计期的总能耗高于改造前。丙：所有设备改造后统计期内实际运行时长均缩短，原报告未控制该变化。以下评价正确的是？","options":["乙可靠且在全称范围内，足以推翻；丙覆盖全部设备，削弱改造归因但不单独证明原结论为假；甲范围及可靠性较弱","甲是反例类所以必然最强","只要丙能解释观察就可忽略乙","乙丙都证明所有设备增耗"],"answer":0,"explanation":"乙的同设备等长统计期测量与全称下降事实直接冲突，足以反驳该复合结论。丙覆盖全部设备，提供总量下降的其他解释而削弱归因，但仅靠丙不能断言下降事实为假或改造绝无效果。甲来自别市旧型号且未核实，不能凭反例类型优先。","optionReviews":["乙直接反驳每台都降耗；丙提供全范围其他解释而不排除改造共同贡献；甲关联弱。","固定类型排序忽略范围与可靠性。","替代解释不能抹去可靠反例。","个别反证和混杂因素不证明所有对象相反。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"搭桥接对对象与方向","text":"搭桥补充证据与结论的缺失关系。例：缩短排队推出提高满意度，需要说明目标患者减少等待如何改善评价，不能用满意者更愿等待倒置方向。桥梁须适用相同人群、时段、条件。补足不可缺少的前提可修复断点，但必要条件成立未必充分，其他缺口可能仍在；很强的充分条件也未必不可缺少。能够加强、足以推出和必须依赖应分开。","index":28,"domId":"ki-point-0184"}],"cards":[{"id":"ki-ja-010","title":"搭桥接对对象与方向","core":"桥梁对齐对象方向与范围，必要与充分分开。","boundary":"修复一处断点不代表整条论证无其他缺口。","prompt":"搭桥保持对象和推理{{0}}；不可缺少是{{1}}条件，但未必充分；还查适用{{2}}。","blanks":[{"answer":"方向","accept":[]},{"answer":"必要","accept":[]},{"answer":"范围","accept":[]}]}],"questions":[{"id":"ki-jaq-010","lesson":"argument","stem":"本院上午新流程缩短排队，因此这些患者满意度提高。哪项恰当搭桥并说明逻辑地位？","options":["本院上午患者重视等待，缩短等待改善就诊评价；这提供支持，但不能认定其他影响均已排除","异地夜间停车满意证明本院所有患者满意","只要补一条必要条件就充分证明结论","满意者更愿排队，所以缩短排队必让所有人满意"],"answer":0,"explanation":"对象和方向匹配，补足等待与评价的连接，同时不把局部修复当充分证明。","optionReviews":["对象和方向匹配，补足等待与评价的连接，同时不把局部修复当充分证明。","场景对象指标均不匹配。","必要条件不自动充分。","倒置方向并扩大范围。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"机制与实例各自提供什么","text":"机制说明结果怎样产生，如遮阳膜减少辐射进入降低制冷负荷；实例提供实际支持，如同气候办公楼控制时长后出现降耗。机制若只是猜测或不适用就弱，实例若仅个别成功也可能受选择或他因影响。两者无固定强弱排序，比较可靠性、代表性及目标一致性。平均节能主张下，可靠多点对照可能强于未经核验的机制猜想，但异常单楼实例也可能弱于已验证且适用的机制。","index":29,"domId":"ki-point-0185"}],"cards":[{"id":"ki-ja-011","title":"机制与实例各自提供什么","core":"机制解释路径，实例展示实际效果。","boundary":"机制与实例都不能凭类型自动排第一。","prompt":"{{0}}解释怎样发生，{{1}}展示实际支持；强弱取决于可靠性、{{2}}和是否命中结论。","blanks":[{"answer":"机制解释","accept":[]},{"answer":"实例","accept":[]},{"answer":"代表性","accept":[]}]}],"questions":[{"id":"ki-jaq-011","lesson":"argument","stem":"论点是遮阳膜降低本市同类办公楼夏季平均制冷能耗。甲仅猜测薄膜能阻热；乙是覆盖本市不同朝向同类楼的可靠对照研究，平均能耗下降。判断正确的是？","options":["实例永远强于机制","都是加强所以无需比较","机制永远强于实例","甲解释路径，乙给实际效果；本题乙更可靠且覆盖目标范围，因此更有力，不代表固定类型排序"],"answer":3,"explanation":"正确区分路径与实证，并据可靠性代表性目标一致性比较。","optionReviews":["本题结果不能推广为所有题目的排序。","同方向证据也有强弱。","未核验机制不能凭名称占优。","正确区分路径与实证，并据可靠性代表性目标一致性比较。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"支持证据配合主张力度","text":"可以补充可核验机制、事实、研究或代表性实例，但对象方向范围需一致。本市公交准点率主张不能由外地地铁票价降低直接支持。少量成功可支持可能性，却不足以证明全称；代表性群体数据适合平均改善；预测除历史结果还要核查未来关键条件。例：代表性公交线路同季节对照可支持平均准点率改善，不能断言未来每一班永远准点。","index":30,"domId":"ki-point-0186"}],"cards":[{"id":"ki-ja-012","title":"支持证据配合主张力度","core":"可核验、目标一致、证据力度匹配量词。","boundary":"平均不是人人，历史成功不是未来必然。","prompt":"补充证据应可{{0}}，与对象方向和{{1}}一致；少数成功不证明{{2}}；预测还查未来{{3}}。","blanks":[{"answer":"核验","accept":[]},{"answer":"范围","accept":[]},{"answer":"全称","accept":[]},{"answer":"条件","accept":[]}]}],"questions":[{"id":"ki-jaq-012","lesson":"argument","stem":"本市代表性公交线路实施新调度后平均准点率提高。哪项判断正确？","options":["一班准点证明全市公交永远准点","外地地铁降价直接证明本市公交准点","可核验机制和同类对照支持平均改善；不能断言每班准点，预测明年还要检查关键条件","今年改善就不必考虑明年道路客流人员"],"answer":2,"explanation":"正确匹配可核验证据与目标，并区分全称平均预测要求。","optionReviews":["单例不能证明无限时间全称。","对象地区指标不匹配。","正确匹配可核验证据与目标，并区分全称平均预测要求。","预测需检查未来适用条件。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"必要假设不是最强加强","text":"必须假设或论证依赖的前提问不可缺少连接，不是最强补充。先统一证据结论对象方向，再否定候选。例：正式签到须读取本人身份证，当前没带就推断截止前不能签到，缺口在于能否及时拿到。必须堵住及时取得的可能，不需永久不能取得。否定后若原证据失去关键支持，候选值得保留；结论仍可能因其他理由为真不代表该推理不依赖前提。充分条件使结论成立，必要条件不可缺少。若设问明确问使结论成立，应按充分条件而非必要假设处理。","index":31,"domId":"ki-point-0187"}],"cards":[{"id":"ki-ja-013","title":"必要假设不是最强加强","core":"规范对象与方向后，否定候选检查关键支持。","boundary":"不要把很强的充分条件误选为必要条件。","prompt":"必须依赖的前提找{{0}}连接；先统一对象和{{1}}再做{{2}}检验。","blanks":[{"answer":"不可缺少","accept":[]},{"answer":"方向","accept":[]},{"answer":"否定","accept":[]}]}],"questions":[{"id":"ki-jaq-013","lesson":"argument","stem":"某考场规定正式签到必须读取考生本人身份证。小林目前未携带身份证，工作人员仅凭这一理由便断定他在本场签到截止前无法完成正式签到。要使这一论证从当前状态到截止前结果的时间连接成立，必须补充哪项？","options":["所有考生喜欢身份证签到","小林永远无法取得身份证","截止前小林无法取得可读取的本人身份证","只要带身份证，其他签到条件必然满足"],"answer":2,"explanation":"若能及时取得，当前未携带不足以支持无法签到，故这是必要的时间连接。","optionReviews":["喜好不是正式签到必需条件。","永久无法取得过强，并非论证必需。","若能及时取得，当前未携带不足以支持无法签到，故这是必要的时间连接。","持证是必要条件，不代表足以满足全部要求。"]}]},{"lessonId":"argument","topicId":"argument-analysis","courseRoute":"#course/reasoning/topic/argument-analysis","sections":[{"title":"准确否定后再检查支持","text":"先准确否定候选，再观察原证据关键支持是否失效，不要把否定写得过强。所有A都是B的否定是至少一个A不是B；至少一个A是B的否定是没有A是B。至少3个否定为少于3个，至多3个否定为多于3个。如果P则Q的否定是P且非Q，不是如果P则非Q。P且Q否定为非P或非Q；相容或P或Q否定为非P且非Q。例：凭盖章推出档案真实，规则所有盖章档案都真实的否定只需一份盖章伪档案，就破坏凭章保证真实的规则，却不证明目标档案必假。否定使关键支持失效，候选可能必要，仍要检查范围与其他独立依据。","index":32,"domId":"ki-point-0188"}],"cards":[{"id":"ki-ja-014","title":"准确否定后再检查支持","core":"数量条件及复合句按逻辑否定，再检验支持。","boundary":"支持失效不要求结论现实中必定为假。","prompt":"所有A是B否定为{{0}}；至少一个A是B否定为{{1}}；至少3个否定为{{2}}；至多3个否定为{{3}}；如果P则Q否定为{{4}}；P且Q否定为{{5}}；相容或P或Q否定为{{6}}；准确否定使关键支持失效，候选可能是{{7}}。","blanks":[{"answer":"至少一个A不是B","accept":[]},{"answer":"没有A是B","accept":[]},{"answer":"少于3个","accept":[]},{"answer":"多于3个","accept":[]},{"answer":"P且非Q","accept":[]},{"answer":"非P或非Q","accept":[]},{"answer":"非P且非Q","accept":[]},{"answer":"必要前提","accept":[]}]}],"questions":[{"id":"ki-jaq-014","lesson":"argument","stem":"候选为至少3名委员满足若到场则提交书面意见。哪项给出准确否定及检验方法？","options":["否定为少于3名满足若到场则不提交；必须证明结论必假","否定为至少3名委员到场且未提交；只要不利便可选","否定为少于3名满足该条件句；违反条件句需到场且未提交；再查原论证关键支持是否失效","否定为所有委员未到场；结论仍可能为真就不是必要前提"],"answer":2,"explanation":"正确否定数量；条件句失败须前件真后件假，最后检查支持而非要求结论必假。","optionReviews":["条件句否定错误，且混淆支持失效与结论必假。","满足人数少于3不能直接换成不满足人数至少3，未给总数。","正确否定数量；条件句失败须前件真后件假，最后检查支持而非要求结论必假。","未到场不违反条件句，检验也不要求现实结论必假。"]},{"id":"ki-jaq-015","lesson":"argument","stem":"前提为审计完成且至少一份凭证经过复核。哪项准确否定并说明检验？","options":["审计未完成且没有凭证复核，必须同时失败","审计未完成或没有凭证复核；若切断关键支持则候选可能必要，但不要求结论必假","审计完成且没有凭证复核，只有这一种否定情况","审计未完成或所有凭证复核"],"answer":1,"explanation":"合取与存在量词均准确否定，检验针对论证支持。","optionReviews":["合取否定是至少一项失败，不须两项同时失败。","合取与存在量词均准确否定，检验针对论证支持。","遗漏审计未完成而有复核凭证的情况。","至少一份的否定是没有，不是全部都有。"]},{"id":"ki-jaq-016","lesson":"argument","stem":"候选前提为至多3台设备报警，或者所有阀门关闭；这里或者为相容或。哪项准确否定并说明检验？","options":["至少3台报警且所有阀门打开；只看结论真假","多于3台报警或至少一个阀门未关；或句否定仍用或","多于3台报警且至少一个阀门未关；再检查原论据的关键支持是否失效","少于3台报警且没有阀门关闭；否定后必须证明结论必假"],"answer":2,"explanation":"准确应用至多阈值、全称与相容或的否定，并检查论证依赖。","optionReviews":["至多3的否定须多于3；全称否定无需所有相反。","相容或否定应为两项同时失败。","准确应用至多阈值、全称与相容或的否定，并检查论证依赖。","数量方向和全称否定均错，且检验不要求结论必假。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"先弄清这一次要回答什么","text":"主旨要把握整体判断，意图要在文本支持下辨明表达目的，细节要核对一个具体事实，标题兼顾内容与概括，衔接还需检验前后关系。例如一段同时写社区书屋延时开放和志愿者培训，问开放时段时，只能回答时段，不能拿全段的服务改进替代。 适用边界：先看问题是定位任务的办法，不是允许跳过全文；同一材料的细节题与主旨题可以有不同答案。","index":12,"domId":"ki-point-0189"},{"title":"带着范围读完再逐项核对","text":"读完后标出对象、时间、数量及转折等结构，给每个候选找对应证据。某站只有周六延时服务，不能将其概括成每天延时；原文先讲延时、后强调人员轮值，主旨还应整合后文。 适用边界：先看问题是定位任务的办法，不是允许跳过全文；同一材料的细节题与主旨题可以有不同答案。","index":13,"domId":"ki-point-0190"}],"cards":[{"id":"ki-v-001","title":"先弄清这一次要回答什么","core":"主旨要把握整体判断，意图要在文本支持下辨明表达目的，细节要核对一个具体事实，标题兼顾内容与概括，衔接还需检验前后关系。例如一段同时写社区书屋延时开放和志愿者培训，问开放时段时，只能回答时段，不能拿全段的服务改进替代。","boundary":"先看问题是定位任务的办法，不是允许跳过全文；同一材料的细节题与主旨题可以有不同答案。","prompt":"一段介绍书屋的时段与培训，问题只问“何时闭馆”，应查找{{0}}信息。","blanks":[{"answer":"闭馆时间","accept":[]}]},{"id":"ki-v-002","title":"带着范围读完再逐项核对","core":"读完后标出对象、时间、数量及转折等结构，给每个候选找对应证据。某站只有周六延时服务，不能将其概括成每天延时；原文先讲延时、后强调人员轮值，主旨还应整合后文。","boundary":"先看问题是定位任务的办法，不是允许跳过全文；同一材料的细节题与主旨题可以有不同答案。","prompt":"原文说“仅周六延时”，选项说“每天延时”，它扩大了{{0}}。","blanks":[{"answer":"时间范围","accept":[]}]}],"questions":[{"id":"ki-vq-001","lesson":"mainidea","stem":"社区书屋自本月起只在周六延长开放至21时，其他日子仍于18时闭馆。为维持这项安排，书屋建立了志愿者轮值表。根据文段，哪项符合事实？","options":["文段主要讨论志愿者的收入","本月周六书屋开放至21时","本月每天书屋都延长至21时","轮值表用于缩短周六开放时间"],"answer":1,"explanation":"“只在周六”与21时直接对应，回答事实判断任务。","optionReviews":["收入没有出现，且本题并非要求主旨。","“只在周六”与21时直接对应，回答事实判断任务。","把周六扩为每天，越过明确限定。","原文轮值为维持延时，不是缩短。"]},{"id":"ki-vq-002","lesson":"mainidea","stem":"城市展馆发现，新增展品并未显著提升回访率；访谈显示，缺少讲解使观众难以理解展品联系。因此，展馆决定定期组织主题导览。若问题是“文段着重说明什么”，最佳答案是：","options":["展馆新增了若干展品","所有展馆都应取消自由参观","观众的平均回访间隔已缩短","展馆根据理解障碍调整服务方式"],"answer":3,"explanation":"概括现象、原因和决定，符合主旨任务。","optionReviews":["只摘取开头背景，不能覆盖后文。","扩大对象并增添取消参观的措施。","文本只说原先未明显提升，未报告调整后的间隔。","概括现象、原因和决定，符合主旨任务。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"让步与修正要放回句群","text":"“虽然、尽管”常先让步承认一面，“但是、然而、不过、却”常引出限制或修正。“尽管设备更轻，续航仍不足”先承认优点，再补出限制。后半句常是当前句群的新判断；若后面还有总括，就不能停在一个“但”字上选答案。 适用边界：转折提示值得检查的结构变化，但若它位于例证或引语内部，仍须服从整段论证。","index":14,"domId":"ki-point-0191"},{"title":"纠正预期不一定有但是","text":"“其实、事实上、实际上”都可能纠正已有看法，但要确认是作者立场还是被引用的话。“人们以为排队慢是窗口少。实际上，重复填表才是主要耗时环节”通过预期与事实的落差纠偏。要比较前后所指，不是把“实际上”后的任何零碎信息都当全文核心。 适用边界：转折提示值得检查的结构变化，但若它位于例证或引语内部，仍须服从整段论证。","index":15,"domId":"ki-point-0192"},{"title":"主判断靠结构检验","text":"先问后文是否持续解释这一修正，再看结尾是否重新统摄。若“不过”只出现在访客的一句抱怨中，作者最后讨论无障碍改造，主旨应对应作者总结，不应截取抱怨。 适用边界：转折提示值得检查的结构变化，但若它位于例证或引语内部，仍须服从整段论证。","index":16,"domId":"ki-point-0193"}],"cards":[{"id":"ki-v-003","title":"让步与修正要放回句群","core":"“虽然、尽管”常先让步承认一面，“但是、然而、不过、却”常引出限制或修正。“尽管设备更轻，续航仍不足”先承认优点，再补出限制。后半句常是当前句群的新判断；若后面还有总括，就不能停在一个“但”字上选答案。","boundary":"转折提示值得检查的结构变化，但若它位于例证或引语内部，仍须服从整段论证。","prompt":"“虽然设备更轻，但续航不足”中，让步承认的优点是{{0}}。","blanks":[{"answer":"设备更轻","accept":[]}]},{"id":"ki-v-004","title":"纠正预期不一定有但是","core":"“其实、事实上、实际上”都可能纠正已有看法，但要确认是作者立场还是被引用的话。“人们以为排队慢是窗口少。实际上，重复填表才是主要耗时环节”通过预期与事实的落差纠偏。要比较前后所指，不是把“实际上”后的任何零碎信息都当全文核心。","boundary":"转折提示值得检查的结构变化，但若它位于例证或引语内部，仍须服从整段论证。","prompt":"“以为是窗口少，实际上主要耗时在重复填表”纠正的是对{{0}}的判断。","blanks":[{"answer":"排队慢原因","accept":[]}]},{"id":"ki-v-005","title":"主判断靠结构检验","core":"先问后文是否持续解释这一修正，再看结尾是否重新统摄。若“不过”只出现在访客的一句抱怨中，作者最后讨论无障碍改造，主旨应对应作者总结，不应截取抱怨。","boundary":"转折提示值得检查的结构变化，但若它位于例证或引语内部，仍须服从整段论证。","prompt":"引语里说“不过椅子太少”，全文结尾主张完善无障碍通行，概括中心应优先对应{{0}}。","blanks":[{"answer":"完善无障碍通行","accept":[]}]}],"questions":[{"id":"ki-vq-003","lesson":"mainidea","stem":"不少人把夜间公交客流少归因于需求不足。实际上，调查发现车辆实际到站时间经常偏离公布的时刻表，使许多潜在乘客改乘其他交通工具。改善夜间公交，首先需要提高时刻表的可靠性。这段话主要说明：","options":["调查只能统计已乘车者","夜间公交应以可靠班次回应潜在需求","夜间公交没有出行需求","所有线路都应彻夜不间断运行"],"answer":1,"explanation":"“实际上”纠正需求不足，结尾提出对应的可靠性主张，覆盖整段。","optionReviews":["材料未说调查方法存在此限制。","“实际上”纠正需求不足，结尾提出对应的可靠性主张，覆盖整段。","把被纠正的看法当作者结论。","彻夜运行属于新增强措施。"]},{"id":"ki-vq-004","lesson":"mainidea","stem":"博物馆导览既要解释单件藏品，也要揭示藏品之间的联系。一位观众说：“新导览画面很美，不过字太小。”这只是形式反馈；更关键的是，导览能否帮助观众建立历史脉络。文段重点是：","options":["观众只关心画面和字体","导览应帮助观众理解藏品的历史联系","单件藏品不需要讲解","导览应全面放大字体"],"answer":1,"explanation":"开头与结尾共同指向关联理解，引语中的转折只是例子。","optionReviews":["把一位观众反馈扩展为所有观众的唯一关注。","开头与结尾共同指向关联理解，引语中的转折只是例子。","“既要……也要……”明确保留单件讲解。","局部反馈未被作者提升为全段核心。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"区分理由与所支持的判断","text":"“旧渠淤积、暴雨时排水不畅，因此应先疏通旧渠”中，前两项是提出行动的理由，疏通是被支持的判断。概括时保留结论及它面对的问题，不要只复述证据。 适用边界：连接词只提示可能的推理；“换句话说”常是复述，“于是”还可能只记述事件先后。","index":17,"domId":"ki-point-0194"},{"title":"结论词还需要覆盖范围","text":"“因此、因而、由此可见”都可能把理由推向结论，但每一处的覆盖范围仍需核查。“由此可见”可连接前面的多条事实与一个综合判断，也可能只连接某个小例子。判断它是否为全文中心，要看它是否能覆盖前后的主要内容。 适用边界：连接词只提示可能的推理；“换句话说”常是复述，“于是”还可能只记述事件先后。","index":18,"domId":"ki-point-0195"},{"title":"把事件承接与推论分开","text":"“工作人员开门，于是游客入场”描述事件进程；“记录持续缺失，看来故障并非偶发”才是从证据推断。看词语承担何种语义任务，比机械识别词表更可靠。 适用边界：连接词只提示可能的推理；“换句话说”常是复述，“于是”还可能只记述事件先后。","index":19,"domId":"ki-point-0196"}],"cards":[{"id":"ki-v-006","title":"区分理由与所支持的判断","core":"“旧渠淤积、暴雨时排水不畅，因此应先疏通旧渠”中，前两项是提出行动的理由，疏通是被支持的判断。概括时保留结论及它面对的问题，不要只复述证据。","boundary":"连接词只提示可能的推理；“换句话说”常是复述，“于是”还可能只记述事件先后。","prompt":"旧渠淤积使排水不畅，因此应先疏通；被支持的行动是{{0}}。","blanks":[{"answer":"疏通旧渠","accept":[]}]},{"id":"ki-v-007","title":"结论词还需要覆盖范围","core":"“因此、因而、由此可见”都可能把理由推向结论，但每一处的覆盖范围仍需核查。“由此可见”可连接前面的多条事实与一个综合判断，也可能只连接某个小例子。判断它是否为全文中心，要看它是否能覆盖前后的主要内容。","boundary":"连接词只提示可能的推理；“换句话说”常是复述，“于是”还可能只记述事件先后。","prompt":"“某次试验成功，由此可见这次方案可行”并不直接证明{{0}}方案都可行。","blanks":[{"answer":"所有","accept":[]}]},{"id":"ki-v-008","title":"把事件承接与推论分开","core":"“工作人员开门，于是游客入场”描述事件进程；“记录持续缺失，看来故障并非偶发”才是从证据推断。看词语承担何种语义任务，比机械识别词表更可靠。","boundary":"连接词只提示可能的推理；“换句话说”常是复述，“于是”还可能只记述事件先后。","prompt":"“管理员开门，于是游客入场”中的“于是”主要连接{{0}}进程。","blanks":[{"answer":"事件","accept":[]}]}],"questions":[{"id":"ki-vq-005","lesson":"mainidea","stem":"山区道路遇雨时常被落石阻断，且清理一次需要较长时间。因此，在雨季前完善落石监测，比事后反复抢通更有助于保障通行。文段意在说明：","options":["事后抢通对山区道路毫无意义","落石清理时间已经大幅缩短","全部山区道路应在雨季关闭","山区道路应提前完善雨季落石监测"],"answer":3,"explanation":"前两句提供风险和成本理由，结论是提前监测，未扩大为全面关闭。","optionReviews":["文本比较两者作用，没有否认抢通价值。","与“需要较长时间”不符。","没有任何全面关闭的依据。","前两句提供风险和成本理由，结论是提前监测，未扩大为全面关闭。"]},{"id":"ki-vq-006","lesson":"mainidea","stem":"甲段：“试点中三次提醒都未送达，看来当前通知链条仍有缺口。”乙段：“管理员按下开门键，于是参观者依次入馆。换句话说，入馆已经开始。”对两段关系的理解正确的是：","options":["两个“于是、看来”都必然引出全文主旨","甲作出证据支持的推断，乙主要记录并复述进程","甲只是复述三次提醒，乙证明所有通知都有效","“换句话说”表明开门是入馆的唯一原因"],"answer":1,"explanation":"甲由重复未达判断链条缺口；乙的于是连接动作，换句话说复述入馆状态。","optionReviews":["词语本身不能决定全文层级。","甲由重复未达判断链条缺口；乙的于是连接动作，换句话说复述入馆状态。","甲有推断，乙也未谈通知有效性。","复述不是唯一因果证明。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"判断后文是在证明还是转向","text":"开头提出“河岸应保留连续步道”，后面列步行调查和断点案例，属于证据；若随后另谈夜间照明的安全目标，就要检查是否出现并列议题。句子位置不能替代任务分析。 适用边界：中心不总在最后一句，也不一定能在原文中逐字圈出；必须比较各句是否同层以及是否出现新主张。","index":20,"domId":"ki-point-0197"},{"title":"中心在前时不要被数字带走","text":"“纸质记录仍有备份价值。某次系统故障后，值班本帮助找回交接信息”中，故障案例证明第一句。概括要提备份价值，不能只讲那一次故障。 适用边界：中心不总在最后一句，也不一定能在原文中逐字圈出；必须比较各句是否同层以及是否出现新主张。","index":21,"domId":"ki-point-0198"},{"title":"后续主张出现要重新合并","text":"材料先说保存资料，再补充“但仅保存还不够，更要建立检索入口”，讨论已推进到可用性。答案若只写保存，就遗漏修正；若数句并列讨论不同环节，需要用共同上位判断概括。 适用边界：中心不总在最后一句，也不一定能在原文中逐字圈出；必须比较各句是否同层以及是否出现新主张。","index":22,"domId":"ki-point-0199"}],"cards":[{"id":"ki-v-009","title":"判断后文是在证明还是转向","core":"开头提出“河岸应保留连续步道”，后面列步行调查和断点案例，属于证据；若随后另谈夜间照明的安全目标，就要检查是否出现并列议题。句子位置不能替代任务分析。","boundary":"中心不总在最后一句，也不一定能在原文中逐字圈出；必须比较各句是否同层以及是否出现新主张。","prompt":"“应保留连续步道”之后列出断点案例，案例在这里用于{{0}}前述判断。","blanks":[{"answer":"支持","accept":[]}]},{"id":"ki-v-010","title":"中心在前时不要被数字带走","core":"“纸质记录仍有备份价值。某次系统故障后，值班本帮助找回交接信息”中，故障案例证明第一句。概括要提备份价值，不能只讲那一次故障。","boundary":"中心不总在最后一句，也不一定能在原文中逐字圈出；必须比较各句是否同层以及是否出现新主张。","prompt":"值班本在系统故障后找回交接信息，是“纸质记录有备份价值”的{{0}}。","blanks":[{"answer":"例证","accept":[]}]},{"id":"ki-v-011","title":"后续主张出现要重新合并","core":"材料先说保存资料，再补充“但仅保存还不够，更要建立检索入口”，讨论已推进到可用性。答案若只写保存，就遗漏修正；若数句并列讨论不同环节，需要用共同上位判断概括。","boundary":"中心不总在最后一句，也不一定能在原文中逐字圈出；必须比较各句是否同层以及是否出现新主张。","prompt":"“保存还不够，更要建立检索入口”使重点从单纯保存推进到资料的{{0}}。","blanks":[{"answer":"可用性","accept":[]}]}],"questions":[{"id":"ki-vq-007","lesson":"mainidea","stem":"老城街巷改造应保留步行网络的连续性。调查发现，三处临时围挡使居民绕行；另有两段新铺路面因未接通巷口而使用率很低。文段主要说明：","options":["新铺路面普遍不如旧路好用","老城共有五处不能通行的路段","居民绕行只由临时围挡造成","街巷改造应重视步行连接的连续性"],"answer":3,"explanation":"两个调查事实均支撑首句，首句承担中心。","optionReviews":["从两段路面扩为普遍并新增新旧比较。","混加围挡和路段且把使用率低改为不能通行。","文段没有穷尽居民绕行的所有原因，不能推出只由临时围挡造成。","两个调查事实均支撑首句，首句承担中心。"]},{"id":"ki-vq-008","lesson":"mainidea","stem":"地方档案馆近年来加快了资料扫描，许多纸质档案已有数字副本。但扫描只是起点；没有统一检索入口，研究者仍难找到所需资料。因此，后续建设应把可检索性纳入重点。最佳概括是：","options":["只要统一入口就能解决所有研究困难","档案数字化应从完成扫描推进到方便检索","研究者已经不需要纸质档案","档案馆最应继续增加扫描数量"],"answer":1,"explanation":"整合已有扫描、转折限制和结尾行动，体现结构推进。","optionReviews":["将一个重要环节夸成全部问题的充分条件。","整合已有扫描、转折限制和结尾行动，体现结构推进。","原文未作纸质需求判断。","只概括背景，忽略后半重点。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"把必要与充分分清","text":"“只有核对版本，才能合并记录”表示合并前不能缺少版本核对；并未承诺只核对版本即可安全合并，权限、字段等也可能需要检查。 适用边界：必要条件表示缺它不行，不表示有它就够；还要看它是否属于全文关键而非局部背景。","index":23,"domId":"ki-point-0200"},{"title":"围绕目标定位关键环节","text":"全文若解释为什么跨部门数据难以共用，最后强调“只有统一口径，才能可靠比较”，统一口径便是针对目标的着力点。但一句仅介绍某实验入组条件时，不能自动将其提升为全文主张。 适用边界：必要条件表示缺它不行，不表示有它就够；还要看它是否属于全文关键而非局部背景。","index":24,"domId":"ki-point-0201"},{"title":"对象目标条件都要留下","text":"原文只讲同一区域年度数据的比较，答案不能扩成一切数据整合。把“年度比较需统一统计口径”改成“统一口径即可消除所有数据错误”，还把必要性变成充分性。 适用边界：必要条件表示缺它不行，不表示有它就够；还要看它是否属于全文关键而非局部背景。","index":25,"domId":"ki-point-0202"}],"cards":[{"id":"ki-v-012","title":"把必要与充分分清","core":"“只有核对版本，才能合并记录”表示合并前不能缺少版本核对；并未承诺只核对版本即可安全合并，权限、字段等也可能需要检查。","boundary":"必要条件表示缺它不行，不表示有它就够；还要看它是否属于全文关键而非局部背景。","prompt":"只有核对版本才能合并记录，说明核对版本是合并的{{0}}条件。","blanks":[{"answer":"必要","accept":[]}]},{"id":"ki-v-013","title":"围绕目标定位关键环节","core":"全文若解释为什么跨部门数据难以共用，最后强调“只有统一口径，才能可靠比较”，统一口径便是针对目标的着力点。但一句仅介绍某实验入组条件时，不能自动将其提升为全文主张。","boundary":"必要条件表示缺它不行，不表示有它就够；还要看它是否属于全文关键而非局部背景。","prompt":"全文围绕让跨部门数据可比展开，统一口径是实现该目标的关键{{0}}。","blanks":[{"answer":"条件","accept":[]}]},{"id":"ki-v-014","title":"对象目标条件都要留下","core":"原文只讲同一区域年度数据的比较，答案不能扩成一切数据整合。把“年度比较需统一统计口径”改成“统一口径即可消除所有数据错误”，还把必要性变成充分性。","boundary":"必要条件表示缺它不行，不表示有它就够；还要看它是否属于全文关键而非局部背景。","prompt":"“本市年度比较需统一口径”不能扩大为统一口径便能消除{{0}}。","blanks":[{"answer":"所有数据错误","accept":[]}]}],"questions":[{"id":"ki-vq-009","lesson":"mainidea","stem":"三个部门对“新增企业”采用不同的登记时间点，直接比较会造成误差。只有统一这些部门的统计口径，才能对本市年度新增企业数量作可靠比较。文段重点是：","options":["三个部门都不能再公布企业数量","所有地区必须采用同一个登记时间点","本市相关部门作年度新增企业数量比较前须统一口径","只要统一口径，全部统计错误都会消失"],"answer":2,"explanation":"保留本市、部门、年度比较目标及必要条件。","optionReviews":["文段主张可比条件，非停止公布。","原文没有跨地区统一的范围。","保留本市、部门、年度比较目标及必要条件。","把必要条件变成万能充分条件。"]},{"id":"ki-vq-010","lesson":"mainidea","stem":"某测试说明：“只有完成校准，仪器读数才能用于本次比对；校准后还需排除温度干扰。”据此正确的是：","options":["这台仪器永远无法用于比对","完成校准后读数必然可直接比对","只要温度不变，就无需校准","校准是本次比对的必要准备，但不是足够保证"],"answer":3,"explanation":"前句规定缺校准不行，后句又加温度检查，因此不是校准即足够。","optionReviews":["把有条件可用歪曲为永不可能。","漏掉温度干扰条件。","否认明示的校准要求。","前句规定缺校准不行，后句又加温度检查，因此不是校准即足够。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"建议词背后应有具体行动","text":"“应、需、必须”若用于要求主体采取动作，可提示建议；也可能用于推测或条件说明。“应设置清晰站牌”是行动主张，“明日应当降温”只是可能性判断。识别建议须看谁被要求做什么，而不只是看到“应”字。 适用边界：“基础、责任、保障”既可能提出行动要求，也可能只描述现状；必须确认作者是否在主张改变。","index":26,"domId":"ki-point-0203"},{"title":"措施与目标组成路径","text":"“借助共享清单减少重复采购”同时交代用什么办法、解决什么问题。概括路径时不能只留“共享”而删去清单对象，也不能把减少写成完全杜绝。 适用边界：“基础、责任、保障”既可能提出行动要求，也可能只描述现状；必须确认作者是否在主张改变。","index":27,"domId":"ki-point-0204"},{"title":"关键或保障可能突出条件","text":"“稳定维护是设备长期使用的保障”若接着要求设立维护预算，可转为保障维护的主张；若只是记录旧制度特点，则没有新建议。条件性名词须结合全段功能读。 适用边界：“基础、责任、保障”既可能提出行动要求，也可能只描述现状；必须确认作者是否在主张改变。","index":28,"domId":"ki-point-0205"},{"title":"把抽象责任翻译成动作","text":"“接收单位负有登记义务”可转为接收单位应登记；“核验是必要路径”可转为办理前需核验；“人员培训是实施基础”可转为实施前应先完成材料明确要求的培训；“持续维护是重要保障”可转为需要安排维护。责任、必要路径、基础和保障可承载建议，但只转出文本支持的动作，不能自行增添处罚、收费或新系统。 适用边界：“基础、责任、保障”既可能提出行动要求，也可能只描述现状；必须确认作者是否在主张改变。","index":29,"domId":"ki-point-0206"}],"cards":[{"id":"ki-v-015","title":"建议词背后应有具体行动","core":"“应、需、必须”若用于要求主体采取动作，可提示建议；也可能用于推测或条件说明。“应设置清晰站牌”是行动主张，“明日应当降温”只是可能性判断。识别建议须看谁被要求做什么，而不只是看到“应”字。","boundary":"“基础、责任、保障”既可能提出行动要求，也可能只描述现状；必须确认作者是否在主张改变。","prompt":"“车站应补充夜间照明”要求执行的动作是{{0}}。","blanks":[{"answer":"补充夜间照明","accept":[]}]},{"id":"ki-v-016","title":"措施与目标组成路径","core":"“借助共享清单减少重复采购”同时交代用什么办法、解决什么问题。概括路径时不能只留“共享”而删去清单对象，也不能把减少写成完全杜绝。","boundary":"“基础、责任、保障”既可能提出行动要求，也可能只描述现状；必须确认作者是否在主张改变。","prompt":"“借助共享清单减少重复采购”的手段是建立{{0}}。","blanks":[{"answer":"共享清单","accept":[]}]},{"id":"ki-v-017","title":"关键或保障可能突出条件","core":"“稳定维护是设备长期使用的保障”若接着要求设立维护预算，可转为保障维护的主张；若只是记录旧制度特点，则没有新建议。条件性名词须结合全段功能读。","boundary":"“基础、责任、保障”既可能提出行动要求，也可能只描述现状；必须确认作者是否在主张改变。","prompt":"“稳定维护是保障，因此要设维护预算”落实到行动是设立{{0}}。","blanks":[{"answer":"维护预算","accept":[]}]},{"id":"ki-v-018","title":"把抽象责任翻译成动作","core":"“接收单位负有登记义务”可转为接收单位应登记；“核验是必要路径”可转为办理前需核验；“人员培训是实施基础”可转为实施前应先完成材料明确要求的培训；“持续维护是重要保障”可转为需要安排维护。责任、必要路径、基础和保障可承载建议，但只转出文本支持的动作，不能自行增添处罚、收费或新系统。","boundary":"“基础、责任、保障”既可能提出行动要求，也可能只描述现状；必须确认作者是否在主张改变。","prompt":"“接收单位负有登记义务”可转写为接收单位应当{{0}}。","blanks":[{"answer":"登记","accept":[]}]}],"questions":[{"id":"ki-vq-011","lesson":"mainidea","stem":"为减少展览器材重复购买，文化中心应建立可查询的共享清单，借助清单协调各活动使用时段。更新记录是这一路径持续有效的保障，因此还须明确专人维护。哪项最完整？","options":["只需购买更多器材就能降低重复采购","用共享清单协调器材使用，并明确记录维护责任","共享清单建成后不再需要人员维护","所有活动必须停止自行安排时段"],"answer":1,"explanation":"建议、路径、保障和责任都指向清单协调及维护，符合全段。","optionReviews":["更换手段，且增加购买与目标不符。","建议、路径、保障和责任都指向清单协调及维护，符合全段。","与明确专人维护直接相反。","协调不等于完全剥夺安排权。"]},{"id":"ki-vq-012","lesson":"mainidea","stem":"甲：“旧制度规定仓库负责登记，本文据此统计过去的交接次数。”乙：“交接记录屡有遗漏，今后应由仓库负责登记，并每周核对。”哪项判断成立？","options":["乙只陈述历史，未提出行动","甲乙都只要出现“负责”就必须以登记为全文主旨","甲介绍既有规定，乙提出针对遗漏的行动要求","甲已经要求仓库立即修改登记制度"],"answer":2,"explanation":"甲的登记规定服务于历史统计；乙用今后应、每周核对提出行动。","optionReviews":["乙明确指向今后行动。","责任词不能自动确定主旨。","甲的登记规定服务于历史统计；乙用今后应、每周核对提出行动。","甲只介绍既有规定与统计用途，没有要求修改登记制度。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"识别问题与措施的组织方式","text":"材料可先说明堵点再提方案，也可先提方案后说明理由，或在方案后补效果。无论次序怎样，都要把“要解决什么、怎么解决、为何有效”连起来。 适用边界：有问题不意味着必有对策中心；须确认作者是否在提出措施，以及措施确实回应同一问题。","index":30,"domId":"ki-point-0207"},{"title":"核对方案与问题是否对口","text":"如果问题是表格项目重复，改进合并字段直接回应原因；延长营业时间未必减少重复填写。不能把任何看似积极的行动都算同一个问题的解决办法。 适用边界：有问题不意味着必有对策中心；须确认作者是否在提出措施，以及措施确实回应同一问题。","index":31,"domId":"ki-point-0208"},{"title":"从例子上升到合适层级","text":"文段列导览牌、语音提示、人工咨询以便利游客，概括可说完善信息服务；不能只写其中一块牌，也不宜上升成无所不包的城市治理。 适用边界：有问题不意味着必有对策中心；须确认作者是否在提出措施，以及措施确实回应同一问题。","index":32,"domId":"ki-point-0209"}],"cards":[{"id":"ki-v-019","title":"识别问题与措施的组织方式","core":"材料可先说明堵点再提方案，也可先提方案后说明理由，或在方案后补效果。无论次序怎样，都要把“要解决什么、怎么解决、为何有效”连起来。","boundary":"有问题不意味着必有对策中心；须确认作者是否在提出措施，以及措施确实回应同一问题。","prompt":"“增设预约入口，因为现场登记太慢”先提出{{0}}，再说明理由。","blanks":[{"answer":"措施","accept":[]}]},{"id":"ki-v-020","title":"核对方案与问题是否对口","core":"如果问题是表格项目重复，改进合并字段直接回应原因；延长营业时间未必减少重复填写。不能把任何看似积极的行动都算同一个问题的解决办法。","boundary":"有问题不意味着必有对策中心；须确认作者是否在提出措施，以及措施确实回应同一问题。","prompt":"原因是重复填表，直接对应的改进是{{0}}重复字段。","blanks":[{"answer":"合并","accept":[]}]},{"id":"ki-v-021","title":"从例子上升到合适层级","core":"文段列导览牌、语音提示、人工咨询以便利游客，概括可说完善信息服务；不能只写其中一块牌，也不宜上升成无所不包的城市治理。","boundary":"有问题不意味着必有对策中心；须确认作者是否在提出措施，以及措施确实回应同一问题。","prompt":"导览牌、语音提示和人工咨询的共同上位内容是{{0}}服务。","blanks":[{"answer":"信息","accept":[]}]}],"questions":[{"id":"ki-vq-013","lesson":"mainidea","stem":"办事大厅拟将三个窗口要求的同类材料合并为一次提交。过去，申请人常因重复准备证明而多次往返；试行合并后，同一事项的补交次数有所减少。这段话主要说明：","options":["补交次数减少说明所有申请都能一次办结","应延长大厅的午间营业时间","通过材料一次提交减少重复准备和往返","三个窗口应全部取消"],"answer":2,"explanation":"措施在前，随后给原因和效果，主张是合并提交。","optionReviews":["“有所减少”不等于全部零补交。","与所述原因没有直接联系，也未提出。","措施在前，随后给原因和效果，主张是合并提交。","合并材料不等于取消窗口。"]},{"id":"ki-vq-014","lesson":"mainidea","stem":"山地小镇的应急广播在低谷区信号较弱，高处村落却主要受供电不稳影响。本文比较地形与供电对覆盖的不同限制，尚不讨论具体改造方案。最恰当的概括是：","options":["只需抬高天线就能解决全镇广播问题","全镇应立即统一更换广播设备","供电不稳由低谷地形造成","应急广播覆盖受地形和供电等不同因素限制"],"answer":3,"explanation":"作者任务是解释不同限制，没有提出统一对策。","optionReviews":["只对应一类因素且夸为全解决。","未经材料支持增添措施。","把并列限制强加成因果。","作者任务是解释不同限制，没有提出统一对策。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"从风险条件读出有限提醒","text":"“若跳过交接检查，遗漏可能进入下一班”指出跳检风险，可支持不要跳过检查的提醒。它没有说检查是防止遗漏的唯一办法，也没有说执行检查便绝对安全。 适用边界：避免一种风险来源不保证消除全部风险；根据警示提建议时，只能调整有明确机制依据的行为。","index":33,"domId":"ki-point-0210"},{"title":"反推行动须对准机制","text":"原文说一次发送过多附件易触发网关限制，适量分批是对机制的调整；更换全部设备不是由此自然得到的方案。否定风险前提也不能证明所有失败都消失。 适用边界：避免一种风险来源不保证消除全部风险；根据警示提建议时，只能调整有明确机制依据的行为。","index":34,"domId":"ki-point-0211"}],"cards":[{"id":"ki-v-022","title":"从风险条件读出有限提醒","core":"“若跳过交接检查，遗漏可能进入下一班”指出跳检风险，可支持不要跳过检查的提醒。它没有说检查是防止遗漏的唯一办法，也没有说执行检查便绝对安全。","boundary":"避免一种风险来源不保证消除全部风险；根据警示提建议时，只能调整有明确机制依据的行为。","prompt":"“跳过检查可能留下遗漏”可以支持避免{{0}}的提醒。","blanks":[{"answer":"跳过检查","accept":[]}]},{"id":"ki-v-023","title":"反推行动须对准机制","core":"原文说一次发送过多附件易触发网关限制，适量分批是对机制的调整；更换全部设备不是由此自然得到的方案。否定风险前提也不能证明所有失败都消失。","boundary":"避免一种风险来源不保证消除全部风险；根据警示提建议时，只能调整有明确机制依据的行为。","prompt":"附件过多触发网关限制，直接针对该机制的调整是{{0}}发送。","blanks":[{"answer":"分批","accept":[]}]}],"questions":[{"id":"ki-vq-015","lesson":"mainidea","stem":"若一次向预约系统导入过多记录，校验队列可能拥堵，部分请求会超时。因此，维护人员准备将导入任务拆成适量批次。哪项推断最稳妥？","options":["只要分批就能保证系统永不超时","所有超时都是一次导入过多记录造成的","分批导入针对记录集中造成的队列拥堵","必须立即更换所有用户终端"],"answer":2,"explanation":"明确机制是集中任务挤占队列，分批直接作用于该机制。","optionReviews":["没有排除网络等其他超时原因。","由一种可能原因不能推出唯一原因。","明确机制是集中任务挤占队列，分批直接作用于该机制。","终端更换与队列机制无直接证据。"]},{"id":"ki-vq-016","lesson":"mainidea","stem":"材料仅指出：“如果省略包装检查，破损件可能流入配送环节。”以下工作提醒最符合材料？","options":["省略检查必然使每一件商品破损","只要做过包装检查，配送中绝不会破损","停止配送是材料要求的唯一办法","不要省略包装检查，以降低该途径带来的风险"],"answer":3,"explanation":"针对被指出的风险来源作有限调整，没有过度保证。","optionReviews":["原文为可能，非必然且非每件。","把消减某一途径风险夸成消除所有风险。","无停止配送或唯一措施的依据。","针对被指出的风险来源作有限调整，没有过度保证。"]}]},{"lessonId":"scoped-reading","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"问题本身也可以是主旨","text":"一段只比较老街积水的多种成因，并指出原因仍待检验，中心可以是成因复杂且需辨析，不能硬选“全面改造地下管网”。主旨首先概括实际说出的信息。 适用边界：主旨应忠实呈现材料，意图可作有根据的适度延伸；缺少行动线索时，不用常识凭空替作者立方案。","index":9,"domId":"ki-point-0212"},{"title":"意图延伸须有文本牵引","text":"若原文连续强调信息入口分散使公众找不到办事指南，统一入口是自然支持的方向；但不能借此新增收费咨询或实名门槛。隐含建议应紧贴明确堵点。 适用边界：主旨应忠实呈现材料，意图可作有根据的适度延伸；缺少行动线索时，不用常识凭空替作者立方案。","index":10,"domId":"ki-point-0213"},{"title":"检查是否对因且无附加条件","text":"同样是改进措施，整理重复入口回应入口分散，强制更换手机却将问题转嫁给用户。比较选项时，把每个新增对象、限制与承诺逐一找依据。 适用边界：主旨应忠实呈现材料，意图可作有根据的适度延伸；缺少行动线索时，不用常识凭空替作者立方案。","index":11,"domId":"ki-point-0214"}],"cards":[{"id":"ki-v-024","title":"问题本身也可以是主旨","core":"一段只比较老街积水的多种成因，并指出原因仍待检验，中心可以是成因复杂且需辨析，不能硬选“全面改造地下管网”。主旨首先概括实际说出的信息。","boundary":"主旨应忠实呈现材料，意图可作有根据的适度延伸；缺少行动线索时，不用常识凭空替作者立方案。","prompt":"材料只分析积水成因且未定论，主旨应保留成因的{{0}}性。","blanks":[{"answer":"复杂","accept":[]}]},{"id":"ki-v-025","title":"意图延伸须有文本牵引","core":"若原文连续强调信息入口分散使公众找不到办事指南，统一入口是自然支持的方向；但不能借此新增收费咨询或实名门槛。隐含建议应紧贴明确堵点。","boundary":"主旨应忠实呈现材料，意图可作有根据的适度延伸；缺少行动线索时，不用常识凭空替作者立方案。","prompt":"指南入口分散妨碍查询，材料自然支持的方向是{{0}}查询入口。","blanks":[{"answer":"统一","accept":[]}]},{"id":"ki-v-026","title":"检查是否对因且无附加条件","core":"同样是改进措施，整理重复入口回应入口分散，强制更换手机却将问题转嫁给用户。比较选项时，把每个新增对象、限制与承诺逐一找依据。","boundary":"主旨应忠实呈现材料，意图可作有根据的适度延伸；缺少行动线索时，不用常识凭空替作者立方案。","prompt":"以“入口分散”为由要求用户换手机，增加了材料未支持的{{0}}。","blanks":[{"answer":"限制","accept":[]}]}],"questions":[{"id":"ki-vq-017","lesson":"scoped-reading","stem":"旧城区多处积水：有的发生在低洼街口，有的与短时强降雨相伴，还有的可能涉及施工遮挡。现有记录尚不足以确定各因素作用大小。最准确的主旨是：","options":["施工遮挡是所有积水的唯一原因","旧城区积水成因多样，现有证据尚难区分其作用","应立即对全部旧城区道路进行抬升","现有记录已确定强降雨起决定作用"],"answer":1,"explanation":"忠实概括多种可能与证据不足，无强造措施。","optionReviews":["将一个可能因素扩成唯一原因。","忠实概括多种可能与证据不足，无强造措施。","全范围抬升没有文段支持。","与尚难确定作用大小矛盾。"]},{"id":"ki-vq-018","lesson":"scoped-reading","stem":"公众反映，办事指南散落在不同页面，名称相近却版本不一，常需多次跳转才能确认最新要求。作者反复强调，障碍不在阅读能力，而在信息入口的组织。作者最可能赞同：","options":["取消全部线上指南改为口头询问","整合指南入口并清楚标明版本","要求公众更换性能更好的手机","对所有查询指南者收取服务费"],"answer":1,"explanation":"紧扣入口分散与版本混乱，方向由文段自然支持。","optionReviews":["从组织改进跳到全面取消，无依据。","紧扣入口分散与版本混乱，方向由文段自然支持。","作者已将原因定位在组织而非用户设备。","收费未对应原因且新增负担。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"看多个方面是否同层展开","text":"“以及”连接的项目也可能与“此外、同时”和分号一样呈现同层方面，而不自动构成因果。“此外、同时”常添加另一个方面，分号也可分隔平行内容。例如公园既改善遮阴，同时补充饮水点，是两项服务改进；要检查是否都服务于同一讨论对象。 适用边界：连接词和时间序列只提供线索；只有语义任务同层时才适合并列概括，因果链应保留方向。","index":35,"domId":"ki-point-0215"},{"title":"平行句式不只靠连接词","text":"“清晨方便通勤，午后承接休闲，夜间提供漫步空间”按时段呈现同一滨河道的多重用途；如果后一句由前一句引起，则不是简单罗列。时间词不自动决定结构。 适用边界：连接词和时间序列只提供线索；只有语义任务同层时才适合并列概括，因果链应保留方向。","index":36,"domId":"ki-point-0216"},{"title":"共同对象和主要维度一起留","text":"文段说改造既保护旧树又增加儿童活动区，答案可概括兼顾生态保护与使用需求，只说公园变好太空，只说儿童活动又漏掉保护维度。 适用边界：连接词和时间序列只提供线索；只有语义任务同层时才适合并列概括，因果链应保留方向。","index":37,"domId":"ki-point-0217"}],"cards":[{"id":"ki-v-027","title":"看多个方面是否同层展开","core":"“以及”连接的项目也可能与“此外、同时”和分号一样呈现同层方面，而不自动构成因果。“此外、同时”常添加另一个方面，分号也可分隔平行内容。例如公园既改善遮阴，同时补充饮水点，是两项服务改进；要检查是否都服务于同一讨论对象。","boundary":"连接词和时间序列只提供线索；只有语义任务同层时才适合并列概括，因果链应保留方向。","prompt":"补遮阴与增饮水点是同一公园服务改善的两个{{0}}。","blanks":[{"answer":"方面","accept":[]}]},{"id":"ki-v-028","title":"平行句式不只靠连接词","core":"“清晨方便通勤，午后承接休闲，夜间提供漫步空间”按时段呈现同一滨河道的多重用途；如果后一句由前一句引起，则不是简单罗列。时间词不自动决定结构。","boundary":"连接词和时间序列只提供线索；只有语义任务同层时才适合并列概括，因果链应保留方向。","prompt":"同一滨河道在早午晚提供不同用途，可概括为功能的{{0}}化。","blanks":[{"answer":"多样","accept":[]}]},{"id":"ki-v-029","title":"共同对象和主要维度一起留","core":"文段说改造既保护旧树又增加儿童活动区，答案可概括兼顾生态保护与使用需求，只说公园变好太空，只说儿童活动又漏掉保护维度。","boundary":"连接词和时间序列只提供线索；只有语义任务同层时才适合并列概括，因果链应保留方向。","prompt":"旧树保护与儿童活动区建设的概括要同时保留生态和{{0}}需求。","blanks":[{"answer":"使用","accept":[]}]}],"questions":[{"id":"ki-vq-019","lesson":"mainidea","stem":"城郊湿地修复后，候鸟有了更多停歇地；同时，步道设置让市民能够在限定区域观察自然。此外，监测平台也为研究者积累了数据。主要说明：","options":["湿地修复兼顾生态、公众体验与科研支持","所有湿地都已建立监测平台","观鸟活动必然导致科研数据增加","湿地修复的唯一目的在于吸引游客"],"answer":0,"explanation":"同一修复对象下三方面同层，概括保留各主要维度。","optionReviews":["同一修复对象下三方面同层，概括保留各主要维度。","把个案范围扩为所有湿地。","把并列功能强加因果。","遗漏生态与科研，并添唯一。"]},{"id":"ki-vq-020","lesson":"mainidea","stem":"春季连续降雨使地面含水量上升，随后边坡土体松动，最后部分路段发生滑移。对此段组织的理解正确的是：","options":["重点在于春季适合修路","并列介绍三个互不相关的季节现象","按时间展开一条降雨影响边坡的因果过程","只列三个同等独立的道路功能"],"answer":2,"explanation":"含水、松动、滑移由前因向后果推进，不能见时间词就判并列。","optionReviews":["修路适宜性未提及。","三项存在机制和顺序，不是互不相关。","含水、松动、滑移由前因向后果推进，不能见时间词就判并列。","内容不是道路功能且非独立同层。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"无标记也能分述","text":"“社区厨房提供平价午餐。夜校开放技能课程。共享工具柜满足小修小补。”三句可从不同服务切入社区便利建设，虽然没有“此外”。语义同层才是依据。 适用边界：没有关联词仍可能有解释或递进；是否并列要靠内容关系验证，不能凭“多方面”一词替代概括。","index":38,"domId":"ki-point-0218"},{"title":"比较对象句式与任务","text":"若三句分别说渠道、人员、时间安排，且都解释服务如何到达居民，可同层概括；若后句回答前句为什么，则属解释。相似句式只是候选证据。 适用边界：没有关联词仍可能有解释或递进；是否并列要靠内容关系验证，不能凭“多方面”一词替代概括。","index":39,"domId":"ki-point-0219"},{"title":"上位概括必须落地覆盖","text":"“服务更便民”只有在能涵盖各项信息时才可用。材料分别讲预约、接驳和陪同，可以概括优化就医服务链；说提高医术既未覆盖这些环节又换了判断。 适用边界：没有关联词仍可能有解释或递进；是否并列要靠内容关系验证，不能凭“多方面”一词替代概括。","index":40,"domId":"ki-point-0220"}],"cards":[{"id":"ki-v-030","title":"无标记也能分述","core":"“社区厨房提供平价午餐。夜校开放技能课程。共享工具柜满足小修小补。”三句可从不同服务切入社区便利建设，虽然没有“此外”。语义同层才是依据。","boundary":"没有关联词仍可能有解释或递进；是否并列要靠内容关系验证，不能凭“多方面”一词替代概括。","prompt":"没有“同时、此外”的三项社区服务也可能构成{{0}}关系。","blanks":[{"answer":"并列","accept":[]}]},{"id":"ki-v-031","title":"比较对象句式与任务","core":"若三句分别说渠道、人员、时间安排，且都解释服务如何到达居民，可同层概括；若后句回答前句为什么，则属解释。相似句式只是候选证据。","boundary":"没有关联词仍可能有解释或递进；是否并列要靠内容关系验证，不能凭“多方面”一词替代概括。","prompt":"“客流下降。原因是道路施工阻断入口。”后句主要在{{0}}前句。","blanks":[{"answer":"解释","accept":[]}]},{"id":"ki-v-032","title":"上位概括必须落地覆盖","core":"“服务更便民”只有在能涵盖各项信息时才可用。材料分别讲预约、接驳和陪同，可以概括优化就医服务链；说提高医术既未覆盖这些环节又换了判断。","boundary":"没有关联词仍可能有解释或递进；是否并列要靠内容关系验证，不能凭“多方面”一词替代概括。","prompt":"预约、接驳、陪同可统摄为优化就医{{0}}。","blanks":[{"answer":"服务链","accept":[]}]}],"questions":[{"id":"ki-vq-021","lesson":"mainidea","stem":"村里开设了预约接送服务。卫生室建立了用药提醒簿。志愿者为独居老人提供就诊陪同。文段主要介绍：","options":["村庄医院全面提高了诊疗技术","用药提醒簿是唯一有效的养老办法","预约接送导致所有老人都无需陪同","村庄从多个服务环节支持老人就医"],"answer":3,"explanation":"三句无连接词却同层介绍就医支持，概括覆盖三项。","optionReviews":["诊疗技术未涉及，替换中心判断。","只留一项且无唯一依据。","捏造因果并与陪同存在的事实不合。","三句无连接词却同层介绍就医支持，概括覆盖三项。"]},{"id":"ki-vq-022","lesson":"mainidea","stem":"展厅观众经常在同一岔口迷路。那里两条走廊的名称完全相同，指示牌又被柱体遮挡。哪项概括最好？","options":["名称重复与标识受阻解释了岔口的辨路困难","展厅需要立刻迁往新馆","迷路说明所有观众都不看指示牌","文段并列介绍展厅的两个独立主题"],"answer":0,"explanation":"后句回答前句原因，缺关联词也能形成解释关系。","optionReviews":["后句回答前句原因，缺关联词也能形成解释关系。","迁馆方案远超证据。","把环境问题归于所有观众习惯，未获支持。","对象和任务集中在同一迷路现象，非独立主题。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"找到持续讨论的对象","text":"一段反复提到游客、展品和路线，但各句都在说明导览怎样帮助理解，真正核心对象是导览服务。找主题要问判断围绕谁展开，而不是数名词。 适用边界：主题可用同义表达，不以某个名词出现次数最多为准；主题相同的选项仍可能判断相反或范围不当。","index":41,"domId":"ki-point-0221"},{"title":"从共同指向提取而非数词频","text":"中心句能直接定位对象；无中心句时，可把数句的共同主语或共同被解释对象归并。反复出现的案例名称不一定是中心，单次出现的总括概念反而可能统摄全文。 适用边界：主题可用同义表达，不以某个名词出现次数最多为准；主题相同的选项仍可能判断相反或范围不当。","index":42,"domId":"ki-point-0222"},{"title":"主题之外还要核对判断","text":"原文讲数字目录帮助检索，答案用“在线索引提高查找效率”可以同义对应；“数字目录取代全部原件”虽对象相近，却换了作者判断。 适用边界：主题可用同义表达，不以某个名词出现次数最多为准；主题相同的选项仍可能判断相反或范围不当。","index":43,"domId":"ki-point-0223"},{"title":"识别对象与范围偷换","text":"把“基层图书室的借阅登记”换成“全部文化事业”，范围过大；只谈某一登记员又过窄。对象、判断和适用范围必须同时一致。 适用边界：主题可用同义表达，不以某个名词出现次数最多为准；主题相同的选项仍可能判断相反或范围不当。","index":44,"domId":"ki-point-0224"}],"cards":[{"id":"ki-v-033","title":"找到持续讨论的对象","core":"一段反复提到游客、展品和路线，但各句都在说明导览怎样帮助理解，真正核心对象是导览服务。找主题要问判断围绕谁展开，而不是数名词。","boundary":"主题可用同义表达，不以某个名词出现次数最多为准；主题相同的选项仍可能判断相反或范围不当。","prompt":"多次提及游客和展品，却始终讨论导览作用，核心对象是{{0}}服务。","blanks":[{"answer":"导览","accept":[]}]},{"id":"ki-v-034","title":"从共同指向提取而非数词频","core":"中心句能直接定位对象；无中心句时，可把数句的共同主语或共同被解释对象归并。反复出现的案例名称不一定是中心，单次出现的总括概念反而可能统摄全文。","boundary":"主题可用同义表达，不以某个名词出现次数最多为准；主题相同的选项仍可能判断相反或范围不当。","prompt":"三个村庄案例都在说明山区运输成本高。即使村名出现次数最多，主题也应围绕山区的{{0}}。","blanks":[{"answer":"运输成本","accept":[]}]},{"id":"ki-v-035","title":"主题之外还要核对判断","core":"原文讲数字目录帮助检索，答案用“在线索引提高查找效率”可以同义对应；“数字目录取代全部原件”虽对象相近，却换了作者判断。","boundary":"主题可用同义表达，不以某个名词出现次数最多为准；主题相同的选项仍可能判断相反或范围不当。","prompt":"“在线索引提高查找效率”可同义对应数字目录的{{0}}作用。","blanks":[{"answer":"检索","accept":[]}]},{"id":"ki-v-036","title":"识别对象与范围偷换","core":"把“基层图书室的借阅登记”换成“全部文化事业”，范围过大；只谈某一登记员又过窄。对象、判断和适用范围必须同时一致。","boundary":"主题可用同义表达，不以某个名词出现次数最多为准；主题相同的选项仍可能判断相反或范围不当。","prompt":"“部分社区图书室”被改成“全国全部图书馆”，属于{{0}}范围。","blanks":[{"answer":"扩大","accept":[]}]}],"questions":[{"id":"ki-vq-023","lesson":"mainidea","stem":"三个乡镇的档案室分别介绍了纸本目录、电子目录和分类标签的改进。名称不同，目的都是让使用者更快找到资料；这些工具并不替代档案原件。最佳概括是：","options":["电子目录应全面替代档案原件","档案检索工具的改进有助于提高资料查找效率","全国档案馆都已完成数字化","三个乡镇名称的差异决定档案价值"],"answer":1,"explanation":"共同对象是检索工具，核心判断是提高查找效率，未扩大范围。","optionReviews":["虽含目录话题，但判断与原文否定相反。","共同对象是检索工具，核心判断是提高查找效率，未扩大范围。","从三个案例扩为全国并增加完成状态。","把案例名称当核心且捏造决定关系。"]},{"id":"ki-vq-024","lesson":"mainidea","stem":"文段持续讨论社区图书室如何通过简化登记减少排队，其中反复举出“南巷图书室”的做法。以下概括最恰当的是：","options":["全国文化事业都应取消登记","社区图书室需要增加所有书籍的价格","简化借阅登记有助于社区图书室减少排队","南巷名称的由来"],"answer":2,"explanation":"抓共同对象与判断，不被高频案例名牵走。","optionReviews":["扩大为全国文化事业，并把简化变取消。","价格调整与登记排队无文本依据。","抓共同对象与判断，不被高频案例名牵走。","名称高频不代表在讨论名称由来。"]}]},{"lessonId":"mainidea","topicId":"central-meaning","courseRoute":"#course/verbal/topic/central-meaning","sections":[{"title":"把支撑材料连到它证明的判断","text":"“雨棚延长后，候车区淋雨投诉减少”可用作设施改善有效的事实证据。背景交代环境，数据交代变化，多角度说明交代不同方面；它们是否从属须看与主判断的联系。 适用边界：例子和数据在主旨题中常是支持材料，在细节任务中却可能正是答案；不应一律删除。","index":45,"domId":"ki-point-0225"},{"title":"后句未必始终从属","text":"“导览文字更清楚，调查中理解率提高”是在解释前述改进；“但理解提升不等于参与增加，接下来应设计互动环节”又提出新层。读到新评价和新主张时，要更新全段结构。 适用边界：例子和数据在主旨题中常是支持材料，在细节任务中却可能正是答案；不应一律删除。","index":46,"domId":"ki-point-0226"},{"title":"事实与评价分两层核对","text":"“50人中有30人完成操作”是记录；“参与效果尚有提升空间”是对记录的评价。主旨要看作者借事实说明什么，细节题则不能把评价当成新增实验结果。 适用边界：例子和数据在主旨题中常是支持材料，在细节任务中却可能正是答案；不应一律删除。","index":47,"domId":"ki-point-0227"}],"cards":[{"id":"ki-v-037","title":"把支撑材料连到它证明的判断","core":"“雨棚延长后，候车区淋雨投诉减少”可用作设施改善有效的事实证据。背景交代环境，数据交代变化，多角度说明交代不同方面；它们是否从属须看与主判断的联系。","boundary":"例子和数据在主旨题中常是支持材料，在细节任务中却可能正是答案；不应一律删除。","prompt":"“增设雨棚后淋雨投诉减少”可支持候车设施改善{{0}}的判断。","blanks":[{"answer":"有效","accept":[]}]},{"id":"ki-v-038","title":"后句未必始终从属","core":"“导览文字更清楚，调查中理解率提高”是在解释前述改进；“但理解提升不等于参与增加，接下来应设计互动环节”又提出新层。读到新评价和新主张时，要更新全段结构。","boundary":"例子和数据在主旨题中常是支持材料，在细节任务中却可能正是答案；不应一律删除。","prompt":"后文说“理解提升还不够，应增加互动”，论述已从解释旧判断转向新的{{0}}。","blanks":[{"answer":"主张","accept":[]}]},{"id":"ki-v-039","title":"事实与评价分两层核对","core":"“50人中有30人完成操作”是记录；“参与效果尚有提升空间”是对记录的评价。主旨要看作者借事实说明什么，细节题则不能把评价当成新增实验结果。","boundary":"例子和数据在主旨题中常是支持材料，在细节任务中却可能正是答案；不应一律删除。","prompt":"“50人中30人完成”是事实，“仍需改进”是作者的{{0}}。","blanks":[{"answer":"评价","accept":[]}]}],"questions":[{"id":"ki-vq-025","lesson":"mainidea","stem":"小型阅读角也能提升借阅便利。某社区将书架移到居民必经的服务站后，借阅人数增加；另一个社区设置流动还书箱，逾期归还明显减少。文段主要说明：","options":["两个社区的居民都更喜欢流动还书箱","逾期归还减少由借阅人数增加直接造成","通过便捷设置，小型阅读角也能改善借阅服务","小型阅读角必须取代大型图书馆"],"answer":2,"explanation":"首句判断由位置调整和还书箱两个例子支持，未出现新中心。","optionReviews":["第二个措施不能扩为两社区共同偏好。","两例分属不同社区，不能强加因果。","首句判断由位置调整和还书箱两个例子支持，未出现新中心。","“也能”非必须取代。"]},{"id":"ki-vq-026","lesson":"mainidea","stem":"试用记录显示，40名参与者中有28人独立完成操作。报告认为，这反映出新版界面具有一定可用性；但仍需为首次使用者提供引导，以减少初次尝试中的困难。哪项理解正确？","options":["全文只说界面具有一定可用性，不存在新的行动要求","28人完成是事实，引导首次使用者是后续主张","28人完成证明所有新用户都能独立操作","“仍需引导”是另一项已经完成的试验结果"],"answer":1,"explanation":"区分记录与评价，并识别转折后新的引导要求。","optionReviews":["末句明确新增首次使用引导。","区分记录与评价，并识别转折后新的引导要求。","28/40不等于所有用户。","“需”是要求，非完成记录。"]}]},{"lessonId":"detail-reading","topicId":"detail-reading-topic","courseRoute":"#course/verbal/topic/detail-reading-topic","sections":[{"title":"逐项拆开对象关系与新增内容","text":"核对细节时拆成谁、做什么、何时、多少、为什么。把“参观者”改成“工作人员”是偷换概念；增添工程费用是新增事实；把“封路引起绕行”改成“绕行引起封路”是倒置因果；把“同时增设座椅与遮阴”改成“遮阴使座椅增加”是强加因果。并列、因果或比较关系都不能擅改。 适用边界：绝对词只意味着值得检查，不能直接判错；相对词也可能偷换对象或关系。未说明与被否定须分别处理。","index":9,"domId":"ki-point-0228"},{"title":"反向证据与缺乏证据不同","text":"原文说周二闭馆，“周二开放”与文本相反；原文未报票价，“票价十元”只是没有依据。两者都不能作为符合项，但解释不能混写成全部被原文否定。 适用边界：绝对词只意味着值得检查，不能直接判错；相对词也可能偷换对象或关系。未说明与被否定须分别处理。","index":10,"domId":"ki-point-0229"},{"title":"数量程度比较都要找对应依据","text":"“所有预约者均收到通知”可以支持全部收到；如果只说多数，就不能换成全部。“比去年更快”需要去年的比较基准，不能由今年某个时长单独推出。 适用边界：绝对词只意味着值得检查，不能直接判错；相对词也可能偷换对象或关系。未说明与被否定须分别处理。","index":11,"domId":"ki-point-0230"},{"title":"解释什么须对准问题","text":"问为何减少，答案应提供作用机制；问如何减少，应给操作办法；问资料从哪来，应给来源。材料里即便确实出现一个步骤，也不能用它直接回答来源问题。 适用边界：绝对词只意味着值得检查，不能直接判错；相对词也可能偷换对象或关系。未说明与被否定须分别处理。","index":12,"domId":"ki-point-0231"}],"cards":[{"id":"ki-v-040","title":"逐项拆开对象关系与新增内容","core":"核对细节时拆成谁、做什么、何时、多少、为什么。把“参观者”改成“工作人员”是偷换概念；增添工程费用是新增事实；把“封路引起绕行”改成“绕行引起封路”是倒置因果；把“同时增设座椅与遮阴”改成“遮阴使座椅增加”是强加因果。并列、因果或比较关系都不能擅改。","boundary":"绝对词只意味着值得检查，不能直接判错；相对词也可能偷换对象或关系。未说明与被否定须分别处理。","prompt":"材料只说座椅与遮阴同时增加，选项改成遮阴导致座椅增加，是{{0}}因果。","blanks":[{"answer":"强加","accept":[]}]},{"id":"ki-v-041","title":"反向证据与缺乏证据不同","core":"原文说周二闭馆，“周二开放”与文本相反；原文未报票价，“票价十元”只是没有依据。两者都不能作为符合项，但解释不能混写成全部被原文否定。","boundary":"绝对词只意味着值得检查，不能直接判错；相对词也可能偷换对象或关系。未说明与被否定须分别处理。","prompt":"原文没有票价信息，“票价十元”属于文本{{0}}。","blanks":[{"answer":"未说明","accept":[]}]},{"id":"ki-v-042","title":"数量程度比较都要找对应依据","core":"“所有预约者均收到通知”可以支持全部收到；如果只说多数，就不能换成全部。“比去年更快”需要去年的比较基准，不能由今年某个时长单独推出。","boundary":"绝对词只意味着值得检查，不能直接判错；相对词也可能偷换对象或关系。未说明与被否定须分别处理。","prompt":"原文明确“全部通过核验”，不能仅因选项含“全部”就判{{0}}。","blanks":[{"answer":"错误","accept":[]}]},{"id":"ki-v-043","title":"解释什么须对准问题","core":"问为何减少，答案应提供作用机制；问如何减少，应给操作办法；问资料从哪来，应给来源。材料里即便确实出现一个步骤，也不能用它直接回答来源问题。","boundary":"绝对词只意味着值得检查，不能直接判错；相对词也可能偷换对象或关系。未说明与被否定须分别处理。","prompt":"题目问数据来源，回答“逐条去重”给的是处理{{0}}，不一定是来源。","blanks":[{"answer":"方法","accept":[]}]}],"questions":[{"id":"ki-vq-027","lesson":"detail-reading","stem":"试点仅在甲区进行。工作人员同时增加遮阴棚和座椅，所有新增座椅均经过承重检验；报告未公布工程费用。哪项符合文意？","options":["全部新增座椅都经过了承重检验","该措施已在全市实施","工程费用低于去年同类项目","遮阴棚增加导致座椅数量增加"],"answer":0,"explanation":"原文明确所有新增座椅均检验，绝对表达在这里有证据。","optionReviews":["原文明确所有新增座椅均检验，绝对表达在这里有证据。","“仅甲区”与“全市”相反，扩大范围。","费用及去年比较均未说明，并非已被反向事实否定。","同时发生是并列，不证明棚导致座椅增加。"]},{"id":"ki-vq-028","lesson":"detail-reading","stem":"为统计步道使用量，团队从入口计数器取得记录，再剔除设备重复上传的数据。剔除后总数下降，因为原始记录含有重复项。若问“本次统计的原始记录从何而来”，哪项直接作答？","options":["剔除后下降的统计总数","剔除重复上传的数据","因为原始记录包含重复项","步道入口的计数器"],"answer":3,"explanation":"计数器是明确的数据来源，问答类型一致。","optionReviews":["这是处理结果，不是原始来源。","这是数据清理方法，不回答来源。","这是总数下降的原因。","计数器是明确的数据来源，问答类型一致。"]},{"id":"ki-vq-029","lesson":"detail-reading","stem":"文段写道：“本周仅周二暂停开放；周一、周三至周日均正常开放。开放日所有预约时段都提供讲解。”哪项理解有据？","options":["周二也正常开放，只是不提供讲解","本周讲解质量一定高于上周","开放日的每个预约时段均有讲解","多数预约时段可能没有讲解"],"answer":2,"explanation":"原文明确所有，故“每个”同义成立。","optionReviews":["与周二暂停开放直接冲突。","上下周质量比较没有证据。","原文明确所有，故“每个”同义成立。","与所有时段有讲解相反。"]},{"id":"ki-vq-073","lesson":"detail-reading","stem":"“道路检修导致主入口临时关闭，参观者因而改走北门。工作人员仍从侧门进入。”哪项符合文意？","options":["参观者改走北门是主入口临时关闭后的调整","所有工作人员也只能从北门进入","参观者改走北门导致主入口关闭","主入口关闭必然提高展馆收入"],"answer":0,"explanation":"检修、关闭、改道的方向清楚，保留参观者对象。","optionReviews":["检修、关闭、改道的方向清楚，保留参观者对象。","将参观者替换成工作人员且与侧门进入事实冲突。","把关闭导致改道倒置为改道导致关闭。","新增收入因果，原文未提供机制或数据。"]}]},{"lessonId":"sentence-link","topicId":"cohesion","courseRoute":"#course/verbal/topic/cohesion","sections":[{"title":"句内先保证语法与搭配成立","text":"“不仅缩短等候时间，还提高办理效率”需前后结构协调，不能填成主谓缺失或让“缩短”支配不合适的抽象对象。读半句时也要连看下一句是否改变对象。 适用边界：空缺即使只有半句，也可能被后文对象和指代限制；完整句不能只看前一句顺口。","index":9,"domId":"ki-point-0232"},{"title":"整句要前后都能接上","text":"前句说纸质地图更新慢，后句说“这些版本变动可被及时同步”，中间需要引入可同步更新的地图方案。只承接旧地图而不引出新方案，就无法解释后句的“这些”。 适用边界：空缺即使只有半句，也可能被后文对象和指代限制；完整句不能只看前一句顺口。","index":10,"domId":"ki-point-0233"},{"title":"五类约束一起核验","text":"话题要连续，代词要有先行对象，因果与转折方向要合理，已完成与将来计划不能混淆，语气强度也要一致。“预计可改善”不能无证据接成“已经彻底解决”。 适用边界：空缺即使只有半句，也可能被后文对象和指代限制；完整句不能只看前一句顺口。","index":11,"domId":"ki-point-0234"}],"cards":[{"id":"ki-v-044","title":"句内先保证语法与搭配成立","core":"“不仅缩短等候时间，还提高办理效率”需前后结构协调，不能填成主谓缺失或让“缩短”支配不合适的抽象对象。读半句时也要连看下一句是否改变对象。","boundary":"空缺即使只有半句，也可能被后文对象和指代限制；完整句不能只看前一句顺口。","prompt":"“缩短”在“缩短等候时间”中支配的对象是{{0}}。","blanks":[{"answer":"等候时间","accept":[]}]},{"id":"ki-v-045","title":"整句要前后都能接上","core":"前句说纸质地图更新慢，后句说“这些版本变动可被及时同步”，中间需要引入可同步更新的地图方案。只承接旧地图而不引出新方案，就无法解释后句的“这些”。","boundary":"空缺即使只有半句，也可能被后文对象和指代限制；完整句不能只看前一句顺口。","prompt":"前句提出旧地图更新慢，后句谈及时同步，中间句要建立{{0}}更新方案。","blanks":[{"answer":"可同步","accept":[]}]},{"id":"ki-v-046","title":"五类约束一起核验","core":"话题要连续，代词要有先行对象，因果与转折方向要合理，已完成与将来计划不能混淆，语气强度也要一致。“预计可改善”不能无证据接成“已经彻底解决”。","boundary":"空缺即使只有半句，也可能被后文对象和指代限制；完整句不能只看前一句顺口。","prompt":"“预计可改善”接成“已经彻底解决”同时改变了时态和判断的{{0}}。","blanks":[{"answer":"强度","accept":[]}]}],"questions":[{"id":"ki-vq-030","lesson":"sentence-link","stem":"大厅合并了重复填写的字段，不仅____，还减少了核验人员逐项比对的负担。新的表单因此更便于双方使用。填入最恰当的是：","options":["增加了重复填写的次数","压缩了申请人的个人能力","缩短了申请人的填表时间","申请人填表时间的缩短"],"answer":2,"explanation":"动宾搭配成立，主语承接合并字段，且与后半句并列为正面效果。","optionReviews":["与合并重复字段的效果及后文便利用途相反。","能力不能在此被“压缩”，且不符合改进方向。","动宾搭配成立，主语承接合并字段，且与后半句并列为正面效果。","名词性短语直接接“不仅”后破坏与“还减少”的谓语平行。"]},{"id":"ki-vq-031","lesson":"sentence-link","stem":"纸质导览图一旦印发，就难以及时反映临时封路信息。____。这些动态提示可在道路恢复后撤下，避免游客继续绕行。填入最恰当的一句是：","options":["因此旧纸图早已准确标出每次临时封路","所有纸质地图必须永久禁止使用","景区计划在电子导览图上实时显示封路提示","游客对餐饮服务的评价总体较高"],"answer":2,"explanation":"引入动态提示作为后句指代对象，话题、未来计划和作用逻辑连贯。","optionReviews":["既与前句难以反映冲突，也无法解释这些动态提示。","无全面禁用依据且不引入动态提示。","引入动态提示作为后句指代对象，话题、未来计划和作用逻辑连贯。","转移到餐饮，缺少指代承接。"]}]},{"lessonId":"sentence-link","topicId":"cohesion","courseRoute":"#course/verbal/topic/cohesion","sections":[{"title":"段首常要统领后面的范围","text":"空在开头，后文分说早高峰、午后、夜间服务，可用一句统摄分时需求；如果后文只是一个实验步骤，开头也可作情境引入，不必强塞全篇结论。 适用边界：段首、中、末只是位置线索；最终应由具体内容和前后照应决定，段末也可以继续举例。","index":12,"domId":"ki-point-0235"},{"title":"段中要有双向通道","text":"前句讲分类不清，后句讲标签试行效果，中间句应把问题转入贴标签的改进。承接不是复读前句，开启也不是突然引入全新对象。 适用边界：段首、中、末只是位置线索；最终应由具体内容和前后照应决定，段末也可以继续举例。","index":13,"domId":"ki-point-0236"},{"title":"段末按语义收束而非一律对策","text":"前文给出多次成功记录，结尾可有限总结；前文有明确问题也可提有据建议；若前句说“还可见于以下场景”，段末继续举例反而最合适。 适用边界：段首、中、末只是位置线索；最终应由具体内容和前后照应决定，段末也可以继续举例。","index":14,"domId":"ki-point-0237"}],"cards":[{"id":"ki-v-047","title":"段首常要统领后面的范围","core":"空在开头，后文分说早高峰、午后、夜间服务，可用一句统摄分时需求；如果后文只是一个实验步骤，开头也可作情境引入，不必强塞全篇结论。","boundary":"段首、中、末只是位置线索；最终应由具体内容和前后照应决定，段末也可以继续举例。","prompt":"开头后分述早午晚公交需求，总领句可概括需求的{{0}}差异。","blanks":[{"answer":"时段","accept":[]}]},{"id":"ki-v-048","title":"段中要有双向通道","core":"前句讲分类不清，后句讲标签试行效果，中间句应把问题转入贴标签的改进。承接不是复读前句，开启也不是突然引入全新对象。","boundary":"段首、中、末只是位置线索；最终应由具体内容和前后照应决定，段末也可以继续举例。","prompt":"分类不清之后、试行标签效果之前，中间句要引出{{0}}措施。","blanks":[{"answer":"标签","accept":[]}]},{"id":"ki-v-049","title":"段末按语义收束而非一律对策","core":"前文给出多次成功记录，结尾可有限总结；前文有明确问题也可提有据建议；若前句说“还可见于以下场景”，段末继续举例反而最合适。","boundary":"段首、中、末只是位置线索；最终应由具体内容和前后照应决定，段末也可以继续举例。","prompt":"前句承诺“下面再举一例”，段末应完成{{0}}任务而非硬加建议。","blanks":[{"answer":"举例","accept":[]}]}],"questions":[{"id":"ki-vq-032","lesson":"sentence-link","stem":"____。早高峰的乘客需要减少候车时间，午后的老年乘客更重视换乘便利，夜间乘客则更关注末班车衔接。填入段首最恰当的是：","options":["城市公交线路已经全面停止换乘","公交服务应关注不同时段的出行需求","候车时间是公交服务唯一需要关注的因素","夜间乘客的需求代表所有乘客"],"answer":1,"explanation":"统领后文三时段不同需求，范围合适。","optionReviews":["与后文需求讨论脱节且新增事实。","统领后文三时段不同需求，范围合适。","遗漏换乘及末班衔接。","以夜间一项替代全部。"]},{"id":"ki-vq-033","lesson":"sentence-link","stem":"资料柜分类不清，工作人员寻找旧记录常需反复开柜。____。试行一个月后，按标签查找的平均耗时有所下降，但尚未覆盖全部柜体。填入段中最恰当的是：","options":["管理人员于是为部分柜体设置了统一分类标签","所有柜体的检索问题已经彻底解决","资料柜的木材颜色与办公室墙面一致","工作人员决定停止保存任何旧记录"],"answer":0,"explanation":"承接分类问题，引出后句标签试行；“部分”与尚未全覆盖一致。","optionReviews":["承接分类问题，引出后句标签试行；“部分”与尚未全覆盖一致。","时态和范围均越过试行结果。","无问题到措施的衔接，也无标签来源。","既不引入标签又与继续查旧记录不合。"]},{"id":"ki-vq-034","lesson":"sentence-link","stem":"共享资料箱不仅用于课堂，培训活动也会使用。下面再看一个例子：____。填入段末最恰当的是：","options":["社区急救培训把练习材料装入共享箱，供不同小组轮换使用","共享箱的未来价值尚需从宏观经济角度证明","所有活动都必须立刻采购相同箱子","课堂永远不应使用资料箱"],"answer":0,"explanation":"完成“再看一个例子”的承诺，说明培训场景；段末并非必须总结。","optionReviews":["完成“再看一个例子”的承诺，说明培训场景；段末并非必须总结。","转向论证议题，未完成举例。","无要求采购的依据，也未给承诺的例子。","否认开头课堂使用的事实。"]}]},{"lessonId":"next-paragraph","topicId":"cohesion","courseRoute":"#course/verbal/topic/cohesion","sections":[{"title":"末句线索须放在全文脉络中","text":"前文讲旧系统缺点，末句引入“差异化校验”，关注点已转为新办法。仍要回看它要解决的对象，防止把一个与全文无关的同名概念接进来。 适用边界：最可能的下文是当前语篇任务的下一步，不是预言实际作者写作；只提名称不表示已完成解释。","index":9,"domId":"ki-point-0238"},{"title":"辨认已经提出却没完成的任务","text":"“这套方法包括两个步骤”后尚未列步骤，下一步通常介绍步骤；“这种偏差为何出现”后缺原因，则需要解释机制。新术语刚被命名，还不能视为已讲完。 适用边界：最可能的下文是当前语篇任务的下一步，不是预言实际作者写作；只提名称不表示已完成解释。","index":10,"domId":"ki-point-0239"},{"title":"选择紧接而非遥远相关","text":"新机制刚引入时，先解释它如何运作比跳到十年后的行业格局更连贯。相关性不等于紧邻性，答案应完成最近的明确承诺。 适用边界：最可能的下文是当前语篇任务的下一步，不是预言实际作者写作；只提名称不表示已完成解释。","index":11,"domId":"ki-point-0240"},{"title":"排除重复和突然换题","text":"前文已充分交代旧系统成本，再接同样的成本罗列推进性弱；跳到办公室装饰则换题。除非末句明确重开旧题，应优先补全尚缺内容。 适用边界：最可能的下文是当前语篇任务的下一步，不是预言实际作者写作；只提名称不表示已完成解释。","index":12,"domId":"ki-point-0241"}],"cards":[{"id":"ki-v-050","title":"末句线索须放在全文脉络中","core":"前文讲旧系统缺点，末句引入“差异化校验”，关注点已转为新办法。仍要回看它要解决的对象，防止把一个与全文无关的同名概念接进来。","boundary":"最可能的下文是当前语篇任务的下一步，不是预言实际作者写作；只提名称不表示已完成解释。","prompt":"前文谈数据校验，末句提出“差异化校验”，下文仍应围绕{{0}}。","blanks":[{"answer":"数据校验","accept":[]}]},{"id":"ki-v-051","title":"辨认已经提出却没完成的任务","core":"“这套方法包括两个步骤”后尚未列步骤，下一步通常介绍步骤；“这种偏差为何出现”后缺原因，则需要解释机制。新术语刚被命名，还不能视为已讲完。","boundary":"最可能的下文是当前语篇任务的下一步，不是预言实际作者写作；只提名称不表示已完成解释。","prompt":"末句提出“该方法分两步”却未展开，留下了介绍{{0}}的任务。","blanks":[{"answer":"步骤","accept":[]}]},{"id":"ki-v-052","title":"选择紧接而非遥远相关","core":"新机制刚引入时，先解释它如何运作比跳到十年后的行业格局更连贯。相关性不等于紧邻性，答案应完成最近的明确承诺。","boundary":"最可能的下文是当前语篇任务的下一步，不是预言实际作者写作；只提名称不表示已完成解释。","prompt":"刚提出未解释的新机制，下文优先说明其{{0}}方式。","blanks":[{"answer":"运作","accept":[]}]},{"id":"ki-v-053","title":"排除重复和突然换题","core":"前文已充分交代旧系统成本，再接同样的成本罗列推进性弱；跳到办公室装饰则换题。除非末句明确重开旧题，应优先补全尚缺内容。","boundary":"最可能的下文是当前语篇任务的下一步，不是预言实际作者写作；只提名称不表示已完成解释。","prompt":"前文已解释完成的内容再次原样罗列，通常缺少语篇{{0}}。","blanks":[{"answer":"推进","accept":[]}]}],"questions":[{"id":"ki-vq-035","lesson":"next-paragraph","stem":"文章先介绍人工核查的耗时及差错，再说明统一校验只能筛出格式错误。末段提出：“为识别内容之间的冲突，我们引入关系校验。它通过两轮比对完成判断。”下文最可能介绍：","options":["关系校验两轮比对的具体过程","办公室设备摆放的审美原则","再次逐项重复人工核查的耗时数据","直接断言所有差错从此消失"],"answer":0,"explanation":"末句留下两轮过程的说明任务，且承接内容冲突问题。","optionReviews":["末句留下两轮过程的说明任务，且承接内容冲突问题。","与数据校验话题无关。","前文已完成旧方法问题，重复不推进。","跳过机制且作不受支持的完全保证。"]},{"id":"ki-vq-036","lesson":"next-paragraph","stem":"文段已完整比较两种纸张的耐水性，随后写道：“然而，装订材料也会影响保存年限。尤其是‘酸迁移’，容易被忽视。它究竟怎样发生？”最连贯的下文是：","options":["宣布已详细解释完酸迁移，无需再谈","解释装订材料中的酸如何迁移并影响保存","再将前文耐水性实验原样列一次","转而比较各出版社的封面绘画风格"],"answer":1,"explanation":"新对象与保存主题相关，且末句明确追问机制，须完成解释。","optionReviews":["只提术语和问题不等于解释完成。","新对象与保存主题相关，且末句明确追问机制，须完成解释。","重复已完整说明的比较。","封面画风不回应机制问题。"]}]},{"lessonId":"sentence-order","topicId":"cohesion","courseRoute":"#course/verbal/topic/cohesion","sections":[{"title":"用选项分歧减少核查量","text":"若四个排列只在谁先开头上不同，先看哪句能独立引题；若都以同一句开头，则比较内部差异更有效。这是利用选项分歧安排检查顺序，而非必须先求首句。 适用边界：首尾不必最先锁定，内部强约束更清楚时可以先用；读完还须检验全文，不能只认一组顺口短句。","index":9,"domId":"ki-point-0242"},{"title":"把强依赖画成箭头","text":"“这一结果”必须在可识别的结果之后，“先清理再涂装”存在工序顺序。成对关联词还可建立局部关系；但某句必须在前，不一定意味着两句必须紧挨。 适用边界：首尾不必最先锁定，内部强约束更清楚时可以先用；读完还须检验全文，不能只认一组顺口短句。","index":10,"domId":"ki-point-0243"},{"title":"完整回读是最后一道检查","text":"局部指代可成立但整体仍可能从结论突然跳回未引入背景。回读时看对象引入、时间进程、解释层次以及每个给定句是否只用一次；不能因一对句子通顺便停止。 适用边界：首尾不必最先锁定，内部强约束更清楚时可以先用；读完还须检验全文，不能只认一组顺口短句。","index":11,"domId":"ki-point-0244"}],"cards":[{"id":"ki-v-054","title":"用选项分歧减少核查量","core":"若四个排列只在谁先开头上不同，先看哪句能独立引题；若都以同一句开头，则比较内部差异更有效。这是利用选项分歧安排检查顺序，而非必须先求首句。","boundary":"首尾不必最先锁定，内部强约束更清楚时可以先用；读完还须检验全文，不能只认一组顺口短句。","prompt":"四个排列首句完全相同而内部次序不同，应优先核对{{0}}差异。","blanks":[{"answer":"内部","accept":[]}]},{"id":"ki-v-055","title":"把强依赖画成箭头","core":"“这一结果”必须在可识别的结果之后，“先清理再涂装”存在工序顺序。成对关联词还可建立局部关系；但某句必须在前，不一定意味着两句必须紧挨。","boundary":"首尾不必最先锁定，内部强约束更清楚时可以先用；读完还须检验全文，不能只认一组顺口短句。","prompt":"“这一结果”需要前文提供可识别的{{0}}。","blanks":[{"answer":"结果","accept":[]}]},{"id":"ki-v-056","title":"完整回读是最后一道检查","core":"局部指代可成立但整体仍可能从结论突然跳回未引入背景。回读时看对象引入、时间进程、解释层次以及每个给定句是否只用一次；不能因一对句子通顺便停止。","boundary":"首尾不必最先锁定，内部强约束更清楚时可以先用；读完还须检验全文，不能只认一组顺口短句。","prompt":"排序完成后应检查每个给定句是否使用{{0}}次且全文连贯。","blanks":[{"answer":"一","accept":[]}]}],"questions":[{"id":"ki-vq-037","lesson":"sentence-order","stem":"将下列句子排序，哪项最连贯？①扫描模型显示二层扶梯锈蚀严重。②社区拟开放旧水塔，首先需要了解内部状况。③这一发现促使团队把加固扶梯列为首项任务。④为此，团队先对塔体进行了扫描。⑤加固完成后，水塔才向预约访客开放。","options":["②④①③⑤","④②③①⑤","②①④⑤③","①③②④⑤"],"answer":0,"explanation":"②引入目标，④“为此”承接了解状况，①给扫描结果，③“这一发现”承接锈蚀，⑤在加固后开放；整段完整。","optionReviews":["②引入目标，④“为此”承接了解状况，①给扫描结果，③“这一发现”承接锈蚀，⑤在加固后开放；整段完整。","④的“为此”无前因，③又在①发现之前。","①结果先于④扫描，且开放先于③决定加固。","①结果先于扫描背景，②目标被插在发现和操作之间。"]},{"id":"ki-vq-038","lesson":"sentence-order","stem":"给定四句：①社区计划设共享工具柜。②柜体安装完成后，管理员把工具放入柜内。③在安装之前，志愿者先核对了工具清单。④清单核对完毕，工人开始安装柜体。以下排序哪项可行？","options":["①③④②","②①③④","③②④①","①④③②"],"answer":0,"explanation":"计划先引入柜体，核对先于安装、安装先于入柜，四句齐全且指代明确。","optionReviews":["计划先引入柜体，核对先于安装、安装先于入柜，四句齐全且指代明确。","②尚未引入柜体且安装完成在计划之前。","②完成安装在④开始安装之前，且①引题滞后。","④说核对完毕却放在③核对之前。"]}]},{"lessonId":"sentence-order","topicId":"cohesion","courseRoute":"#course/verbal/topic/cohesion","sections":[{"title":"首句要能为读者建立对象","text":"孤立段落若只出现“因此……”这类后半关联，通常缺少前文理由，不能仅凭句法完整就认定可作首句。“雨水花园是一种汇集并渗透雨水的绿化设施”能独立引题。“这种设施”或“例如该小区”通常需要前文，但若题干已给对象，判定还要结合上下文。 适用边界：独立引入、总结收束都不是模板；先后依赖不自动等于紧邻，不足以区分两个顺序时要承认不唯一。","index":12,"domId":"ki-point-0245"},{"title":"收束句要符合前面的任务","text":"前文解释问题后提出对应措施，可自然收束；前文承诺列案例时，案例也能结束。不能只因某句含“因此建议”就强判结尾，仍看建议是否由前文支撑。 适用边界：独立引入、总结收束都不是模板；先后依赖不自动等于紧邻，不足以区分两个顺序时要承认不唯一。","index":13,"domId":"ki-point-0246"},{"title":"局部依赖与紧邻分别判断","text":"“这种装置”要求装置在前文被引入，但中间可有与装置相关的补充句。“一方面”与“另一方面”构成配对，也要看是否允许插入说明。强依赖只证明它实际表达的约束。 适用边界：独立引入、总结收束都不是模板；先后依赖不自动等于紧邻，不足以区分两个顺序时要承认不唯一。","index":14,"domId":"ki-point-0247"},{"title":"用问题回答和动作步骤定方向","text":"在本例中，应先提出“为什么加装滤网？”，再解释原因；倒置会破坏问答推进。先安装再测试有工序约束。观点后解释、问题后措施也常提供方向，但须以实际语义为准。 适用边界：独立引入、总结收束都不是模板；先后依赖不自动等于紧邻，不足以区分两个顺序时要承认不唯一。","index":15,"domId":"ki-point-0248"}],"cards":[{"id":"ki-v-057","title":"首句要能为读者建立对象","core":"孤立段落若只出现“因此……”这类后半关联，通常缺少前文理由，不能仅凭句法完整就认定可作首句。“雨水花园是一种汇集并渗透雨水的绿化设施”能独立引题。“这种设施”或“例如该小区”通常需要前文，但若题干已给对象，判定还要结合上下文。","boundary":"独立引入、总结收束都不是模板；先后依赖不自动等于紧邻，不足以区分两个顺序时要承认不唯一。","prompt":"孤立段落开头出现“这种设施”，首先应查找它缺少的{{0}}。","blanks":[{"answer":"指代对象","accept":[]}]},{"id":"ki-v-058","title":"收束句要符合前面的任务","core":"前文解释问题后提出对应措施，可自然收束；前文承诺列案例时，案例也能结束。不能只因某句含“因此建议”就强判结尾，仍看建议是否由前文支撑。","boundary":"独立引入、总结收束都不是模板；先后依赖不自动等于紧邻，不足以区分两个顺序时要承认不唯一。","prompt":"前文讲排队由重复登记造成，末句建议合并登记属于对应问题的{{0}}。","blanks":[{"answer":"收束","accept":[]}]},{"id":"ki-v-059","title":"局部依赖与紧邻分别判断","core":"“这种装置”要求装置在前文被引入，但中间可有与装置相关的补充句。“一方面”与“另一方面”构成配对，也要看是否允许插入说明。强依赖只证明它实际表达的约束。","boundary":"独立引入、总结收束都不是模板；先后依赖不自动等于紧邻，不足以区分两个顺序时要承认不唯一。","prompt":"已知甲必须先于乙，尚不能直接断定两句必须{{0}}。","blanks":[{"answer":"紧邻","accept":[]}]},{"id":"ki-v-060","title":"用问题回答和动作步骤定方向","core":"在本例中，应先提出“为什么加装滤网？”，再解释原因；倒置会破坏问答推进。先安装再测试有工序约束。观点后解释、问题后措施也常提供方向，但须以实际语义为准。","boundary":"独立引入、总结收束都不是模板；先后依赖不自动等于紧邻，不足以区分两个顺序时要承认不唯一。","prompt":"“先装滤网，再做通水测试”要求安装在测试{{0}}。","blanks":[{"answer":"之前","accept":[]}]}],"questions":[{"id":"ki-vq-039","lesson":"sentence-order","stem":"排序题：①这种设施通过下凹空间暂存雨水。②雨水花园是一种汇集并渗透雨水的绿化设施。③为什么入口还要加装滤网？④因为落叶可能堵塞入水口，滤网可减少这种堵塞。⑤因此，维护时应定期清理滤网，保持入口畅通。哪项最连贯？","options":["②①③④⑤","②③⑤④①","⑤②①③④","①②④③⑤"],"answer":0,"explanation":"②独立定义，①的这种设施有着落；③提出滤网问题，④给原因，⑤由堵塞机制推出维护建议。","optionReviews":["②独立定义，①的这种设施有着落；③提出滤网问题，④给原因，⑤由堵塞机制推出维护建议。","⑤清理建议先于④堵塞原因，①对设施的介绍被割裂到末尾。","⑤的因此缺少前因，建议先于对象及机制。","①指代无来源，④回答又在③提问前。"]},{"id":"ki-vq-040","lesson":"sentence-order","stem":"四句为：①馆方拟设置新的饮水点。②饮水点可以减少游客离开展厅找水的往返。③馆方还将更新导览牌。④这一饮水设施将在月底启用。仅据这四句，以下判断最稳妥的是：","options":["③必须最后出现，因为“还”只能放段末","④必能独立作首句，因为有完整谓语","①②③④和①③②④都能满足饮水点先引入、后说明的关系，现有信息不足以强求唯一顺序","①与④必须紧挨，其他句不能插入"],"answer":2,"explanation":"两种给定顺序均先引入饮水点再讲作用与启用，③提供并列事项；无更强约束排除其一。","optionReviews":["“还”提示补充，不规定结尾位置。","这一饮水设施依赖前文，孤立开头缺对象。","两种给定顺序均先引入饮水点再讲作用与启用，③提供并列事项；无更强约束排除其一。","先行对象依赖不等于紧邻，中间两句不妨碍辨认饮水设施。"]}]},{"lessonId":"word","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"先比较词在强调什么","text":"“鼓励”强调增强信心与行动意愿，“奖励”强调给予肯定性回报，两词虽有关联，动作核心并不一样。若文段只说用语言让人愿意继续尝试，就不能凭空改为已经发给物质奖励。先确定当前句子需要哪一种动作，再比较词的义项。 适用边界：义项、对象、强度、色彩需合并判断；还可检查词性和语体，但标签不能替代实际句义。","index":12,"domId":"ki-point-0249"},{"title":"检查谁支配或修饰谁","text":"动词要与宾语搭配，形容词要能描述中心名词。“开阔视野”与“拓宽道路”分别对准认识范围和空间宽度，不能仅因都表示变大就任意互换。 适用边界：义项、对象、强度、色彩需合并判断；还可检查词性和语体，但标签不能替代实际句义。","index":13,"domId":"ki-point-0250"},{"title":"程度不要多许诺一步","text":"“控制”是约束在一定范围，“消除”常表示不再存在。数据只证明投诉减少，就不能写“根除了投诉”；词的强度必须由信息支撑。 适用边界：义项、对象、强度、色彩需合并判断；还可检查词性和语体，但标签不能替代实际句义。","index":14,"domId":"ki-point-0251"},{"title":"评价色彩服从作者态度","text":"赞许有益探索可用“勇于创新”；批评无视规章的行动可用“擅自决定”。若报道只记录某人作出决定，未给评价依据，应避免强塞贬义。 适用边界：义项、对象、强度、色彩需合并判断；还可检查词性和语体，但标签不能替代实际句义。","index":15,"domId":"ki-point-0252"}],"cards":[{"id":"ki-v-061","title":"先比较词在强调什么","core":"“鼓励”强调增强信心与行动意愿，“奖励”强调给予肯定性回报，两词虽有关联，动作核心并不一样。若文段只说用语言让人愿意继续尝试，就不能凭空改为已经发给物质奖励。先确定当前句子需要哪一种动作，再比较词的义项。","boundary":"义项、对象、强度、色彩需合并判断；还可检查词性和语体，但标签不能替代实际句义。","prompt":"“老师用话语增强试验者继续尝试的信心”更直接对应{{0}}，而不是已经发给物质回报。","blanks":[{"answer":"鼓励","accept":[]}]},{"id":"ki-v-062","title":"检查谁支配或修饰谁","core":"动词要与宾语搭配，形容词要能描述中心名词。“开阔视野”与“拓宽道路”分别对准认识范围和空间宽度，不能仅因都表示变大就任意互换。","boundary":"义项、对象、强度、色彩需合并判断；还可检查词性和语体，但标签不能替代实际句义。","prompt":"“开阔视野”中，要求与“开阔”搭配的对象是{{0}}。","blanks":[{"answer":"视野","accept":[]}]},{"id":"ki-v-063","title":"程度不要多许诺一步","core":"“控制”是约束在一定范围，“消除”常表示不再存在。数据只证明投诉减少，就不能写“根除了投诉”；词的强度必须由信息支撑。","boundary":"义项、对象、强度、色彩需合并判断；还可检查词性和语体，但标签不能替代实际句义。","prompt":"投诉只是减少，写成“根除”会使语义程度{{0}}。","blanks":[{"answer":"过重","accept":[]}]},{"id":"ki-v-064","title":"评价色彩服从作者态度","core":"赞许有益探索可用“勇于创新”；批评无视规章的行动可用“擅自决定”。若报道只记录某人作出决定，未给评价依据，应避免强塞贬义。","boundary":"义项、对象、强度、色彩需合并判断；还可检查词性和语体，但标签不能替代实际句义。","prompt":"只客观记录人员调整，使用“恶意操纵”会额外增加{{0}}评价。","blanks":[{"answer":"贬义","accept":[]}]}],"questions":[{"id":"ki-vq-041","lesson":"word","stem":"试行分时入场后，高峰排队由40分钟降到25分钟，等待现象仍然存在。报告宜写：“分时入场在一定程度上____了高峰拥堵。”填入最恰当的是：","options":["根除","缓解","聆听","纵容"],"answer":1,"explanation":"缓解表示程度减轻，与仍有等待及“在一定程度上”一致，能支配拥堵。","optionReviews":["根除表示从根本消除，与仍然存在矛盾，强度过重。","缓解表示程度减轻，与仍有等待及“在一定程度上”一致，能支配拥堵。","聆听支配声音或意见，不与拥堵搭配。","纵容含放任不良行为的贬义，既非改善方向又不合此机制。"]},{"id":"ki-vq-042","lesson":"word","stem":"“工作人员认真核对每一项记录，发现异常便追查来源，绝不为赶进度随意略过。”最适合评价其工作态度的是：","options":["苛责","严谨","完美无缺","敷衍"],"answer":1,"explanation":"强调认真细致、核查有据，与文中行为和赞许态度一致。","optionReviews":["苛责是过严责备他人，文中是核对记录，不是责难对象。","强调认真细致、核查有据，与文中行为和赞许态度一致。","从态度认真不能推出所有工作毫无缺陷，程度过强。","敷衍是应付了事，与不随意略过相反。"]}]},{"lessonId":"word","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"从不同部分提出可检验假设","text":"辨“遏制”与“遏止”时，可由“制”想到控制扩展，由“止”想到停止，再检查词典义与上下文结果。词素分析是提出候选，不是凭一个字就宣判任何搭配。 适用边界：词素只能提示可能的区别，完整词义与惯常用法才是最终依据，成语尤其不能逐字相加。","index":16,"domId":"ki-point-0253"},{"title":"用整词与回填阻止望文生义","text":"确认词义后还要检查整词的典型搭配，再放回原句看是否自然且与全文一致。“差强人意”通常表示大体使人满意，并非“差得不能让人满意”。若材料说仍基本达到要求，可以用它；若说完全不合格就不适合。回填后检验整句评价是否一致。 适用边界：词素只能提示可能的区别，完整词义与惯常用法才是最终依据，成语尤其不能逐字相加。","index":17,"domId":"ki-point-0254"}],"cards":[{"id":"ki-v-065","title":"从不同部分提出可检验假设","core":"辨“遏制”与“遏止”时，可由“制”想到控制扩展，由“止”想到停止，再检查词典义与上下文结果。词素分析是提出候选，不是凭一个字就宣判任何搭配。","boundary":"词素只能提示可能的区别，完整词义与惯常用法才是最终依据，成语尤其不能逐字相加。","prompt":"由“止”推测更接近停止后，还必须用完整{{0}}检验。","blanks":[{"answer":"词义","accept":[]}]},{"id":"ki-v-066","title":"用整词与回填阻止望文生义","core":"确认词义后还要检查整词的典型搭配，再放回原句看是否自然且与全文一致。“差强人意”通常表示大体使人满意，并非“差得不能让人满意”。若材料说仍基本达到要求，可以用它；若说完全不合格就不适合。回填后检验整句评价是否一致。","boundary":"词素只能提示可能的区别，完整词义与惯常用法才是最终依据，成语尤其不能逐字相加。","prompt":"“差强人意”在规范用法中表示大体{{0}}。","blanks":[{"answer":"使人满意","accept":[]}]}],"questions":[{"id":"ki-vq-043","lesson":"word","stem":"试验发现，新的调度方案使拥堵扩展趋势受到控制，但尚未完全停止。此时用“遏制”而不直接断言“遏止”，最主要的依据是：","options":["两个词只要字形相似便可任意互换","整句只支持控制扩展，尚不支持完全停止","拥堵是中性名词，所有表示控制的词都不能搭配","只要见到“制”字就一定适用于所有对象"],"answer":1,"explanation":"可由词素提出控制与停止的区别，最终由尚未停止这一语境确认强度。","optionReviews":["近义不等于任何语境无差别。","可由词素提出控制与停止的区别，最终由尚未停止这一语境确认强度。","没有中性对象不能搭配控制词的规则。","把词素提示夸成绝对规则，忽略完整词义和搭配。"]},{"id":"ki-vq-044","lesson":"word","stem":"“尽管这次演示还有小缺点，但主要功能已达到预定要求，总体上____。”填入最恰当的是：","options":["惨不忍睹","无懈可击","一无是处","差强人意"],"answer":3,"explanation":"规范整词义为大体令人满意，符合有小缺点但主要达标。","optionReviews":["极度糟糕，与总体达标相反。","完全无可挑剔，超过仍有小缺点的证据。","全盘否定，与主要功能达标相反。","规范整词义为大体令人满意，符合有小缺点但主要达标。"]}]},{"lessonId":"word","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"定位空格真正修饰或支配的成分","text":"同时检查施事：是机器自动校验、管理员人工核对，还是记录本身呈现状态，不要给主语安排不可能实施的动作。动词空格先找宾语，定语空格找中心名词，状态描述还要看主语。“积累经验”与“积蓄力量”虽然相近，所支配的对象不同；不能只看空前一个字。 适用边界：常用搭配提供强证据但不是穷尽表；专业语境可以有特定用法，仍应以完整句义检验。","index":18,"domId":"ki-point-0255"},{"title":"对象可以藏在下一句","text":"“这份清单需要继续____。遗漏的设备编号下周补入。”后句揭示清单内容尚有缺项，故“补充”直接对应，不能只在“清单需要”四字里猜。多空时对象也可能由另一空显现。 适用边界：常用搭配提供强证据但不是穷尽表；专业语境可以有特定用法，仍应以完整句义检验。","index":19,"domId":"ki-point-0256"}],"cards":[{"id":"ki-v-067","title":"定位空格真正修饰或支配的成分","core":"同时检查施事：是机器自动校验、管理员人工核对，还是记录本身呈现状态，不要给主语安排不可能实施的动作。动词空格先找宾语，定语空格找中心名词，状态描述还要看主语。“积累经验”与“积蓄力量”虽然相近，所支配的对象不同；不能只看空前一个字。","boundary":"常用搭配提供强证据但不是穷尽表；专业语境可以有特定用法，仍应以完整句义检验。","prompt":"“不断____实践经验”中，动词应优先与宾语{{0}}核对搭配。","blanks":[{"answer":"实践经验","accept":[]}]},{"id":"ki-v-068","title":"对象可以藏在下一句","core":"“这份清单需要继续____。遗漏的设备编号下周补入。”后句揭示清单内容尚有缺项，故“补充”直接对应，不能只在“清单需要”四字里猜。多空时对象也可能由另一空显现。","boundary":"常用搭配提供强证据但不是穷尽表；专业语境可以有特定用法，仍应以完整句义检验。","prompt":"后句说“遗漏的设备编号下周补入”，空格“继续____清单”宜填{{0}}。","blanks":[{"answer":"补充","accept":[]}]}],"questions":[{"id":"ki-vq-045","lesson":"word","stem":"“项目组把每次试验的失败原因写入手册，以便不断____实践经验，并为后续测试____必要的技术力量。”填入最恰当的是：","options":["积累／积蓄","聆听／积累","积蓄／聆听","消耗／摒弃"],"answer":0,"explanation":"积累支配经验，积蓄支配力量，两处对象与目的同时成立。","optionReviews":["积累支配经验，积蓄支配力量，两处对象与目的同时成立。","聆听经验不表达从试验总结并累积，后一搭配也较弱。","积蓄经验在此不如积累贴切，聆听力量明显不合搭配。","消耗经验、摒弃力量与保存教训和准备后续相反。"]},{"id":"ki-vq-046","lesson":"word","stem":"“这份设备清单尚需____。核查人员发现有三台新购仪器没有登记，下周会把它们的编号补入。”填入最恰当的是：","options":["补充","背诵","废止","压缩"],"answer":0,"explanation":"下句明确缺项并将补入，跨句确认补充清单内容。","optionReviews":["下句明确缺项并将补入，跨句确认补充清单内容。","背诵不对应清单缺项的处理目的。","未主张取消清单，且补入与废止方向相反。","缺项要补，不是删减内容。"]}]},{"lessonId":"word","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"改善幅度决定用词力度","text":"若故障率由8%降到5%，可说降低或缓解，不能说彻底消除。强度要由结果约束，而不是越积极越好。 适用边界：递进可在范围、数量、程度或出乎预料的层面展开，不能一看到“甚至”就只找更重的同义词。","index":20,"domId":"ki-point-0257"},{"title":"找出被加强的具体维度","text":"递进还可加强数量，例如从少数环节到多数环节，并不只表现为形容词程度加重。“村镇可以接入，偏远哨所甚至也能使用”是覆盖范围与意外性的推进；“不便、甚至难以维持”是程度推进。先写出比较轴，才知道空格需要怎样的词。 适用边界：递进可在范围、数量、程度或出乎预料的层面展开，不能一看到“甚至”就只找更重的同义词。","index":21,"domId":"ki-point-0258"},{"title":"甚至后面未必更严重","text":"“专家可用，甚至初学者也能独立操作”强调适用门槛降低与超预期，并不是初学者比专家程度更重。需要比较相邻两项在当前目的下的难易或意外性。 适用边界：递进可在范围、数量、程度或出乎预料的层面展开，不能一看到“甚至”就只找更重的同义词。","index":22,"domId":"ki-point-0259"}],"cards":[{"id":"ki-v-069","title":"改善幅度决定用词力度","core":"若故障率由8%降到5%，可说降低或缓解，不能说彻底消除。强度要由结果约束，而不是越积极越好。","boundary":"递进可在范围、数量、程度或出乎预料的层面展开，不能一看到“甚至”就只找更重的同义词。","prompt":"故障率降到5%而非零，不能写“{{0}}故障”。","blanks":[{"answer":"彻底消除","accept":[]}]},{"id":"ki-v-070","title":"找出被加强的具体维度","core":"递进还可加强数量，例如从少数环节到多数环节，并不只表现为形容词程度加重。“村镇可以接入，偏远哨所甚至也能使用”是覆盖范围与意外性的推进；“不便、甚至难以维持”是程度推进。先写出比较轴，才知道空格需要怎样的词。","boundary":"递进可在范围、数量、程度或出乎预料的层面展开，不能一看到“甚至”就只找更重的同义词。","prompt":"“从城区覆盖到偏远海岛”主要扩展了服务的{{0}}。","blanks":[{"answer":"范围","accept":[]}]},{"id":"ki-v-071","title":"甚至后面未必更严重","core":"“专家可用，甚至初学者也能独立操作”强调适用门槛降低与超预期，并不是初学者比专家程度更重。需要比较相邻两项在当前目的下的难易或意外性。","boundary":"递进可在范围、数量、程度或出乎预料的层面展开，不能一看到“甚至”就只找更重的同义词。","prompt":"“专家会用，甚至初学者也会用”强调使用门槛更{{0}}。","blanks":[{"answer":"低","accept":[]}]}],"questions":[{"id":"ki-vq-047","lesson":"word","stem":"改进散热后，设备停机次数有所减少，但高负荷运行时仍会停机。“该改进____了停机问题，却未将其彻底____。”填入最恰当的是：","options":["根除／减轻","制造／解决","消除／减少","缓解／消除"],"answer":3,"explanation":"前空匹配减少但仍有，后空在未的否定下保留未完全消除，两处强度一致。","optionReviews":["根除与仍停机矛盾，且未减轻不合有所减少。","改进未制造问题，原文说次数减少。","先说消除后又未减少，自相冲突且违背仍有停机。","前空匹配减少但仍有，后空在未的否定下保留未完全消除，两处强度一致。"]},{"id":"ki-vq-048","lesson":"word","stem":"“简化流程后，有经验的技术员能独立安装，甚至第一次接触设备的学员也能完成。”这里“甚至”的推进主要在于：","options":["表示安装故障从轻微变成严重","表示参与者总人数必然翻倍","从有经验者扩展到新手，突出上手门槛降低","证明新手的技术水平高于所有技术员"],"answer":2,"explanation":"两项人群经验不同，新手也能完成带来超预期，非同义词程度升级。","optionReviews":["文中是成功适用人群，不是故障程度。","没有人数数据，不能推出翻倍。","两项人群经验不同，新手也能完成带来超预期，非同义词程度升级。","能完成不等于能力全面高于技术员。"]}]},{"lessonId":"word","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"把词语评价对准作者态度","text":"文段肯定认真试验可用“探索”，若批评明知规则仍越界可用“擅自”。先找到作者的赞许、批评或客观说明证据，再选带相应评价的词。 适用边界：正负事实与词的褒贬不是一一对应；反讽、引用和固定表达需判断说话人及真实态度。","index":23,"domId":"ki-point-0260"},{"title":"不利现象可以中性报告","text":"“受暴雨影响，运输延迟”描述不利结果，但“延迟”本身可中性。不能因事件不好就填“恶意耽搁”，后者增加了行为动机和谴责。 适用边界：正负事实与词的褒贬不是一一对应；反讽、引用和固定表达需判断说话人及真实态度。","index":24,"domId":"ki-point-0261"},{"title":"看引号和话语身份","text":"固定表达要按整词理解：“不负众望”的“负”是辜负，整词表示没有辜负期待，不能见“负”字就判贬义。“他所谓的‘高效’，只是跳过核验”带反讽，表面的褒词不表示作者赞许；“受访者称其‘大胆’”只是引用，也未必是作者结论。必须结合语境定真实评价。 适用边界：正负事实与词的褒贬不是一一对应；反讽、引用和固定表达需判断说话人及真实态度。","index":25,"domId":"ki-point-0262"}],"cards":[{"id":"ki-v-072","title":"把词语评价对准作者态度","core":"文段肯定认真试验可用“探索”，若批评明知规则仍越界可用“擅自”。先找到作者的赞许、批评或客观说明证据，再选带相应评价的词。","boundary":"正负事实与词的褒贬不是一一对应；反讽、引用和固定表达需判断说话人及真实态度。","prompt":"作者明确批评未经许可私改记录，可用“{{0}}修改”表达否定态度。","blanks":[{"answer":"擅自","accept":[]}]},{"id":"ki-v-073","title":"不利现象可以中性报告","core":"“受暴雨影响，运输延迟”描述不利结果，但“延迟”本身可中性。不能因事件不好就填“恶意耽搁”，后者增加了行为动机和谴责。","boundary":"正负事实与词的褒贬不是一一对应；反讽、引用和固定表达需判断说话人及真实态度。","prompt":"“暴雨导致运输延迟”不等于工作人员{{0}}耽搁。","blanks":[{"answer":"恶意","accept":[]}]},{"id":"ki-v-074","title":"看引号和话语身份","core":"固定表达要按整词理解：“不负众望”的“负”是辜负，整词表示没有辜负期待，不能见“负”字就判贬义。“他所谓的‘高效’，只是跳过核验”带反讽，表面的褒词不表示作者赞许；“受访者称其‘大胆’”只是引用，也未必是作者结论。必须结合语境定真实评价。","boundary":"正负事实与词的褒贬不是一一对应；反讽、引用和固定表达需判断说话人及真实态度。","prompt":"“所谓的‘高效’只是跳过核验”中，“高效”主要带有{{0}}意味。","blanks":[{"answer":"反讽","accept":[]}]}],"questions":[{"id":"ki-vq-049","lesson":"word","stem":"“受持续暴雨影响，山区物资运输出现____，工作人员正在协调替代路线。”报道只说明客观影响，填入最恰当的是：","options":["欣欣向荣","蓄意阻挠","恶意拖延","延迟"],"answer":3,"explanation":"延迟中性说明晚于预期，不新增恶意或人为责任。","optionReviews":["欣欣向荣褒写繁荣，不能描述运输受阻。","蓄意阻挠同样增加故意行为。","恶意是材料未给的主观动机，且评价过强。","延迟中性说明晚于预期，不新增恶意或人为责任。"]},{"id":"ki-vq-050","lesson":"word","stem":"“他把未经许可删掉核验步骤称为‘高效创新’。然而，审查发现遗漏因此增加，作者指出这种做法只是____。”填入最恰当的是：","options":["稳妥改进规范","精益求精","擅自简化流程","客观记录天气"],"answer":2,"explanation":"未经许可与遗漏增加支持批评；引语中的高效创新被后文反转。","optionReviews":["稳妥与遗漏增加的评价相反。","精益求精褒义，与作者明确批评不符。","未经许可与遗漏增加支持批评；引语中的高效创新被后文反转。","转移对象，无天气内容。"]},{"id":"ki-vq-072","lesson":"word","stem":"“团队克服困难，如期完成了居民期待的修复任务，可谓____。报道在此对结果表示肯定。”填入最恰当的是：","options":["一败涂地","不负众望","辜负期待","敷衍塞责"],"answer":1,"explanation":"不负众望表示没有辜负大家期待，整词评价与如期完成、肯定一致；不能因负字误判贬义。","optionReviews":["一败涂地表示失败严重，与完成任务矛盾。","不负众望表示没有辜负大家期待，整词评价与如期完成、肯定一致；不能因负字误判贬义。","辜负期待与满足居民期待相反。","敷衍塞责贬斥应付推责，文中没有且与肯定态度不合。"]}]},{"lessonId":"context-blanks","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"先把两端关系读成白话","text":"转折可能是原以为有效却发现局限，因果是前项说明后项为什么，同层并列则罗列多个方面。例如“记录格式统一，因此比对更省时”不是转折，也不允许选使比对更困难的词。 适用边界：常见关系不只三类；递进、条件、让步、解释也会限定词义。必须同时通过关系与搭配检验。","index":9,"domId":"ki-point-0263"},{"title":"先预测意思再挑合适词","text":"先用日常话写出空格需要“减少无用步骤”，再比对精简、增加、隐瞒等词，不必一开始被四个近义标签牵走。选出后还要检查它能否支配当前宾语，并与整段方向一致。 适用边界：常见关系不只三类；递进、条件、让步、解释也会限定词义。必须同时通过关系与搭配检验。","index":10,"domId":"ki-point-0264"}],"cards":[{"id":"ki-v-075","title":"先把两端关系读成白话","core":"转折可能是原以为有效却发现局限，因果是前项说明后项为什么，同层并列则罗列多个方面。例如“记录格式统一，因此比对更省时”不是转折，也不允许选使比对更困难的词。","boundary":"常见关系不只三类；递进、条件、让步、解释也会限定词义。必须同时通过关系与搭配检验。","prompt":"“格式统一，因此比对更省时”主要是{{0}}关系。","blanks":[{"answer":"因果","accept":[]}]},{"id":"ki-v-076","title":"先预测意思再挑合适词","core":"先用日常话写出空格需要“减少无用步骤”，再比对精简、增加、隐瞒等词，不必一开始被四个近义标签牵走。选出后还要检查它能否支配当前宾语，并与整段方向一致。","boundary":"常见关系不只三类；递进、条件、让步、解释也会限定词义。必须同时通过关系与搭配检验。","prompt":"空格需要“减少不必要环节”，且宾语是流程，可选“{{0}}流程”。","blanks":[{"answer":"精简","accept":[]}]}],"questions":[{"id":"ki-vq-051","lesson":"context-blanks","stem":"过去一张表需在三个窗口反复填写；新系统让同类信息只录入一次，因此显著____了办理流程。同时，人工咨询台继续为不熟悉网络的人提供帮助。填入最恰当的是：","options":["遮蔽","繁复","聆听","精简"],"answer":3,"explanation":"一次录入减少重复步骤，因果方向支持精简，且精简可支配流程；咨询台为同层补充服务。","optionReviews":["遮蔽是遮挡，不对应步骤减少。","繁复通常为形容词，此处不合谓语搭配且方向相反。","聆听用于声音或意见，不能表示对办理流程的精简。","一次录入减少重复步骤，因果方向支持精简，且精简可支配流程；咨询台为同层补充服务。"]},{"id":"ki-vq-052","lesson":"context-blanks","stem":"“团队既保留了旧地图的地名线索，也补入了新路网信息；但这些改动并未____所有定位误差，后续仍需校核。”填入最恰当的是：","options":["消除","制造","积累","聆听"],"answer":0,"explanation":"前面两项改动是并列，转折限制效果；后句仍需校核支持未消除全部误差。","optionReviews":["前面两项改动是并列，转折限制效果；后句仍需校核支持未消除全部误差。","文段限制的是改进未完全解决，不是未制造误差，后句机制不合。","积累误差不表达校核要解决的目标，且与改进语境不符。","定位误差不能被聆听。"]}]},{"lessonId":"context-blanks","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"看不一致究竟在哪里","text":"“新馆面积不大，却容纳了多种活动”反预期在面积与承载能力之间，两词并非反义。“但是”后要回应被修正的预期，而非强找前词反义。 适用边界：转折可以连接两项正面或中性信息；反义或褒贬相反只是可能形式，不是必需条件。","index":11,"domId":"ki-point-0265"},{"title":"锁定对比维度再填词","text":"“设备便于携带，但续航仍显不足”对比的是便携与持久两维，空格不能机械填“不便”。转折也可纠正误判，如外观朴素但操作方便，两边都可非负面。 适用边界：转折可以连接两项正面或中性信息；反义或褒贬相反只是可能形式，不是必需条件。","index":12,"domId":"ki-point-0266"},{"title":"词义对立不是万能配对","text":"若句子真对比成本上升与收益下降，需要相反方向；若对比“方案简单，却能处理复杂任务”，两端评价可以都正面。判断语义关系后再确定是否需要反义。 适用边界：转折可以连接两项正面或中性信息；反义或褒贬相反只是可能形式，不是必需条件。","index":13,"domId":"ki-point-0267"}],"cards":[{"id":"ki-v-077","title":"看不一致究竟在哪里","core":"“新馆面积不大，却容纳了多种活动”反预期在面积与承载能力之间，两词并非反义。“但是”后要回应被修正的预期，而非强找前词反义。","boundary":"转折可以连接两项正面或中性信息；反义或褒贬相反只是可能形式，不是必需条件。","prompt":"“面积不大，却能承接多种活动”的落差在面积与{{0}}能力之间。","blanks":[{"answer":"承载","accept":[]}]},{"id":"ki-v-078","title":"锁定对比维度再填词","core":"“设备便于携带，但续航仍显不足”对比的是便携与持久两维，空格不能机械填“不便”。转折也可纠正误判，如外观朴素但操作方便，两边都可非负面。","boundary":"转折可以连接两项正面或中性信息；反义或褒贬相反只是可能形式，不是必需条件。","prompt":"“便于携带，但续航不足”并不否认设备的{{0}}性。","blanks":[{"answer":"便携","accept":[]}]},{"id":"ki-v-079","title":"词义对立不是万能配对","core":"若句子真对比成本上升与收益下降，需要相反方向；若对比“方案简单，却能处理复杂任务”，两端评价可以都正面。判断语义关系后再确定是否需要反义。","boundary":"转折可以连接两项正面或中性信息；反义或褒贬相反只是可能形式，不是必需条件。","prompt":"“步骤简单，却运行可靠”两边可以同时属于{{0}}评价。","blanks":[{"answer":"正面","accept":[]}]}],"questions":[{"id":"ki-vq-053","lesson":"context-blanks","stem":"这套装置体积小巧、携带方便，却打破了“小设备续航短”的预期，能在野外连续工作一周，达到同类装置中的较高水平，续航表现相当____。填入最恰当的是：","options":["便携","笨重","短暂","出色"],"answer":3,"explanation":"小巧便携通常可能让人担心续航，连续一周修正预期，出色评价续航且两边都正面。","optionReviews":["便携评价搬运方便，不评价续航，虽重复前词也不合对象。","笨重修饰体积重量，不修饰续航表现。","与一周连续工作及相当的评价方向不合。","小巧便携通常可能让人担心续航，连续一周修正预期，出色评价续航且两边都正面。"]},{"id":"ki-vq-054","lesson":"context-blanks","stem":"“新展厅外观朴素，但动线清楚，初次到访者也很容易____。”填入最恰当的是：","options":["否认全部标识","辨认建筑昂贵程度","找到目标展区","延长迷路时间"],"answer":2,"explanation":"转折由外观转入使用体验，动线清楚支持容易找到目标，非朴素的反义词。","optionReviews":["否认标识与寻找方向无关。","昂贵程度不是动线清楚带来的结果。","转折由外观转入使用体验，动线清楚支持容易找到目标，非朴素的反义词。","与容易和动线清楚的改善方向相反。"]}]},{"lessonId":"context-blanks","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"识别原因端和结果端","text":"“因为”与“由于”引出理由端，“因此”可引出结果或由理由形成的推论。“由于编码不统一，记录难以匹配”前项是原因；“因此要统一编码”后项是由此提出的行动。因果词的位置有助于分端，但真正关系仍靠内容成立。 适用边界：因果词不证明任意事实构成因果；还要核对机制、方向与词语搭配，不能按单一褒贬表机械选词。","index":14,"domId":"ki-point-0268"},{"title":"使役词也把两件事连成因果","text":"“致使、造成、使得”都可能把一个动作或条件与后果连接，须结合实际结果和搭配确认。“漏报造成统计偏差”“自动备份使恢复更快”都把前项作为后项变化的原因。“造成”常见于不利结果，“使得”可较中性，仍要依据具体句义而非绝对标签。 适用边界：因果词不证明任意事实构成因果；还要核对机制、方向与词语搭配，不能按单一褒贬表机械选词。","index":15,"domId":"ki-point-0269"},{"title":"空格要补出可解释机制","text":"“通知分散在多个群，因此____”应接增加漏看的可能或不便核对，而非毫无中介地接“必然增加收入”。即使两件事同时发生，也不能靠因此二字强造联系。 适用边界：因果词不证明任意事实构成因果；还要核对机制、方向与词语搭配，不能按单一褒贬表机械选词。","index":16,"domId":"ki-point-0270"}],"cards":[{"id":"ki-v-080","title":"识别原因端和结果端","core":"“因为”与“由于”引出理由端，“因此”可引出结果或由理由形成的推论。“由于编码不统一，记录难以匹配”前项是原因；“因此要统一编码”后项是由此提出的行动。因果词的位置有助于分端，但真正关系仍靠内容成立。","boundary":"因果词不证明任意事实构成因果；还要核对机制、方向与词语搭配，不能按单一褒贬表机械选词。","prompt":"“由于编号重复，匹配失败”中的原因是{{0}}。","blanks":[{"answer":"编号重复","accept":[]}]},{"id":"ki-v-081","title":"使役词也把两件事连成因果","core":"“致使、造成、使得”都可能把一个动作或条件与后果连接，须结合实际结果和搭配确认。“漏报造成统计偏差”“自动备份使恢复更快”都把前项作为后项变化的原因。“造成”常见于不利结果，“使得”可较中性，仍要依据具体句义而非绝对标签。","boundary":"因果词不证明任意事实构成因果；还要核对机制、方向与词语搭配，不能按单一褒贬表机械选词。","prompt":"“自动备份使恢复更快”中，备份是恢复提速的{{0}}。","blanks":[{"answer":"原因","accept":[]}]},{"id":"ki-v-082","title":"空格要补出可解释机制","core":"“通知分散在多个群，因此____”应接增加漏看的可能或不便核对，而非毫无中介地接“必然增加收入”。即使两件事同时发生，也不能靠因此二字强造联系。","boundary":"因果词不证明任意事实构成因果；还要核对机制、方向与词语搭配，不能按单一褒贬表机械选词。","prompt":"通知分散导致核对不便，空格要符合可解释的因果{{0}}。","blanks":[{"answer":"机制","accept":[]}]}],"questions":[{"id":"ki-vq-055","lesson":"context-blanks","stem":"“由于同一设备被赋予两个不同编号，系统把它当作两台设备，____了统计中的重复计数。”填入最恰当的是：","options":["消除","赞许","造成","聆听"],"answer":2,"explanation":"编号不一致导致误认两台，进而产生重复计数，造成连接原因与不利结果。","optionReviews":["与误认引发重复的机制相反。","赞许指评价行为，非数据错误形成。","编号不一致导致误认两台，进而产生重复计数，造成连接原因与不利结果。","聆听不连接这种结果，也不能支配重复计数。"]},{"id":"ki-vq-056","lesson":"context-blanks","stem":"“自动备份保留了昨日的完整副本，因此____。”最合适的续句是：","options":["恢复副本造成昨日已经发生备份","办公室的噪声因此必然下降","误删后可以利用该副本恢复相应文件","所有文件从此都绝不可能被误删"],"answer":2,"explanation":"完整副本提供可恢复来源，方向和机制清楚，未绝对保证。","optionReviews":["倒置了备份与恢复的方向，并造成时间错误。","噪声无因果机制支持。","完整副本提供可恢复来源，方向和机制清楚，未绝对保证。","备份改善恢复，并不防止所有误删。"]}]},{"lessonId":"context-blanks","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"形式平行先当候选证据","text":"顿号、逗号和“有人……有人……”等重复句式可以呈现同层内容，也可能另有结构作用。“登记清楚、更新及时、查询方便”可同层描述记录管理的三个方面，却不是三个近义词。逗号也可能分开原因与结果，因此仍需检验各项语义功能。 适用边界：标点或相同句式不保证近义；并列可以互补，也可以对照，“不是而是”更常在纠正认识。","index":17,"domId":"ki-point-0271"},{"title":"相近互补和反向对照分开","text":"“相反、反之”或前肯定后否定的对照可突出差异，但不能因此要求两词必是字典反义。“既能预约，也能查询”是互补；“有人重速度，相反另一些人更重准确”是偏好对照。对照并不总要填字典反义词，要看实际不同在哪一维。 适用边界：标点或相同句式不保证近义；并列可以互补，也可以对照，“不是而是”更常在纠正认识。","index":18,"domId":"ki-point-0272"},{"title":"纠偏取舍看真正否定对象","text":"“不是增加表格，而是合并重复字段”否定一种办法，肯定另一种办法；空格应维持解决同一问题的取舍，不能因“而是”就要求所有字与前文相反。 适用边界：标点或相同句式不保证近义；并列可以互补，也可以对照，“不是而是”更常在纠正认识。","index":19,"domId":"ki-point-0273"}],"cards":[{"id":"ki-v-083","title":"形式平行先当候选证据","core":"顿号、逗号和“有人……有人……”等重复句式可以呈现同层内容，也可能另有结构作用。“登记清楚、更新及时、查询方便”可同层描述记录管理的三个方面，却不是三个近义词。逗号也可能分开原因与结果，因此仍需检验各项语义功能。","boundary":"标点或相同句式不保证近义；并列可以互补，也可以对照，“不是而是”更常在纠正认识。","prompt":"“登记清楚、更新及时、查询方便”是三个互补{{0}}，并非必须近义。","blanks":[{"answer":"方面","accept":[]}]},{"id":"ki-v-084","title":"相近互补和反向对照分开","core":"“相反、反之”或前肯定后否定的对照可突出差异，但不能因此要求两词必是字典反义。“既能预约，也能查询”是互补；“有人重速度，相反另一些人更重准确”是偏好对照。对照并不总要填字典反义词，要看实际不同在哪一维。","boundary":"标点或相同句式不保证近义；并列可以互补，也可以对照，“不是而是”更常在纠正认识。","prompt":"“有人重速度，另一些人重准确”主要比较不同人的{{0}}。","blanks":[{"answer":"偏好","accept":[]}]},{"id":"ki-v-085","title":"纠偏取舍看真正否定对象","core":"“不是增加表格，而是合并重复字段”否定一种办法，肯定另一种办法；空格应维持解决同一问题的取舍，不能因“而是”就要求所有字与前文相反。","boundary":"标点或相同句式不保证近义；并列可以互补，也可以对照，“不是而是”更常在纠正认识。","prompt":"“不是增加表格，而是合并字段”肯定的办法是{{0}}重复字段。","blanks":[{"answer":"合并","accept":[]}]}],"questions":[{"id":"ki-vq-057","lesson":"context-blanks","stem":"“好的交接记录应当条目清楚、更新____、查询方便。三者分别对应内容组织、维护节奏与使用体验。”填入最恰当的是：","options":["沉重","及时","悦耳","宽阔"],"answer":1,"explanation":"“维护节奏”直接限定及时，三项是互补维度而非近义堆叠。","optionReviews":["沉重多说重量或负担，不合此处更新要求。","“维护节奏”直接限定及时，三项是互补维度而非近义堆叠。","悦耳评价声音，不评价更新节奏。","宽阔评价空间或范围，不对应时间节奏。"]},{"id":"ki-vq-058","lesson":"context-blanks","stem":"“减少重复劳动，靠的不是要求员工把同样的表填得更快，而是____，让同一信息不必多次录入。”填入最恰当的是：","options":["合并重复字段","延长所有人的工时","把表格标题写得更醒目","增加重复录入次数"],"answer":0,"explanation":"后半句解释取舍标准：减少重复录入，合并字段直接回应。","optionReviews":["后半句解释取舍标准：减少重复录入，合并字段直接回应。","仍让人重复工作，且材料不支持延长工时。","标题醒目不解决字段重复。","与不必多次录入相反。"]},{"id":"ki-vq-059","lesson":"context-blanks","stem":"“一组乘客更重视车速，另一组则宁愿稍慢一些，也希望换乘更____，少走几段路。”填入最恰当的是：","options":["遥远","响亮","便利","昂贵"],"answer":2,"explanation":"以少走路解释换乘便利，与车速是不同偏好维度，不要求和车速构成反义。","optionReviews":["遥远与少走几段路方向相反。","响亮不修饰换乘便利性。","以少走路解释换乘便利，与车速是不同偏好维度，不要求和车速构成反义。","成本提高不能解释少走路。"]}]},{"lessonId":"word","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"改述可直接给出词义需求","text":"“即、也就是、也就是说”可能把前面的概念直接说得更具体；先核对它们实际改述哪一项。“这一安排具有弹性，也就是说，参与者可在规定范围内调整时段”后半句解释弹性，而非夸奖安排速度快。把改述翻成普通语言，可筛除方向相近却义项不同的词。 适用边界：解释词与标点只是线索；“无疑”常加强判断而非下定义，冒号也可列举或引语，必须确认所解释的对象。","index":26,"domId":"ki-point-0274"},{"title":"冒号和破折号要找其作用","text":"破折号也可引出说明，例如“条目须可回查——修改来源要有记录”；但破折号也可表示插说，仍需核对功能。“记录须可追溯：每次修改都能查到时间与操作者”给前词下具体界定；“名单如下：甲、乙”则是列举。不能仅见冒号就把后面所有词当空格的同义词。 适用边界：解释词与标点只是线索；“无疑”常加强判断而非下定义，冒号也可列举或引语，必须确认所解释的对象。","index":27,"domId":"ki-point-0275"},{"title":"例子能间接限定共同义","text":"“他做事很周全，比方说，出发前检查路线、天气和备用方案”由行为实例支持周全，不是支持轻率。要找例子共同呈现的特征，避免抓一个道具名称。 适用边界：解释词与标点只是线索；“无疑”常加强判断而非下定义，冒号也可列举或引语，必须确认所解释的对象。","index":28,"domId":"ki-point-0276"},{"title":"解释到底指向哪个空","text":"一段同时讨论反馈快与记录全，冒号后写“发生时间、处理人、处理经过都有”，解释的是完整性，不是响应速度。先连准解释对象，再选词，才不被邻近空吸引。 适用边界：解释词与标点只是线索；“无疑”常加强判断而非下定义，冒号也可列举或引语，必须确认所解释的对象。","index":29,"domId":"ki-point-0277"}],"cards":[{"id":"ki-v-086","title":"改述可直接给出词义需求","core":"“即、也就是、也就是说”可能把前面的概念直接说得更具体；先核对它们实际改述哪一项。“这一安排具有弹性，也就是说，参与者可在规定范围内调整时段”后半句解释弹性，而非夸奖安排速度快。把改述翻成普通语言，可筛除方向相近却义项不同的词。","boundary":"解释词与标点只是线索；“无疑”常加强判断而非下定义，冒号也可列举或引语，必须确认所解释的对象。","prompt":"“可在规定范围内调整时段”解释安排具有{{0}}。","blanks":[{"answer":"弹性","accept":[]}]},{"id":"ki-v-087","title":"冒号和破折号要找其作用","core":"破折号也可引出说明，例如“条目须可回查——修改来源要有记录”；但破折号也可表示插说，仍需核对功能。“记录须可追溯：每次修改都能查到时间与操作者”给前词下具体界定；“名单如下：甲、乙”则是列举。不能仅见冒号就把后面所有词当空格的同义词。","boundary":"解释词与标点只是线索；“无疑”常加强判断而非下定义，冒号也可列举或引语，必须确认所解释的对象。","prompt":"“每次修改都能查到时间与操作者”具体解释记录可{{0}}。","blanks":[{"answer":"追溯","accept":[]}]},{"id":"ki-v-088","title":"例子能间接限定共同义","core":"“他做事很周全，比方说，出发前检查路线、天气和备用方案”由行为实例支持周全，不是支持轻率。要找例子共同呈现的特征，避免抓一个道具名称。","boundary":"解释词与标点只是线索；“无疑”常加强判断而非下定义，冒号也可列举或引语，必须确认所解释的对象。","prompt":"出发前逐项检查路线、天气和备用方案，支持做事{{0}}。","blanks":[{"answer":"周全","accept":[]}]},{"id":"ki-v-089","title":"解释到底指向哪个空","core":"一段同时讨论反馈快与记录全，冒号后写“发生时间、处理人、处理经过都有”，解释的是完整性，不是响应速度。先连准解释对象，再选词，才不被邻近空吸引。","boundary":"解释词与标点只是线索；“无疑”常加强判断而非下定义，冒号也可列举或引语，必须确认所解释的对象。","prompt":"冒号后列时间、处理人、经过都有，主要限定记录的{{0}}性。","blanks":[{"answer":"完整","accept":[]}]}],"questions":[{"id":"ki-vq-060","lesson":"word","stem":"“预约安排具有____，也就是说，参与者可在规定范围内自行调整到场时段，而不必固定在同一时间。”填入最恰当的是：","options":["隐蔽性","唯一性","弹性","迟滞性"],"answer":2,"explanation":"改述明确允许范围内调整，与弹性义相符。","optionReviews":["隐蔽是难被发现，不对应可调整。","唯一强调只有一种，与允许调整相反。","改述明确允许范围内调整，与弹性义相符。","迟滞指反应慢，文中没有速度含义。"]},{"id":"ki-vq-061","lesson":"word","stem":"“记录应当____：每次修改的时间、操作者及修改内容，都能回查到原始条目。系统响应也很快，但此处要求的不是响应速度。”填入最恰当的是：","options":["廉价","迅猛","悦耳","可追溯"],"answer":3,"explanation":"冒号后逐项解释可回查来源及过程，直接对应可追溯，且题干排除速度。","optionReviews":["冒号说明回查过程，没有成本高低的信息。","迅猛表示迅速而有力，不对应来源与过程回查。","悦耳不描述记录查验功能。","冒号后逐项解释可回查来源及过程，直接对应可追溯，且题干排除速度。"]},{"id":"ki-vq-062","lesson":"word","stem":"“她为活动作了____的准备。比方说，既查了主路线，也核对了天气，还准备了道路封闭时的替代方案。负责人无疑赞许这种做法。”填入最恰当的是：","options":["仓促","单一","周全","草率"],"answer":2,"explanation":"多个实例共同说明考虑全面；无疑加强负责人赞许判断，不能替代实例的解释证据。","optionReviews":["未见时间紧迫，且周全行为不能支持仓促。","并非只准备一种方案。","多个实例共同说明考虑全面；无疑加强负责人赞许判断，不能替代实例的解释证据。","与多项核对及备用方案相反。"]}]},{"lessonId":"word","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"识别本体喻体及比较维度","text":"“如同、好比、像”可能提示本体与喻体之间的比较，需要找到共同特征。“目录像路标，帮助读者找到资料”把目录比作路标，比较的是导向功能而非木材或颜色。“如同”也可能只作比较，须有明确映射才按比喻处理。 适用边界：引号还可表示引用、强调或反讽；比喻填词要映射功能等共同特征，不照抄喻体的物理画面。","index":30,"domId":"ki-point-0278"},{"title":"引号提示可能特殊用法","text":"“数据孤岛”用引号可能把数据彼此隔绝比作岛；“他称之为‘完美’”也可能只是引用，后文若否定则是反讽。要先判语义身份，不自动按比喻理解。 适用边界：引号还可表示引用、强调或反讽；比喻填词要映射功能等共同特征，不照抄喻体的物理画面。","index":31,"domId":"ki-point-0279"},{"title":"取功能状态或动作而非外观","text":"制度被说成“护栏”，通常强调限制越界、降低风险，不表示制度必须由金属制成。空格需对应材料强调的共同点；若写桥梁，则多强调连接而非防越界。 适用边界：引号还可表示引用、强调或反讽；比喻填词要映射功能等共同特征，不照抄喻体的物理画面。","index":32,"domId":"ki-point-0280"}],"cards":[{"id":"ki-v-090","title":"识别本体喻体及比较维度","core":"“如同、好比、像”可能提示本体与喻体之间的比较，需要找到共同特征。“目录像路标，帮助读者找到资料”把目录比作路标，比较的是导向功能而非木材或颜色。“如同”也可能只作比较，须有明确映射才按比喻处理。","boundary":"引号还可表示引用、强调或反讽；比喻填词要映射功能等共同特征，不照抄喻体的物理画面。","prompt":"目录与路标的共同特征是提供{{0}}。","blanks":[{"answer":"导向","accept":[]}]},{"id":"ki-v-091","title":"引号提示可能特殊用法","core":"“数据孤岛”用引号可能把数据彼此隔绝比作岛；“他称之为‘完美’”也可能只是引用，后文若否定则是反讽。要先判语义身份，不自动按比喻理解。","boundary":"引号还可表示引用、强调或反讽；比喻填词要映射功能等共同特征，不照抄喻体的物理画面。","prompt":"“他称之为‘完美’，审查却发现错漏”中的引号不能直接证明作者{{0}}。","blanks":[{"answer":"赞许","accept":[]}]},{"id":"ki-v-092","title":"取功能状态或动作而非外观","core":"制度被说成“护栏”，通常强调限制越界、降低风险，不表示制度必须由金属制成。空格需对应材料强调的共同点；若写桥梁，则多强调连接而非防越界。","boundary":"引号还可表示引用、强调或反讽；比喻填词要映射功能等共同特征，不照抄喻体的物理画面。","prompt":"制度如“护栏”时，通常映射约束越界、降低{{0}}的功能。","blanks":[{"answer":"风险","accept":[]}]}],"questions":[{"id":"ki-vq-063","lesson":"word","stem":"“清晰的目录如同山路上的路标，能够为查找资料的人____，减少来回摸索。”填入最恰当的是：","options":["增添重量","指明方向","封闭道路","涂抹颜色"],"answer":1,"explanation":"路标与目录共同承担导向功能，指明方向映射准确。","optionReviews":["重量是物理特征，与查找任务无关。","路标与目录共同承担导向功能，指明方向映射准确。","封闭道路与减少摸索、帮助查找相反。","复制画面颜色而不回应导向。"]},{"id":"ki-vq-064","lesson":"word","stem":"“审核制度是防止流程越界的‘护栏’。”另有一句：“有人把跳过审核称为‘高效’，但事故说明这种‘高效’代价很大。”理解正确的是：","options":["所有带引号的词都必须按物理形状理解","护栏比喻约束功能，高效带反讽意味","护栏表示制度由金属构成，高效表示毫无缺点","两处引号都证明作者由衷赞美"],"answer":1,"explanation":"第一句有防越界功能映射，第二句由事故与代价否定表面褒词，语义身份不同。","optionReviews":["引号作用多样，不能一律物理化。","第一句有防越界功能映射，第二句由事故与代价否定表面褒词，语义身份不同。","将功能比喻实物化，并误读反讽。","第二处明确带批评，不是赞美。"]}]},{"lessonId":"context-blanks","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"从核心对象确定义域","text":"一段谈旧照片修复，空格应对应影像清晰、色调或保存状态；看似漂亮的“激昂”一般不描述照片清晰度。无关联词不代表四个候选都自由。 适用边界：无明显标志也有对象和语义照应，但重复某个原词不保证正确；需检查它在句中表达的判断。","index":20,"domId":"ki-point-0281"},{"title":"重复动作结果评价可照应","text":"反复出现的意象也可能照应，如“照亮前路、辨明方向”共同限定导向功能，但不能只凭某词重复就选它。前句说逐个核对编号，后句说不放过任何错位，虽没有“即”，共同指向细致校验。选择时抓两句共同呈现的特征，不是复制两句都出现的名词。 适用边界：无明显标志也有对象和语义照应，但重复某个原词不保证正确；需检查它在句中表达的判断。","index":21,"domId":"ki-point-0282"},{"title":"限制可能隔着一句才出现","text":"空后先谈人员分工，再写“破损书页已经逐页编号、配齐”，仍能限定前空应是整理、修复类动作。跨句甚至跨段回查，找真正的对象状态与结果。 适用边界：无明显标志也有对象和语义照应，但重复某个原词不保证正确；需检查它在句中表达的判断。","index":22,"domId":"ki-point-0283"}],"cards":[{"id":"ki-v-093","title":"从核心对象确定义域","core":"一段谈旧照片修复，空格应对应影像清晰、色调或保存状态；看似漂亮的“激昂”一般不描述照片清晰度。无关联词不代表四个候选都自由。","boundary":"无明显标志也有对象和语义照应，但重复某个原词不保证正确；需检查它在句中表达的判断。","prompt":"旧照片修复中“轮廓更____”的义域应围绕影像{{0}}度。","blanks":[{"answer":"清晰","accept":[]}]},{"id":"ki-v-094","title":"重复动作结果评价可照应","core":"反复出现的意象也可能照应，如“照亮前路、辨明方向”共同限定导向功能，但不能只凭某词重复就选它。前句说逐个核对编号，后句说不放过任何错位，虽没有“即”，共同指向细致校验。选择时抓两句共同呈现的特征，不是复制两句都出现的名词。","boundary":"无明显标志也有对象和语义照应，但重复某个原词不保证正确；需检查它在句中表达的判断。","prompt":"逐个核对且不放过错位，前后共同支持校验{{0}}。","blanks":[{"answer":"细致","accept":[]}]},{"id":"ki-v-095","title":"限制可能隔着一句才出现","core":"空后先谈人员分工，再写“破损书页已经逐页编号、配齐”，仍能限定前空应是整理、修复类动作。跨句甚至跨段回查，找真正的对象状态与结果。","boundary":"无明显标志也有对象和语义照应，但重复某个原词不保证正确；需检查它在句中表达的判断。","prompt":"空格后隔一句写“缺页已配齐”，这仍可作为空格动词的跨句{{0}}。","blanks":[{"answer":"证据","accept":[]}]}],"questions":[{"id":"ki-vq-065","lesson":"context-blanks","stem":"“修复师____地核对每一张底片的编号。桌上只留必要工具。他把相邻底片逐张比对，任何细小错位都不放过。”填入最恰当的是：","options":["迟钝","细致","喧闹","草率"],"answer":1,"explanation":"逐张比对与不放过小错位跨句照应细致，桌上工具不改变核心动作。","optionReviews":["迟钝描述反应不敏捷，材料未支持且与动作特征无关。","逐张比对与不放过小错位跨句照应细致，桌上工具不改变核心动作。","喧闹描述声音环境，不能由核对行为推出。","与不放过细小错位相反。"]},{"id":"ki-vq-066","lesson":"context-blanks","stem":"“团队完成了旧地图的____。馆内随后调整了展柜位置。原先模糊的路线已重新辨清，破损的边缘也得到加固，地图能够继续展出。”填入最恰当的是：","options":["修复","遗弃","售卖","命名"],"answer":0,"explanation":"隔句后的辨清路线、加固边缘及继续展出，共同限定修复。","optionReviews":["隔句后的辨清路线、加固边缘及继续展出，共同限定修复。","遗弃与继续展出相反。","展出不等于售卖，售卖也不解释修补结果。","命名不产生辨清与加固效果。"]}]},{"lessonId":"word","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"对象还带有阶段与状态","text":"还须明确对象当前的功能与状态：用于防护、连接还是展示，处于完好、破损还是待测状态，都会限制合适动作。同样讲河流，勘测阶段需要测量、建设阶段涉及施工、维护阶段关注疏通。文段若谈竣工后排除淤积，不能只因“建设”也是河流话题便选它。 适用边界：话题相关只是进入比较的门槛；阶段、对象状态、词义、搭配和实际判断必须同时合适。","index":33,"domId":"ki-point-0284"},{"title":"转移对象或扩大范围要警惕","text":"材料只谈一座桥的桥面修补，填成“治理全流域污染”换了对象与任务；“修缮”比这种跨题词更贴近。但还需核查修缮是否真能支配对象及表达预定动作。 适用边界：话题相关只是进入比较的门槛；阶段、对象状态、词义、搭配和实际判断必须同时合适。","index":34,"domId":"ki-point-0285"},{"title":"相关词仍需完成句子要求","text":"论题是交通不表示“车流、桥梁、速度”任意可填。“修补桥面裂缝”要求修复类动词，不能“行驶裂缝”。对象相关性不能取代语义和搭配。 适用边界：话题相关只是进入比较的门槛；阶段、对象状态、词义、搭配和实际判断必须同时合适。","index":35,"domId":"ki-point-0286"}],"cards":[{"id":"ki-v-096","title":"对象还带有阶段与状态","core":"还须明确对象当前的功能与状态：用于防护、连接还是展示，处于完好、破损还是待测状态，都会限制合适动作。同样讲河流，勘测阶段需要测量、建设阶段涉及施工、维护阶段关注疏通。文段若谈竣工后排除淤积，不能只因“建设”也是河流话题便选它。","boundary":"话题相关只是进入比较的门槛；阶段、对象状态、词义、搭配和实际判断必须同时合适。","prompt":"竣工后定期清除淤积，属于工程的{{0}}阶段。","blanks":[{"answer":"维护","accept":[]}]},{"id":"ki-v-097","title":"转移对象或扩大范围要警惕","core":"材料只谈一座桥的桥面修补，填成“治理全流域污染”换了对象与任务；“修缮”比这种跨题词更贴近。但还需核查修缮是否真能支配对象及表达预定动作。","boundary":"话题相关只是进入比较的门槛；阶段、对象状态、词义、搭配和实际判断必须同时合适。","prompt":"从“一座桥面修补”跳到“全流域污染治理”，同时转移对象并扩大了{{0}}。","blanks":[{"answer":"范围","accept":[]}]},{"id":"ki-v-098","title":"相关词仍需完成句子要求","core":"论题是交通不表示“车流、桥梁、速度”任意可填。“修补桥面裂缝”要求修复类动词，不能“行驶裂缝”。对象相关性不能取代语义和搭配。","boundary":"话题相关只是进入比较的门槛；阶段、对象状态、词义、搭配和实际判断必须同时合适。","prompt":"“____桥面裂缝”需能支配裂缝的修复类动词，如{{0}}。","blanks":[{"answer":"修补","accept":[]}]}],"questions":[{"id":"ki-vq-067","lesson":"word","stem":"“这座步行桥已投入使用五年。当前工作的重点是定期检查并____桥面裂缝，以保持既有通行功能，而不是新建线路。”填入最恰当的是：","options":["行驶","污染","拓展","修补"],"answer":3,"explanation":"投入使用五年定位维护阶段，裂缝要求修补动作，范围仍为既有桥面。","optionReviews":["行驶支配或依附车辆道路，不能行驶裂缝。","污染不保持通行且与修复目的相反。","拓展用于范围或空间，不符合裂缝维护与非新建限定。","投入使用五年定位维护阶段，裂缝要求修补动作，范围仍为既有桥面。"]},{"id":"ki-vq-068","lesson":"word","stem":"“育苗室中的幼苗尚未定植，当前需要____根系发育，待根系稳定后再移栽。”填入最恰当的是：","options":["收割","终止","促进","歌颂"],"answer":2,"explanation":"幼苗培育阶段需要推动根系发育，促进支配发育且符合后续移栽。","optionReviews":["收割对象是成熟作物等，不合幼苗根系发育阶段。","终止发育与待根系稳定再移栽的目标相反。","幼苗培育阶段需要推动根系发育，促进支配发育且符合后续移栽。","歌颂虽可涉及农业却不表达培育动作。"]}]},{"lessonId":"context-blanks","topicId":"context-words","courseRoute":"#course/verbal/topic/context-words","sections":[{"title":"先检验局部句法与对象","text":"“缓解压力”动宾成立，“聆听压力”一般不合本句动作。“有序的安排”定语修饰名词成立，还要检查主语是否真能实施动作，以及代词是否有对象。 适用边界：所有空都须通过句内与全文证据；若现有证据无法区别两个候选，应承认不足，不能凭偏好强造唯一解。","index":23,"domId":"ki-point-0287"},{"title":"再看跨句方向和评价","text":"局部“显著提高”能搭配某名词，却可能把等待时间变长，违背下一句减少等待的目标。跨句回查对象、因果方向和正负评价，防止只求局部顺口。 适用边界：所有空都须通过句内与全文证据；若现有证据无法区别两个候选，应承认不足，不能凭偏好强造唯一解。","index":24,"domId":"ki-point-0288"},{"title":"多空整段一次回填","text":"第一空贴切不等于整组正确。若第一空“缓解”对，第二空却把试行说成已证明永久有效，应淘汰。整段回填也能发现两个候选实际等价时信息不足，而不是编造差别。 适用边界：所有空都须通过句内与全文证据；若现有证据无法区别两个候选，应承认不足，不能凭偏好强造唯一解。","index":25,"domId":"ki-point-0289"}],"cards":[{"id":"ki-v-099","title":"先检验局部句法与对象","core":"“缓解压力”动宾成立，“聆听压力”一般不合本句动作。“有序的安排”定语修饰名词成立，还要检查主语是否真能实施动作，以及代词是否有对象。","boundary":"所有空都须通过句内与全文证据；若现有证据无法区别两个候选，应承认不足，不能凭偏好强造唯一解。","prompt":"“____拥堵”若表达减轻程度，应先检验动宾搭配，合适的词是{{0}}。","blanks":[{"answer":"缓解","accept":[]}]},{"id":"ki-v-100","title":"再看跨句方向和评价","core":"局部“显著提高”能搭配某名词，却可能把等待时间变长，违背下一句减少等待的目标。跨句回查对象、因果方向和正负评价，防止只求局部顺口。","boundary":"所有空都须通过句内与全文证据；若现有证据无法区别两个候选，应承认不足，不能凭偏好强造唯一解。","prompt":"后文说等待缩短，前空不能写“显著{{0}}等待时间”。","blanks":[{"answer":"增加","accept":[]}]},{"id":"ki-v-101","title":"多空整段一次回填","core":"第一空贴切不等于整组正确。若第一空“缓解”对，第二空却把试行说成已证明永久有效，应淘汰。整段回填也能发现两个候选实际等价时信息不足，而不是编造差别。","boundary":"所有空都须通过句内与全文证据；若现有证据无法区别两个候选，应承认不足，不能凭偏好强造唯一解。","prompt":"一组答案第一空正确、第二空越过证据，整组选项仍应{{0}}。","blanks":[{"answer":"淘汰","accept":[]}]}],"questions":[{"id":"ki-vq-069","lesson":"context-blanks","stem":"新增接驳车使平均候车时间下降，但高峰仍有排队，说明它____了候车压力。一周试行尚不足以支持全季节结论，因此判断仍应____。填入最恰当的是：","options":["根除／审慎","缓解／审慎","缓解／武断","聆听／审慎"],"answer":1,"explanation":"缓解与候车压力搭配，匹配改善但仍排队；样本仅一周要求审慎，两空均有明确证据。","optionReviews":["根除与高峰仍有排队矛盾，第二空正确不能弥补第一空。","缓解与候车压力搭配，匹配改善但仍排队；样本仅一周要求审慎，两空均有明确证据。","缓解正确，但武断违背证据有限应保留判断的后句要求。","聆听不能表达候车压力减轻，且搭配不当。"]},{"id":"ki-vq-070","lesson":"context-blanks","stem":"“电子标签使查找时间由十分钟降为六分钟，____了检索效率。但这只是一次小规模试验，结论仍需更多样本____。”填入最恰当的是：","options":["提高／终结","提高／庆祝","降低／验证","提高／验证"],"answer":3,"explanation":"时间缩短支持效率提高，试验规模小要求进一步验证，两个空共同成立。","optionReviews":["提高对，但终结样本或结论不表达继续检验的要求。","提高对，但庆祝不能完成样本支持结论的验证任务。","将时间减少误读为效率降低，方向相反。","时间缩短支持效率提高，试验规模小要求进一步验证，两个空共同成立。"]},{"id":"ki-vq-071","lesson":"context-blanks","stem":"编辑只得到一句：“新安排使等候时间有所减少，改善了服务体验。”备选词为“改进”和“优化”，均拟替换“改善”，未提供其他语体或搭配限制。以下判断最稳妥的是：","options":["现有信息不足以证明两者只能选一个，应补充限制或允许同义答案","必须选优化，因为它字数与改善相同而改进不同","两者都与服务改善完全相反","必须选改进，因为优化在任何语境都不能用于服务"],"answer":0,"explanation":"在该笼统语境中，两者均可能表达改良，缺区分证据时不强造唯一；正式四选一题应另加足够限制。","optionReviews":["在该笼统语境中，两者均可能表达改良，缺区分证据时不强造唯一；正式四选一题应另加足够限制。","二者都是两个字，且字数本身不是语义依据。","两个词均非与改善方向相反。","优化服务是可成立的表达，绝对排除错误。"]}]}];

const C=window.STUDY_CONTENT,T=window.STUDY_COMPLETE_TOPICS,D=window.STUDY_TOPIC_RECALL_CARDS,P=window.STUDY_COURSE;
if(!C||!T||!D||!P)throw Error('Knowledge integration load order');
const recallCoreCounts=Object.fromEntries(Object.entries(D).map(([id,cards])=>[id,cards.length]));
const anchors=[];const baselineIds=new Set(C.questions.map(q=>q.id));
for(const r of rows){
 const l=C.lessons.find(l=>l.id===r.lessonId),t=T.topics.find(t=>t.id===r.topicId);
 if(!l||!t||!t.sourceLessonIds.includes(l.id))throw Error('Knowledge integration map');
 let block=t.blocks.find(b=>b.parts.some(p=>p.lessonId===l.id));
 if(!block){block={id:'knowledge-'+l.id,title:l.title.split('：')[0],parts:[]};t.blocks.push(block);}
 let part=block.parts.find(p=>p.lessonId===l.id);if(!part){part={lessonId:l.id,sectionIndexes:[]};block.parts.push(part);}
 const indexes=[];
 for(const s of r.sections){if(l.sections.length!==s.index)throw Error('Knowledge section baseline changed');l.sections.push([s.title,s.text]);indexes.push(s.index);part.sectionIndexes.push(s.index);anchors.push({...s,lessonId:l.id,topicId:t.id,courseRoute:r.courseRoute,questionIds:r.questions.map(q=>q.id)});}
 for(const q of r.questions){
  if(baselineIds.has(q.id))throw Error('Knowledge question duplicate');baselineIds.add(q.id);
  q.trainingStage=q.trainingStage||'迁移运用';q.trainingGoal=q.trainingGoal||'用独立情境检验知识与适用条件';
  q.meta={module:l.category,type:l.questionType||l.title.split('：')[0],trainingStage:q.trainingStage,trainingGoal:q.trainingGoal,knowledgeIds:[l.id],tags:[...l.tags],applicableExams:['national','fujian'],examSource:{system:null,year:null,paper:null,number:null},difficulty:{level:null,basis:null},purpose:'独立知识应用训练，未作考生样本难度标定',source:{kind:'original',title:'本站原创知识应用练习',url:null,referenceIds:[...(l.sources||[])]},rights:{status:'original',note:'题干、选项、逐项解析独立编写，未转载课程原题或原图。'},answerReview:{status:'editorial-reviewed-offline-candidate',date:'2026-11-09',basis:'知识、条件、答案与选项解析离线审校；选项重排后保留正确答案文本与对应解析；未作真实浏览器验收或难度实测。'},methodIds:[]};
  C.questions.push(q);l.practice.push(q.id);
 }
 for(const c of r.cards){c.part=t.blocks.indexOf(block);(D[t.id]||(D[t.id]=[])).push(c);}
 if(l.learningLevels?.practice){l.learningLevels={...l.learningLevels,practice:{...l.learningLevels.practice}};const level=l.learningLevels.practice;level.sections=[...(level.sections||[]),...indexes];level.questionIds=[...(level.questionIds||[]),...r.questions.map(q=>q.id)];}
 l.updated='2026-11-09';
}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Keep one whole-topic summary card. Detailed applications stay available on demand,
// rather than turning its short main outline into hundreds of visible fragments.
function compactRecall(root){
 const areas=[];
 if(root.matches?.('[data-topic-recall-id]'))areas.push(root);
 areas.push(...(root.querySelectorAll?.('[data-topic-recall-id]')||[]));
 for(const area of areas){
  const id=area.dataset.topicRecallId,keep=recallCoreCounts[id],card=area.querySelector('.recall-topic-card'),list=card?.querySelector('.recall-topic-points');
  if(!list||keep===undefined||card.querySelector('[data-knowledge-recall-more]'))continue;
  const points=Array.from(list.children);if(points.length<=keep)continue;
  const details=document.createElement('details');details.dataset.knowledgeRecallMore='';
  const summary=document.createElement('summary');summary.textContent='展开方法与易混补充 · '+(points.length-keep)+' 条';
  const extra=document.createElement('ul');extra.className='recall-topic-points';
  points.slice(keep).forEach(point=>extra.append(point));details.append(summary,extra);list.after(details);
 }
}
if(typeof MutationObserver!=='undefined'&&document.body){
 const observer=new MutationObserver(()=>{if(document?.body)compactRecall(document);});
 observer.observe(document.body,{childList:true,subtree:true});
}
const oldRender=P.render;
P.render=(parts,...rest)=>{
 const deep=parts[2]==='topic'&&parts[4]==='point'&&parts.length===6;
 const route=deep?parts.slice(0,4):parts,html=oldRender(route,...rest);
 if(route[2]!=='topic'||typeof document==='undefined')return html;
 const own=anchors.filter(a=>a.topicId===route[3]);if(!own.length)return html;
 const tmp=document.createElement('template');tmp.innerHTML=html;compactRecall(tmp.content);
 for(const a of own){const el=tmp.content.querySelector('[data-source-lesson="'+a.lessonId+'"][data-source-section="'+a.index+'"]');if(!el)continue;el.id=a.domId;el.tabIndex=-1;
  if(a.diagramSvg){const img=document.createElement('img');img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(a.diagramSvg);img.alt=a.title+'的原创示意图';img.style.cssText='max-width:100%;height:auto';el.append(img);}
  const nav=document.createElement('p');nav.className='knowledge-practice-link';nav.innerHTML='<a href="#quiz/target/'+a.questionIds.join(',')+a.courseRoute.slice(1).replace(/^course/,'/course')+'">用原创题检验本节 →</a>';el.append(nav);
 }
 if(deep&&own.some(a=>a.domId===parts[5])&&typeof setTimeout==='function')setTimeout(()=>{const el=document.getElementById(parts[5]);el?.scrollIntoView({block:'start'});el?.focus({preventScroll:true});},0);
 return tmp.innerHTML;
};
window.STUDY_KNOWLEDGE_INTEGRATION={version:'20261109-reviewed-candidate.1',sections:anchors.map(a=>({id:a.domId,lessonId:a.lessonId,topicId:a.topicId,sectionIndex:a.index,questionIds:a.questionIds})),questionIds:rows.flatMap(r=>r.questions.map(q=>q.id)),cardIds:rows.flatMap(r=>r.cards.map(c=>c.id)),status:'offline-reviewed-candidate-not-published'};
})();
